/* ===== src/introContent.js ===== */
window.STREETS_INTRO_TEXT = `Россия. 2026 год. 

Сумасшедший тиран держит страну в страхе. 

Телевизоры давно говорят громче людей. 

Каждый вечер они объясняют, кого бояться, кого ненавидеть и почему снова нужно терпеть. 

Страх стал привычкой. 

Ложь стала воздухом. 

Молчание — способом выжить.

Эта страна могла быть счастливой. 

Люди могли жить свободно, говорить правду и смотреть в завтрашний день без страха. 

Но этому не дали случиться. 

Шаг за шагом страну захватили твари. 

Они пролезли во власть, в суды, в школы, в армию и полицию. 

Несогласных ломали, давили, убивали или заставляли исчезнуть. 

Казалось, надежды больше нет. 

Но у людей осталась вера в светлое будущее. 

И однажды эта вера стала сопротивлением. 

Сначала это был почти незаметный жест. 

Кто-то вышел из молчания. 

Кто-то рядом перестал отводить глаза.

Кто-то впервые сказал вслух то, о чём все давно думали. 

И страх дал трещину. 

Проснулся один город, за ним — другой. 

Потом огни сопротивления начали загораться всё дальше: улица за улицей, район за районом, город за городом. 

Страна, которую заставили молчать, начала говорить. 

Люди начали возвращать себе страну. 

Герои прошлого вернулись в сердца людей. 

Сопротивление выходит на улицы. 

В каждом теперь есть герой. 

Это Streets of Russia!`;


/* ===== src/responsive.js ===== */
const Responsive = {
  canvas: null,
  ctx: null,
  scale: 1,
  scaleX: 1,
  scaleY: 1,
  offsetX: 0,
  offsetY: 0,
  cssWidth: GAME_CONFIG.width,
  cssHeight: GAME_CONFIG.height,
  isPortrait: false,
  isTouchDevice: false,

  init(canvas, ctx) {
    this.canvas = canvas;
    this.ctx = ctx;
    this.isTouchDevice = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('orientationchange', () => setTimeout(() => this.resize(), 120));
    this.resize();
  },

  resize() {
    const gameW = GAME_CONFIG.width;
    const gameH = GAME_CONFIG.height;
    const vw = Math.max(1, window.innerWidth);
    const vh = Math.max(1, window.innerHeight);
    const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2));

    this.isPortrait = vw < vh && vw < 900;

    if (this.isPortrait && this.isTouchDevice) {
      this.cssWidth = vw;
      this.cssHeight = vh;
      this.offsetX = 0;
      this.offsetY = 0;
      this.scaleX = vw / gameW;
      this.scaleY = vh / gameH;
      this.scale = Math.min(this.scaleX, this.scaleY);
    } else {
      const scale = Math.min(vw / gameW, vh / gameH);
      this.scale = scale;
      this.scaleX = scale;
      this.scaleY = scale;
      this.cssWidth = Math.round(gameW * scale);
      this.cssHeight = Math.round(gameH * scale);
      this.offsetX = Math.round((vw - this.cssWidth) / 2);
      this.offsetY = Math.round((vh - this.cssHeight) / 2);
    }

    this.canvas.style.width = this.cssWidth + 'px';
    this.canvas.style.height = this.cssHeight + 'px';
    this.canvas.style.marginLeft = this.offsetX + 'px';
    this.canvas.style.marginTop = this.offsetY + 'px';

    this.canvas.width = Math.round(gameW * dpr);
    this.canvas.height = Math.round(gameH * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  },

  screenToGame(clientX, clientY) {
    return {
      x: (clientX - this.offsetX) / this.scaleX,
      y: (clientY - this.offsetY) / this.scaleY
    };
  }
};


/* ===== src/input.js ===== */
const Input = {
  keys: {},
  virtualKeys: {},
  just: {},
  pointer: { x: 0, y: 0, down: false, justDown: false },
  touches: [],
  lastTouchAt: 0,

  init(canvas) {
    window.addEventListener('keydown', (event) => {
      const key = this.normalizeKey(event);
      if (!this.keys[key]) this.just[key] = true;
      this.just.any = true;
      this.keys[key] = true;

      if (event.code === 'Backquote') {
        this.just.dev = true;
        this.keys.dev = true;
        event.preventDefault();
      }

      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' ', 'Enter'].includes(event.key) ||
          ['KeyW', 'KeyA', 'KeyS', 'KeyD', 'Space'].includes(event.code)) event.preventDefault();
    });

    window.addEventListener('keyup', (event) => {
      const key = this.normalizeKey(event);
      this.keys[key] = false;
      if (event.code === 'Backquote') this.keys.dev = false;
    });

    const setPointerFromGamePoint = (point, justDown = false) => {
      this.pointer.x = point.x;
      this.pointer.y = point.y;
      this.pointer.down = true;
      if (justDown) {
        this.pointer.justDown = true;
        this.just.any = true;
      }
    };

    const setPointerFromClient = (clientX, clientY, justDown = false) => {
      const pos = Responsive.screenToGame(clientX, clientY);
      setPointerFromGamePoint(pos, justDown);
    };

    const syncTouches = (event, markChangedAsJustDown = false) => {
      const changedIds = new Set();
      if (event.changedTouches) {
        for (let i = 0; i < event.changedTouches.length; i++) changedIds.add(event.changedTouches[i].identifier);
      }

      this.touches = [];
      for (let i = 0; i < event.touches.length; i++) {
        const touch = event.touches[i];
        const pos = Responsive.screenToGame(touch.clientX, touch.clientY);
        this.touches.push({
          id: touch.identifier,
          x: pos.x,
          y: pos.y,
          justDown: markChangedAsJustDown && changedIds.has(touch.identifier)
        });
      }

      if (this.touches.length > 0) {
        const first = this.touches[0];
        setPointerFromGamePoint(first, markChangedAsJustDown && first.justDown);
      } else {
        this.pointer.down = false;
      }
    };

    canvas.addEventListener('touchstart', (event) => {
      if (event.cancelable) event.preventDefault();
      this.lastTouchAt = performance.now();
      syncTouches(event, true);
    }, { passive: false });

    canvas.addEventListener('touchmove', (event) => {
      if (event.cancelable) event.preventDefault();
      this.lastTouchAt = performance.now();
      syncTouches(event, false);
    }, { passive: false });

    const handleTouchEnd = (event) => {
      if (event.cancelable) event.preventDefault();
      this.lastTouchAt = performance.now();
      syncTouches(event, false);
      if (!event.touches || event.touches.length === 0) {
        this.pointer.down = false;
        this.pointer.justDown = false;
        this.clearVirtualKeys();
      }
    };

    canvas.addEventListener('touchend', handleTouchEnd, { passive: false });
    canvas.addEventListener('touchcancel', handleTouchEnd, { passive: false });
    canvas.addEventListener('contextmenu', (event) => event.preventDefault());

    canvas.addEventListener('pointerdown', (event) => {
      if (performance.now() - this.lastTouchAt < 450) return;
      if (event.cancelable) event.preventDefault();
      if (canvas.setPointerCapture && event.pointerId != null) {
        try { canvas.setPointerCapture(event.pointerId); } catch (error) {}
      }
      setPointerFromClient(event.clientX, event.clientY, true);
    }, { passive: false });

    canvas.addEventListener('pointermove', (event) => {
      if (performance.now() - this.lastTouchAt < 450) return;
      if (event.cancelable) event.preventDefault();
      setPointerFromClient(event.clientX, event.clientY, false);
    }, { passive: false });

    window.addEventListener('pointerup', (event) => {
      if (performance.now() - this.lastTouchAt < 450 || this.touches.length > 0) return;
      if (event && event.cancelable) event.preventDefault();
      this.pointer.down = false;
      this.clearVirtualKeys();
    }, { passive: false });
  },

  normalizeKey(event) {
    if (event.code === 'Space') return 'space';
    if (event.code === 'Backquote') return 'dev';
    if (/^Key[A-Z]$/.test(event.code || '')) return event.code.slice(3).toLowerCase();
    if (event.key === 'Escape') return 'escape';
    if (event.key === 'Enter') return 'enter';
    return String(event.key || '').toLowerCase();
  },

  pressed(key) {
    return !!this.keys[key] || !!this.virtualKeys[key];
  },

  setVirtualKey(key, value) {
    const wasDown = !!this.virtualKeys[key];
    this.virtualKeys[key] = !!value;
    if (value && !wasDown) {
      this.just[key] = true;
      this.just.any = true;
    }
  },

  clearVirtualKeys() {
    this.virtualKeys = {};
  },

  consume(key) {
    const value = !!this.just[key];
    this.just[key] = false;
    return value;
  },

  consumeAnyKey() {
    const value = !!this.just.any;
    this.just.any = false;
    return value;
  },

  consumePointer() {
    const value = this.pointer.justDown ? { x: this.pointer.x, y: this.pointer.y } : null;
    this.pointer.justDown = false;
    return value;
  },

  restorePointer(point) {
    if (!point) return;
    this.pointer.x = point.x;
    this.pointer.y = point.y;
    this.pointer.justDown = true;
  },

  endFrame() {
    this.just = {};
    this.pointer.justDown = false;
    for (const touch of this.touches) touch.justDown = false;
  }
};



/* ===== src/combat.js ===== */
const Combat = {
  overlap(a, b) {
    return !!a && !!b && a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  },

  sameLane(aY, bY, tolerance = GAME_CONFIG.yHitTolerance) {
    return Math.abs(aY - bY) <= tolerance;
  },

  sameFootLane(aY, bY, tolerance = GAME_CONFIG.yHitTolerance) {
    return this.sameLane(aY, bY, tolerance);
  },

  laneIndex(y) {
    const top = GAME_CONFIG.laneTop;
    const bottom = GAME_CONFIG.laneBottom;
    const count = Math.max(1, GAME_CONFIG.combatLaneCount || 3);
    const laneHeight = Math.max(1, (bottom - top) / count);
    const index = Math.floor((y - top) / laneHeight);
    return Math.max(0, Math.min(count - 1, index));
  },

  laneCenter(index) {
    const top = GAME_CONFIG.laneTop;
    const bottom = GAME_CONFIG.laneBottom;
    const count = Math.max(1, GAME_CONFIG.combatLaneCount || 3);
    const laneHeight = Math.max(1, (bottom - top) / count);
    return top + laneHeight * (Math.max(0, Math.min(count - 1, index)) + 0.5);
  },

  actorLaneY(actor) {
    if (!actor) return GAME_CONFIG.laneTop;
    if (Number.isFinite(actor.laneY)) return actor.laneY;
    if (Number.isFinite(actor.feetY)) return actor.feetY;
    if (Number.isFinite(actor.y)) return actor.y;
    const box = typeof actor.getPushbox === 'function' ? actor.getPushbox() :
      typeof actor.getBodyBox === 'function' ? actor.getBodyBox() :
      typeof actor.getHurtbox === 'function' ? actor.getHurtbox() : null;
    return box ? box.y + box.h : GAME_CONFIG.laneTop;
  },

  actorFeetY(actor) {
    return this.actorLaneY(actor);
  },

  actorsSameLane(a, b, tolerance = GAME_CONFIG.yHitTolerance) {
    return this.sameLane(this.actorLaneY(a), this.actorLaneY(b), tolerance);
  },

  actorsSameFootLane(a, b, tolerance = GAME_CONFIG.yHitTolerance) {
    return this.sameFootLane(this.actorFeetY(a), this.actorFeetY(b), tolerance);
  },

  actorFootTolerance(actor, fallback = GAME_CONFIG.yHitTolerance) {
    if (!actor) return fallback;
    if (Number.isFinite(actor.footTolerance)) return actor.footTolerance;
    if (Number.isFinite(actor.hitLaneTolerance)) return actor.hitLaneTolerance;

    const pushbox = typeof actor.getPushbox === 'function' ? actor.getPushbox() : null;
    if (pushbox && Number.isFinite(pushbox.h)) {
      return Math.max(14, Math.min(fallback, pushbox.h * 0.62));
    }

    return fallback;
  },

  actorFootBand(actor, tolerance = this.actorFootTolerance(actor)) {
    const y = this.actorFeetY(actor);
    const radius = Math.max(1, tolerance || GAME_CONFIG.yHitTolerance || 28);
    return { top: y - radius, bottom: y + radius, center: y, radius };
  },

  footBandsOverlap(a, b, tolerance = GAME_CONFIG.yHitTolerance) {
    const aBand = this.actorFootBand(a, this.actorFootTolerance(a, tolerance));
    const bBand = this.actorFootBand(b, this.actorFootTolerance(b, tolerance));
    return aBand.top <= bBand.bottom && aBand.bottom >= bBand.top;
  },

  verticalBandsOverlap(aTop, aBottom, bTop, bBottom, tolerance = 0) {
    return aTop <= bBottom + tolerance && aBottom >= bTop - tolerance;
  },

  pushboxLaneCanConnect(attacker, target, tolerance = GAME_CONFIG.pushboxLaneTolerance || 12) {
    const attackerPush = attacker && typeof attacker.getPushbox === 'function' ? attacker.getPushbox() : null;
    const targetPush = target && typeof target.getPushbox === 'function' ? target.getPushbox() : null;
    if (!attackerPush || !targetPush) return null;
    return this.verticalBandsOverlap(
      attackerPush.y,
      attackerPush.y + attackerPush.h,
      targetPush.y,
      targetPush.y + targetPush.h,
      tolerance
    );
  },

  actorOnLane(actor, laneY, tolerance = GAME_CONFIG.yHitTolerance) {
    if (!Number.isFinite(laneY)) return true;
    const band = this.actorFootBand(actor, tolerance);
    return laneY >= band.top && laneY <= band.bottom;
  },

  laneCanConnect(attacker, target, options = {}) {
    const pushboxResult = this.pushboxLaneCanConnect(attacker, target, options.pushboxLaneTolerance);
    if (pushboxResult !== null) return pushboxResult;

    const tolerance = options.laneTolerance || GAME_CONFIG.yHitTolerance || 28;
    if (Number.isFinite(options.laneY)) return this.actorOnLane(target, options.laneY, tolerance);
    return this.footBandsOverlap(attacker, target, tolerance);
  },

  canHit(attacker, target, options = {}) {
    if (!attacker || !target) return false;
    const attackBox = options.attackBox ||
      (typeof attacker.getAttackBox === 'function' ? attacker.getAttackBox() :
        typeof attacker.getHitbox === 'function' ? attacker.getHitbox() : null);
    const targetBox = options.targetBox ||
      (typeof target.getBodyBox === 'function' ? target.getBodyBox() :
        typeof target.getHurtbox === 'function' ? target.getHurtbox() : null);

    return this.laneCanConnect(attacker, target, options) && this.overlap(attackBox, targetBox);
  },

  canMeleeHit(attacker, target, options = {}) {
    return this.canHit(attacker, target, options);
  },

  canProjectileHit(projectile, target, options = {}) {
    const attackBox = options.attackBox ||
      (typeof projectile.getAttackBox === 'function' ? projectile.getAttackBox() :
        typeof projectile.getHurtbox === 'function' ? projectile.getHurtbox() : null);
    const targetBox = options.targetBox ||
      (typeof target.getBodyBox === 'function' ? target.getBodyBox() :
        typeof target.getHurtbox === 'function' ? target.getHurtbox() : null);
    return this.laneCanConnect(projectile, target, {
      laneY: Number.isFinite(options.laneY) ? options.laneY : projectile.laneY,
      laneTolerance: options.laneTolerance || GAME_CONFIG.yHitTolerance
    }) && this.overlap(attackBox, targetBox);
  },

  canInteractHit(attacker, item, options = {}) {
    if (!attacker || !item) return false;
    const attackBox = options.attackBox ||
      (typeof attacker.getHitbox === 'function' ? attacker.getHitbox() :
        typeof attacker.getAttackBox === 'function' ? attacker.getAttackBox() : null);
    if (!this.overlap(attackBox, item.hitbox)) return false;
    if (!Number.isFinite(item.laneY)) return true;
    return this.actorOnLane(attacker, item.laneY, item.laneTolerance || GAME_CONFIG.yHitTolerance);
  }
};



/* ===== src/audio.js ===== */
const AudioManager = {
  sfx: {},
  optionalSfx: {},
  music: {},
  currentMusicKey: null,
  currentMusic: null,
  audioContext: null,
  unlocked: false,
  musicActuallyPlaying: false,
  activeSfx: [],
  pausedAudio: [],
  externalAudio: new Map(),
  audioContexts: new Set(),
  musicPauseReasons: null,
  enemyAppearType: null,

  init() {
    this.sfx = {};
    this.optionalSfx = {};
    this.music = {};
    this.currentMusicKey = null;
    this.currentMusic = null;
    this.audioContext = null;
    this.unlocked = false;
    this.musicActuallyPlaying = false;
    this.activeSfx = [];
    this.pausedAudio = [];
    this.externalAudio = new Map();
    this.audioContexts = new Set();
    this.musicPauseReasons = new Set();
    this.enemyAppearType = null;

    for (const [key, src] of Object.entries((Assets.audio && Assets.audio.sfx) || {})) {
      if (!src) continue;
      this.sfx[key] = this.createAudio(src, false);
    }

    this.registerCharacterSfx();

    for (const [key, src] of Object.entries((Assets.audio && Assets.audio.music) || {})) {
      if (!src) continue;
      this.music[key] = this.createAudio(src, true);
    }
  },

  createAudio(src, loop, options = {}) {
    const audio = new Audio();
    audio.src = src;
    audio.preload = 'auto';
    audio.loop = loop;
    audio.dataset.failed = 'false';
    audio.addEventListener('error', () => {
      audio.dataset.failed = 'true';
      if (!options.silentMissing) console.warn('Missing audio:', src);
    });
    return audio;
  },

  unlock() {
    if (this.unlocked) return;
    this.unlocked = true;
    this.ensureAudioContext();

    for (const audio of [...Object.values(this.sfx), ...Object.values(this.music), ...Object.values(this.optionalSfx)]) {
      audio.load();
    }

    if (this.currentMusicKey) this.playMusic(this.currentMusicKey, false, true);
  },

  ensureAudioContext() {
    if (this.audioContext) return this.audioContext;
    const Context = window.AudioContext || window.webkitAudioContext;
    if (!Context) return null;
    try {
      this.audioContext = new Context();
      this.registerAudioContext(this.audioContext);
    } catch (error) {
      this.audioContext = null;
    }
    return this.audioContext;
  },

  registerAudioContext(context) {
    if (context) this.audioContexts.add(context);
    return context;
  },

  registerExternalAudio(audio, options = {}) {
    if (!audio) return audio;
    const metadata = {
      owner: options.owner || 'external',
      channel: options.channel || 'sfx',
      resume: options.resume !== false
    };
    this.externalAudio.set(audio, metadata);
    const cleanup = () => this.externalAudio.delete(audio);
    audio.addEventListener('error', cleanup, { once: true });
    if (!audio.loop) audio.addEventListener('ended', cleanup, { once: true });
    return audio;
  },

  unregisterExternalAudio(audio) {
    if (audio) this.externalAudio.delete(audio);
  },

  stopExternalAudio(owner) {
    for (const [audio, metadata] of this.externalAudio) {
      if (owner && metadata.owner !== owner) continue;
      try {
        audio.pause();
        audio.currentTime = 0;
      } catch (error) {}
    }
    this.pausedAudio = (this.pausedAudio || []).filter(audio => {
      const metadata = this.externalAudio.get(audio);
      return !metadata || (owner && metadata.owner !== owner);
    });
  },

  canResumeExternalAudio(audio) {
    const metadata = this.externalAudio.get(audio);
    if (!metadata || !metadata.resume || document.hidden) return false;
    const game = window.game;
    if (metadata.owner === 'intro') return !!game && game.state === 'intro';
    if (metadata.owner === 'gundos') return !!game && game.state === 'level' && !game.paused;
    if (metadata.owner === 'heroVoice') return !!game && game.state === 'level' && !game.paused && this.isSfxOn();
    return metadata.channel === 'music' ? this.isMusicOn() : this.isSfxOn();
  },

  stopAllAudio() {
    this.stopMusic();
    for (const audio of this.activeSfx || []) {
      try {
        audio.pause();
        audio.currentTime = 0;
      } catch (error) {}
    }
    this.activeSfx = [];
    this.stopExternalAudio();
    this.pausedAudio = [];
    for (const context of this.audioContexts || []) {
      try { context.suspend(); } catch (error) {}
    }
    if (this.audioContext) {
      try { this.audioContext.suspend(); } catch (error) {}
    }
  },

  isSoundOn() {
    return !GAME_CONFIG.settings || GAME_CONFIG.settings.soundEnabled !== false;
  },

  isMusicEnabled() {
    return !GAME_CONFIG.settings || GAME_CONFIG.settings.musicEnabled !== false;
  },

  isMusicOn() {
    return this.isSoundOn() && this.isMusicEnabled();
  },

  isSfxOn() {
    return this.isSoundOn() && (!GAME_CONFIG.settings || GAME_CONFIG.settings.sfxEnabled !== false);
  },

  getSfxVolume(volume = 1) {
    if (!this.isSoundOn()) return 0;
    const base = GAME_CONFIG.settings && GAME_CONFIG.settings.sfxVolume != null ? GAME_CONFIG.settings.sfxVolume : 0.85;
    return Math.max(0, Math.min(1, base * volume));
  },

  getMusicVolume() {
    if (!this.isSoundOn() || !this.isMusicEnabled()) return 0;
    const base = GAME_CONFIG.settings && GAME_CONFIG.settings.musicVolume != null ? GAME_CONFIG.settings.musicVolume : 0.45;
    return Math.max(0, Math.min(1, base));
  },

  setMusicVolume(value) {
    GAME_CONFIG.settings.musicVolume = Math.max(0, Math.min(1, value));
    this.refreshSettings();
  },

  setSfxVolume(value) {
    GAME_CONFIG.settings.sfxVolume = Math.max(0, Math.min(1, value));
  },

  toggleSound() {
    GAME_CONFIG.settings.soundEnabled = GAME_CONFIG.settings.soundEnabled === false;
    this.refreshSettings();
    return GAME_CONFIG.settings.soundEnabled !== false;
  },

  toggleMusic() {
    GAME_CONFIG.settings.musicEnabled = !GAME_CONFIG.settings.musicEnabled;
    this.refreshSettings();
    return GAME_CONFIG.settings.musicEnabled;
  },

  toggleSfx() {
    GAME_CONFIG.settings.sfxEnabled = !GAME_CONFIG.settings.sfxEnabled;
    return GAME_CONFIG.settings.sfxEnabled;
  },

  trackSfx(audio) {
    if (!audio) return audio;
    this.activeSfx = this.activeSfx.filter(item => item && !item.ended && !item.paused);
    this.activeSfx.push(audio);
    const cleanup = () => {
      this.activeSfx = this.activeSfx.filter(item => item !== audio);
    };
    audio.addEventListener('ended', cleanup, { once: true });
    audio.addEventListener('error', cleanup, { once: true });
    return audio;
  },

  getAssetDirectory(src) {
    if (!src || typeof src !== 'string' || src.indexOf('/') === -1) return null;
    return src.slice(0, src.lastIndexOf('/'));
  },

  getHeroHitSrc(heroKey) {
    const heroAssets = Assets && Assets[heroKey];
    const dir = this.getAssetDirectory(heroAssets && heroAssets.idle);
    return dir ? dir + '/Hit.mp3' : null;
  },

  getEnemyAppearSrc(enemyType) {
    if (enemyType === 'dogRegime') return null;
    const enemyConfig = (GAME_CONFIG.enemies && GAME_CONFIG.enemies[enemyType]) || {};
    if (enemyConfig.appearSoundPath) return enemyConfig.appearSoundPath;
    if (Assets.enemyAppear && Assets.enemyAppear[enemyType]) return Assets.enemyAppear[enemyType];
    const folder = String(enemyType || 'enemy').replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
    return 'assets/enemies/' + folder + '/Appear.mp3';
  },

  registerCharacterSfx() {
    for (const enemyType of Object.keys((GAME_CONFIG && GAME_CONFIG.enemies) || {})) {
      const src = this.getEnemyAppearSrc(enemyType);
      if (!src) continue;
      this.sfx[enemyType + 'Appear'] = this.createAudio(src, false);
    }

    for (const heroKey of Object.keys((GAME_CONFIG && GAME_CONFIG.heroes) || {})) {
      const src = this.getHeroHitSrc(heroKey);
      if (!src) continue;
      this.sfx[heroKey + 'Hit'] = this.createAudio(src, false);
    }
  },

  isUsableSfxKey(key) {
    const audio = this.sfx && this.sfx[key];
    return !!audio && (!audio.dataset || audio.dataset.failed !== 'true');
  },

  playSfx(key, volume = 1, options = {}) {
    if (!this.isSfxOn()) return;
    if (this.isBlockedHorseAppear(key, options)) return;
    const src = this.sfx[key];
    if (!src) {
      this.playSyntheticSfx(key, volume, options);
      return;
    }

    if (src.dataset && src.dataset.failed === 'true') {
      this.playSyntheticSfx(key, volume, options);
      return;
    }

    try {
      const audio = src.cloneNode(true);
      const playbackRate = options.playbackRate || options.rate || 1;
      const startAt = options.startAt || 0;

      audio.volume = this.getSfxVolume(volume);
      audio.playbackRate = Math.max(0.5, Math.min(2, playbackRate));
      if (startAt > 0) audio.currentTime = startAt;
      this.trackSfx(audio);
      audio.play().catch(() => this.playSyntheticSfx(key, volume, options));
    } catch (error) {
      console.warn('Cannot play sfx:', key, error);
      this.playSyntheticSfx(key, volume, options);
    }
  },

  playOptionalSfx(key, volume = 1, options = {}) {
    if (!this.isSfxOn()) return false;
    if (this.isBlockedHorseAppear(key, options)) return false;

    const registered = this.sfx[key];
    if (registered && (!registered.dataset || registered.dataset.failed !== 'true')) {
      this.playSfx(key, volume, options);
      return true;
    }

    const srcPath = options.src || options.path;
    if (this.isBlockedHorseAppear(key, { src: srcPath })) return false;
    if (!srcPath) return false;

    const cacheKey = key || srcPath;
    let src = this.optionalSfx[cacheKey];
    if (!src) {
      src = this.createAudio(srcPath, false, { silentMissing: true });
      this.optionalSfx[cacheKey] = src;
      if (this.unlocked) src.load();
    }

    if (src.dataset && src.dataset.failed === 'true') return false;

    try {
      const audio = src.cloneNode(true);
      const playbackRate = options.playbackRate || options.rate || 1;
      const startAt = options.startAt || 0;

      audio.volume = this.getSfxVolume(volume);
      audio.playbackRate = Math.max(0.5, Math.min(2, playbackRate));
      if (startAt > 0) audio.currentTime = startAt;
      this.trackSfx(audio);
      audio.play().catch(() => {});
      return true;
    } catch (error) {
      return false;
    }
  },

  isBlockedHorseAppear(key, options = {}) {
    const src = String(options.src || options.path || '').replace(/\\/g, '/').toLowerCase();
    const registered = this.sfx && key ? this.sfx[key] : null;
    const optional = this.optionalSfx && key ? this.optionalSfx[key] : null;
    const registeredSrc = registered && registered.src ? String(registered.src).replace(/\\/g, '/').toLowerCase() : '';
    const optionalSrc = optional && optional.src ? String(optional.src).replace(/\\/g, '/').toLowerCase() : '';
    const isHorseAppear = key === 'horseAppear' ||
      src.includes('assets/enemies/horse/appear.mp3') ||
      registeredSrc.includes('assets/enemies/horse/appear.mp3') ||
      optionalSrc.includes('assets/enemies/horse/appear.mp3');
    return isHorseAppear && this.enemyAppearType !== 'horse';
  },

  stopHorseAppearSfx() {
    this.activeSfx = (this.activeSfx || []).filter((audio) => {
      const src = audio && audio.src ? String(audio.src).replace(/\\/g, '/').toLowerCase() : '';
      if (!src.includes('assets/enemies/horse/appear.mp3')) return true;
      try {
        audio.pause();
        audio.currentTime = 0;
      } catch (error) {}
      return false;
    });
  },

  allMusicTracks() {
    return Object.values(this.music || {}).filter(Boolean);
  },

  silenceOtherMusic(except) {
    for (const audio of this.allMusicTracks()) {
      if (!audio || audio === except) continue;
      try {
        audio.pause();
        audio.currentTime = 0;
      } catch (error) {}
    }
  },

  isMusicPausedByGame() {
    return !!(this.musicPauseReasons && this.musicPauseReasons.size > 0);
  },

  pauseCurrentMusicForReason() {
    this.silenceOtherMusic(this.currentMusic || null);
    if (!this.currentMusic) return;
    try {
      if (!this.currentMusic.paused) this.currentMusic.pause();
    } catch (error) {}
    this.musicActuallyPlaying = false;
  },

  setMusicPauseReason(reason, paused) {
    if (!reason) return;
    if (!this.musicPauseReasons) this.musicPauseReasons = new Set();
    const hadPause = this.musicPauseReasons.size > 0;
    if (paused) this.musicPauseReasons.add(reason);
    else this.musicPauseReasons.delete(reason);

    const hasPause = this.musicPauseReasons.size > 0;
    if (hasPause) {
      this.pauseCurrentMusicForReason();
    } else if (hadPause && this.currentMusicKey && this.isMusicOn()) {
      this.playMusic(this.currentMusicKey, false, true);
    }
  },

  playSyntheticSfx(key, volume = 1, options = {}) {
    if (!this.isSfxOn()) return;
    const presets = {
      menuMove: { start: 540, end: 880, duration: 0.095, gain: 0.18, type: 'square' },
      menuSelect: { start: 660, end: 1040, duration: 0.13, gain: 0.22, type: 'triangle' },
      menuBack: { start: 430, end: 260, duration: 0.13, gain: 0.18, type: 'triangle' },
      waveStart: { start: 360, end: 720, duration: 0.18, gain: 0.18, type: 'sawtooth' },
      waveClear: { start: 520, end: 980, duration: 0.2, gain: 0.2, type: 'triangle' },
      bossAppear: { start: 120, end: 220, duration: 0.28, gain: 0.22, type: 'sawtooth' }
    };
    const preset = presets[key];
    if (!preset) return;
    const context = this.ensureAudioContext();
    if (!context) return;
    if (context.state === 'suspended') context.resume().catch(() => {});

    const now = context.currentTime;
    const rate = Math.max(0.5, Math.min(2, options.playbackRate || options.rate || 1));
    const gain = context.createGain();
    const osc = context.createOscillator();

    osc.type = preset.type;
    osc.frequency.setValueAtTime(preset.start * rate, now);
    osc.frequency.exponentialRampToValueAtTime(Math.max(1, preset.end * rate), now + preset.duration * 0.62);

    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(this.getSfxVolume(volume) * preset.gain, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + preset.duration);

    osc.connect(gain);
    gain.connect(context.destination);
    osc.start(now);
    osc.stop(now + preset.duration + 0.01);
  },

  playMusic(key, forceRestart = false, retryIfBlocked = false) {
    if (!key) return;
    const next = this.music[key];
    if (!next || (next.dataset && next.dataset.failed === 'true')) return;
    const previous = this.currentMusic;
    const isSameTrack = previous === next;
    this.currentMusicKey = key;

    if (this.isMusicPausedByGame()) {
      if (forceRestart) {
        try { next.currentTime = 0; } catch (error) {}
      }
      this.pauseCurrentMusicForReason();
      return;
    }

    if (isSameTrack && !forceRestart) {
      next.volume = this.getMusicVolume();
      if (!next.paused && this.musicActuallyPlaying) return;
    }

    if (!isSameTrack || forceRestart) {
      this.silenceOtherMusic(null);
      this.currentMusic = next;
      if (forceRestart) next.currentTime = 0;
    }

    if (retryIfBlocked && next.paused) {
      next.currentTime = next.currentTime || 0;
    }

    next.volume = this.getMusicVolume();
    const playToken = (this.musicPlayToken || 0) + 1;
    this.musicPlayToken = playToken;
    next.play()
      .then(() => {
        if (this.musicPlayToken !== playToken || this.currentMusic !== next) {
          try { next.pause(); next.currentTime = 0; } catch (error) {}
          return;
        }
        this.musicActuallyPlaying = true;
        this.silenceOtherMusic(next);
      })
      .catch(() => {
        this.musicActuallyPlaying = false;
      });
  },

  stopMusic() {
    if (this.currentMusic) {
      try {
        this.currentMusic.pause();
        this.currentMusic.currentTime = 0;
      } catch (error) {}
    }
    this.currentMusic = null;
    this.currentMusicKey = null;
    this.musicPlayToken = (this.musicPlayToken || 0) + 1;
    this.musicActuallyPlaying = false;
    this.silenceOtherMusic(null);
  },

  pauseAllAudio() {
    const paused = (this.pausedAudio || []).filter(audio => audio && !audio.ended);
    const candidates = [
      this.currentMusic,
      ...this.activeSfx.filter(item => item && !item.ended),
      ...this.externalAudio.keys()
    ];

    for (const audio of candidates) {
      if (!audio || audio.ended || paused.includes(audio)) continue;
      if (audio.paused) continue;
      try {
        audio.pause();
        paused.push(audio);
      } catch (error) {}
    }

    this.pausedAudio = paused;
    this.musicActuallyPlaying = false;
  },

  resumePausedAudio() {
    const paused = this.pausedAudio || [];
    this.pausedAudio = [];
    for (const context of this.audioContexts || []) {
      try {
        if (context.state === 'suspended') context.resume();
      } catch (error) {}
    }
    if (this.audioContext) {
      try {
        if (this.audioContext.state === 'suspended') this.audioContext.resume();
      } catch (error) {}
    }
    for (const audio of paused) {
      if (!audio || audio.ended) continue;
      try {
        if (this.externalAudio.has(audio) && !this.canResumeExternalAudio(audio)) continue;
        if (audio === this.currentMusic) audio.volume = this.getMusicVolume();
        audio.play()
          .then(() => {
            if (audio === this.currentMusic) this.musicActuallyPlaying = true;
          })
          .catch(() => {});
      } catch (error) {}
    }
  },

  refreshSettings() {
    if (this.isMusicPausedByGame()) {
      this.pauseCurrentMusicForReason();
      return;
    }

    if (this.currentMusic) {
      this.currentMusic.volume = this.getMusicVolume();
      if (this.currentMusic.paused && this.currentMusicKey) this.playMusic(this.currentMusicKey, false, true);
      this.silenceOtherMusic(this.currentMusic);
      return;
    }

    if (this.currentMusicKey) this.playMusic(this.currentMusicKey, false, true);
  }
};

if (typeof document !== 'undefined' && !AudioManager.windowPauseListenersInstalled) {
  document.addEventListener('visibilitychange', () => {
    AudioManager.setMusicPauseReason('hidden-tab', document.visibilityState !== 'visible');
    if (document.hidden) AudioManager.pauseAllAudio();
  });

  window.addEventListener('blur', () => {
    AudioManager.setMusicPauseReason('window-blur', true);
    AudioManager.pauseAllAudio();
  });

  window.addEventListener('focus', () => {
    AudioManager.setMusicPauseReason('window-blur', false);
  });

  const stopForExit = () => AudioManager.stopAllAudio();
  window.addEventListener('pagehide', stopForExit);
  window.addEventListener('beforeunload', stopForExit);

  AudioManager.windowPauseListenersInstalled = true;
}



/* ===== src/player.js ===== */
class Player {
  constructor(heroKey, images) {
    const hero = GAME_CONFIG.heroes[heroKey];
    this.heroKey = heroKey;
    this.name = hero.name;
    this.maxHp = hero.hp;
    this.hp = hero.hp;
    this.speed = hero.speed;
    this.damage = hero.damage;
    this.scale = hero.scale || GAME_CONFIG.playerScale;
    this.abilities = hero.abilities || {};
    this.reviveUsed = false;
    this.images = images;

    this.x = 220;
    this.y = 620;
    this.facing = 1;
    this.state = 'idle';

    this.walkCycle = [0, 1, 2, 1];
    this.walkIndex = 1;
    this.walkFrame = 1;
    this.walkTimer = 0;

    this.comboStep = 0;
    this.comboTimer = 0;
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.hitStunTimer = 0;
    this.hurtTimer = 0;
    this.invulnerableTimer = 0;
    this.flash = 0;
    this.knockdownTimer = 0;
    this.knockdownFacing = 1;
    this.standUpFacing = 1;
    this.pinnedBy = null;
    this.reviveTextTimer = 0;
    this.reviveText = '';
  }

  update(dt, scene) {
    if (this.reviveTextTimer > 0) this.reviveTextTimer = Math.max(0, this.reviveTextTimer - dt);
    if (this.invulnerableTimer > 0) this.invulnerableTimer = Math.max(0, this.invulnerableTimer - dt);
    if (this.flash > 0) this.flash = Math.max(0, this.flash - dt);

    if (this.state === 'hurt') {
      this.hurtTimer = Math.max(0, (this.hurtTimer || 0) - dt);
      this.x = Math.max(70, Math.min(GAME_CONFIG.width - 70, this.x));
      this.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, this.y));
      if (this.hurtTimer <= 0) {
        this.hurtTimer = 0;
        this.state = 'idle';
      }
      return;
    }

    if (this.state === 'knockdown') {
      this.knockdownTimer -= dt;
      if (this.knockdownTimer <= 0) this.releaseFromPin();
      return;
    }

    if (this.state === 'pinned') {
      this.knockdownTimer -= dt;
      if (this.knockdownTimer <= 0) this.releaseFromPin();
      return;
    }

    if (this.comboTimer > 0) this.comboTimer -= dt;
    else this.comboStep = 0;

    if (Input.consume('space')) this.startAttack();

    if (this.state === 'attack') {
      if (typeof Responsive !== 'undefined' && Responsive.isTouchDevice) {
        this.updateMovement(dt, false);
      }
      this.updateAttack(dt, scene);
      return;
    }

    this.updateMovement(dt, true);
  }

  updateMovement(dt, updateState) {
    let dx = 0;
    let dy = 0;
    if (Input.pressed('a') || Input.pressed('arrowleft')) dx -= 1;
    if (Input.pressed('d') || Input.pressed('arrowright')) dx += 1;
    if (Input.pressed('w') || Input.pressed('arrowup')) dy -= 1;
    if (Input.pressed('s') || Input.pressed('arrowdown')) dy += 1;

    const moving = dx !== 0 || dy !== 0;
    if (moving) {
      const len = Math.hypot(dx, dy);
      dx /= len;
      dy /= len;
      this.x += dx * this.speed;
      this.y += dy * this.speed * GAME_CONFIG.ySpeedMultiplier;
      if (dx !== 0) this.facing = Math.sign(dx);

      if (updateState) {
        if (Input.consume('a') || Input.consume('d') || Input.consume('w') || Input.consume('s') ||
            Input.consume('arrowleft') || Input.consume('arrowright') || Input.consume('arrowup') || Input.consume('arrowdown')) {
          this.nextWalkFrame();
          this.walkTimer = 0;
        }

        this.walkTimer += dt;
        if (this.walkTimer >= GAME_CONFIG.walkFrameMs) {
          this.walkTimer -= GAME_CONFIG.walkFrameMs;
          this.nextWalkFrame();
        }
        this.state = 'walk';
      }
    } else if (updateState) {
      this.state = 'idle';
      this.walkTimer = 0;
    }

    this.x = Math.max(70, Math.min(GAME_CONFIG.width - 70, this.x));
    this.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, this.y));
  }

  receiveDamage(amount, options = {}) {
    if (this.hp <= 0) return false;
    if (this.invulnerableTimer > 0 && !options.ignoreInvulnerability) return false;
    const wasAlive = this.hp > 0;
    const facingBeforeHit = this.facing || 1;

    const source = options.source || 'melee';
    let damageAmount = Math.max(0, amount || 0);
    if (source === 'ranged' && Number.isFinite(this.abilities.rangedDamageMultiplier)) {
      damageAmount *= Math.max(0, this.abilities.rangedDamageMultiplier);
    } else if (source === 'ranged' && this.abilities.rangedImmune) {
      AudioManager.playSfx('menuMove', 0.45, { playbackRate: 0.72 });
      return false;
    }

    this.hp = Math.max(0, this.hp - damageAmount);

    if (options.knockbackX) {
      const knockbackMultiplier = source === 'melee' ? 2.1 : 1;
      this.x += options.knockbackX * knockbackMultiplier;
      this.x = Math.max(70, Math.min(GAME_CONFIG.width - 70, this.x));
    }

    if (this.hp <= 0 && this.tryRevive()) return true;

    if (this.hp > 0 && options.knockdownMs) {
      this.knockDown(options.knockdownMs, {
        force: options.forceKnockdown,
        facing: options.knockdownFacing || (options.knockbackX ? -Math.sign(options.knockbackX) : this.facing),
        standUpFacing: options.standUpFacing || facingBeforeHit
      });
    } else if (this.hp > 0 && this.state !== 'pinned' && this.state !== 'knockdown') {
      this.startHitStun(options.hitStunMs, options.invulnerableMs);
    }

    if (wasAlive && this.hp > 0 && this.state !== 'knockdown' && this.state !== 'pinned') {
      this.state = 'hurt';
      this.hurtTimer = Math.max(0, options.hurtFreezeMs || GAME_CONFIG.playerHurtFreezeMs || 280);
      this.attackTimer = 0;
      this.attackHasHit = false;
      this.comboStep = 0;
      this.comboTimer = 0;

      const hitKey = this.heroKey + 'Hit';
      if (AudioManager.isUsableSfxKey && AudioManager.isUsableSfxKey(hitKey)) {
        AudioManager.playSfx(hitKey, 0.92, { startAt: 0.01 });
      }
    }

    return true;
  }

  startHitStun(durationMs, invulnerableMs) {
    const stunMs = Math.max(0, durationMs == null ? GAME_CONFIG.playerHitStunMs : Number(durationMs) || 0);
    const guardMs = Math.max(stunMs, invulnerableMs == null ? GAME_CONFIG.playerInvulnerableMs : Number(invulnerableMs) || 0);

    this.hitStunTimer = stunMs;
    this.invulnerableTimer = guardMs;
    this.flash = Math.max(this.flash || 0, Math.min(220, guardMs));
    this.state = stunMs > 0 ? 'hurt' : 'idle';
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.comboStep = 0;
    this.comboTimer = 0;
    this.walkTimer = 0;
  }

  tryRevive() {
    if (!this.abilities.reviveOnce || this.reviveUsed) return false;
    this.reviveUsed = true;
    const restoredHp = Math.max(1, Math.round(this.maxHp * 0.5));
    this.hp = restoredHp;
    this.state = 'knockdown';
    this.hitStunTimer = 0;
    this.hurtTimer = 0;
    this.invulnerableTimer = Math.max(GAME_CONFIG.playerInvulnerableMs, GAME_CONFIG.playerReviveKnockdownMs || 950);
    this.flash = this.invulnerableTimer;
    this.knockdownTimer = GAME_CONFIG.playerReviveKnockdownMs || 950;
    this.pinnedBy = null;
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.comboStep = 0;
    this.comboTimer = 0;
    this.reviveText = '+' + restoredHp + ' HP';
    this.reviveTextTimer = GAME_CONFIG.playerReviveTextMs || 1250;
    AudioManager.playSfx('waveClear', 0.75, { playbackRate: 1.12 });
    return true;
  }

  canBeKnockedDown() {
    return !this.abilities.noKnockdown;
  }

  startAttack() {
    if (this.state === 'attack' || this.state === 'hurt' || this.state === 'knockdown' || this.state === 'pinned') return;

    this.comboStep += 1;
    if (this.comboStep > 3) this.comboStep = 1;

    this.playAttackSwingSound();
    this.comboTimer = GAME_CONFIG.comboResetMs;
    this.state = 'attack';
    this.attackTimer = 0;
    this.attackHasHit = false;
  }

  playAttackSwingSound() {
    AudioManager.playSfx('punch', 0.42, { playbackRate: 1.12, startAt: 0.01 });
  }

  playComboHitSound() {
    const key = this.comboStep === 3 ? 'punch3' : this.comboStep === 2 ? 'punch2' : 'punch1';
    const hasCustomSound = AudioManager.sfx && AudioManager.sfx[key];
    AudioManager.playSfx(hasCustomSound ? key : 'hit', this.comboStep === 3 ? 0.98 : 0.88, {
      playbackRate: this.comboStep === 3 ? 1.12 : 1.16,
      startAt: 0.018
    });
  }

  updateAttack(dt, scene) {
    this.attackTimer += dt;
    const data = this.getAttackData();

    if (!this.attackHasHit && this.attackTimer >= data.activeStart && this.attackTimer <= data.activeEnd) {
      if (scene.tryCollectPickup && scene.tryCollectPickup(this)) {
        this.attackHasHit = true;
        scene.hitStop = Math.max(scene.hitStop || 0, 20);
        return;
      }

      const hitbox = this.getHitbox();
      for (const enemy of scene.enemies) {
        if (!enemy.alive) continue;
        // Projectiles are hazards, not punchable enemies.
        if (enemy.enemyType === 'gundosFireball') continue;
        if (enemy.enemyType === 'sucker' && (enemy.state === 'windup' || enemy.state === 'slide') && this.canCounterSlide(enemy)) {
          this.attackHasHit = true;
          enemy.interruptSlide(this);
          scene.hitStop = GAME_CONFIG.playerHitStopMs;
          break;
        }
        if (enemy.enemyType === 'zetnik' && enemy.gundosMinion && !enemy.redirectedToBoss) {
          const target = enemy.getHurtbox();
          const pad = 34;
          const expandedTarget = {
            x: target.x - pad,
            y: target.y - pad,
            w: target.w + pad * 2,
            h: target.h + pad * 2
          };
          if (Combat.canMeleeHit(this, enemy, {
            attackBox: hitbox,
            targetBox: expandedTarget,
            laneTolerance: GAME_CONFIG.yHitTolerance
          })) {
            this.attackHasHit = true;
            if (enemy.gundosGuarding && enemy.holdGundosGuard) {
              enemy.holdGundosGuard(this);
            } else {
              enemy.redirectToGundos(this);
            }
            scene.hitStop = GAME_CONFIG.playerHitStopMs;
            break;
          }
        }
        if (Combat.canMeleeHit(this, enemy, {
          attackBox: hitbox,
          targetBox: enemy.getHurtbox(),
          laneTolerance: GAME_CONFIG.yHitTolerance
        })) {
          this.attackHasHit = true;
          this.playComboHitSound();
          const wasAlive = enemy.alive;
          enemy.takeHit(data.damage, this.facing, data.knockback);
          if (wasAlive && !enemy.alive && scene.maybeDropPickup) scene.maybeDropPickup(enemy, { source: 'player' });
          if (enemy.enemyType === 'bastard') {
            if (enemy.grantGundosMedicHeal) {
              enemy.grantGundosMedicHeal(this, scene);
            } else {
              const healAmount = 5;
              this.hp = Math.min(this.maxHp, this.hp + healAmount);
              if (scene.addGundosFloatText) scene.addGundosFloatText('+5 HP', enemy.x, enemy.y - 150, '#6dff8d');
            }
            AudioManager.playSfx('enemyDown', 0.75, { playbackRate: 1.08, startAt: 0.01 });
          }
          scene.hitStop = GAME_CONFIG.playerHitStopMs;
          break;
        }
      }
    }

    if (this.attackTimer >= data.duration) {
      this.state = 'idle';
      this.attackTimer = 0;
      this.attackHasHit = false;
    }
  }

  getAttackData() {
    if (this.comboStep === 1) return { duration: 170, activeStart: 25, activeEnd: 120, damage: this.damage, knockback: 24, range: 46 };
    if (this.comboStep === 2) return { duration: 190, activeStart: 30, activeEnd: 135, damage: this.damage + 5, knockback: 32, range: 52 };
    return { duration: 240, activeStart: 34, activeEnd: 160, damage: this.damage + 14, knockback: 68, range: 62 };
  }

  getHitbox() {
    const data = this.getAttackData();
    return {
      x: this.x + (this.facing === 1 ? 22 : -22 - data.range),
      y: this.y - 118,
      w: data.range,
      h: 40
    };
  }

  getBodyBox() {
    const hero = GAME_CONFIG.heroes[this.heroKey] || {};
    const knockdownBody = (this.state === 'knockdown' || this.state === 'pinned') ? hero.knockdownBody : null;
    if (knockdownBody) {
      const w = Math.max(1, knockdownBody.w || 160);
      const h = Math.max(1, knockdownBody.h || 44);
      const bodyOffset = Math.max(0, knockdownBody.bodyOffsetX || 0);
      const bottomOffset = Math.max(0, knockdownBody.bottomOffsetY || 0);
      const localLeft = this.facing === 1 ? bodyOffset : -bodyOffset - w;
      return {
        x: this.x + localLeft,
        y: this.y - h - bottomOffset,
        w,
        h
      };
    }
    return { x: this.x - 34, y: this.y - 132, w: 68, h: 132 };
  }

  canCounterSlide(enemy) {
    if (this.state !== 'attack' || !enemy) return false;
    if (Combat.laneCanConnect && !Combat.laneCanConnect(this, enemy, {
      laneTolerance: (GAME_CONFIG.enemies.sucker && GAME_CONFIG.enemies.sucker.counterRangeY) || GAME_CONFIG.yHitTolerance
    })) return false;

    const data = this.getAttackData();
    if (this.attackTimer < data.activeStart || this.attackTimer > data.activeEnd) return false;

    const config = (GAME_CONFIG.enemies && GAME_CONFIG.enemies.sucker) || {};
    const rangeY = config.counterRangeY || GAME_CONFIG.enemyAttackRangeY || 58;
    const counterZone = this.getHitbox();
    const forgiveness = config.counterForgiveness == null ? 2 : config.counterForgiveness;
    const targets = [];
    if (enemy.state === 'slide' && typeof enemy.getSlideHitbox === 'function') targets.push(enemy.getSlideHitbox());
    if (enemy.state === 'slide' && typeof enemy.getHurtbox === 'function') targets.push(enemy.getHurtbox());

    return targets.some(target => target && Combat.canMeleeHit(this, enemy, {
      attackBox: counterZone,
      targetBox: {
      x: target.x - forgiveness,
      y: target.y - forgiveness,
      w: target.w + forgiveness * 2,
      h: target.h + forgiveness * 2
      },
      laneTolerance: rangeY
    }));
  }

  knockDown(durationMs = 900, options = {}) {
    if (!options.force && !this.canBeKnockedDown()) return false;
    if (this.state === 'pinned') return false;
    AudioManager.playSfx('playerDown', 0.85);
    this.state = 'knockdown';
    this.knockdownFacing = options.facing ? Math.sign(options.facing) || this.facing || 1 : this.facing || 1;
    this.standUpFacing = options.standUpFacing ? Math.sign(options.standUpFacing) || this.facing || 1 : this.facing || 1;
    this.facing = this.knockdownFacing;
    this.hitStunTimer = 0;
    this.hurtTimer = 0;
    this.invulnerableTimer = GAME_CONFIG.playerInvulnerableMs;
    this.flash = GAME_CONFIG.playerInvulnerableMs;
    this.knockdownTimer = durationMs;
    this.pinnedBy = null;
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.comboStep = 0;
    return true;
  }

  pinBy(enemy, durationMs, options = {}) {
    if (!options.force && !this.canBeKnockedDown()) return false;
    AudioManager.playSfx('playerDown', 0.85);
    this.state = 'pinned';
    if (options.standUpFacing) this.standUpFacing = Math.sign(options.standUpFacing) || this.facing || 1;
    this.hitStunTimer = 0;
    this.hurtTimer = 0;
    this.invulnerableTimer = 0;
    this.flash = 0;
    this.knockdownTimer = durationMs;
    this.pinnedBy = enemy;
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.comboStep = 0;
    return true;
  }

  releaseFromPin() {
    if (this.standUpFacing) this.facing = Math.sign(this.standUpFacing) || this.facing || 1;
    this.state = 'idle';
    this.hitStunTimer = 0;
    this.hurtTimer = 0;
    this.knockdownTimer = 0;
    this.pinnedBy = null;
  }

  nextWalkFrame() {
    this.walkIndex = (this.walkIndex + 1) % this.walkCycle.length;
    this.walkFrame = this.walkCycle[this.walkIndex];
  }

  getHeroImages() {
    return (this.images.heroes && this.images.heroes[this.heroKey]) || this.images.heroes.boris;
  }

  getImage() {
    const heroImages = this.getHeroImages();
    if (this.state === 'knockdown' || this.state === 'pinned') return heroImages.knockdown || heroImages.idle;
    if (this.state === 'hurt') return heroImages.hurt || heroImages.idle;
    if (this.state === 'attack') return heroImages.punch[this.comboStep - 1] || heroImages.punch[0] || heroImages.idle;
    if (this.state === 'walk') return heroImages.walk[this.walkFrame] || heroImages.idle;
    return heroImages.idle;
  }

  draw(ctx, debug = false) {
    const img = this.getImage();
    if (!img) return;
    const hero = GAME_CONFIG.heroes[this.heroKey] || {};
    const scale = hero.scale || this.scale || GAME_CONFIG.playerScale;
    const w = img.width * scale;
    const h = img.height * scale;
    const isKnockdown = this.state === 'knockdown' || this.state === 'pinned';
    const knockdownDraw = isKnockdown ? hero.knockdownDraw : null;
    const drawFacing = knockdownDraw && knockdownDraw.facingMultiplier ? this.facing * knockdownDraw.facingMultiplier : this.facing;
    const drawX = knockdownDraw ? -(knockdownDraw.alphaCenterX || img.width / 2) * scale : -w / 2;
    const drawY = knockdownDraw ? -(knockdownDraw.alphaBottomY || img.height) * scale : -h;

    ctx.save();
    ctx.translate(this.x, this.y);
    if (drawFacing === -1) ctx.scale(-1, 1);
    if (this.flash > 0 && Math.floor(this.flash / 55) % 2 === 0) ctx.globalAlpha = 0.48;
    ctx.drawImage(img, drawX, drawY, w, h);
    ctx.restore();

    if (this.reviveTextTimer > 0) {
      const ratio = Math.max(0, Math.min(1, this.reviveTextTimer / (GAME_CONFIG.playerReviveTextMs || 1250)));
      const rise = (1 - ratio) * 32;
      ctx.save();
      ctx.globalAlpha = Math.min(1, ratio * 1.5);
      ctx.font = 'bold 24px Arial';
      ctx.textAlign = 'center';
      ctx.lineWidth = 5;
      ctx.strokeStyle = 'rgba(0,0,0,0.85)';
      ctx.fillStyle = '#76ff8f';
      ctx.strokeText(this.reviveText, this.x, this.y - h - 22 - rise);
      ctx.fillText(this.reviveText, this.x, this.y - h - 22 - rise);
      ctx.restore();
    }

    if (debug && this.state === 'attack') {
      const hb = this.getHitbox();
      ctx.strokeStyle = 'lime';
      ctx.lineWidth = 2;
      ctx.strokeRect(hb.x, hb.y, hb.w, hb.h);

      const counterRangeX = (GAME_CONFIG.enemies.sucker && GAME_CONFIG.enemies.sucker.counterRangeX) || 120;
      const counterRangeY = (GAME_CONFIG.enemies.sucker && GAME_CONFIG.enemies.sucker.counterRangeY) || GAME_CONFIG.enemyAttackRangeY;
      ctx.strokeStyle = 'rgba(0,255,255,0.75)';
      ctx.strokeRect(this.x + (this.facing === 1 ? 0 : -counterRangeX), this.y - counterRangeY, counterRangeX, counterRangeY * 2);
    }

    if (debug) {
      ctx.strokeStyle = 'rgba(80,255,120,0.85)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(this.x - 36, this.y);
      ctx.lineTo(this.x + 36, this.y);
      ctx.stroke();
    }
  }
}



/* ===== src/enemy.js ===== */
class DogRegimeEnemy {
  constructor(x, y, images, id = 0, enemyType = 'dogRegime') {
    this.id = id;
    this.images = images;
    this.enemyType = enemyType;
    this.x = x;
    this.y = y;
    this.facing = -1;

    this.applyTuning(true);

    this.state = 'walk';
    this.intent = 'approach';
    this.walkFrame = 0;
    this.walkTimer = 0;

    this.attackTimer = 0;
    this.attackHasHit = false;
    this.cooldown = 160 + id * 120;
    this.decisionTimer = 80 + id * 60;
    this.strafeDirection = id % 2 === 0 ? -1 : 1;
    this.retreatTimer = 0;

    this.hitStun = 0;
    this.flash = 0;
    this.deadTimer = 0;
    this.alive = true;
    this.remove = false;

    this.halfHpKnockdownDone = false;
    this.knockdownTimer = 0;
    this.knockdownDuration = 900;
  }

  applyTuning(resetHp = false) {
    const config = GAME_CONFIG.enemies[this.enemyType] || GAME_CONFIG.enemies.dogRegime;
    this.speed = config.speed;
    this.damage = config.damage;
    this.maxHp = config.hp;
    this.scale = config.scale || GAME_CONFIG.enemyScale;
    this.attackScale = config.attackScale || 1;
    this.minDistanceX = config.minDistanceX || 42;
    this.preferredDistanceX = config.preferredDistanceX || 76;
    this.tooFarDistanceX = config.tooFarDistanceX || Math.max(this.preferredDistanceX + 40, 140);
    this.attackRangeX = config.attackRangeX || GAME_CONFIG.enemyAttackRangeX;
    this.attackRangeY = config.attackRangeY || GAME_CONFIG.enemyAttackRangeY;
    this.attackMinDistanceX = config.attackMinDistanceX == null ? 28 : config.attackMinDistanceX;
    this.attackMaxDistanceX = config.attackMaxDistanceX || this.attackRangeX;
    this.maxAttackers = config.maxAttackers || 1;
    this.decisionMinMs = config.decisionMinMs || 160;
    this.decisionMaxMs = config.decisionMaxMs || 420;
    this.strafeChance = config.strafeChance == null ? 0.32 : config.strafeChance;
    this.retreatChance = config.retreatChance == null ? 0.16 : config.retreatChance;
    this.attackChance = config.attackChance == null ? 0.82 : config.attackChance;
    this.closeRetreatChance = config.closeRetreatChance == null ? 0.42 : config.closeRetreatChance;
    this.playerAttackFearDistance = config.playerAttackFearDistance || 86;
    this.postAttackRetreatMs = config.postAttackRetreatMs || 220;
    this.attackCooldownMinMs = config.attackCooldownMinMs || 300;
    this.attackCooldownMaxMs = config.attackCooldownMaxMs || 520;
    this.backstabChance = config.backstabChance == null ? 0.78 : config.backstabChance;
    this.slotSpacingX = config.slotSpacingX || 46;
    this.slotSpacingY = config.slotSpacingY || 32;
    this.flankDistanceX = config.flankDistanceX || 105;
    this.pressureDistanceX = config.pressureDistanceX || 150;
    this.bodyRadiusX = config.bodyRadiusX || GAME_CONFIG.enemyBodyRadiusX || 42;
    this.bodyRadiusY = config.bodyRadiusY || GAME_CONFIG.enemyBodyRadiusY || 20;
    this.attackSlotRadiusX = config.attackSlotRadiusX || GAME_CONFIG.enemyAttackSlotRadiusX || 46;
    this.attackSlotRadiusY = config.attackSlotRadiusY || GAME_CONFIG.enemyAttackSlotRadiusY || 24;
    this.hp = resetHp ? this.maxHp : Math.min(this.hp, this.maxHp);
  }

  clampToScreen() {
    const margin = this.alive ? (GAME_CONFIG.enemyOffscreenMargin || 180) : 45;
    this.x = Math.max(-margin, Math.min(GAME_CONFIG.width + margin, this.x));
    this.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, this.y));
  }

  isOffscreenX(padding = 45) {
    return this.x < padding || this.x > GAME_CONFIG.width - padding;
  }

  update(dt, scene) {
    if (this.remove) return;

    if (!this.alive) {
      this.deadTimer += dt;
      if (this.deadTimer > GAME_CONFIG.enemyDeathFadeMs) this.remove = true;
      this.clampToScreen();
      return;
    }

    if (this.flash > 0) this.flash -= dt;

    if (this.state === 'knockdown') {
      this.knockdownTimer -= dt;
      this.clampToScreen();
      if (this.knockdownTimer <= 0) {
        this.state = 'walk';
        this.intent = 'flank';
        this.hitStun = 0;
        this.cooldown = 260 + Math.random() * 220;
      }
      return;
    }

    if (this.hitStun > 0) {
      this.hitStun -= dt;
      this.clampToScreen();
      return;
    }

    this.applyTuning(false);
    if (this.cooldown > 0) this.cooldown -= dt;
    if (this.decisionTimer > 0) this.decisionTimer -= dt;
    if (this.retreatTimer > 0) this.retreatTimer -= dt;

    const player = scene.player;
    const dx = player.x - this.x;
    const absX = Math.abs(dx);
    const absY = Math.abs(player.y - this.y);
    this.facing = dx >= 0 ? 1 : -1;

    if (this.isOffscreenX()) {
      this.intent = 'approach';
      this.retreatTimer = 0;
      this.decisionTimer = Math.min(this.decisionTimer, 80);
    }

    if (this.state === 'attack') {
      this.updateAttack(dt, scene);
      this.clampToScreen();
      return;
    }

    const activeAttackers = this.countActiveAttackers(scene);
    const hasAttackPermission = activeAttackers < this.maxAttackers || this.intent === 'attack';
    const inAttackRange = this.isInAttackRange(player);
    const clearAttackPosition = this.hasClearAttackPosition(scene);
    const frontThreat = this.isPlayerAttackThreat(player);
    const goodAttackDistance = absX >= this.attackMinDistanceX && absX <= this.attackMaxDistanceX;
    const alignedForAttack = absY <= this.attackRangeY;
    const canAttackNow = hasAttackPermission && clearAttackPosition && goodAttackDistance && alignedForAttack && inAttackRange && !frontThreat;

    if (canAttackNow && this.cooldown <= 0) {
      this.state = 'attack';
      this.intent = 'attack';
      this.attackFacing = this.facing || 1;
      if (this.enemyType === 'horse') {
        this.attackLockX = this.x;
        this.attackLockY = this.y;
        this.attackPositionLocked = true;
      }
      this.attackTimer = 0;
      this.attackHasHit = false;
      this.clampToScreen();
      return;
    }

    if (this.decisionTimer <= 0) this.chooseIntent(scene, canAttackNow, inAttackRange, frontThreat, absX);

    if (frontThreat && this.intent !== 'backstab') {
      this.intent = Math.random() < 0.58 ? 'strafe' : 'retreat';
      this.retreatTimer = 120 + Math.random() * 120;
      this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
      this.decisionTimer = 110 + Math.random() * 120;
    } else if (absX < this.attackMinDistanceX && this.intent !== 'retreat') {
      this.intent = Math.random() < this.closeRetreatChance ? 'retreat' : 'strafe';
      this.retreatTimer = 130 + Math.random() * 130;
      this.decisionTimer = 100 + Math.random() * 130;
    }

    this.moveWithSpacing(dt, scene, canAttackNow);
    this.clampToScreen();
  }

  chooseIntent(scene, canAttackNow, inAttackRange, frontThreat = false, absX = Infinity) {
    const player = scene.player;
    const roll = Math.random();
    const playerBusy = this.isPlayerBusy(scene);

    if (playerBusy && roll < this.backstabChance && !this.isBehindPlayer(player)) {
      this.intent = 'backstab';
    } else if (frontThreat) {
      this.intent = roll < 0.58 ? 'strafe' : 'retreat';
      this.retreatTimer = 120 + Math.random() * 140;
      this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
    } else if (canAttackNow && this.cooldown <= 0 && inAttackRange) {
      this.intent = 'attack';
    } else if (absX < this.attackMinDistanceX) {
      this.intent = roll < this.closeRetreatChance ? 'retreat' : 'strafe';
      this.retreatTimer = 120 + Math.random() * 150;
      this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
    } else if (absX > this.tooFarDistanceX) {
      this.intent = 'approach';
    } else if (roll < this.attackChance && this.cooldown <= 0) {
      this.intent = 'attack';
    } else if (roll < this.attackChance + this.strafeChance) {
      this.intent = 'strafe';
      this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
    } else {
      this.intent = 'hold';
    }

    this.decisionTimer = this.decisionMinMs + Math.random() * Math.max(1, this.decisionMaxMs - this.decisionMinMs);
  }

  moveWithSpacing(dt, scene, canAttackNow) {
    const player = scene.player;
    if (this.isOffscreenX()) {
      const returnX = this.x < 45 ? 1 : -1;
      const returnY = Math.abs(player.y - this.y) > 10 ? Math.sign(player.y - this.y) : 0;
      this.applyMovement(returnX, returnY, dt);
      return;
    }

    const slot = this.getCombatSlot(scene, player);
    const target = this.getSlotTarget(player, slot, canAttackNow);
    const dxToPlayer = player.x - this.x;
    const absX = Math.abs(dxToPlayer);
    const dyToTarget = target.y - this.y;
    const frontThreat = this.isPlayerAttackThreat(player);
    let moveX = 0;
    let moveY = 0;

    if (frontThreat && this.intent !== 'backstab') {
      moveX = -Math.sign(dxToPlayer || this.facing);
      moveY = Math.abs(dyToTarget) > 8 ? Math.sign(dyToTarget) : this.strafeDirection;
    } else if (this.intent === 'retreat' && this.retreatTimer > 0) {
      const retreatTargetX = player.x - Math.sign(dxToPlayer || this.facing) * this.preferredDistanceX;
      moveX = Math.sign(retreatTargetX - this.x);
      if (Math.abs(dyToTarget) > 8) moveY = Math.sign(dyToTarget);
      else if (Math.random() < 0.25) moveY = this.strafeDirection;
    } else if (this.intent === 'backstab') {
      const backSide = -(player.facing || 1);
      const backTargetX = player.x + backSide * this.preferredDistanceX;
      moveX = Math.abs(this.x - backTargetX) > 10 ? Math.sign(backTargetX - this.x) : 0;
      moveY = Math.abs(dyToTarget) > 8 ? Math.sign(dyToTarget) : 0;
      if (this.isBehindPlayer(player) && Math.abs(this.x - backTargetX) <= 16) this.intent = 'attack';
    } else if (absX < this.attackMinDistanceX) {
      moveX = -Math.sign(dxToPlayer || this.facing);
      moveY = Math.abs(dyToTarget) > 8 ? Math.sign(dyToTarget) : this.strafeDirection;
    } else if (this.intent === 'attack') {
      if (Math.abs(player.y - this.y) > this.attackRangeY * 0.65) moveY = Math.sign(player.y - this.y);
      if (absX < this.attackMinDistanceX) moveX = -Math.sign(dxToPlayer || this.facing);
      else if (absX > this.attackMaxDistanceX) moveX = Math.sign(dxToPlayer);
      else moveX = 0;
    } else if (this.intent === 'strafe') {
      if (Math.abs(dyToTarget) > 20) moveY = Math.sign(dyToTarget);
      else moveY = this.strafeDirection;
      if (absX > this.tooFarDistanceX) moveX = Math.sign(target.x - this.x);
    } else if (this.intent === 'flank') {
      if (Math.abs(dyToTarget) > 8) moveY = Math.sign(dyToTarget);
      if (Math.abs(this.x - target.x) > 18) moveX = Math.sign(target.x - this.x);
    } else if (absX > this.tooFarDistanceX || Math.abs(this.x - target.x) > 24) {
      moveX = Math.sign(target.x - this.x);
      if (Math.abs(dyToTarget) > 12) moveY = Math.sign(dyToTarget);
    } else if (Math.abs(dyToTarget) > 12) {
      moveY = Math.sign(dyToTarget);
    }

    this.applyMovement(moveX, moveY, dt);
  }

  getCombatSlot(scene, player) {
    const aliveEnemies = (scene.enemies || [])
      .filter(enemy => enemy && enemy.alive && enemy.blocksWaveClear !== false && enemy.state !== 'jump' && enemy.state !== 'crash')
      .sort((a, b) => a.id - b.id);
    const index = Math.max(0, aliveEnemies.indexOf(this));
    const playerFacing = player ? player.facing || 1 : 1;
    const backSide = -playerFacing;
    const frontSide = playerFacing;
    const playerBusy = this.isPlayerBusy(scene);
    const backFirst = playerBusy && Math.random() < this.backstabChance;
    const slots = backFirst ? [
      { side: backSide, y: 0, role: 'attacker' },
      { side: frontSide, y: 0, role: 'attacker' },
      { side: backSide, y: -1, role: 'flank' },
      { side: backSide, y: 1, role: 'flank' },
      { side: frontSide, y: 1, role: 'frontFlank' },
      { side: frontSide, y: -1, role: 'frontFlank' },
      { side: backSide, y: -2, role: 'outer' },
      { side: frontSide, y: 2, role: 'outer' }
    ] : [
      { side: frontSide, y: 0, role: 'attacker' },
      { side: backSide, y: 0, role: 'attacker' },
      { side: backSide, y: -1, role: 'flank' },
      { side: frontSide, y: 1, role: 'frontFlank' },
      { side: backSide, y: 1, role: 'flank' },
      { side: frontSide, y: -1, role: 'frontFlank' },
      { side: frontSide, y: 2, role: 'outer' },
      { side: backSide, y: -2, role: 'outer' }
    ];
    return slots[index % slots.length];
  }

  getSlotTarget(player, slot, canAttackNow) {
    let distanceX = this.preferredDistanceX;
    if (slot.role === 'back' || slot.role === 'flank' || slot.role === 'outer') distanceX = this.flankDistanceX;
    if (!canAttackNow && slot.role !== 'attacker') distanceX = Math.min(this.flankDistanceX, this.pressureDistanceX);

    const x = player.x + slot.side * distanceX + slot.side * Math.abs(slot.y) * this.slotSpacingX;
    const y = player.y + slot.y * this.slotSpacingY;
    return {
      x: Math.max(70, Math.min(GAME_CONFIG.width - 70, x)),
      y: Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, y))
    };
  }

  getWalkFrameCount() {
    const enemyImages = this.getEnemyImages();
    return Math.max(1, (enemyImages.walk || []).filter(Boolean).length);
  }

  applyMovement(moveX, moveY, dt) {
    if (moveX === 0 && moveY === 0) return;
    if (this.isOffscreenX()) moveX = this.x < 45 ? 1 : -1;
    const len = Math.hypot(moveX, moveY);
    moveX /= len;
    moveY /= len;
    this.x += moveX * this.speed;
    this.y += moveY * this.speed * GAME_CONFIG.ySpeedMultiplier;
    this.clampToScreen();

    this.walkTimer += dt;
    if (this.walkTimer >= GAME_CONFIG.enemyWalkFrameMs) {
      this.walkTimer -= GAME_CONFIG.enemyWalkFrameMs;
      this.walkFrame = (this.walkFrame + 1) % this.getWalkFrameCount();
    }
  }

  countActiveAttackers(scene) {
    return (scene.enemies || []).filter(enemy =>
      enemy !== this &&
      enemy.alive &&
      enemy.blocksWaveClear !== false &&
      (enemy.state === 'attack' || enemy.intent === 'attack')
    ).length;
  }

  isPlayerBusy(scene) {
    const player = scene.player;
    return (scene.enemies || []).some(enemy =>
      enemy !== this &&
      enemy &&
      enemy.alive &&
      !enemy.remove &&
      Math.abs(enemy.x - player.x) < this.attackRangeX + 18 &&
      Math.abs(enemy.y - player.y) < this.attackRangeY + 18 &&
      (enemy.state === 'attack' || enemy.intent === 'attack' || enemy.intent === 'hold')
    );
  }

  isBehindPlayer(player) {
    if (!player) return false;
    const playerFacing = player.facing || 1;
    return Math.sign(this.x - player.x || playerFacing) === -playerFacing;
  }

  isPlayerAttackThreat(player) {
    if (!player || player.state !== 'attack') return false;
    if (this.isBehindPlayer(player)) return false;
    const sideFromPlayer = Math.sign(this.x - player.x || 1);
    const playerFacing = player.facing || 1;
    const absX = Math.abs(this.x - player.x);
    return sideFromPlayer === playerFacing && absX < this.playerAttackFearDistance &&
      Combat.laneCanConnect(player, this, { laneTolerance: this.attackRangeY * 1.25 });
  }

  hasClearAttackPosition(scene) {
    const player = scene.player;
    if (!player || !this.isInAttackRange(player)) return true;

    const mySide = Math.sign(this.x - player.x || this.facing || 1);
    for (const other of scene.enemies || []) {
      if (!other || other === this || !other.alive || other.remove) continue;
      if (other.blocksWaveClear === false) continue;
      if (scene.enemyHasPhysicalPresence && !scene.enemyHasPhysicalPresence(other)) continue;
      if (!scene.enemyHasPhysicalPresence && (other.state === 'jump' || other.state === 'crash' || other.state === 'knockdown')) continue;

      const otherSide = Math.sign(other.x - player.x || other.facing || 1);
      if (otherSide !== mySide) continue;

      const otherRadiusX = other.attackSlotRadiusX || other.bodyRadiusX || GAME_CONFIG.enemyAttackSlotRadiusX || 46;
      const otherRadiusY = other.attackSlotRadiusY || other.bodyRadiusY || GAME_CONFIG.enemyAttackSlotRadiusY || 24;
      const nearThisEnemy = Math.abs(other.x - this.x) < this.attackSlotRadiusX + otherRadiusX &&
        Math.abs(other.y - this.y) < this.attackSlotRadiusY + otherRadiusY;
      const nearPlayerLine = Math.abs(other.y - player.y) < this.attackRangeY;
      const otherIsCommitted = other.state === 'attack' || other.intent === 'attack' || Math.abs(other.x - player.x) < this.attackRangeX * 0.72;

      if (nearThisEnemy && nearPlayerLine && otherIsCommitted) return false;
    }

    return true;
  }

  isInAttackRange(player) {
    return this.canClubReachPlayer(player, true);
  }

  getClubReachBox() {
    const minX = Math.max(0, this.attackMinDistanceX || 0);
    const maxX = Math.max(minX + 1, this.attackRangeX || GAME_CONFIG.enemyAttackRangeX || 76);
    const rangeY = Math.max(1, this.attackRangeY || GAME_CONFIG.enemyAttackRangeY || 36);
    return {
      x: this.facing === 1 ? this.x + minX : this.x - maxX,
      y: this.y - rangeY,
      w: maxX - minX,
      h: rangeY * 2
    };
  }

  canClubReachPlayer(player, anticipation = false) {
    if (!player) return false;
    if (typeof Combat !== 'undefined' && Combat.actorsSameLane && !Combat.actorsSameLane(this, player)) return false;
    const forwardDistance = (player.x - this.x) * (this.facing || 1);
    const yDistance = Math.abs(player.y - this.y);
    const padX = anticipation ? 6 : 0;
    const padY = anticipation ? 4 : 0;
    const minX = Math.max(0, (this.attackMinDistanceX || 0) - padX);
    const maxX = Math.max(minX + 1, (this.attackRangeX || GAME_CONFIG.enemyAttackRangeX || 76) + padX);
    const maxY = (this.attackRangeY || GAME_CONFIG.enemyAttackRangeY || 36) + padY;
    return forwardDistance >= minX && forwardDistance <= maxX && yDistance <= maxY;
  }

  updateAttack(dt, scene) {
    this.attackTimer += dt;
    const activeStart = GAME_CONFIG.enemyWindupMs;
    const activeEnd = GAME_CONFIG.enemyWindupMs + GAME_CONFIG.enemyActiveMs;

    if (!this.attackHasHit && this.attackTimer >= activeStart && this.attackTimer <= activeEnd) {
      const player = scene.player;
      if (this.canClubReachPlayer(player, false)) {
        const hit = player.receiveDamage(this.damage, {
          source: 'melee',
          knockbackX: this.facing * 18
        });
        if (hit) scene.hitStop = 42;
      }
      this.attackHasHit = true;
    }

    if (this.attackTimer >= GAME_CONFIG.enemyWindupMs + GAME_CONFIG.enemyActiveMs + GAME_CONFIG.enemyRecoveryMs) {
      this.state = 'walk';
      this.intent = Math.random() < 0.58 ? 'retreat' : 'strafe';
      this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
      this.retreatTimer = this.postAttackRetreatMs;
      this.cooldown = this.attackCooldownMinMs + Math.random() * Math.max(1, this.attackCooldownMaxMs - this.attackCooldownMinMs);
      this.attackTimer = 0;
      this.attackHasHit = false;
      this.attackFacing = null;
      this.attackPositionLocked = false;
      this.attackLockX = null;
      this.attackLockY = null;
    }
  }

  startKnockdown(direction, knockback = 82) {
    this.x += direction * knockback;
    this.clampToScreen();
    this.state = 'knockdown';
    this.knockdownTimer = this.knockdownDuration;
    this.hitStun = 0;
    this.flash = 160;
    this.intent = 'flank';
    this.retreatTimer = 0;
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.attackFacing = null;
    this.attackPositionLocked = false;
    this.attackLockX = null;
    this.attackLockY = null;
    this.facing = -direction;
  }

  takeHit(damage, direction, knockback) {
    if (!this.alive) return;
    const oldHp = this.hp;
    this.hp -= damage;
    this.x += direction * knockback;
    this.clampToScreen();
    this.hitStun = GAME_CONFIG.enemyHitStunMs;
    this.flash = 120;
    this.state = 'hit';
    this.intent = 'flank';
    this.retreatTimer = 0;
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.attackFacing = null;
    this.attackPositionLocked = false;
    this.attackLockX = null;
    this.attackLockY = null;

    if (this.hp <= 0) {
      this.alive = false;
      this.state = 'dead';
      this.deadTimer = 0;
      this.clampToScreen();
      return;
    }

    if (!this.halfHpKnockdownDone && oldHp > this.maxHp * 0.5 && this.hp <= this.maxHp * 0.5) {
      this.halfHpKnockdownDone = true;
      this.startKnockdown(direction, Math.max(72, knockback + 42));
    }
  }

  getGroundBodyBox() {
    return {
      x: this.x - this.bodyRadiusX,
      y: this.y - this.bodyRadiusY,
      w: this.bodyRadiusX * 2,
      h: this.bodyRadiusY * 2
    };
  }

  getHurtbox() {
    return { x: this.x - 38, y: this.y - 140, w: 76, h: 140 };
  }

  getAttackBox() {
    return { x: this.x + (this.facing === 1 ? 30 : -108), y: this.y - 112, w: 108, h: 50 };
  }

  getEnemyImages() {
    const enemies = this.images.enemies || {};
    return enemies[this.enemyType] || enemies.dogRegime || {
      idle: this.images.dogIdle,
      walk: this.images.dogWalk,
      attack: this.images.dogAttack,
      dead: this.images.dogDead
    };
  }

  getImage() {
    const enemyImages = this.getEnemyImages();
    if (!this.alive) return enemyImages.dead;
    if (this.state === 'knockdown') return enemyImages.dead || enemyImages.idle;
    if (this.state === 'attack') {
      const attack = enemyImages.attack || [];
      const windupMs = this.attackWindupMs || GAME_CONFIG.enemyWindupMs;
      return this.attackTimer < windupMs ? attack[0] || enemyImages.idle : attack[1] || attack[0] || enemyImages.idle;
    }
    if (this.hitStun > 0) return enemyImages.idle;
    return enemyImages.walk[this.walkFrame] || enemyImages.idle;
  }

  draw(ctx, debug = false) {
    const img = this.getImage();
    if (!img) return;
    const baseScale = this.scale || GAME_CONFIG.enemyScale;
    const frameScale = typeof this.getFrameScale === 'function'
      ? this.getFrameScale(img, baseScale)
      : (this.state === 'attack' ? baseScale * (this.attackScale || 1) : baseScale);
    const w = img.width * frameScale;
    const h = img.height * frameScale;
    const baseH = img.height * baseScale;
    const drawOffsetY = typeof this.getDrawOffsetY === 'function' ? this.getDrawOffsetY(img, frameScale) : 0;
    const drawOffsetX = typeof this.getDrawOffsetX === 'function' ? this.getDrawOffsetX(img, frameScale) : 0;

    let alpha = 1;
    if (!this.alive) alpha = Math.max(0, 1 - this.deadTimer / GAME_CONFIG.enemyDeathFadeMs);
    else if (this.flash > 0) alpha = 0.55;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(this.x, this.y);
    if (this.facing === -1) ctx.scale(-1, 1);
    ctx.drawImage(img, -w / 2 + drawOffsetX, -h + drawOffsetY, w, h);
    ctx.restore();
    ctx.globalAlpha = 1;

    if (this.alive) {
      const bx = this.x - 38;
      const by = this.y - baseH - 12;
      ctx.fillStyle = '#220000';
      ctx.fillRect(bx, by, 76, 6);
      ctx.fillStyle = this.hp > this.maxHp * 0.6 ? 'lime' : this.hp > this.maxHp * 0.28 ? 'yellow' : 'red';
      ctx.fillRect(bx, by, 76 * Math.max(0, this.hp / this.maxHp), 6);
    }

    if (debug && this.alive) {
      const hb = this.getHurtbox();
      ctx.strokeStyle = 'rgba(255,0,0,0.85)';
      ctx.lineWidth = 2;
      ctx.strokeRect(hb.x, hb.y, hb.w, hb.h);
      const gb = this.getGroundBodyBox();
      ctx.strokeStyle = 'rgba(0,180,255,0.75)';
      ctx.strokeRect(gb.x, gb.y, gb.w, gb.h);
      ctx.strokeStyle = 'rgba(80,255,120,0.85)';
      ctx.beginPath();
      ctx.moveTo(this.x - 36, this.y);
      ctx.lineTo(this.x + 36, this.y);
      ctx.stroke();
      if (this.state === 'attack') {
        const ab = this.getAttackBox();
        ctx.strokeStyle = 'orange';
        ctx.strokeRect(ab.x, ab.y, ab.w, ab.h);
      }
    }
  }
}



/* ===== src/zetnikEnemy.js ===== */
class ZetnikEnemy extends DogRegimeEnemy {
  constructor(x, y, images, id = 0) {
    super(x, y, images, id, 'zetnik');
    this.state = 'walk';
    this.intent = 'approach';
    this.jumpTimer = 0;
    this.prepareTimer = 0;
    this.jumpStartX = x;
    this.jumpStartY = y;
    this.jumpTargetX = x;
    this.jumpTargetY = y;
    this.lockedTargetX = x;
    this.lockedTargetY = y;
    this.jumpHasHit = false;
    this.crashTimer = 0;
    this.gundosMinion = false;
    this.gundosBoss = null;
    this.redirectedToBoss = false;
    this.gundosDirection = -1;
    this.gundosSpeed = 21.75;
    this.gundosHitPlayer = false;
    this.gundosGuarding = false;
    this.gundosGuardX = x;
    this.gundosGuardY = y;
    this.chargeLaneY = this.pickChargeLane(y);
    this.y = this.chargeLaneY;
    this.chargeDirection = x < GAME_CONFIG.width / 2 ? 1 : -1;
    this.hasEnteredPlayfield = this.isInsidePlayfield();
  }

  pickChargeLane(fallbackY) {
    const lanes = [
      GAME_CONFIG.laneTop + 46,
      (GAME_CONFIG.laneTop + GAME_CONFIG.laneBottom) / 2,
      GAME_CONFIG.laneBottom - 34
    ];
    return lanes[Math.floor(Math.random() * lanes.length)] || fallbackY;
  }

  applyTuning(resetHp = false) {
    super.applyTuning(resetHp);
    const config = GAME_CONFIG.enemies.zetnik || {};
    this.jumpTriggerDistanceX = config.jumpTriggerDistanceX || 260;
    this.jumpMinDistanceX = config.jumpMinDistanceX || 160;
    this.jumpRangeX = config.jumpRangeX || 360;
    this.jumpRangeY = config.jumpRangeY || 42;
    this.jumpDurationMs = config.jumpDurationMs || 540;
    this.jumpArcHeight = config.jumpArcHeight || 82;
    this.prepareDurationMs = config.prepareDurationMs || 1250;
    this.crashDurationMs = config.crashDurationMs || 520;
    this.selfRemoveDelayMs = config.selfRemoveDelayMs || 720;
    this.knockdownMs = config.knockdownMs || 680;
    this.crashKnockbackX = config.crashKnockbackX || 76;
    this.hitWindowX = config.hitWindowX || 54;
    this.hitWindowY = config.hitWindowY || 30;
  }

  update(dt, scene) {
    if (this.remove) return;

    if (this.gundosMinion) {
      this.updateGundosMinion(dt, scene);
      return;
    }

    if (!this.alive) {
      this.deadTimer += dt;
      if (this.deadTimer > this.selfRemoveDelayMs) this.remove = true;
      this.clampToScreen();
      return;
    }

    if (this.flash > 0) this.flash -= dt;

    if (this.state === 'crash') {
      this.updateCrash(dt);
      return;
    }

    if (this.hitStun > 0) {
      this.hitStun -= dt;
      this.clampToScreen();
      return;
    }

    this.applyTuning(false);
    const player = scene.player;
    const dx = player.x - this.x;
    const dy = player.y - this.y;
    const absX = Math.abs(dx);
    const absY = Math.abs(dy);
    if (!Number.isFinite(this.chargeLaneY)) this.chargeLaneY = this.y;
    if (!Number.isFinite(this.chargeDirection) || this.chargeDirection === 0) {
      this.chargeDirection = this.x < GAME_CONFIG.width / 2 ? 1 : -1;
    }
    this.facing = this.chargeDirection >= 0 ? 1 : -1;

    this.updateCharge(dt, scene, player, dx, dy, absX, absY);
    if (!this.remove) this.clampToScreen();
  }

  updateCharge(dt, scene, player, dx, dy, absX, absY) {
    this.state = 'charge';
    this.intent = 'attack';

    let moveX = this.chargeDirection || this.facing || 1;
    let laneDelta = (this.chargeLaneY || this.y) - this.y;
    let dtScale = Math.max(0.65, Math.min(1.55, dt / 16.67));
    this.x += Math.sign(moveX || 1) * this.speed * dtScale;
    if (Math.abs(laneDelta) > 2) {
      this.y += Math.sign(laneDelta) * Math.min(Math.abs(laneDelta), this.speed * GAME_CONFIG.ySpeedMultiplier * dtScale);
    }
    this.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, this.chargeLaneY || this.y));
    this.facing = moveX >= 0 ? 1 : -1;
    this.walkTimer += dt;
    if (this.walkTimer >= GAME_CONFIG.enemyWalkFrameMs) {
      this.walkTimer -= GAME_CONFIG.enemyWalkFrameMs;
      this.walkFrame = (this.walkFrame + 1) % this.getWalkFrameCount();
    }

    this.markEnteredPlayfield();
    if (this.hasEnteredPlayfield && this.isPastEscapeMargin()) {
      this.escapeOffscreen();
      return;
    }

    if (player.state === 'knockdown' || player.state === 'pinned') return;
    if (!Combat.canProjectileHit(this, player, {
      attackBox: this.getHurtbox(),
      laneY: this.y,
      laneTolerance: GAME_CONFIG.yHitTolerance
    })) return;

    const hit = player.receiveDamage(this.damage, {
      source: 'ranged',
      knockbackX: 0,
      knockdownMs: this.knockdownMs,
      forceKnockdown: true,
      knockdownFacing: this.getImpactFallFacing(player)
    });
    if (hit) {
      this.jumpTargetY = this.y;
      this.finishCrash(scene);
    }
  }

  shouldStartJump(player, absX, absY) {
    if (player.state === 'knockdown' || player.state === 'pinned') return false;
    if (absY > this.jumpRangeY) return false;
    return absX >= this.jumpMinDistanceX && absX <= this.jumpTriggerDistanceX;
  }

  approachCarefully(dt, player, dx, dy, absX, absY) {
    let moveX = 0;
    let moveY = 0;

    if (absY > 10) moveY = Math.sign(dy);

    if (absX > this.jumpTriggerDistanceX) {
      moveX = Math.sign(dx);
    } else if (absX < this.jumpMinDistanceX) {
      moveX = -Math.sign(dx || this.facing);
    }

    this.applyMovement(moveX, moveY, dt);
  }

  startPrepareJump(player) {
    this.state = 'prepareJump';
    this.intent = 'attack';
    this.prepareTimer = 0;
    this.jumpHasHit = false;
    this.facing = player.x >= this.x ? 1 : -1;
    this.lockedTargetX = player.x;
    this.lockedTargetY = player.y;
    this.laneY = player.y;
    this.attackTimer = 0;
    this.attackHasHit = false;
    AudioManager.playSfx('zetnikPreparing', 0.9, { playbackRate: 1, startAt: 0.01 });
  }

  setupGundosMinion(boss) {
    this.gundosMinion = true;
    this.gundosBoss = boss || null;
    this.redirectedToBoss = false;
    this.gundosDirection = -1;
    this.gundosSpeed = 18 + Math.random() * 3.375;
    this.gundosHitPlayer = false;
    this.gundosGuarding = false;
    this.blocksWaveClear = false;
    this.state = 'gundosCharge';
    this.intent = 'gundosCharge';
    this.facing = -1;
    this.hp = Math.max(this.hp, 1);
    this.alive = true;
    this.remove = false;
    this.flash = 0;
    this.hitStun = 0;
    this.walkTimer = 0;
  }

  setupGundosGuard(boss, x, y) {
    this.setupGundosMinion(boss);
    this.gundosGuarding = true;
    this.gundosGuardX = x;
    this.gundosGuardY = y;
    this.x = x;
    this.y = y;
    this.gundosSpeed = 0;
    this.state = 'gundosGuard';
    this.intent = 'gundosGuard';
    this.walkFrame = 0;
  }

  updateGundosMinion(dt, scene) {
    if (!this.alive) {
      this.updateCrash(dt);
      return;
    }

    if (this.flash > 0) this.flash -= dt;
    const frameScale = Math.max(0.65, Math.min(1.55, dt / 16.67));
    if (this.gundosGuarding && !this.redirectedToBoss) {
      this.x += (this.gundosGuardX - this.x) * 0.18;
      this.y += (this.gundosGuardY - this.y) * 0.18;
      this.facing = -1;
      if (scene && scene.player && Combat.overlap(this.getHurtbox(), scene.player.getBodyBox())) {
        scene.player.x = Math.min(scene.player.x, this.x - 86);
      }
      return;
    }

    const player = scene && scene.player;
    this.x += this.gundosDirection * this.gundosSpeed * frameScale;
    this.facing = this.gundosDirection >= 0 ? 1 : -1;
    this.walkTimer += dt;
    if (this.walkTimer >= GAME_CONFIG.enemyWalkFrameMs) {
      this.walkTimer -= GAME_CONFIG.enemyWalkFrameMs;
      this.walkFrame = (this.walkFrame + 1) % 3;
    }

    if (!this.redirectedToBoss && player && !this.gundosHitPlayer &&
        Combat.canProjectileHit(this, player, {
          attackBox: this.getHurtbox(),
          laneY: this.y,
          laneTolerance: GAME_CONFIG.yHitTolerance
        })) {
      this.gundosHitPlayer = true;
      player.receiveDamage(this.damage, {
        source: 'ranged',
        knockbackX: 0,
        knockdownMs: this.knockdownMs,
        forceKnockdown: true,
        knockdownFacing: this.getImpactFallFacing(player)
      });
      this.finishGundosCrash(scene);
      return;
    }

    const boss = this.gundosBoss || this.findGundosBoss(scene);
    if (this.redirectedToBoss && boss && boss.alive && Combat.overlap(this.getHurtbox(), boss.getHurtbox())) {
      if (boss.receiveZetnikHit) boss.receiveZetnikHit(this, scene);
      this.finishGundosCrash(scene);
      return;
    }

    this.markEnteredPlayfield();
    if (this.hasEnteredPlayfield && this.isPastEscapeMargin()) {
      this.escapeOffscreen();
    }
  }

  findGundosBoss(scene) {
    if (!scene || !scene.enemies) return null;
    return scene.enemies.find(enemy => enemy && enemy.enemyType === 'gundos' && enemy.alive) || null;
  }

  redirectToGundos(player) {
    const boss = this.gundosBoss;
    this.redirectedToBoss = true;
    this.gundosGuarding = false;
    this.gundosDirection = boss && boss.x < this.x ? -1 : 1;
    this.gundosSpeed = Math.max(this.gundosSpeed, 30.75);
    this.facing = this.gundosDirection >= 0 ? 1 : -1;
    this.flash = 260;
    this.state = 'gundosRedirected';
    if (player && player.playComboHitSound) player.playComboHitSound();
    AudioManager.playSfx('zetnikPreparing', 0.75, { playbackRate: 1.25, startAt: 0.01 });
  }

  holdGundosGuard(player) {
    this.flash = 220;
    if (player && player.playComboHitSound) player.playComboHitSound();
  }

  releaseGundosGuard() {
    if (!this.gundosGuarding) return;
    this.gundosGuarding = false;
    this.gundosSpeed = 18 + Math.random() * 3.375;
    this.state = 'gundosCharge';
    this.intent = 'gundosCharge';
  }

  finishGundosCrash(scene) {
    this.alive = false;
    this.state = 'crash';
    this.crashTimer = 0;
    this.deadTimer = 0;
    this.hp = 0;
    this.flash = 180;
    AudioManager.playSfx('zetnikCrash', 0.95, { playbackRate: 1, startAt: 0.01 });
    if (scene) scene.hitStop = Math.max(scene.hitStop || 0, 45);
  }

  updatePrepareJump(dt, scene) {
    this.prepareTimer += dt;
    if (this.prepareTimer >= this.prepareDurationMs) {
      this.startJump();
    }
  }

  startJump() {
    this.state = 'jump';
    this.intent = 'attack';
    this.jumpTimer = 0;
    this.jumpHasHit = false;
    this.jumpStartX = this.x;
    this.jumpStartY = this.y;
    this.jumpTargetX = this.lockedTargetX + this.facing * 52;
    this.jumpTargetY = this.lockedTargetY;
    this.attackTimer = 0;
    this.attackHasHit = false;
    AudioManager.playSfx('punch', 0.55, { playbackRate: 1.05, startAt: 0.01 });
  }

  updateJump(dt, scene) {
    this.jumpTimer += dt;
    const progress = Math.min(1, this.jumpTimer / this.jumpDurationMs);
    const eased = progress < 0.5
      ? 2 * progress * progress
      : 1 - Math.pow(-2 * progress + 2, 2) / 2;
    const arc = Math.sin(progress * Math.PI) * this.jumpArcHeight;

    this.x = this.jumpStartX + (this.jumpTargetX - this.jumpStartX) * eased;
    this.y = this.jumpStartY + (this.jumpTargetY - this.jumpStartY) * eased - arc;

    if (!this.jumpHasHit && progress >= 0.32) {
      this.tryHitPlayer(scene);
    }

    if (progress >= 1) {
      this.finishCrash(scene);
    }
  }

  tryHitPlayer(scene) {
    const player = scene.player;
    if (player.state === 'knockdown' || player.state === 'pinned') return;

    const stayedNearLockedX = Math.abs(player.x - this.lockedTargetX) <= this.hitWindowX;
    const projectileOverlapsPlayer = Math.abs(player.x - this.x) <= this.hitWindowX;
    if (!stayedNearLockedX || !projectileOverlapsPlayer ||
        !Combat.canProjectileHit(this, player, {
          attackBox: this.getHurtbox(),
          laneY: this.lockedTargetY,
          laneTolerance: this.hitWindowY
        })) return;

    const hit = player.receiveDamage(this.damage, {
      source: 'ranged',
      knockbackX: 0,
      knockdownMs: this.knockdownMs,
      forceKnockdown: true,
      knockdownFacing: this.getImpactFallFacing(player)
    });

    this.jumpHasHit = true;
    if (hit) {
      scene.hitStop = 70;
      if (player.canBeKnockedDown && player.canBeKnockedDown()) {
        AudioManager.playSfx('playerDown', 0.85, { playbackRate: 1.08, startAt: 0.01 });
      }
    }
  }

  getImpactFallFacing(player) {
    if (player && Number.isFinite(player.x) && Number.isFinite(this.x) && Math.abs(player.x - this.x) > 1) {
      return Math.sign(player.x - this.x);
    }
    if (Number.isFinite(this.gundosDirection) && this.gundosDirection !== 0) return Math.sign(this.gundosDirection);
    return this.facing || 1;
  }

  finishCrash(scene) {
    this.y = this.jumpTargetY;
    this.laneY = this.y;
    this.state = 'crash';
    this.crashTimer = 0;
    this.alive = false;
    this.deadTimer = 0;
    this.flash = 180;
    this.hp = 0;
    AudioManager.playSfx('zetnikCrash', 1, { playbackRate: 1, startAt: 0.01 });
    if (scene && scene.maybeDropPickup) scene.maybeDropPickup(this);
    scene.hitStop = Math.max(scene.hitStop || 0, 55);
  }

  escapeOffscreen() {
    this.alive = false;
    this.hp = 0;
    this.remove = true;
    this.blocksWaveClear = false;
    this.pickupDropped = true;
    this.state = 'escaped';
    this.hitStun = 0;
    this.deadTimer = 0;
    this.flash = 0;
    this.gundosHitPlayer = true;
  }

  isPastEscapeMargin(margin = GAME_CONFIG.zetnikEscapeMargin == null ? (GAME_CONFIG.enemyOffscreenMargin || 180) : GAME_CONFIG.zetnikEscapeMargin) {
    return this.x < -margin || this.x > GAME_CONFIG.width + margin;
  }

  isInsidePlayfield(margin = 20) {
    return this.x >= -margin && this.x <= GAME_CONFIG.width + margin;
  }

  markEnteredPlayfield() {
    if (!this.hasEnteredPlayfield && this.isInsidePlayfield()) this.hasEnteredPlayfield = true;
  }

  updateCrash(dt) {
    this.crashTimer += dt;
    this.deadTimer += dt;
    if (this.deadTimer > this.selfRemoveDelayMs) this.remove = true;
  }

  takeHit(damage, direction, knockback) {
    if (this.gundosMinion) {
      if (this.gundosGuarding && !this.redirectedToBoss && this.alive) {
        this.holdGundosGuard();
      } else if (!this.redirectedToBoss && this.alive) {
        this.redirectToGundos();
      }
      return;
    }
    super.takeHit(damage, direction, knockback);
  }

  getHurtbox() {
    if (this.gundosMinion) {
      return { x: this.x - 58, y: this.y - 150, w: 116, h: 132 };
    }
    if (this.state === 'jump') {
      return { x: this.x - 44, y: this.y - 150, w: 88, h: 120 };
    }
    return super.getHurtbox();
  }

  getEnemyImages() {
    return (this.images.enemies && this.images.enemies.zetnik) || super.getEnemyImages();
  }

  getImage() {
    const enemyImages = this.getEnemyImages();
    if (!this.alive || this.state === 'crash') return enemyImages.crashed || enemyImages.dead || enemyImages.attack[0] || enemyImages.idle;
    if (this.gundosGuarding) return enemyImages.preparing || enemyImages.attack[0] || enemyImages.idle;
    if (this.gundosMinion) return this.redirectedToBoss
      ? (enemyImages.fly || enemyImages.preparing || enemyImages.attack[0] || enemyImages.idle)
      : (enemyImages.walk[this.walkFrame] || enemyImages.idle || enemyImages.preparing || enemyImages.attack[0]);
    if (this.hitStun > 0) return enemyImages.idle;
    return enemyImages.walk[this.walkFrame] || enemyImages.idle;
  }

  draw(ctx, debug = false) {
    const img = this.getImage();
    if (!img) return;
    const scale = this.scale || GAME_CONFIG.enemyScale;
    const w = img.width * scale;
    const h = img.height * scale;

    let alpha = 1;
    if (!this.alive) alpha = Math.max(0, 1 - this.deadTimer / this.selfRemoveDelayMs);
    else if (this.flash > 0) alpha = 0.55;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(this.x, this.y);
    if (this.facing === -1) ctx.scale(-1, 1);
    ctx.drawImage(img, -w / 2, -h, w, h);
    ctx.restore();
    ctx.globalAlpha = 1;

    if (debug && !this.remove) {
      const hb = this.getHurtbox();
      ctx.strokeStyle = this.state === 'prepareJump' ? 'rgba(255,255,0,0.95)' : 'rgba(255, 180, 0, 0.9)';
      ctx.lineWidth = 2;
      ctx.strokeRect(hb.x, hb.y, hb.w, hb.h);
    }
  }
}



/* ===== src/suckerEnemy.js ===== */
class SuckerEnemy extends DogRegimeEnemy {
  constructor(x, y, images, id = 0) {
    super(x, y, images, id, 'sucker');
    this.state = 'reposition';
    this.windupTimer = 0;
    this.slideDistance = 0;
    this.slideDirection = -1;
    this.slideY = y;
    this.recoveryTimer = 0;
    this.pinTimer = 0;
    this.biteTimer = 0;
    this.biteCount = 0;
    this.biteFrame = 0;
    this.hasPinnedPlayer = false;
    this.hitsSinceFastRetreat = 0;
    this.fastRetreatTimer = 0;
    this.fastRetreatDirection = -1;
    this.pinBiteBottomGaps = [378, 361];
  }

  applyTuning(resetHp = false) {
    const config = GAME_CONFIG.enemies.sucker;
    this.speed = config.speed;
    this.damage = config.damage;
    this.maxHp = config.hp;
    this.scale = config.scale || GAME_CONFIG.enemyScale;
    this.slideSpeed = config.slideSpeed;
    this.attackStartDistance = config.attackStartDistance || config.preferredDistance || 420;
    this.minDistance = config.minDistance;
    this.alignToleranceY = config.alignToleranceY;
    this.slideRange = config.slideRange;
    this.windupMs = config.windupMs;
    this.slideRecoveryMs = config.slideRecoveryMs;
    this.interruptedRecoveryMs = config.interruptedRecoveryMs || config.slideRecoveryMs || 900;
    this.fastRetreatSpeed = config.fastRetreatSpeed || Math.max(this.slideSpeed * 1.15, 12);
    this.fastRetreatMs = config.fastRetreatMs || 620;
    this.hitsBeforeFastRetreat = config.hitsBeforeFastRetreat || 2;
    this.pinDurationMs = config.pinDurationMs;
    this.pinEscapeMinBites = config.pinEscapeMinBites || 3;
    this.pinHoldMs = config.pinHoldMs || 120000;
    this.biteTickMs = config.biteTickMs;
    this.biteDamage = config.biteDamage;
    this.otherEnemyScatterDistance = config.otherEnemyScatterDistance;
    this.hp = resetHp ? this.maxHp : Math.min(this.hp, this.maxHp);
  }

  update(dt, scene) {
    if (this.remove) return;

    if (!this.alive) {
      this.deadTimer += dt;
      if (this.deadTimer > GAME_CONFIG.enemyDeathFadeMs) this.remove = true;
      return;
    }

    if (this.flash > 0) this.flash -= dt;

    if (this.hitStun > 0) {
      this.hitStun -= dt;
      return;
    }

    this.applyTuning(false);

    const player = scene.player;
    const dx = player.x - this.x;
    const dy = player.y - this.y;
    const absX = Math.abs(dx);
    const absY = Math.abs(dy);
    this.facing = dx >= 0 ? 1 : -1;

    if (this.state === 'windup') {
      this.updateWindup(dt, scene);
      return;
    }

    if (this.state === 'slide') {
      this.updateSlide(dt, scene);
      return;
    }

    if (this.state === 'interrupted') {
      this.updateInterrupted(dt);
      return;
    }

    if (this.state === 'fastRetreat') {
      this.updateFastRetreat(dt, scene);
      return;
    }

    if (this.state === 'pinBite') {
      this.updatePinBite(dt, scene);
      return;
    }

    if (this.state === 'recovery') {
      this.recoveryTimer -= dt;
      if (this.recoveryTimer <= 0) this.state = 'reposition';
      return;
    }

    let moveX = 0;
    let moveY = 0;

    if (absY > this.alignToleranceY) moveY = Math.sign(dy);
    if (absX < this.minDistance) moveX = -Math.sign(dx);
    else if (absX > this.attackStartDistance) moveX = Math.sign(dx);

    if (moveX !== 0 || moveY !== 0) {
      const len = Math.hypot(moveX, moveY);
      moveX /= len;
      moveY /= len;
      if (this.isOffscreenX && this.isOffscreenX()) moveX = this.x < 45 ? 1 : -1;
      this.x += moveX * this.speed;
      this.y += moveY * this.speed * GAME_CONFIG.ySpeedMultiplier;
      this.updateWalkFrame(dt);
    }

    this.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, this.y));

    const readyDistance = absX >= this.minDistance && absX <= this.attackStartDistance;
    const playerFree = player.state !== 'knockdown' && player.state !== 'pinned';
    if (absY <= this.alignToleranceY && readyDistance && playerFree) {
      this.state = 'windup';
      this.windupTimer = 0;
      this.slideDirection = this.facing;
      this.slideY = this.y;
    }
  }

  updateWalkFrame(dt) {
    this.walkTimer += dt;
    if (this.walkTimer >= GAME_CONFIG.enemyWalkFrameMs) {
      this.walkTimer -= GAME_CONFIG.enemyWalkFrameMs;
      this.walkFrame = 1 - this.walkFrame;
    }
  }

  updateWindup(dt, scene) {
    this.windupTimer += dt;
    const player = scene.player;
    this.facing = player.x >= this.x ? 1 : -1;
    this.slideDirection = this.facing;
    this.slideY = this.y;

    if (player.canCounterSlide(this)) {
      this.interruptSlide(player);
      scene.hitStop = GAME_CONFIG.playerHitStopMs;
      return;
    }

    if (this.windupTimer >= this.windupMs) {
      this.state = 'slide';
      this.slideDistance = 0;
      this.hasPinnedPlayer = false;
      this.y = this.slideY;
    }
  }

  updateSlide(dt, scene) {
    const step = this.slideSpeed * Math.max(1, dt / 16.67);
    this.x += this.slideDirection * step;
    this.y = this.slideY;
    this.slideDistance += Math.abs(step);
    this.facing = this.slideDirection;

    const player = scene.player;

    if (player.canCounterSlide(this)) {
      this.interruptSlide(player);
      scene.hitStop = GAME_CONFIG.playerHitStopMs;
      return;
    }

    if (player.state !== 'knockdown' && player.state !== 'pinned' &&
        Combat.canProjectileHit(this, player, {
          attackBox: this.getSlideHitbox(),
          laneY: this.slideY,
          laneTolerance: this.alignToleranceY || GAME_CONFIG.yHitTolerance
        })) {
      this.pinPlayer(scene);
      return;
    }

    const margin = GAME_CONFIG.enemyOffscreenMargin || 180;
    const leftExit = this.slideDirection < 0 && this.x < -margin;
    const rightExit = this.slideDirection > 0 && this.x > GAME_CONFIG.width + margin;
    if (this.slideDistance >= this.slideRange || leftExit || rightExit) {
      this.state = 'recovery';
      this.recoveryTimer = this.slideRecoveryMs;
    }
  }

  interruptSlide(player) {
    if (player && player.playComboHitSound) player.playComboHitSound();
    this.hp -= player.damage + 8;
    this.flash = 160;
    this.hitStun = this.interruptedRecoveryMs;
    this.state = 'interrupted';
    this.recoveryTimer = this.interruptedRecoveryMs;
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.x += player.facing * 90;
    if (this.hp <= 0) {
      this.alive = false;
      this.state = 'dead';
      this.deadTimer = 0;
      return;
    }
    this.registerFastRetreatHit(player.facing);
  }

  updateInterrupted(dt) {
    this.recoveryTimer -= dt;
    if (this.recoveryTimer <= 0 && this.alive) {
      this.state = 'reposition';
      this.hitStun = 0;
    }
  }

  registerFastRetreatHit(direction) {
    this.hitsSinceFastRetreat += 1;
    if (this.hitsSinceFastRetreat < this.hitsBeforeFastRetreat) return;
    this.startFastRetreat(direction);
  }

  startFastRetreat(direction) {
    this.hitsSinceFastRetreat = 0;
    this.fastRetreatDirection = direction || -this.facing || 1;
    this.fastRetreatTimer = this.fastRetreatMs;
    this.hitStun = 0;
    this.recoveryTimer = 0;
    this.state = 'fastRetreat';
    this.intent = 'retreat';
    this.attackTimer = 0;
    this.attackHasHit = false;
    this.facing = -this.fastRetreatDirection;
  }

  updateFastRetreat(dt, scene) {
    this.fastRetreatTimer -= dt;
    const player = scene && scene.player;
    const frameScale = Math.max(0.65, Math.min(1.75, dt / 16.67));
    this.x += this.fastRetreatDirection * this.fastRetreatSpeed * frameScale;
    if (player && Math.abs(player.y - this.y) > this.alignToleranceY * 0.6) {
      this.y += Math.sign(player.y - this.y) * this.speed * GAME_CONFIG.ySpeedMultiplier;
    }
    this.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, this.y));
    this.updateWalkFrame(dt);

    const margin = GAME_CONFIG.enemyOffscreenMargin || 180;
    if (this.fastRetreatTimer <= 0 || this.x < -margin || this.x > GAME_CONFIG.width + margin) {
      this.state = 'reposition';
      this.intent = 'approach';
      this.fastRetreatTimer = 0;
    }
  }

  pinPlayer(scene) {
    const player = scene.player;
    const hit = player.receiveDamage(this.damage, {
      source: 'ranged',
      knockbackX: 0,
      knockdownMs: 180,
      forceKnockdown: true,
      knockdownFacing: this.getImpactFallFacing(player)
    });

    if (!hit) {
      this.state = 'recovery';
      this.recoveryTimer = this.slideRecoveryMs;
      this.hasPinnedPlayer = false;
      return;
    }

    if (!player.pinBy(this, this.pinHoldMs, { force: true })) {
      this.state = 'recovery';
      this.recoveryTimer = this.slideRecoveryMs;
      this.hasPinnedPlayer = false;
      scene.hitStop = 35;
      return;
    }

    this.state = 'pinBite';
    this.pinScene = scene;
    this.pinTimer = 0;
    this.biteTimer = 0;
    this.biteCount = 0;
    this.biteFrame = 0;
    this.hasPinnedPlayer = true;
    if (scene) scene.suckerPinHintActive = true;
    this.alignToPinnedPlayer(player);
    this.scatterOtherEnemies(scene);
    scene.hitStop = 55;
  }

  updatePinBite(dt, scene) {
    const player = scene.player;
    if (player.pinnedBy !== this || player.state !== 'pinned') {
      this.releasePinnedPlayer(player);
      return;
    }

    this.pinTimer += dt;
    this.biteTimer += dt;

    this.alignToPinnedPlayer(player);

    if (this.biteTimer >= this.biteTickMs) {
      this.biteTimer -= this.biteTickMs;
      this.biteFrame = 1 - this.biteFrame;
      this.biteCount += 1;
      player.receiveDamage(this.biteDamage, { source: 'melee' });
    }

    if (player.hp <= 0) {
      this.releasePinnedPlayer(player);
      return;
    }

    if (this.canEscapePin() && Input.consume('space')) {
      if (player.playComboHitSound) player.playComboHitSound();
      scene.hitStop = Math.max(scene.hitStop || 0, 45);
      this.releasePinnedPlayer(player);
    }
  }

  canEscapePin() {
    return this.state === 'pinBite' && this.biteCount >= this.pinEscapeMinBites;
  }

  getImpactFallFacing(player) {
    if (player && Number.isFinite(player.x) && Number.isFinite(this.x) && Math.abs(player.x - this.x) > 1) {
      return Math.sign(player.x - this.x);
    }
    return this.slideDirection || this.facing || 1;
  }

  alignToPinnedPlayer(player) {
    if (!player) return;
    const body = player.getBodyBox ? player.getBodyBox() : null;
    const centerX = body ? body.x + body.w / 2 : player.x;
    const bottomY = body ? body.y + body.h : player.y;
    this.x = centerX;
    this.y = bottomY;
  }

  releasePinnedPlayer(player) {
    if (player && player.pinnedBy === this) player.releaseFromPin();
    const scene = this.pinScene || this.__scene;
    if (scene) scene.suckerPinHintActive = false;
    this.pinScene = null;
    this.state = 'recovery';
    this.recoveryTimer = this.slideRecoveryMs;
    this.hasPinnedPlayer = false;
    this.pinTimer = 0;
    this.biteTimer = 0;
  }

  scatterOtherEnemies(scene) {
    for (const enemy of scene.enemies || []) {
      if (enemy === this || !enemy.alive) continue;
      const direction = enemy.x < this.x ? -1 : 1;
      enemy.x += direction * this.otherEnemyScatterDistance;
      enemy.y += enemy.y < this.y ? -18 : 18;
      enemy.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, enemy.y));
    }
  }

  takeHit(damage, direction, knockback) {
    if (!this.alive) return;
    super.takeHit(damage, direction, knockback);
    if (this.alive) {
      this.registerFastRetreatHit(direction);
      if (this.state !== 'fastRetreat') {
        this.state = 'recovery';
        this.recoveryTimer = this.slideRecoveryMs;
      }
    }
  }

  getSlideHitbox() {
    return {
      x: this.x + (this.facing === 1 ? 8 : -88),
      y: this.slideY - 112,
      w: 88,
      h: 54
    };
  }

  getEnemyImages() {
    return this.images.enemies.sucker;
  }

  getImage() {
    const enemyImages = this.getEnemyImages();
    if (!this.alive) return enemyImages.dead;
    if (this.state === 'slide') return enemyImages.slide || enemyImages.attack[0];
    if (this.state === 'pinBite') return enemyImages.bite[this.biteFrame] || enemyImages.attack[0];
    if (this.state === 'windup') return enemyImages.idle;
    if (this.state === 'fastRetreat') return enemyImages.walk[this.walkFrame] || enemyImages.idle;
    if (this.state === 'interrupted') return enemyImages.dead || enemyImages.idle;
    if (this.hitStun > 0) return enemyImages.idle;
    return enemyImages.walk[this.walkFrame] || enemyImages.idle;
  }

  getDrawOffsetY(img, frameScale) {
    if (this.state !== 'pinBite') return 0;
    const bottomGap = this.pinBiteBottomGaps[this.biteFrame] || this.pinBiteBottomGaps[0] || 0;
    return bottomGap * frameScale;
  }

  draw(ctx, debug = false) {
    super.draw(ctx, debug);

    if (debug && this.alive && this.state === 'slide') {
      const hb = this.getSlideHitbox();
      ctx.strokeStyle = 'cyan';
      ctx.lineWidth = 2;
      ctx.strokeRect(hb.x, hb.y, hb.w, hb.h);
    }
  }
}



/* ===== src/bastardEnemy.js ===== */
class BastardEnemy {
  constructor(x, y, images, id = 0) {
    this.id = id;
    this.enemyType = 'bastard';
    this.images = images;
    this.x = x;
    this.y = y;
    this.facing = Math.random() < 0.5 ? -1 : 1;
    this.fallFacing = this.facing;

    this.applyTuning(true);

    this.state = 'wander';
    this.alive = true;
    this.remove = false;
    this.blocksWaveClear = false;

    this.walkFrame = id % 3;
    this.walkTimer = 0;
    this.decisionTimer = 250 + id * 120;
    this.fallenTimer = 0;
    this.moveX = this.facing;
    this.moveY = Math.random() < 0.5 ? -1 : 1;
    this.flash = 0;
    this.knockdowns = 0;
    this.gundosMedic = false;
    this.gundosMedicTimer = 0;
    this.gundosMedicPhase = 'none';
    this.gundosMedicTargetX = x;
    this.gundosMedicHealGiven = 0;
    this.bastardHealExitQueued = false;
    this.bastardHealingExit = false;
    this.bastardHealExitDirection = -1;
  }

  applyTuning(resetHp = false) {
    const config = GAME_CONFIG.enemies.bastard || {};
    this.speed = config.speed || 0.75;
    this.damage = 0;
    this.maxHp = config.hp || 9999;
    this.scale = config.scale || GAME_CONFIG.enemyScale;
    this.canAttack = false;
    this.canDie = false;
    this.blocksWaveClear = false;
    this.wanderMinMs = config.wanderMinMs || 700;
    this.wanderMaxMs = config.wanderMaxMs || 1900;
    this.idleMinMs = config.idleMinMs || 900;
    this.idleMaxMs = config.idleMaxMs || 2200;
    this.fallenMinMs = config.fallenMinMs || 1300;
    this.fallenMaxMs = config.fallenMaxMs || 2600;
    this.idleChance = config.idleChance == null ? 0.32 : config.idleChance;
    this.fallChance = config.fallChance == null ? 0.04 : config.fallChance;
    this.turnChance = config.turnChance == null ? 0.3 : config.turnChance;
    this.knockbackX = config.knockbackX || 34;
    this.hp = resetHp ? this.maxHp : this.maxHp;
  }

  update(dt) {
    if (this.bastardHealingExit) {
      this.updateBastardHealingExit(dt);
      return;
    }
    if (this.bastardHealExitQueued && this.state !== 'fallen') {
      this.startBastardHealingExit();
      this.updateBastardHealingExit(dt);
      return;
    }

    if (this.gundosMedic) {
      this.updateGundosMedic(dt);
      return;
    }

    this.applyTuning(false);
    if (this.flash > 0) this.flash -= dt;

    if (this.state === 'fallen') {
      this.fallenTimer -= dt;
      if (this.fallenTimer <= 0) {
        this.state = 'idle';
        this.decisionTimer = this.randomBetween(this.idleMinMs, this.idleMaxMs) * 0.65;
      }
      return;
    }

    this.decisionTimer -= dt;
    if (this.decisionTimer <= 0) this.chooseNextAction();

    if (this.state === 'idle') return;
    if (this.state === 'wander') this.wander(dt);
  }

  setupGundosMedic(targetX = 285, y = this.y) {
    this.gundosMedic = true;
    this.gundosMedicTimer = 10000;
    this.gundosMedicPhase = 'enter';
    this.gundosMedicTargetX = targetX;
    this.gundosMedicHealGiven = 0;
    this.bastardHealExitQueued = false;
    this.bastardHealingExit = false;
    this.x = -70;
    this.y = y;
    this.facing = 1;
    this.moveX = 1;
    this.moveY = 0;
    this.state = 'wander';
    this.speed = Math.max(this.speed || 0.75, 1.45);
    this.blocksWaveClear = false;
    this.alive = true;
    this.remove = false;
  }

  updateGundosMedic(dt) {
    this.applyTuning(false);
    this.speed = Math.max(this.speed || 0.75, 1.45);
    if (this.flash > 0) this.flash -= dt;
    this.walkTimer += dt;
    if (this.walkTimer >= GAME_CONFIG.enemyWalkFrameMs) {
      this.walkTimer -= GAME_CONFIG.enemyWalkFrameMs;
      this.walkFrame = (this.walkFrame + 1) % 3;
    }

    if (this.gundosMedicPhase === 'enter') {
      this.facing = 1;
      this.x += this.speed * 1.75;
      if (this.x >= this.gundosMedicTargetX) {
        this.x = this.gundosMedicTargetX;
        this.gundosMedicPhase = 'idle';
        this.state = 'idle';
      }
      return;
    }

    this.gundosMedicTimer -= dt;
    if (this.state === 'fallen') {
      this.fallenTimer -= dt;
      if (this.fallenTimer > 0) return;
      this.state = 'idle';
    }

    if (this.gundosMedicTimer <= 0) {
      this.gundosMedicPhase = 'exit';
      this.state = 'wander';
    }

    if (this.gundosMedicPhase === 'exit') {
      this.facing = -1;
      this.x -= this.speed * 2.2;
      if (this.x < -120) this.remove = true;
      return;
    }

    this.state = this.flash > 0 ? 'fallen' : 'idle';
  }

  grantGundosMedicHeal(player, scene) {
    if (!player || player.hp >= player.maxHp) return 0;
    const amount = Math.min(5, Math.max(0, player.maxHp - player.hp));
    if (amount <= 0) return 0;

    this.gundosMedicHealGiven += amount;
    player.hp = Math.min(player.maxHp, player.hp + amount);
    if (scene && scene.addGundosFloatText) scene.addGundosFloatText('+' + amount + ' HP', this.x, this.y - 150, '#6dff8d');
    return amount;
  }

  queueBastardHealingExit() {
    this.bastardHealExitQueued = true;
    this.bastardHealExitDirection = this.x < GAME_CONFIG.width / 2 ? -1 : 1;
    if (this.gundosMedic) {
      this.gundosMedicTimer = Math.min(this.gundosMedicTimer || 1300, 1300);
    }
  }

  startBastardHealingExit() {
    this.bastardHealExitQueued = false;
    this.bastardHealingExit = true;
    this.gundosMedicPhase = 'exit';
    this.state = 'wander';
    this.facing = this.bastardHealExitDirection;
    this.moveX = this.bastardHealExitDirection;
    this.moveY = 0;
  }

  isHealingExit() {
    return this.bastardHealingExit || this.gundosMedicPhase === 'exit';
  }

  updateBastardHealingExit(dt) {
    this.applyTuning(false);
    this.walkTimer += dt;
    if (this.walkTimer >= GAME_CONFIG.enemyWalkFrameMs) {
      this.walkTimer -= GAME_CONFIG.enemyWalkFrameMs;
      this.walkFrame = (this.walkFrame + 1) % 3;
    }
    this.state = 'wander';
    this.facing = this.bastardHealExitDirection || -1;
    this.x += this.facing * Math.max(this.speed || 0.75, 1.55) * 2.45;
    if (this.x < -140 || this.x > GAME_CONFIG.width + 140) this.remove = true;
  }

  chooseNextAction() {
    const roll = Math.random();

    if (roll < this.fallChance) {
      this.fallDown(this.facing);
      return;
    }

    if (roll < this.fallChance + this.idleChance) {
      this.state = 'idle';
      this.decisionTimer = this.randomBetween(this.idleMinMs, this.idleMaxMs);
      if (Math.random() < this.turnChance) this.facing *= -1;
      return;
    }

    this.state = 'wander';
    if (Math.random() < this.turnChance) this.facing *= -1;
    this.moveX = Math.random() < 0.15 ? 0 : this.facing;
    this.moveY = Math.random() < 0.45 ? 0 : (Math.random() < 0.5 ? -1 : 1);
    this.decisionTimer = this.randomBetween(this.wanderMinMs, this.wanderMaxMs);
  }

  wander(dt) {
    let moveX = this.moveX;
    let moveY = this.moveY;

    if (this.x < 80) {
      moveX = 1;
      this.facing = 1;
    } else if (this.x > GAME_CONFIG.width - 80) {
      moveX = -1;
      this.facing = -1;
    }

    if (this.y < GAME_CONFIG.laneTop + 12) moveY = 1;
    else if (this.y > GAME_CONFIG.laneBottom - 12) moveY = -1;

    if (moveX === 0 && moveY === 0) return;

    const len = Math.hypot(moveX, moveY);
    this.x += (moveX / len) * this.speed;
    this.y += (moveY / len) * this.speed * GAME_CONFIG.ySpeedMultiplier;
    this.y = Math.max(GAME_CONFIG.laneTop, Math.min(GAME_CONFIG.laneBottom, this.y));

    this.walkTimer += dt;
    if (this.walkTimer >= GAME_CONFIG.enemyWalkFrameMs) {
      this.walkTimer -= GAME_CONFIG.enemyWalkFrameMs;
      this.walkFrame = (this.walkFrame + 1) % 3;
    }
  }

  fallDown(fallFacing = this.facing) {
    this.state = 'fallen';
    this.fallFacing = fallFacing >= 0 ? 1 : -1;
    this.facing = this.fallFacing;
    this.fallenTimer = this.randomBetween(this.fallenMinMs, this.fallenMaxMs);
    if (this.gundosMedic) this.fallenTimer = 1500;
    this.walkTimer = 0;
  }

  takeHit(_damage, direction) {
    const hitDirection = direction >= 0 ? 1 : -1;
    this.x += hitDirection * this.knockbackX;
    if (!this.isHealingExit || !this.isHealingExit()) {
      this.x = Math.max(70, Math.min(GAME_CONFIG.width - 70, this.x));
    }
    this.knockdowns += 1;
    this.flash = 100;
    this.fallDown(hitDirection);
  }

  getHurtbox() {
    return { x: this.x - 38, y: this.y - 132, w: 76, h: 132 };
  }

  getAttackBox() {
    return { x: this.x, y: this.y, w: 0, h: 0 };
  }

  getImages() {
    return (this.images.enemies && this.images.enemies.bastard) || {};
  }

  getImage() {
    const enemyImages = this.getImages();
    if (this.state === 'fallen') return enemyImages.fall || enemyImages.idle;
    if (this.state === 'wander') return enemyImages.walk[this.walkFrame] || enemyImages.idle;
    return enemyImages.idle;
  }

  getDrawFacing() {
    if (this.state === 'fallen') return -(this.fallFacing || this.facing || 1);
    return this.facing || 1;
  }

  draw(ctx, debug = false) {
    const img = this.getImage();
    if (!img) return;

    const w = img.width * this.scale;
    const h = img.height * this.scale;
    const drawFacing = this.getDrawFacing();

    ctx.save();
    if (this.flash > 0) ctx.globalAlpha = 0.65;
    ctx.translate(this.x, this.y);
    if (drawFacing === -1) ctx.scale(-1, 1);
    ctx.drawImage(img, -w / 2, -h, w, h);
    ctx.restore();
    ctx.globalAlpha = 1;

    if (debug) {
      const hb = this.getHurtbox();
      ctx.strokeStyle = 'rgba(255,255,0,0.85)';
      ctx.lineWidth = 2;
      ctx.strokeRect(hb.x, hb.y, hb.w, hb.h);

      ctx.font = '12px Arial';
      ctx.fillStyle = '#ffff66';
      ctx.fillText('bastard: ' + this.state + ' facing=' + drawFacing, this.x - 38, this.y - h - 12);
    }
  }

  randomBetween(min, max) {
    return min + Math.random() * Math.max(1, max - min);
  }
}



/* ===== src/hud.js ===== */
const HUD = {
  draw(ctx, scene) {
    ctx.fillStyle = 'rgba(0,0,0,0.62)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, 86);

    const order = ['alexey', 'anna', 'boris'];
    for (let i = 0; i < order.length; i++) {
      const key = order[i];
      const hero = GAME_CONFIG.heroes[key];
      const x = 20 + i * 205;
      const active = scene.player.heroKey === key;

      ctx.fillStyle = active ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.04)';
      ctx.fillRect(x, 12, 180, 60);

      ctx.fillStyle = hero.color;
      ctx.fillRect(x + 8, 18, 42, 42);
      ctx.fillStyle = '#111';
      ctx.font = 'bold 14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(hero.name[0], x + 29, 44);
      ctx.textAlign = 'left';

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 14px Arial';
      ctx.fillText(hero.name, x + 58, 28);

      const hp = active ? scene.player.hp : hero.hp;
      const pct = Math.max(0, hp / hero.hp);
      ctx.fillStyle = '#222';
      ctx.fillRect(x + 58, 38, 108, 12);
      ctx.fillStyle = pct > 0.55 ? 'lime' : pct > 0.25 ? 'yellow' : 'red';
      ctx.fillRect(x + 58, 38, 108 * pct, 12);
      ctx.strokeStyle = '#777';
      ctx.strokeRect(x + 58, 38, 108, 12);
    }

    this.drawSupportButtons(ctx, scene, 745, 22);
    this.drawLowHpSwitchHint(ctx, scene);
    this.drawSuckerPinHint(ctx, scene);

    this.drawEnemyRoster(ctx, scene);
  },

  supportButtons: [
    { key: 'F', id: 'fact', icon: '!', color: '#4fc3ff' },
    { key: 'G', id: 'damage', icon: '*', color: '#ff5a58' },
    { key: 'H', id: 'heal', icon: '+', color: '#58e37b' },
    { key: 'J', id: 'special', icon: '?', color: '#ffd15a' },
    { key: 'K', id: 'stun', icon: '~', color: '#b58cff' }
  ],

  drawSupportButtons(ctx, scene, x = 745, y = 22) {
    const buttons = this.supportButtons || [];
    const buttonW = 58;
    const buttonH = 44;
    const gap = 8;

    ctx.save();
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    for (let i = 0; i < buttons.length; i++) {
      const button = buttons[i];
      const bx = x + i * (buttonW + gap);
      const by = y;
      const active = scene && scene.pendingSupportCategory === button.id;

      ctx.fillStyle = active ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.44)';
      ctx.fillRect(bx, by, buttonW, buttonH);
      ctx.strokeStyle = active ? '#fff' : 'rgba(255,255,255,0.28)';
      ctx.lineWidth = active ? 2 : 1;
      ctx.strokeRect(bx + 0.5, by + 0.5, buttonW - 1, buttonH - 1);

      ctx.fillStyle = button.color;
      ctx.fillRect(bx + 8, by + 8, 24, 28);
      ctx.strokeStyle = 'rgba(0,0,0,0.38)';
      ctx.strokeRect(bx + 8.5, by + 8.5, 23, 27);

      ctx.fillStyle = '#111';
      ctx.font = 'bold 18px Arial';
      ctx.fillText(button.icon, bx + 20, by + 23);

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 17px Arial';
      ctx.fillText(button.key, bx + 43, by + 23);
    }

    ctx.restore();
  },

  shouldShowLowHpSwitchHint(scene) {
    const game = scene && scene.game;
    const player = scene && scene.player;
    if (!game || !player || player.hp <= 0 || player.dead || player.state === 'knockdown') return false;
    if (game.state && game.state !== 'level') return false;
    if (game.paused || game.devPanelOpen || (typeof DevPanel !== 'undefined' && DevPanel.open)) return false;

    const maxHp = player.maxHp || (GAME_CONFIG.heroes[player.heroKey] && GAME_CONFIG.heroes[player.heroKey].hp) || 1;
    if (player.hp / maxHp > 0.3) return false;

    const heroes = (typeof CharacterSelect !== 'undefined' && CharacterSelect.heroes) || Object.keys(GAME_CONFIG.heroes || {});
    return heroes.some((key) => key !== player.heroKey && !(game.defeatedHeroes && game.defeatedHeroes[key]));
  },

  drawLowHpSwitchHint(ctx, scene) {
    if (!this.shouldShowLowHpSwitchHint(scene)) return;

    const now = performance.now();
    const pulse = 0.55 + 0.45 * Math.sin(now / 135);
    const x = GAME_CONFIG.width / 2 - 300;
    const y = 94;
    const w = 600;
    const h = 44;

    ctx.save();
    ctx.globalAlpha = 0.72 + pulse * 0.28;
    ctx.fillStyle = 'rgba(120,0,0,0.86)';
    ctx.fillRect(x, y, w, h);
    ctx.strokeStyle = '#ffd15a';
    ctx.lineWidth = 3;
    ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

    ctx.fillStyle = '#ffd15a';
    ctx.font = 'bold 17px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('МАЛО ЖИЗНЕЙ', x + 110, y + h / 2);

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 20px Arial';
    ctx.fillText('НАЖМИ C', x + 255, y + h / 2);

    ctx.font = 'bold 16px Arial';
    ctx.fillText('ЧТОБЫ СМЕНИТЬ ПЕРСОНАЖА', x + 445, y + h / 2);
    ctx.restore();
  },

  drawSuckerPinHint(ctx, scene) {
    const player = scene && scene.player;
    if (!scene || !scene.suckerPinHintActive || !player || player.state !== 'pinned') return;
    if (!player.pinnedBy || player.pinnedBy.enemyType !== 'sucker') return;

    const pulse = 0.72 + 0.28 * Math.sin(performance.now() / 95);
    const scale = 1 + pulse * 0.045;
    const text = 'НАЖМИ УДАР';
    const x = GAME_CONFIG.width / 2;
    const y = 152;

    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.globalAlpha = 0.78 + pulse * 0.22;
    ctx.font = 'bold 56px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = 'rgba(255,0,0,0.9)';
    ctx.shadowBlur = 18 + pulse * 18;
    ctx.lineWidth = 9;
    ctx.strokeStyle = 'rgba(0,0,0,0.92)';
    ctx.fillStyle = '#ff1d1d';
    ctx.strokeText(text, 0, 0);
    ctx.fillText(text, 0, 0);

    ctx.globalAlpha = 0.32 + pulse * 0.32;
    ctx.shadowBlur = 0;
    ctx.strokeStyle = '#ffb0b0';
    ctx.lineWidth = 2;
    ctx.strokeText(text, 0, 0);
    ctx.restore();
  },

  drawEnemyRoster(ctx, scene) {
    const enemies = (scene.enemies || []).filter(enemy => enemy && enemy.alive && !enemy.remove);
    if (enemies.length === 0) return;

    const maxVisible = 6;
    const visibleEnemies = enemies.slice(0, maxVisible);
    const cardW = 170;
    const cardH = 46;
    const gap = 6;
    const x = GAME_CONFIG.width - cardW - 18;
    const startY = 96;

    for (let i = 0; i < visibleEnemies.length; i++) {
      const enemy = visibleEnemies[i];
      const y = startY + i * (cardH + gap);
      const config = (GAME_CONFIG.enemies && GAME_CONFIG.enemies[enemy.enemyType]) || {};
      const name = config.name || enemy.enemyType || 'Враг';
      const portrait = this.getEnemyPortraitImage(scene, enemy);

      ctx.fillStyle = 'rgba(0,0,0,0.56)';
      ctx.fillRect(x, y, cardW, cardH);
      ctx.strokeStyle = 'rgba(255,255,255,0.24)';
      ctx.strokeRect(x, y, cardW, cardH);

      ctx.fillStyle = 'rgba(255,255,255,0.08)';
      ctx.fillRect(x + 6, y + 5, 36, 36);
      if (portrait) this.drawEnemyPortrait(ctx, portrait, x + 6, y + 5, 36);

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 13px Arial';
      ctx.textAlign = 'left';
      ctx.fillText(this.shorten(name, 15), x + 50, y + 28);
    }

    if (enemies.length > maxVisible) {
      const moreY = startY + maxVisible * (cardH + gap);
      ctx.fillStyle = 'rgba(0,0,0,0.46)';
      ctx.fillRect(x, moreY, cardW, 24);
      ctx.fillStyle = '#ddd';
      ctx.font = 'bold 12px Arial';
      ctx.fillText(`+${enemies.length - maxVisible} ещё`, x + 12, moreY + 16);
    }
  },

  getEnemyPortraitImage(scene, enemy) {
    const enemyImages = scene.images && scene.images.enemies && scene.images.enemies[enemy.enemyType];
    if (!enemyImages) return null;
    if (enemyImages.portrait) return enemyImages.portrait;
    if (enemyImages.idle) return enemyImages.idle;
    if (enemyImages.walk && enemyImages.walk[0]) return enemyImages.walk[0];
    if (enemyImages.attack && enemyImages.attack[0]) return enemyImages.attack[0];
    return null;
  },

  drawEnemyPortrait(ctx, img, x, y, size) {
    if (!img || !img.width || !img.height) return;

    ctx.save();
    ctx.beginPath();
    ctx.rect(x, y, size, size);
    ctx.clip();

    const sourceH = Math.max(1, img.height * 0.58);
    const sourceW = Math.min(img.width, sourceH);
    const sourceX = Math.max(0, (img.width - sourceW) / 2);
    const sourceY = 0;

    ctx.drawImage(img, sourceX, sourceY, sourceW, sourceH, x, y, size, size);
    ctx.restore();

    ctx.strokeStyle = 'rgba(255,255,255,0.25)';
    ctx.strokeRect(x, y, size, size);
  },

  shorten(text, maxLength) {
    const safe = String(text || '');
    if (safe.length <= maxLength) return safe;
    return safe.slice(0, Math.max(1, maxLength - 1)) + '…';
  }
};



/* ===== src/menu.js ===== */
const Menu = {
  selectedIndex: 0,
  settingsIndex: 0,
  items: ['НОВАЯ ИГРА', 'ТВАРИ', 'НАСТРОЙКИ'],
  settingsItems: ['СЛОЖНОСТЬ', 'МУЗЫКА', 'ГРОМКОСТЬ МУЗЫКИ', 'ЗВУКИ УДАРОВ', 'ГРОМКОСТЬ ЗВУКОВ', 'НАЗАД'],
  difficulties: ['easy', 'normal', 'hard'],
  difficultyLabels: {
    easy: 'ЛЕГКО',
    normal: 'НОРМАЛЬНО',
    hard: 'СЛОЖНО'
  },

  update(game) {
    if (Input.consume('arrowup') || Input.consume('w')) {
      this.selectedIndex = (this.selectedIndex + this.items.length - 1) % this.items.length;
      AudioManager.playSfx('menuMove', 0.75);
    }
    if (Input.consume('arrowdown') || Input.consume('s')) {
      this.selectedIndex = (this.selectedIndex + 1) % this.items.length;
      AudioManager.playSfx('menuMove', 0.75);
    }

    const click = Input.consumePointer();
    if (click) {
      AudioManager.unlock();
      for (let i = 0; i < this.items.length; i++) {
        const box = this.getItemBox(i);
        if (click.x >= box.x && click.x <= box.x + box.w && click.y >= box.y && click.y <= box.y + box.h) {
          this.selectedIndex = i;
          this.activate(game);
        }
      }
    }

    if (Input.consume('enter') || Input.consume('space')) {
      AudioManager.unlock();
      this.activate(game);
    }
  },

  updateSettings(game) {
    if (Input.consume('escape')) {
      AudioManager.playSfx('menuSelect', 0.75);
      game.setState('mainMenu');
    }
    if (Input.consume('arrowup') || Input.consume('w')) {
      this.settingsIndex = (this.settingsIndex + this.settingsItems.length - 1) % this.settingsItems.length;
      AudioManager.playSfx('menuMove', 0.75);
    }
    if (Input.consume('arrowdown') || Input.consume('s')) {
      this.settingsIndex = (this.settingsIndex + 1) % this.settingsItems.length;
      AudioManager.playSfx('menuMove', 0.75);
    }
    if (Input.consume('arrowleft') || Input.consume('a')) {
      this.changeSetting(this.settingsIndex, game, -1);
    }
    if (Input.consume('arrowright') || Input.consume('d')) {
      this.changeSetting(this.settingsIndex, game, 1);
    }

    const click = Input.consumePointer();
    if (click) {
      AudioManager.unlock();
      for (let i = 0; i < this.settingsItems.length; i++) {
        const box = this.getSettingsBox(i);
        if (click.x >= box.x && click.x <= box.x + box.w && click.y >= box.y && click.y <= box.y + box.h) {
          this.settingsIndex = i;
          this.changeSetting(i, game, 1);
        }
      }
    }

    if (Input.consume('enter') || Input.consume('space')) {
      AudioManager.unlock();
      this.changeSetting(this.settingsIndex, game, 1);
    }
  },

  activate(game) {
    const item = this.items[this.selectedIndex];
    AudioManager.playSfx('menuSelect', 0.85);
    if (item === 'НОВАЯ ИГРА') game.setState('characterSelect');
    if (item === 'НАСТРОЙКИ') game.setState('settings');
  },

  changeSetting(index, game, direction = 1) {
    const item = this.settingsItems[index];
    AudioManager.playSfx('menuSelect', 0.75);

    if (item === 'СЛОЖНОСТЬ') {
      const current = this.difficulties.indexOf(GAME_CONFIG.settings.difficulty);
      GAME_CONFIG.settings.difficulty = this.difficulties[this.wrap(current + direction, this.difficulties.length)];
    }

    if (item === 'МУЗЫКА') {
      AudioManager.toggleMusic();
    }

    if (item === 'ГРОМКОСТЬ МУЗЫКИ') {
      AudioManager.setMusicVolume(GAME_CONFIG.settings.musicVolume + direction * 0.05);
    }

    if (item === 'ЗВУКИ УДАРОВ') {
      AudioManager.toggleSfx();
    }

    if (item === 'ГРОМКОСТЬ ЗВУКОВ') {
      AudioManager.setSfxVolume(GAME_CONFIG.settings.sfxVolume + direction * 0.05);
      AudioManager.playSfx('menuSelect', 0.9);
    }

    if (item === 'НАЗАД') {
      game.setState('mainMenu');
    }
  },

  wrap(index, length) {
    if (length <= 0) return 0;
    return ((index % length) + length) % length;
  },

  getItemBox(index) {
    return { x: 485, y: 300 + index * 70, w: 310, h: 54 };
  },

  getSettingsBox(index) {
    return { x: 350, y: 210 + index * 70, w: 580, h: 54 };
  },

  draw(ctx, images) {
    ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    for (let i = 0; i < this.items.length; i++) {
      const box = this.getItemBox(i);
      const active = i === this.selectedIndex;
      ctx.fillStyle = active ? 'rgba(255,255,255,0.16)' : 'rgba(0,0,0,0.28)';
      ctx.strokeStyle = active ? '#ffffff' : 'rgba(255,255,255,0.45)';
      ctx.lineWidth = active ? 4 : 2;
      ctx.fillRect(box.x, box.y, box.w, box.h);
      ctx.strokeRect(box.x, box.y, box.w, box.h);
      ctx.font = 'bold 28px Arial';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 4;
      ctx.strokeText(this.items[i], box.x + box.w / 2, box.y + 36);
      ctx.fillText(this.items[i], box.x + box.w / 2, box.y + 36);
    }
    ctx.textAlign = 'left';
  },

  drawSettings(ctx, images) {
    ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    ctx.font = 'bold 42px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 5;
    ctx.strokeText('НАСТРОЙКИ', GAME_CONFIG.width / 2, 135);
    ctx.fillText('НАСТРОЙКИ', GAME_CONFIG.width / 2, 135);

    for (let i = 0; i < this.settingsItems.length; i++) {
      const box = this.getSettingsBox(i);
      const active = i === this.settingsIndex;
      const label = this.getSettingsLabel(i);
      ctx.fillStyle = active ? 'rgba(255,255,255,0.16)' : 'rgba(0,0,0,0.36)';
      ctx.strokeStyle = active ? '#ffffff' : 'rgba(255,255,255,0.45)';
      ctx.lineWidth = active ? 4 : 2;
      ctx.fillRect(box.x, box.y, box.w, box.h);
      ctx.strokeRect(box.x, box.y, box.w, box.h);
      ctx.font = 'bold 24px Arial';
      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 4;
      ctx.strokeText(label, box.x + box.w / 2, box.y + 35);
      ctx.fillText(label, box.x + box.w / 2, box.y + 35);
    }

    ctx.font = '18px Arial';
    ctx.fillStyle = '#ddd';
    ctx.fillText('A/D или ←/→ — изменить громкость. Enter/Space — переключить.', 340, 660);
    ctx.textAlign = 'left';
  },

  getSettingsLabel(index) {
    const item = this.settingsItems[index];
    if (item === 'СЛОЖНОСТЬ') return 'СЛОЖНОСТЬ: ' + this.difficultyLabels[GAME_CONFIG.settings.difficulty];
    if (item === 'МУЗЫКА') return 'МУЗЫКА: ' + (GAME_CONFIG.settings.musicEnabled ? 'ВКЛ' : 'ВЫКЛ');
    if (item === 'ГРОМКОСТЬ МУЗЫКИ') return 'ГРОМКОСТЬ МУЗЫКИ: ' + Math.round(GAME_CONFIG.settings.musicVolume * 100) + '%';
    if (item === 'ЗВУКИ УДАРОВ') return 'ЗВУКИ: ' + (GAME_CONFIG.settings.sfxEnabled ? 'ВКЛ' : 'ВЫКЛ');
    if (item === 'ГРОМКОСТЬ ЗВУКОВ') return 'ГРОМКОСТЬ ЗВУКОВ: ' + Math.round(GAME_CONFIG.settings.sfxVolume * 100) + '%';
    return item;
  },

  drawSplash(ctx, images) {
    ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.18)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    ctx.fillStyle = 'rgba(0,0,0,0.28)';
    ctx.fillRect(410, 560, 460, 62);
    ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    ctx.lineWidth = 3;
    ctx.strokeRect(410, 560, 460, 62);
    ctx.font = 'bold 30px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 5;
    ctx.strokeText('НАЖМИ ЛЮБУЮ КНОПКУ', 640, 600);
    ctx.fillText('НАЖМИ ЛЮБУЮ КНОПКУ', 640, 600);
    ctx.font = 'bold 18px Arial';
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(255,255,255,0.82)';
    ctx.strokeStyle = 'rgba(0,0,0,0.85)';
    ctx.lineWidth = 4;
    const version = 'v' + (GAME_CONFIG.buildVersion || 'dev');
    ctx.strokeText(version, GAME_CONFIG.width - 28, GAME_CONFIG.height - 26);
    ctx.fillText(version, GAME_CONFIG.width - 28, GAME_CONFIG.height - 26);
    ctx.textAlign = 'left';
  }
};



/* ===== src/intro.js ===== */
const Intro = {
  scrollY: 0,
  finished: false,
  lines: null,
  text: '',
  loading: false,
  loaded: false,
  loadError: false,
  voice: null,
  voiceStarted: false,
  voiceDuration: 150,
  totalScrollDistance: 0,
  fallbackElapsed: 0,
  typedCharacters: 0,

  reset() {
    this.stopVoice();
    if (typeof AudioManager !== 'undefined') AudioManager.stopMusic();

    this.scrollY = 0;
    this.finished = false;
    this.lines = null;
    this.text = '';
    this.loading = false;
    this.loaded = false;
    this.loadError = false;
    this.voiceStarted = false;
    this.totalScrollDistance = 0;
    this.fallbackElapsed = 0;
    this.typedCharacters = 0;
    this.loadText();
    this.startVoice();
  },

  getIntroText() {
    if (typeof window !== 'undefined' && typeof window.STREETS_INTRO_TEXT === 'string' && window.STREETS_INTRO_TEXT.trim()) {
      return window.STREETS_INTRO_TEXT;
    }
    return '';
  },

  loadText() {
    const text = this.getIntroText();
    if (!text) {
      this.text = 'Ошибка загрузки introContent.js';
      this.lines = null;
      this.loaded = false;
      this.loadError = true;
      return;
    }

    this.text = text;
    this.lines = null;
    this.loaded = true;
    this.loadError = false;
    console.log('[INTRO] Text loaded from window.STREETS_INTRO_TEXT. Length:', this.text.length);
  },

  getVoiceSrc() {
    return 'assets/audio/music/intro-voice.mp3';
  },

  startVoice() {
    try {
      const audio = new Audio(this.getVoiceSrc());
      audio.preload = 'auto';
      audio.loop = false;
      audio.volume = this.getVoiceVolume();
      audio.addEventListener('loadedmetadata', () => {
        if (Number.isFinite(audio.duration) && audio.duration > 0) this.voiceDuration = audio.duration;
        console.log('[INTRO] Voice loaded. Duration:', this.voiceDuration);
      });
      audio.addEventListener('play', () => {
        this.voiceStarted = true;
      });
      audio.addEventListener('ended', () => {
        this.voiceStarted = false;
        this.typedCharacters = this.getTotalCharacterCount();
      });
      audio.addEventListener('error', () => {
        console.warn('[INTRO] Missing intro voice:', this.getVoiceSrc());
      });
      this.voice = audio;

      audio.play()
        .then(() => {
          this.voiceStarted = true;
        })
        .catch((error) => {
          this.voiceStarted = false;
          console.warn('[INTRO] Voice autoplay blocked or failed:', error);
        });
    } catch (error) {
      console.warn('[INTRO] Cannot start intro voice:', error);
    }
  },

  stopVoice() {
    if (!this.voice) return;
    try {
      this.voice.pause();
      this.voice.currentTime = 0;
    } catch (error) {}
    this.voice = null;
    this.voiceStarted = false;
  },

  getVoiceVolume() {
    if (!AudioManager.isMusicOn()) return 0;
    return AudioManager.getMusicVolume();
  },

  syncVoiceVolume() {
    if (!this.voice) return;
    this.voice.volume = this.getVoiceVolume();
  },

  getVoiceProgress() {
    if (!this.voice || !Number.isFinite(this.voice.currentTime)) return null;
    if (!this.voiceStarted && this.voice.currentTime <= 0.01) return null;
    const duration = Number.isFinite(this.voice.duration) && this.voice.duration > 0 ? this.voice.duration : this.voiceDuration;
    if (!duration) return null;
    return Math.max(0, Math.min(1, this.voice.currentTime / duration));
  },

  getTotalCharacterCount() {
    const lines = this.lines || [];
    if (!lines.length) return this.text.length;
    return lines.reduce((sum, line) => sum + line.length + 1, 0);
  },

  updateTypedCharacters(progress) {
    const totalCharacters = this.getTotalCharacterCount();
    this.typedCharacters = Math.max(0, Math.min(totalCharacters, Math.floor(progress * totalCharacters)));
  },

  resumeMenuMusic(game) {
    if (game && typeof game.ensureMenuMusic === 'function') game.ensureMenuMusic();
  },

  finish(game) {
    if (this.finished) return;
    this.finished = true;
    this.typedCharacters = this.getTotalCharacterCount();
    this.stopVoice();
    AudioManager.playSfx('menuSelect', 0.85);
    game.setState('characterSelect');
    this.resumeMenuMusic(game);
  },

  update(game, dt) {
    if (!this.loaded && !this.loading && !this.loadError) this.loadText();
    this.syncVoiceVolume();

    if (Input.consume('escape')) {
      this.stopVoice();
      AudioManager.playSfx('menuSelect', 0.75);
      game.setState('mainMenu');
      this.resumeMenuMusic(game);
      return;
    }

    const skip = Input.consume('enter') || Input.consume('space') || Input.consumePointer();
    if (skip && this.loaded) {
      this.finish(game);
      return;
    }

    const progress = this.getVoiceProgress();
    if (progress != null) {
      this.updateTypedCharacters(progress);
      return;
    }

    if (!this.voiceStarted) {
      this.fallbackElapsed += dt / 1000;
      const fallbackProgress = Math.max(0, Math.min(1, this.fallbackElapsed / this.voiceDuration));
      this.updateTypedCharacters(fallbackProgress);
    }
  },

  getWrappedLines(ctx) {
    if (this.lines) return this.lines;

    const maxWidth = 900;
    const paragraphs = this.text.split('\n');
    const lines = [];

    paragraphs.forEach((paragraph) => {
      const trimmed = paragraph.trim();
      if (!trimmed) {
        lines.push('');
        return;
      }

      const words = trimmed.split(/\s+/);
      let line = '';

      words.forEach((word) => {
        const testLine = line ? line + ' ' + word : word;
        if (ctx.measureText(testLine).width > maxWidth && line) {
          lines.push(line);
          line = word;
        } else {
          line = testLine;
        }
      });

      if (line) lines.push(line);
    });

    this.lines = lines;
    return lines;
  },

  getLineHeight(lineHeight, line) {
    return line === '' ? lineHeight * 0.75 : lineHeight;
  },

  calculateTotalScrollDistance(lines, lineHeight) {
    const contentHeight = lines.reduce((sum, line) => sum + this.getLineHeight(lineHeight, line), 0);
    const startY = 130;
    const endY = 430;
    return Math.max(0, contentHeight + startY - endY);
  },

  calculateVisibleHeight(lines, lineHeight, visibleCharacters) {
    let remaining = visibleCharacters;
    let height = 0;

    for (const line of lines) {
      if (remaining <= 0) break;
      height += this.getLineHeight(lineHeight, line);
      remaining -= line.length + 1;
    }

    return height;
  },

  updateScrollForTypedText(lines, lineHeight) {
    const startY = 130;
    const endY = 585;
    const visibleHeight = this.calculateVisibleHeight(lines, lineHeight, this.typedCharacters);
    this.scrollY = Math.max(0, visibleHeight + startY - endY);
  },

  drawLoadingMessage(ctx, message) {
    ctx.font = 'bold 28px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 4;
    ctx.strokeText(message, GAME_CONFIG.width / 2, GAME_CONFIG.height / 2);
    ctx.fillText(message, GAME_CONFIG.width / 2, GAME_CONFIG.height / 2);
    ctx.textAlign = 'left';
  },

  draw(ctx, images) {
    if (images.main) ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    ctx.fillStyle = 'rgba(0,0,0,0.78)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    const gradient = ctx.createLinearGradient(0, 0, 0, GAME_CONFIG.height);
    gradient.addColorStop(0, 'rgba(0,0,0,0.95)');
    gradient.addColorStop(0.15, 'rgba(0,0,0,0.15)');
    gradient.addColorStop(0.82, 'rgba(0,0,0,0.1)');
    gradient.addColorStop(1, 'rgba(0,0,0,0.95)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    if (!this.loaded) {
      this.drawLoadingMessage(ctx, this.loadError ? 'НЕ УДАЛОСЬ ЗАГРУЗИТЬ introContent.js' : 'ЗАГРУЗКА ИНТРО...');
      return;
    }

    ctx.save();
    ctx.beginPath();
    ctx.rect(130, 84, 1020, 530);
    ctx.clip();

    ctx.font = '26px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#f1f1f1';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 4;

    const lines = this.getWrappedLines(ctx);
    const lineHeight = 34;
    this.totalScrollDistance = this.calculateTotalScrollDistance(lines, lineHeight);
    this.updateScrollForTypedText(lines, lineHeight);

    let y = 130 - this.scrollY;
    let remainingCharacters = this.typedCharacters;

    lines.forEach((line) => {
      const lineBudget = line.length + 1;
      const visibleCount = Math.max(0, Math.min(line.length, remainingCharacters));
      const visibleLine = line.slice(0, visibleCount);

      if (visibleLine && y > 55 && y < 640) {
        if (line === 'Россия. 2026 год.' || line === 'Это Streets of Russia!') {
          ctx.font = 'bold 34px Arial';
          ctx.fillStyle = '#ffffff';
        } else {
          ctx.font = '26px Arial';
          ctx.fillStyle = '#f1f1f1';
        }
        ctx.strokeText(visibleLine, GAME_CONFIG.width / 2, y);
        ctx.fillText(visibleLine, GAME_CONFIG.width / 2, y);
      }

      remainingCharacters -= lineBudget;
      y += this.getLineHeight(lineHeight, line);
    });

    ctx.restore();

    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(300, 638, 680, 46);
    ctx.strokeStyle = 'rgba(255,255,255,0.55)';
    ctx.lineWidth = 2;
    ctx.strokeRect(300, 638, 680, 46);
    ctx.font = 'bold 20px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffffff';
    ctx.fillText('ENTER / SPACE / КЛИК — ПРОПУСТИТЬ   •   КНОПКА 🔊 СПРАВА — ЗВУК   •   ESC — НАЗАД', GAME_CONFIG.width / 2, 668);
    ctx.textAlign = 'left';
  }
};



/* ===== src/characterSelect.js ===== */
const CharacterSelect = {
  heroes: ['alexey', 'anna', 'boris'],
  selectedIndex: 2,
  footerFocus: null,
  infoOpen: false,

  update(game) {
    if (this.infoOpen) {
      if (Input.consume('escape') || Input.consume('i') || Input.consume('backspace') || Input.consume('enter') || Input.consume('space')) {
        this.closeInfo();
        return;
      }

      const infoClick = Input.consumePointer();
      if (infoClick) {
        const close = this.getInfoCloseBox();
        if (this.isPointInBox(infoClick, close)) {
          this.closeInfo();
          return;
        }
        this.closeInfo();
      }
      return;
    }

    if (Input.consume('arrowdown') || Input.consume('s')) {
      this.footerFocus = 'confirm';
      AudioManager.playSfx('menuMove', 0.65);
    }

    if (Input.consume('arrowup') || Input.consume('w')) {
      if (this.footerFocus) AudioManager.playSfx('menuMove', 0.65);
      this.footerFocus = null;
    }

    if (Input.consume('arrowleft') || Input.consume('a')) {
      if (this.footerFocus) this.moveFooterFocus(-1);
      else this.moveSelection(-1);
    }

    if (Input.consume('arrowright') || Input.consume('d')) {
      if (this.footerFocus) this.moveFooterFocus(1);
      else this.moveSelection(1);
    }

    if (Input.consume('i')) this.openInfo();
    if (Input.consume('escape')) {
      AudioManager.playSfx('menuSelect', 0.65);
      game.setState('mainMenu');
    }

    const click = Input.consumePointer();
    if (click) {
      for (let i = 0; i < this.heroes.length; i++) {
        const info = this.getInfoButtonBox(i);
        if (this.isPointInCircle(click, info)) {
          this.setSelection(i);
          this.footerFocus = null;
          this.openInfo();
          return;
        }

        const box = this.getCardBox(i);
        if (this.isPointInBox(click, box)) {
          this.setSelection(i);
          this.footerFocus = null;
        }
      }

      if (this.isPointInBox(click, this.getConfirmBox())) this.confirm(game);
      if (this.isPointInBox(click, this.getBackBox())) {
        AudioManager.playSfx('menuSelect', 0.65);
        game.setState('mainMenu');
      }
    }

    if (Input.consume('enter') || Input.consume('space')) {
      if (this.footerFocus === 'back') {
        AudioManager.playSfx('menuSelect', 0.65);
        game.setState('mainMenu');
      } else {
        this.confirm(game);
      }
    }
  },

  moveSelection(direction) {
    this.selectedIndex = (this.selectedIndex + direction + this.heroes.length) % this.heroes.length;
    AudioManager.playSfx('menuMove', 0.85, { playbackRate: direction < 0 ? 0.95 : 1.05 });
  },

  moveFooterFocus(direction) {
    this.footerFocus = this.footerFocus === 'confirm' ? 'back' : 'confirm';
    AudioManager.playSfx('menuMove', 0.7, { playbackRate: direction < 0 ? 0.95 : 1.05 });
  },

  setSelection(index) {
    if (index === this.selectedIndex) return;
    this.selectedIndex = index;
    AudioManager.playSfx('menuMove', 0.85);
  },

  openInfo() {
    this.infoOpen = true;
    AudioManager.playSfx('menuSelect', 0.75);
  },

  closeInfo() {
    this.infoOpen = false;
    AudioManager.playSfx('menuSelect', 0.55);
  },

  confirm(game) {
    game.selectedHero = this.heroes[this.selectedIndex];
    AudioManager.playSfx('menuSelect', 0.85);
    game.startLevel();
  },

  getCardBox(i) {
    return { x: 120 + i * 355, y: 126, w: 320, h: 488 };
  },

  getPortraitBox(i) {
    const box = this.getCardBox(i);
    return { x: box.x + 42, y: box.y + 44, w: box.w - 84, h: 244 };
  },

  getInfoButtonBox(i) {
    const box = this.getCardBox(i);
    return { x: box.x + 25, y: box.y + 25, r: 14 };
  },

  getConfirmBox() {
    return { x: 420, y: 628, w: 260, h: 46 };
  },

  getBackBox() {
    return { x: 720, y: 628, w: 160, h: 46 };
  },

  getInfoCloseBox() {
    return { x: GAME_CONFIG.width / 2 + 330, y: 128, w: 46, h: 46 };
  },

  isPointInBox(point, box) {
    return point.x >= box.x && point.x <= box.x + box.w && point.y >= box.y && point.y <= box.y + box.h;
  },

  isPointInCircle(point, circle) {
    const dx = point.x - circle.x;
    const dy = point.y - circle.y;
    return dx * dx + dy * dy <= circle.r * circle.r;
  },

  draw(ctx, images) {
    ctx.fillStyle = '#08080d';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = 'rgba(0,0,0,0.58)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    this.drawTitle(ctx, 'ВЫБЕРИТЕ ПЕРСОНАЖА', 72);

    for (let i = 0; i < this.heroes.length; i++) {
      this.drawCard(ctx, images, this.heroes[i], i, i === this.selectedIndex && !this.footerFocus);
    }

    const confirm = this.getConfirmBox();
    const back = this.getBackBox();
    this.drawButton(ctx, confirm.x, confirm.y, confirm.w, confirm.h, 'ПОДТВЕРДИТЬ', this.footerFocus === 'confirm' || !this.footerFocus);
    this.drawButton(ctx, back.x, back.y, back.w, back.h, 'НАЗАД', this.footerFocus === 'back');

    ctx.font = '18px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = 'rgba(255,255,255,0.72)';
    ctx.fillText('←/→ или A/D — выбрать   ↓ — кнопки   Enter — начать   I — информация', GAME_CONFIG.width / 2, 704);
    ctx.textAlign = 'left';

    if (this.infoOpen) this.drawInfoModal(ctx, images);
  },

  drawCard(ctx, images, heroKey, index, selected) {
    const hero = GAME_CONFIG.heroes[heroKey];
    const box = this.getCardBox(index);
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(box.x, box.y, box.w, box.h);
    ctx.strokeStyle = selected ? '#ffffff' : 'rgba(255,255,255,0.35)';
    ctx.lineWidth = selected ? 5 : 2;
    ctx.strokeRect(box.x, box.y, box.w, box.h);

    this.drawHeroPortrait(ctx, images, heroKey, index, hero.color);
    this.drawInfoIcon(ctx, index, selected, hero.color);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.font = 'bold 32px Arial';
    ctx.fillStyle = hero.color;
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 4;
    ctx.strokeText(hero.name.toUpperCase(), box.x + box.w / 2, box.y + 334);
    ctx.fillText(hero.name.toUpperCase(), box.x + box.w / 2, box.y + 334);
    ctx.textAlign = 'left';

    this.drawStat(ctx, box.x + 35, box.y + 385, 'СИЛА', hero.strength, hero.color);
    this.drawStat(ctx, box.x + 35, box.y + 427, 'СКОРОСТЬ', hero.speedStat, hero.color);
    this.drawStat(ctx, box.x + 35, box.y + 469, 'ЗДОРОВЬЕ', hero.health, hero.color);
  },

  drawHeroPortrait(ctx, images, heroKey, index, color) {
    const heroImages = images.heroes && images.heroes[heroKey];
    const portrait = this.getPortraitBox(index);
    const box = this.getCardBox(index);

    if (heroImages && heroImages.idle) {
      const img = heroImages.idle;
      const scale = Math.min(portrait.w / img.width, portrait.h / img.height);
      const w = img.width * scale;
      const h = img.height * scale;
      const x = portrait.x + portrait.w / 2 - w / 2;
      const y = portrait.y + portrait.h - h;
      ctx.drawImage(img, x, y, w, h);
      return;
    }

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(box.x + box.w / 2, portrait.y + 118, 62, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#111';
    ctx.font = 'bold 18px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('SPRITES', box.x + box.w / 2, portrait.y + 116);
    ctx.fillText('ПОЗЖЕ', box.x + box.w / 2, portrait.y + 140);
  },

  drawInfoIcon(ctx, index, selected, color) {
    const icon = this.getInfoButtonBox(index);
    ctx.save();
    ctx.beginPath();
    ctx.arc(icon.x, icon.y, icon.r, 0, Math.PI * 2);
    ctx.fillStyle = selected ? color : 'rgba(0,0,0,0.72)';
    ctx.fill();
    ctx.lineWidth = selected ? 2.5 : 2;
    ctx.strokeStyle = selected ? '#fff' : 'rgba(255,255,255,0.74)';
    ctx.stroke();

    ctx.font = 'bold 16px Georgia, Times New Roman, serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.75)';
    ctx.lineWidth = 2.5;
    ctx.strokeText('I', icon.x, icon.y + 0.5);
    ctx.fillText('I', icon.x, icon.y + 0.5);
    ctx.restore();
  },

  drawStat(ctx, x, y, label, value, color) {
    ctx.font = 'bold 18px Arial';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff';
    ctx.fillText(label, x, y);
    const barX = x + 118;
    const boxY = y - 8;
    for (let i = 0; i < 8; i++) {
      ctx.fillStyle = i < value ? color : 'rgba(255,255,255,0.12)';
      ctx.fillRect(barX + i * 18, boxY, 13, 16);
    }
    ctx.textBaseline = 'alphabetic';
  },

  drawInfoModal(ctx, images) {
    const heroKey = this.heroes[this.selectedIndex];
    const hero = GAME_CONFIG.heroes[heroKey];
    const modal = { x: 210, y: 118, w: 860, h: 470 };

    ctx.fillStyle = 'rgba(0,0,0,0.72)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = 'rgba(8,8,13,0.96)';
    ctx.fillRect(modal.x, modal.y, modal.w, modal.h);
    ctx.strokeStyle = hero.color;
    ctx.lineWidth = 4;
    ctx.strokeRect(modal.x, modal.y, modal.w, modal.h);

    const close = this.getInfoCloseBox();
    this.drawButton(ctx, close.x, close.y, close.w, close.h, '×', false);

    const heroImages = images.heroes && images.heroes[heroKey];
    if (heroImages && heroImages.idle) {
      const img = heroImages.idle;
      const maxW = 210;
      const maxH = 330;
      const scale = Math.min(maxW / img.width, maxH / img.height);
      const w = img.width * scale;
      const h = img.height * scale;
      ctx.drawImage(img, modal.x + 44 + maxW / 2 - w / 2, modal.y + 84 + maxH - h, w, h);
    }

    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.font = 'bold 38px Arial';
    ctx.fillStyle = hero.color;
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 5;
    ctx.strokeText(hero.name.toUpperCase(), modal.x + 300, modal.y + 82);
    ctx.fillText(hero.name.toUpperCase(), modal.x + 300, modal.y + 82);

    ctx.font = 'bold 22px Arial';
    ctx.fillStyle = '#fff';
    ctx.fillText(hero.tagline || '', modal.x + 300, modal.y + 124);

    ctx.font = '21px Arial';
    ctx.fillStyle = 'rgba(255,255,255,0.88)';
    this.drawWrappedText(ctx, hero.bio || '', modal.x + 300, modal.y + 168, 505, 30);

    ctx.font = 'bold 22px Arial';
    ctx.fillStyle = hero.color;
    ctx.fillText('ОСОБЕННОСТЬ', modal.x + 300, modal.y + 345);
    ctx.font = '20px Arial';
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    this.drawWrappedText(ctx, hero.ability || '', modal.x + 300, modal.y + 378, 505, 28);

    ctx.font = '18px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(255,255,255,0.65)';
    ctx.fillText('Esc / Enter / клик — закрыть', modal.x + modal.w / 2, modal.y + modal.h - 28);
    ctx.textAlign = 'left';
  },

  drawWrappedText(ctx, text, x, y, maxWidth, lineHeight) {
    const words = String(text).split(' ');
    let line = '';
    for (const word of words) {
      const test = line ? line + ' ' + word : word;
      if (ctx.measureText(test).width > maxWidth && line) {
        ctx.fillText(line, x, y);
        line = word;
        y += lineHeight;
      } else {
        line = test;
      }
    }
    if (line) ctx.fillText(line, x, y);
  },

  drawButton(ctx, x, y, w, h, text, strong) {
    ctx.fillStyle = strong ? 'rgba(255,255,255,0.16)' : 'rgba(0,0,0,0.4)';
    ctx.strokeStyle = strong ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.72)';
    ctx.lineWidth = strong ? 3 : 2;
    ctx.fillRect(x, y, w, h);
    ctx.strokeRect(x, y, w, h);
    ctx.font = h < 44 ? 'bold 18px Arial' : 'bold 24px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 4;
    ctx.strokeText(text, x + w / 2, y + h / 2 + 1);
    ctx.fillText(text, x + w / 2, y + h / 2 + 1);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
  },

  drawTitle(ctx, text, y) {
    ctx.font = 'bold 42px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 6;
    ctx.strokeText(text, GAME_CONFIG.width / 2, y);
    ctx.fillText(text, GAME_CONFIG.width / 2, y);
    ctx.textAlign = 'left';
  }
};


/* ===== src/scene.js ===== */
class HealthPickup {
  constructor(type, x, y, images) {
    this.type = type;
    this.x = x;
    this.y = y;
    this.images = images;
    this.age = 0;
    this.remove = false;
    this.floatText = null;
    this.floatTimer = 0;
    this.floatTextX = x;
    this.floatTextY = y - 58;
    this.popDuration = 420;
  }

  getConfig() {
    return (GAME_CONFIG.pickups && GAME_CONFIG.pickups[this.type]) || {};
  }

  getImage() {
    const cfg = this.getConfig();
    return this.images && this.images.pickups && this.images.pickups[cfg.image || this.type];
  }

  getHealAmount(player) {
    const cfg = this.getConfig();
    if (!player) return 0;
    if (cfg.fullHeal) return Math.max(0, player.maxHp - player.hp);
    if (cfg.healPercent != null) return Math.ceil(player.maxHp * cfg.healPercent);
    return Math.max(0, Number(cfg.heal) || 0);
  }

  update(dt, scene) {
    this.age += dt;
    if (this.floatTimer > 0) {
      this.floatTimer -= dt;
      if (this.floatTimer <= 0) this.remove = true;
    }
  }

  canCollect(player) {
    if (!player || player.hp <= 0) return;
    const cfg = this.getConfig();
    const dx = Math.abs(player.x - this.x);
    const dy = Math.abs(player.y - this.y);
    const radiusX = cfg.collectRadiusX == null ? 58 : cfg.collectRadiusX;
    const laneTolerance = cfg.collectLaneTolerance == null ? 42 : cfg.collectLaneTolerance;
    return dx <= radiusX && dy <= laneTolerance;
  }

  collect(player) {
    if (!this.canCollect(player)) return false;
    const cfg = this.getConfig();
    const before = player.hp;
    const heal = this.getHealAmount(player);
    player.hp = Math.min(player.maxHp, player.hp + heal);
    const gained = Math.max(0, player.hp - before);
    if (gained <= 0) return;
    this.floatText = gained > 0 ? (cfg.label || ('+' + gained + ' HP')) : 'FULL';
    this.floatTextX = player.x;
    this.floatTextY = player.y - 136;
    this.floatTimer = 650;
    AudioManager.playSfx('waveClear', 0.35, { playbackRate: 1.35 });
    return true;
  }

  draw(ctx) {
    const img = this.getImage();
    const cfg = this.getConfig();
    const pop = Math.min(1, this.age / this.popDuration);
    const bounce = Math.sin(pop * Math.PI);
    const pulse = 1 + Math.sin(this.age / 130) * 0.045;
    const appearScale = pop < 1 ? (0.35 + 0.65 * pop) : 1;
    const scale = (cfg.scale || 0.32) * pulse * appearScale;
    const popY = pop < 1 ? -bounce * 42 : 0;

    ctx.save();
    if (this.floatTimer <= 0 && img && img.complete !== false && img.naturalWidth !== 0) {
      const w = img.width * scale;
      const h = img.height * scale;
      ctx.globalAlpha = Math.min(1, 0.25 + pop * 0.75);
      ctx.shadowColor = 'rgba(255,255,210,0.7)';
      ctx.shadowBlur = 12;
      try {
        ctx.drawImage(img, this.x - w / 2, this.y - h + popY, w, h);
      } catch (error) {
        this.drawFallback(ctx, pop, appearScale, popY);
      }
      ctx.shadowBlur = 0;
      ctx.globalAlpha = 1;
    } else if (this.floatTimer <= 0) {
      this.drawFallback(ctx, pop, appearScale, popY);
    }

    if (this.floatText) {
      const t = 1 - Math.max(0, this.floatTimer) / 650;
      ctx.globalAlpha = Math.max(0, 1 - t * 0.55);
      ctx.font = 'bold 18px Arial';
      ctx.textAlign = 'center';
      ctx.lineWidth = 4;
      ctx.strokeStyle = '#10260f';
      ctx.fillStyle = '#87ff8f';
      ctx.strokeText(this.floatText, this.floatTextX, this.floatTextY - t * 24);
      ctx.fillText(this.floatText, this.floatTextX, this.floatTextY - t * 24);
      ctx.textAlign = 'left';
    }
    ctx.restore();
  }

  drawFallback(ctx, pop, appearScale, popY) {
    const color = this.type === 'medkit' ? '#ff3f3f' : this.type === 'tea' ? '#d89641' : '#f7b23b';
    ctx.globalAlpha = Math.min(1, 0.25 + pop * 0.75);
    ctx.shadowColor = 'rgba(255,255,210,0.75)';
    ctx.shadowBlur = 12;
    ctx.fillStyle = color;
    ctx.strokeStyle = '#fff1c0';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.ellipse(this.x, this.y - 22 + popY, 24 * appearScale, 16 * appearScale, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.globalAlpha = 1;
    ctx.font = 'bold 13px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#111';
    ctx.fillText(this.type === 'medkit' ? '+' : this.type === 'tea' ? 'TEA' : 'HP', this.x, this.y - 18 + popY);
  }
}

class LevelScene {
  constructor(game, images) {
    this.game = game;
    this.images = images;
    this.screenIndex = 0;
    this.player = new Player(game.selectedHero || 'boris', images);
    this.enemies = [];
    this.pickups = [];
    this.pendingPickupDrops = [];
    this.hitStop = 0;
    this.encounterActive = false;
    this.encounterCleared = false;
    this.debug = false;
    this.currentWaveIndex = -1;
    this.nonBlockingWaveTimer = 0;
    this.pendingWave = null;
    this.pendingWaveTimer = 0;
    this.scheduledGroups = [];
    this.spawnInitialWave();
  }

  getLevelKey() {
    return GAME_CONFIG.levelOrder[this.screenIndex] || 'street01';
  }

  getLevelConfig() {
    return GAME_CONFIG.levels[this.getLevelKey()] || GAME_CONFIG.levels.street01;
  }

  getLevelBackgroundImage() {
    return this.images.streets[this.screenIndex] || this.images.streets[0];
  }

  updateLevelInteractives(dt) {
  }

  drawLevelBackgroundEffects(ctx) {
  }

  drawLevelForegroundObjects(ctx) {
    const level = this.getLevelConfig();
    const items = Array.isArray(level && level.interactives) ? level.interactives : [];
    for (const item of items) {
      if (!item || item.type !== 'vehicleObstacle' || !item.drawRect) continue;
      const rect = item.drawRect;
      const image = item.image && this.images.levelInteractiveImages && this.images.levelInteractiveImages[item.image];
      ctx.save();
      if (image && image.complete !== false && image.naturalWidth !== 0) {
        try {
          ctx.drawImage(image, rect.x, rect.y, rect.w, rect.h);
          ctx.restore();
          continue;
        } catch (error) {}
      }
      ctx.fillStyle = 'rgba(20,45,75,0.82)';
      ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.45)';
      ctx.lineWidth = 2;
      ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
      ctx.restore();
    }
  }

  spawnInitialWave() {
    this.currentWaveIndex = -1;
    this.enemies = [];
    this.pickups = [];
    this.pendingPickupDrops = [];
    this.encounterActive = false;
    this.encounterCleared = false;
    this.nonBlockingWaveTimer = 0;
    this.pendingWave = null;
    this.pendingWaveTimer = 0;
    this.scheduledGroups = [];
    this.spawnNextWave('onEnter');
  }

  hasLaterWave(expectedTrigger = 'afterWaveCleared') {
    const level = this.getLevelConfig();
    const waves = level.waves || [];
    for (let i = this.currentWaveIndex + 1; i < waves.length; i++) {
      if (waves[i].trigger === expectedTrigger) return true;
    }
    return false;
  }

  scheduleNonBlockingWaveAdvance() {
    this.encounterActive = false;
    if (this.hasLaterWave('afterWaveCleared')) {
      this.encounterCleared = false;
      this.nonBlockingWaveTimer = 5000;
    } else {
      this.encounterCleared = true;
      this.nonBlockingWaveTimer = 0;
    }
  }

  getWaveAppearDelayMs(wave) {
    if (wave.appearDelayMs != null) return Math.max(0, Number(wave.appearDelayMs) || 0);
    const key = this.getWaveAppearKey(wave);
    return key === 'zetnikAppear' ? 850 : 0;
  }

  getWaveAppearKey(wave) {
    for (const group of wave.enemies || []) {
      if (group.type === 'dogRegime') continue;
      const key = group.type + 'Appear';
      if (AudioManager.isUsableSfxKey && AudioManager.isUsableSfxKey(key)) return key;
    }
    return null;
  }

  getEnemyAppearSoundKey(type) {
    return `${type}Appear`;
  }

  getEnemyAppearSoundPath(type) {
    const enemyConfig = (GAME_CONFIG.enemies && GAME_CONFIG.enemies[type]) || {};
    if (enemyConfig.appearSoundPath) return enemyConfig.appearSoundPath;
    const folder = String(type || 'enemy').replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
    return `assets/enemies/${folder}/appear.mp3`;
  }

  playEnemyAppearSound(type) {
    if (!type) return;
    if (type === 'dogRegime') {
      if (AudioManager.stopHorseAppearSfx) AudioManager.stopHorseAppearSfx();
      return;
    }
    const previousAppearType = AudioManager.enemyAppearType;
    AudioManager.enemyAppearType = type;
    try {
      AudioManager.playOptionalSfx(this.getEnemyAppearSoundKey(type), 0.9, {
        src: this.getEnemyAppearSoundPath(type),
        startAt: 0.01
      });
    } finally {
      AudioManager.enemyAppearType = previousAppearType || null;
    }
  }

  spawnNextWave(expectedTrigger = 'afterWaveCleared') {
    const level = this.getLevelConfig();
    const waves = level.waves || [];

    for (let i = this.currentWaveIndex + 1; i < waves.length; i++) {
      const wave = waves[i];
      if (wave.trigger !== expectedTrigger) continue;
      this.currentWaveIndex = i;
      this.beginWave(wave);
      return true;
    }

    this.encounterActive = false;
    this.encounterCleared = true;
    this.nonBlockingWaveTimer = 0;
    this.pendingWave = null;
    this.pendingWaveTimer = 0;
    return false;
  }

  beginWave(wave) {
    this.handleWaveAudio(wave);
    const delayMs = this.getWaveAppearDelayMs(wave);

    if (delayMs > 0) {
      this.playWaveAppearSounds(wave);
      this.pendingWave = wave;
      this.pendingWaveTimer = delayMs;
      this.encounterActive = false;
      this.encounterCleared = false;
      this.nonBlockingWaveTimer = 0;
      return;
    }

    this.materializeWave(wave);
  }

  playWaveAppearSounds(wave) {
    const playedTypes = new Set();
    for (const group of wave.enemies || []) {
      if (!group.type || playedTypes.has(group.type)) continue;
      playedTypes.add(group.type);
      this.playEnemyAppearSound(group.type);
    }
  }

  materializeWave(wave) {
    this.spawnWave(wave);
    this.encounterActive = this.hasWaveBlockers() || this.hasScheduledGroups();
    this.encounterCleared = !this.encounterActive;
    this.nonBlockingWaveTimer = 0;
    this.pendingWave = null;
    this.pendingWaveTimer = 0;

    if (!this.encounterActive) {
      this.scheduleNonBlockingWaveAdvance();
    }
  }

  spawnWave(wave) {
    this.enemies = this.enemies.filter(enemy => enemy && enemy.alive && enemy.enemyType === 'bastard');
    this.scheduledGroups = [];

    for (const group of wave.enemies || []) {
      const delayMs = Math.max(0, Number(group.delayMs) || 0);
      if (delayMs > 0) this.scheduleEnemyGroup(group, delayMs);
      else this.spawnEnemyGroup(group);
    }

    this.separateEnemies(16.67, true);
  }

  scheduleEnemyGroup(group, delayMs) {
    this.scheduledGroups.push({
      group: JSON.parse(JSON.stringify(group)),
      timer: delayMs
    });
  }

  updateScheduledGroups(dt) {
    if (!this.scheduledGroups.length) return;
    for (const item of this.scheduledGroups) item.timer -= dt;

    const ready = this.scheduledGroups.filter(item => item.timer <= 0);
    this.scheduledGroups = this.scheduledGroups.filter(item => item.timer > 0);
    for (const item of ready) {
      this.spawnEnemyGroup(item.group);
      this.separateEnemies(16.67, true);
    }
  }

  hasScheduledGroups() {
    return this.scheduledGroups && this.scheduledGroups.length > 0;
  }

  spawnEnemyGroup(group) {
    const count = Math.max(0, Number(group.count) || 0);
    if (group && group.type === 'dogRegime' && AudioManager.stopHorseAppearSfx) {
      AudioManager.stopHorseAppearSfx();
    }
    let enemyId = this.enemies.length;
    let playedAppearSound = false;
    for (let i = 0; i < count; i++) {
      if (group.type === 'bastard' && this.enemies.some(enemy => enemy.enemyType === 'bastard' && enemy.alive)) {
        continue;
      }

      const spawn = this.getSpawnPoint(group.side, i, count);
      const enemy = this.createEnemy(group.type, spawn.x, spawn.y, enemyId);
      if (!enemy) continue;

      this.enemies.push(enemy);
      if (!playedAppearSound) {
        this.playEnemyAppearSound(enemy.enemyType);
        playedAppearSound = true;
      }
      enemyId += 1;
    }
  }

  getBossMusicKey(wave) {
    for (const group of wave.enemies || []) {
      const enemyConfig = GAME_CONFIG.enemies[group.type] || {};
      const isBoss = enemyConfig.bossMusic === true || group.boss === true;
      if (!isBoss) continue;
      return group.bossMusicKey || enemyConfig.bossMusicKey || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.boss) || 'bossTheme';
    }
    return null;
  }

  handleWaveAudio(wave) {
    const bossMusicKey = this.getBossMusicKey(wave);

    if (bossMusicKey) {
      AudioManager.playSfx('bossAppear', 0.9);
      AudioManager.playMusic(bossMusicKey, true);
    } else {
      AudioManager.playSfx('waveStart', 0.55);
      const level = this.getLevelConfig();
      AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
    }
  }

  createEnemy(type, x, y, id) {
    if (type === 'zetnik') return new ZetnikEnemy(x, y, this.images, id);
    if (type === 'sucker') return new SuckerEnemy(x, y, this.images, id);
    if (type === 'bastard') return new BastardEnemy(x, y, this.images, id);
    if (GAME_CONFIG.enemies[type]) return new DogRegimeEnemy(x, y, this.images, id, type);
    console.warn('Unknown enemy type:', type);
    return null;
  }

  hasWaveBlockers() {
    return this.enemies.some(enemy => this.isWaveBlocker(enemy));
  }

  isWaveBlocker(enemy) {
    if (enemy && enemy.enemyType === 'zetnik' && typeof enemy.markEnteredPlayfield === 'function') {
      enemy.markEnteredPlayfield();
    }
    if (enemy && enemy.enemyType === 'zetnik' && enemy.alive && !enemy.remove &&
        enemy.hasEnteredPlayfield !== false &&
        typeof enemy.isPastEscapeMargin === 'function' && enemy.isPastEscapeMargin()) {
      if (typeof enemy.escapeOffscreen === 'function') enemy.escapeOffscreen();
      else {
        enemy.alive = false;
        enemy.hp = 0;
        enemy.remove = true;
        enemy.blocksWaveClear = false;
        enemy.pickupDropped = true;
      }
      return false;
    }
    return enemy && enemy.alive && enemy.blocksWaveClear !== false;
  }

  cleanupEscapedZetniks() {
    for (const enemy of this.enemies || []) {
      if (!enemy || enemy.enemyType !== 'zetnik' || !enemy.alive || enemy.remove) continue;
      if (typeof enemy.markEnteredPlayfield === 'function') enemy.markEnteredPlayfield();
      if (enemy.hasEnteredPlayfield !== false &&
          typeof enemy.isPastEscapeMargin === 'function' && enemy.isPastEscapeMargin()) {
        if (typeof enemy.escapeOffscreen === 'function') enemy.escapeOffscreen();
        else {
          enemy.alive = false;
          enemy.hp = 0;
          enemy.remove = true;
          enemy.blocksWaveClear = false;
          enemy.pickupDropped = true;
        }
      }
    }
  }

  getSpawnPoint(side, index, count) {
    const safeSide = side || 'right';
    const rowRatio = count <= 1 ? 0.5 : index / Math.max(1, count - 1);
    const y = GAME_CONFIG.laneTop + 28 + rowRatio * (GAME_CONFIG.laneBottom - GAME_CONFIG.laneTop - 56);

    if (safeSide === 'left') {
      return { x: 120 + index * 34, y };
    }

    if (safeSide === 'both') {
      const fromLeft = index % 2 === 0;
      return {
        x: fromLeft ? 110 + index * 18 : GAME_CONFIG.width - 110 - index * 18,
        y
      };
    }

    return { x: GAME_CONFIG.width - 130 - index * 34, y };
  }

  enemyHasPhysicalPresence(enemy) {
    if (!enemy || !enemy.alive || enemy.remove) return false;
    if (enemy.attackPositionLocked) return false;
    return !['jump', 'crash', 'pinBite', 'knockdown', 'dead', 'fallen', 'interrupted'].includes(enemy.state);
  }

  separateEnemies(dt = 16.67, force = false) {
    const active = this.enemies.filter(enemy => this.enemyHasPhysicalPresence(enemy));

    const iterations = force ? 4 : Math.max(1, GAME_CONFIG.enemySeparationIterations || 1);
    const strength = force ? 0.85 : Math.max(0, Math.min(1, GAME_CONFIG.enemySeparationStrength == null ? 0.5 : GAME_CONFIG.enemySeparationStrength));
    const dtScale = Math.max(0.65, Math.min(1.35, dt / 16.67));

    for (let pass = 0; pass < iterations; pass++) {
      for (let i = 0; i < active.length; i++) {
        const a = active[i];
        const arx = a.bodyRadiusX || GAME_CONFIG.enemyBodyRadiusX || 42;
        const ary = a.bodyRadiusY || GAME_CONFIG.enemyBodyRadiusY || 20;

        for (let j = i + 1; j < active.length; j++) {
          const b = active[j];
          const brx = b.bodyRadiusX || GAME_CONFIG.enemyBodyRadiusX || 42;
          const bry = b.bodyRadiusY || GAME_CONFIG.enemyBodyRadiusY || 20;
          const minX = arx + brx;
          const minY = ary + bry;
          let dx = b.x - a.x;
          let dy = b.y - a.y;

          if (dx === 0 && dy === 0) {
            const sign = (a.id || 0) <= (b.id || 0) ? 1 : -1;
            dx = sign * 0.01;
            dy = sign * 0.01;
          }

          const nx = dx / minX;
          const ny = dy / minY;
          const distSq = nx * nx + ny * ny;
          if (distSq >= 1) continue;

          const dist = Math.max(0.001, Math.sqrt(distSq));
          const overlap = (1 - dist) * strength * dtScale;
          const pushX = (nx / dist) * minX * overlap * 0.5;
          const pushY = (ny / dist) * minY * overlap * 0.5;

          a.x -= pushX;
          a.y -= pushY;
          b.x += pushX;
          b.y += pushY;

          if (a.clampToScreen) a.clampToScreen();
          if (b.clampToScreen) b.clampToScreen();
        }
      }
    }
  }

  restartCurrentLevel() {
    this.player.x = 190;
    this.player.y = 620;
    this.player.releaseFromPin();
    const level = this.getLevelConfig();
    AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
    this.spawnInitialWave();
  }

  nextScreen() {
    if (this.screenIndex < this.images.streets.length - 1) {
      this.screenIndex += 1;
      this.player.x = 190;
      this.player.y = 620;
      this.player.releaseFromPin();
      const level = this.getLevelConfig();
      AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
      this.spawnInitialWave();
    } else {
      this.game.setState('mainMenu');
    }
  }

  update(dt) {
    if (Input.consume('q')) this.debug = !this.debug;
    if (Input.consume('escape')) this.game.setState('mainMenu');

    if (this.hitStop > 0) {
      this.hitStop -= dt;
      return;
    }

    this.player.update(dt, this);
    this.updateLevelInteractives(dt);

    if (this.pendingWave) {
      this.pendingWaveTimer -= dt;
      if (this.pendingWaveTimer <= 0) {
        const wave = this.pendingWave;
        this.materializeWave(wave);
      }
    }

    this.updateScheduledGroups(dt);

    for (const enemy of this.enemies) {
      const wasAlive = enemy.alive;
      if (!wasAlive) this.maybeDropPickup(enemy, { source: 'system' });
      enemy.update(dt, this);
      if (wasAlive && !enemy.alive) this.maybeDropPickup(enemy, { source: 'system' });
    }
    this.cleanupEscapedZetniks();
    this.flushPickupDrops();
    for (const pickup of this.pickups) pickup.update(dt, this);
    this.separateEnemies(dt);
    this.enemies = this.enemies.filter(enemy => !enemy.remove);
    this.pickups = this.pickups.filter(pickup => !pickup.remove);

    if (this.nonBlockingWaveTimer > 0) {
      this.nonBlockingWaveTimer -= dt;
      if (this.nonBlockingWaveTimer <= 0) {
        const spawnedNext = this.spawnNextWave('afterWaveCleared');
        if (!spawnedNext) {
          this.encounterActive = false;
          this.encounterCleared = true;
        }
      }
    }

    if (this.encounterActive && !this.hasScheduledGroups() && !this.enemies.some(enemy => this.isWaveBlocker(enemy))) {
      AudioManager.playSfx('waveClear', 0.7);
      const spawnedNext = this.spawnNextWave('afterWaveCleared');
      if (!spawnedNext) {
        this.encounterActive = false;
        this.encounterCleared = true;
      }
    }

    if (this.encounterCleared && this.player.x > GAME_CONFIG.width - 95) {
      this.nextScreen();
    }

    if (this.player.hp <= 0) {
      if (this.game && this.game.handleHeroDefeat) this.game.handleHeroDefeat(this);
      else this.game.setState('characterSelect');
    }
  }

  draw(ctx) {
    const bg = this.getLevelBackgroundImage();
    if (bg) ctx.drawImage(bg, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    else {
      ctx.fillStyle = '#222';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    }
    this.drawLevelBackgroundEffects(ctx);

    ctx.fillStyle = 'rgba(255,255,255,0.025)';
    ctx.fillRect(0, GAME_CONFIG.laneTop, GAME_CONFIG.width, GAME_CONFIG.laneBottom - GAME_CONFIG.laneTop);
    if (this.drawLevelForegroundObjects) this.drawLevelForegroundObjects(ctx);

    const entities = [{ type: 'player', y: this.player.y, ref: this.player }];
    for (const enemy of this.enemies) entities.push({ type: 'enemy', y: enemy.y, ref: enemy });
    entities.sort((a, b) => a.y - b.y);

    for (const entity of entities) entity.ref.draw(ctx, this.debug);
    for (const pickup of this.pickups) pickup.draw(ctx);

    if (this.encounterCleared) {
      ctx.font = 'bold 42px Arial';
      ctx.fillStyle = 'lime';
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 5;
      ctx.strokeText('→', GAME_CONFIG.width - 90, 380);
      ctx.fillText('→', GAME_CONFIG.width - 90, 380);
    }

    HUD.draw(ctx, this);

    if (this.debug) {
      ctx.strokeStyle = 'rgba(255,255,255,0.25)';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, GAME_CONFIG.laneTop, GAME_CONFIG.width - 0, GAME_CONFIG.laneBottom - GAME_CONFIG.laneTop);
    }
  }

  dropPickup(type, x, y) {
    if (!type) return;
    const rawX = Number.isFinite(x) ? x : GAME_CONFIG.width / 2;
    const rawY = Number.isFinite(y) ? y : GAME_CONFIG.laneBottom;
    const safeX = Math.max(70, Math.min(GAME_CONFIG.width - 70, rawX));
    const safeY = Math.max(GAME_CONFIG.laneTop + 35, Math.min(GAME_CONFIG.laneBottom, rawY));
    if (!this.pendingPickupDrops) this.pendingPickupDrops = [];
    this.pendingPickupDrops.push({ type, x: safeX, y: safeY });
  }

  maybeDropPickup(enemy, options = {}) {
    if (!enemy || enemy.pickupDropped) return;
    enemy.pickupDropped = true;
    if (options.source !== 'player') return;
    if (enemy.enemyType !== 'zetnik') return;
    if (enemy.gundosMinion || enemy.gundosGuarding || enemy.redirectedToBoss) return;
    if (this.gundosArenaActive || this.gundosIntroActive || this.gundosVictoryPending) return;

    const rawX = Number.isFinite(enemy.x) ? enemy.x : GAME_CONFIG.width / 2;
    const rawY = Number.isFinite(enemy.y) ? enemy.y : GAME_CONFIG.laneBottom;
    const x = Math.max(70, Math.min(GAME_CONFIG.width - 70, rawX));
    const y = Math.max(GAME_CONFIG.laneTop + 35, Math.min(GAME_CONFIG.laneBottom, rawY));
    this.dropPickup('pirozhok', x, y);
  }

  flushPickupDrops() {
    if (!this.pendingPickupDrops || !this.pendingPickupDrops.length) return;
    for (const drop of this.pendingPickupDrops) {
      if (!drop || !drop.type) continue;
      this.pickups.push(new HealthPickup(drop.type, drop.x, drop.y, this.images));
    }
    this.pendingPickupDrops.length = 0;
  }

  tryCollectPickup(player) {
    if (!player || !this.pickups || !this.pickups.length) return false;
    for (const pickup of this.pickups) {
      if (!pickup || pickup.remove || pickup.floatTimer > 0) continue;
      if (pickup.collect(player)) return true;
    }
    return false;
  }
}



/* ===== src/devPanel.js ===== */
const DevPanel = {
  open: false,
  tab: 'PLAYER',
  tabs: ['PLAYER', 'DOG', 'SUCKER', 'LEVEL WAVES'],
  statusText: 'Ready',
  statusUntil: 0,
  selectedLevelIndex: 0,
  selectedWaveIndex: 0,
  selectedGroupIndex: 0,

  fieldGroups: {
    PLAYER: [
      { label: 'Boris speed', path: 'heroes.boris.speed', min: 0.5, max: 5, step: 0.05 },
      { label: 'Boris HP', path: 'heroes.boris.hp', min: 10, max: 300, step: 5 },
      { label: 'Boris damage', path: 'heroes.boris.damage', min: 1, max: 80, step: 1 },
      { label: 'Alexey speed', path: 'heroes.alexey.speed', min: 0.5, max: 5, step: 0.05 },
      { label: 'Alexey HP', path: 'heroes.alexey.hp', min: 10, max: 300, step: 5 },
      { label: 'Alexey damage', path: 'heroes.alexey.damage', min: 1, max: 80, step: 1 },
      { label: 'Anna speed', path: 'heroes.anna.speed', min: 0.5, max: 5, step: 0.05 },
      { label: 'Anna HP', path: 'heroes.anna.hp', min: 10, max: 300, step: 5 },
      { label: 'Anna damage', path: 'heroes.anna.damage', min: 1, max: 80, step: 1 },
      { label: 'Player scale', path: 'playerScale', min: 0.05, max: 0.22, step: 0.005 },
      { label: 'Walk frame ms', path: 'walkFrameMs', min: 80, max: 400, step: 10 }
    ],
    DOG: [
      { label: 'Dog speed', path: 'enemies.dogRegime.speed', min: 0.3, max: 4, step: 0.05 },
      { label: 'Dog HP', path: 'enemies.dogRegime.hp', min: 10, max: 300, step: 5 },
      { label: 'Dog damage', path: 'enemies.dogRegime.damage', min: 1, max: 60, step: 1 },
      { label: 'Dog scale', path: 'enemies.dogRegime.scale', min: 0.05, max: 0.25, step: 0.005 },
      { label: 'Enemy walk ms', path: 'enemyWalkFrameMs', min: 80, max: 500, step: 10 }
    ],
    SUCKER: [
      { label: 'Sucker speed', path: 'enemies.sucker.speed', min: 0.3, max: 4, step: 0.05 },
      { label: 'Sucker HP', path: 'enemies.sucker.hp', min: 20, max: 500, step: 5 },
      { label: 'Sucker damage', path: 'enemies.sucker.damage', min: 1, max: 60, step: 1 },
      { label: 'Sucker scale', path: 'enemies.sucker.scale', min: 0.05, max: 0.25, step: 0.005 },
      { label: 'Attack start dist', path: 'enemies.sucker.attackStartDistance', min: 100, max: 900, step: 20 },
      { label: 'Min dist', path: 'enemies.sucker.minDistance', min: 40, max: 500, step: 10 },
      { label: 'Align Y', path: 'enemies.sucker.alignToleranceY', min: 8, max: 90, step: 2 },
      { label: 'Slide speed', path: 'enemies.sucker.slideSpeed', min: 2, max: 24, step: 0.25 },
      { label: 'Slide range', path: 'enemies.sucker.slideRange', min: 120, max: 1100, step: 20 },
      { label: 'Windup ms', path: 'enemies.sucker.windupMs', min: 80, max: 1200, step: 20 },
      { label: 'Recovery ms', path: 'enemies.sucker.slideRecoveryMs', min: 100, max: 1400, step: 20 },
      { label: 'Interrupt recovery', path: 'enemies.sucker.interruptedRecoveryMs', min: 100, max: 2000, step: 25 },
      { label: 'Pin ms', path: 'enemies.sucker.pinDurationMs', min: 400, max: 3500, step: 50 },
      { label: 'Bite tick', path: 'enemies.sucker.biteTickMs', min: 150, max: 1200, step: 25 },
      { label: 'Bite damage', path: 'enemies.sucker.biteDamage', min: 1, max: 40, step: 1 },
      { label: 'Enemy scatter', path: 'enemies.sucker.otherEnemyScatterDistance', min: 0, max: 300, step: 10 }
    ]
  },

  init() {
    this.ensureLevels();
    this.load();
  },

  update(game) {
    if (!GAME_CONFIG.adminTuningEnabled) return;

    if (Input.consume('dev') || Input.consume('`') || Input.consume('ё')) {
      this.open = !this.open;
      this.syncSelectedLevelWithScene(game);
    }

    const click = Input.consumePointer();
    if (click && !this.open && click.x < 78 && click.y < 42) {
      this.open = true;
      this.syncSelectedLevelWithScene(game);
      return;
    }

    if (!this.open) return;
    if (Input.consume('escape')) {
      this.open = false;
      return;
    }

    if (click) this.handleClick(click, game);
  },

  handleClick(point, game) {
    const panel = this.panelRect();
    if (!this.inRect(point, panel)) return;

    const close = { x: panel.x + panel.w - 78, y: panel.y + 14, w: 56, h: 32 };
    if (this.inRect(point, close)) { this.open = false; return; }

    const tab = this.getClickedTab(point);
    if (tab) { this.tab = tab; this.setStatus('Tab: ' + tab); return; }

    if (this.handleFooterClick(point, game)) return;

    if (this.tab === 'LEVEL WAVES') {
      this.handleWaveEditorClick(point, game);
      return;
    }

    this.handleFieldsClick(point, game);
  },

  handleFieldsClick(point, game) {
    const fields = this.fieldGroups[this.tab] || [];
    const panel = this.panelRect();
    const startY = panel.y + 120;

    for (let i = 0; i < fields.length; i++) {
      const y = startY + i * 32;
      const minus = { x: panel.x + 350, y: y - 20, w: 34, h: 25 };
      const plus = { x: panel.x + 640, y: y - 20, w: 34, h: 25 };
      const bar = { x: panel.x + 395, y: y - 13, w: 235, h: 11 };
      const field = fields[i];

      if (this.inRect(point, minus)) { this.change(field, -field.step, game); return; }
      if (this.inRect(point, plus)) { this.change(field, field.step, game); return; }
      if (this.inRect(point, bar)) {
        const ratio = Math.max(0, Math.min(1, (point.x - bar.x) / bar.w));
        const raw = field.min + ratio * (field.max - field.min);
        this.setValue(field.path, this.roundToStep(raw, field.step));
        this.applyToCurrentScene(game);
        this.setStatus('Changed ' + field.label);
        return;
      }
    }
  },

  handleFooterClick(point, game) {
    const panel = this.panelRect();
    const y = panel.y + panel.h - 54;
    const buttons = {
      save: { x: panel.x + 24, y, w: 92, h: 34 },
      reset: { x: panel.x + 126, y, w: 96, h: 34 },
      apply: { x: panel.x + 232, y, w: 116, h: 34 },
      exportBtn: { x: panel.x + 358, y, w: 112, h: 34 },
      restart: { x: panel.x + 480, y, w: 112, h: 34 }
    };

    if (this.inRect(point, buttons.save)) { this.save(); return true; }
    if (this.inRect(point, buttons.reset)) { this.reset(game); return true; }
    if (this.inRect(point, buttons.apply)) { this.applyToCurrentScene(game); this.restartScene(game); this.setStatus('Applied + restarted'); return true; }
    if (this.inRect(point, buttons.exportBtn)) { this.exportConfig(); return true; }
    if (this.inRect(point, buttons.restart)) { this.restartScene(game); this.setStatus('Level restarted'); return true; }
    return false;
  },

  handleWaveEditorClick(point, game) {
    const r = this.waveEditorRects();
    const levelKeys = this.getLevelKeys();
    const level = this.getSelectedLevel();
    const wave = this.getSelectedWave();
    const group = this.getSelectedEnemyGroup(wave);
    const enemyTypes = this.getEnemyTypes();

    if (this.inRect(point, r.levelPrev)) { this.selectedLevelIndex = this.wrap(this.selectedLevelIndex - 1, levelKeys.length); this.selectedWaveIndex = 0; this.selectedGroupIndex = 0; this.applyLevelMusic(game); this.setStatus('Level: ' + this.getSelectedLevelKey()); return true; }
    if (this.inRect(point, r.levelNext)) { this.selectedLevelIndex = this.wrap(this.selectedLevelIndex + 1, levelKeys.length); this.selectedWaveIndex = 0; this.selectedGroupIndex = 0; this.applyLevelMusic(game); this.setStatus('Level: ' + this.getSelectedLevelKey()); return true; }
    if (this.inRect(point, r.musicPrev)) { this.changeLevelMusic(-1, game); return true; }
    if (this.inRect(point, r.musicNext)) { this.changeLevelMusic(1, game); return true; }
    if (this.inRect(point, r.wavePrev)) { this.selectedWaveIndex = Math.max(0, this.selectedWaveIndex - 1); this.selectedGroupIndex = 0; this.setStatus('Wave: ' + (this.selectedWaveIndex + 1)); return true; }
    if (this.inRect(point, r.waveNext)) { this.selectedWaveIndex = Math.min(level.waves.length - 1, this.selectedWaveIndex + 1); this.selectedGroupIndex = 0; this.setStatus('Wave: ' + (this.selectedWaveIndex + 1)); return true; }
    if (this.inRect(point, r.groupPrev)) { this.selectedGroupIndex = Math.max(0, this.selectedGroupIndex - 1); this.setStatus('Group: ' + (this.selectedGroupIndex + 1)); return true; }
    if (this.inRect(point, r.groupNext)) { this.selectedGroupIndex = Math.min(wave.enemies.length - 1, this.selectedGroupIndex + 1); this.setStatus('Group: ' + (this.selectedGroupIndex + 1)); return true; }
    if (this.inRect(point, r.typeBtn)) { group.type = this.nextValue(group.type, enemyTypes); this.restartScene(game); this.setStatus('Enemy type: ' + group.type); return true; }
    if (this.inRect(point, r.countMinus)) { group.count = Math.max(0, group.count - 1); this.restartScene(game); this.setStatus('Count: ' + group.count); return true; }
    if (this.inRect(point, r.countPlus)) { group.count = Math.min(12, group.count + 1); this.restartScene(game); this.setStatus('Count: ' + group.count); return true; }
    if (this.inRect(point, r.sideBtn)) { group.side = this.nextValue(group.side, ['right', 'left', 'both']); this.restartScene(game); this.setStatus('Side: ' + group.side); return true; }
    if (this.inRect(point, r.delayMinus)) { group.delayMs = Math.max(0, (Number(group.delayMs) || 0) - 500); this.restartScene(game); this.setStatus('Group delay: ' + this.formatDelay(group.delayMs)); return true; }
    if (this.inRect(point, r.delayPlus)) { group.delayMs = Math.min(60000, (Number(group.delayMs) || 0) + 500); this.restartScene(game); this.setStatus('Group delay: ' + this.formatDelay(group.delayMs)); return true; }
    if (this.inRect(point, r.triggerBtn)) { wave.trigger = this.nextValue(wave.trigger, ['onEnter', 'afterWaveCleared']); this.restartScene(game); this.setStatus('Trigger: ' + wave.trigger); return true; }
    if (this.inRect(point, r.addGroup)) { this.addEnemyGroup(game); return true; }
    if (this.inRect(point, r.removeGroup)) { this.removeEnemyGroup(game); return true; }
    if (this.inRect(point, r.addWave)) { this.addWave(game); return true; }
    if (this.inRect(point, r.removeWave)) { this.removeWave(game); return true; }
    if (this.inRect(point, r.copyWave)) { this.copyWave(game); return true; }

    return false;
  },

  change(field, delta, game) {
    const current = this.getValue(field.path);
    const next = Math.max(field.min, Math.min(field.max, this.roundToStep(current + delta, field.step)));
    this.setValue(field.path, next);
    this.applyToCurrentScene(game);
    this.setStatus(field.label + ': ' + next);
  },

  applyToCurrentScene(game) {
    if (!game.scene) return;
    const player = game.scene.player;
    if (player) {
      const hero = GAME_CONFIG.heroes[player.heroKey];
      player.speed = hero.speed;
      player.damage = hero.damage;
      player.maxHp = hero.hp;
      player.hp = Math.min(player.hp, player.maxHp);
    }
    for (const enemy of game.scene.enemies || []) {
      if (typeof enemy.applyTuning === 'function') enemy.applyTuning(false);
    }
  },

  restartScene(game) {
    if (game.scene && typeof game.scene.restartCurrentLevel === 'function') {
      game.scene.restartCurrentLevel();
      this.applyToCurrentScene(game);
    }
  },

  draw(ctx) {
    if (!GAME_CONFIG.adminTuningEnabled) return;

    if (!this.open) {
      ctx.fillStyle = 'rgba(0,0,0,0.45)';
      ctx.fillRect(8, 8, 58, 28);
      ctx.strokeStyle = 'rgba(255,255,255,0.55)';
      ctx.strokeRect(8, 8, 58, 28);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 14px Arial';
      ctx.fillText('DEV', 22, 27);
      return;
    }

    const panel = this.panelRect();
    ctx.fillStyle = 'rgba(0,0,0,0.90)';
    ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 24px Arial';
    ctx.fillText('DEVELOPER PANEL', panel.x + 22, panel.y + 38);
    ctx.font = '13px Arial';
    ctx.fillStyle = '#aaa';
    ctx.fillText('Tabs: balance, enemies, level waves, and per-level music. SAVE stores in localStorage.', panel.x + 22, panel.y + 58);

    this.drawButton(ctx, panel.x + panel.w - 78, panel.y + 14, 56, 32, 'X');
    this.drawTabs(ctx);

    if (this.tab === 'LEVEL WAVES') this.drawWaveEditor(ctx);
    else this.drawFields(ctx);

    this.drawFooter(ctx);
    this.drawStatus(ctx, panel);
  },

  drawTabs(ctx) {
    const panel = this.panelRect();
    for (let i = 0; i < this.tabs.length; i++) {
      const r = this.tabRect(i);
      const active = this.tabs[i] === this.tab;
      ctx.fillStyle = active ? 'rgba(255,255,255,0.22)' : 'rgba(255,255,255,0.08)';
      ctx.fillRect(r.x, r.y, r.w, r.h);
      ctx.strokeStyle = active ? '#fff' : 'rgba(255,255,255,0.45)';
      ctx.strokeRect(r.x, r.y, r.w, r.h);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 13px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(this.tabs[i], r.x + r.w / 2, r.y + 22);
      ctx.textAlign = 'left';
    }
  },

  drawFields(ctx) {
    const fields = this.fieldGroups[this.tab] || [];
    const panel = this.panelRect();
    const startY = panel.y + 120;
    for (let i = 0; i < fields.length; i++) this.drawField(ctx, fields[i], panel.x + 36, startY + i * 32);
  },

  drawField(ctx, field, x, y) {
    const value = this.getValue(field.path);
    const ratio = (value - field.min) / (field.max - field.min);
    ctx.font = '14px Arial';
    ctx.fillStyle = '#fff';
    ctx.fillText(field.label, x, y);
    ctx.fillStyle = '#ccc';
    ctx.fillText(String(value), x + 220, y);

    this.drawButton(ctx, x + 314, y - 20, 34, 25, '-');
    ctx.fillStyle = '#222';
    ctx.fillRect(x + 359, y - 13, 235, 11);
    ctx.fillStyle = '#55ccff';
    ctx.fillRect(x + 359, y - 13, 235 * Math.max(0, Math.min(1, ratio)), 11);
    ctx.strokeStyle = '#777';
    ctx.strokeRect(x + 359, y - 13, 235, 11);
    this.drawButton(ctx, x + 604, y - 20, 34, 25, '+');
  },

  drawWaveEditor(ctx) {
    const r = this.waveEditorRects();
    const level = this.getSelectedLevel();
    const wave = this.getSelectedWave();
    const group = this.getSelectedEnemyGroup(wave);
    const levelKey = this.getSelectedLevelKey();
    const musicKeys = this.getMusicKeys();

    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.fillRect(r.box.x, r.box.y, r.box.w, r.box.h);
    ctx.strokeStyle = 'rgba(255,255,255,0.35)';
    ctx.strokeRect(r.box.x, r.box.y, r.box.w, r.box.h);

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 18px Arial';
    ctx.fillText('LEVEL WAVE EDITOR', r.box.x + 20, r.box.y + 32);

    this.drawRowLabel(ctx, 'Level:', r.box.x + 24, r.box.y + 76);
    this.drawButton(ctx, r.levelPrev.x, r.levelPrev.y, r.levelPrev.w, r.levelPrev.h, '<');
    this.drawButton(ctx, r.levelNext.x, r.levelNext.y, r.levelNext.w, r.levelNext.h, '>');
    this.drawValue(ctx, levelKey + ' / ' + level.name, r.box.x + 145, r.box.y + 76);

    this.drawRowLabel(ctx, 'Music:', r.box.x + 24, r.box.y + 118);
    this.drawButton(ctx, r.musicPrev.x, r.musicPrev.y, r.musicPrev.w, r.musicPrev.h, '<');
    this.drawButton(ctx, r.musicNext.x, r.musicNext.y, r.musicNext.w, r.musicNext.h, '>');
    this.drawValue(ctx, (level.music || 'levelTheme') + '  [' + musicKeys.length + ' tracks]', r.box.x + 145, r.box.y + 118);

    this.drawRowLabel(ctx, 'Wave:', r.box.x + 24, r.box.y + 160);
    this.drawButton(ctx, r.wavePrev.x, r.wavePrev.y, r.wavePrev.w, r.wavePrev.h, '<');
    this.drawButton(ctx, r.waveNext.x, r.waveNext.y, r.waveNext.w, r.waveNext.h, '>');
    this.drawValue(ctx, String(this.selectedWaveIndex + 1) + ' / ' + level.waves.length, r.box.x + 145, r.box.y + 160);

    this.drawRowLabel(ctx, 'Group:', r.box.x + 24, r.box.y + 202);
    this.drawButton(ctx, r.groupPrev.x, r.groupPrev.y, r.groupPrev.w, r.groupPrev.h, '<');
    this.drawButton(ctx, r.groupNext.x, r.groupNext.y, r.groupNext.w, r.groupNext.h, '>');
    this.drawValue(ctx, String(this.selectedGroupIndex + 1) + ' / ' + wave.enemies.length, r.box.x + 145, r.box.y + 202);

    this.drawRowLabel(ctx, 'Enemy type:', r.box.x + 24, r.box.y + 248);
    this.drawButton(ctx, r.typeBtn.x, r.typeBtn.y, r.typeBtn.w, r.typeBtn.h, group.type);

    this.drawRowLabel(ctx, 'Count:', r.box.x + 24, r.box.y + 294);
    this.drawButton(ctx, r.countMinus.x, r.countMinus.y, r.countMinus.w, r.countMinus.h, '-');
    this.drawButton(ctx, r.countPlus.x, r.countPlus.y, r.countPlus.w, r.countPlus.h, '+');
    this.drawValue(ctx, String(group.count), r.box.x + 145, r.box.y + 294);

    this.drawRowLabel(ctx, 'Side:', r.box.x + 24, r.box.y + 340);
    this.drawButton(ctx, r.sideBtn.x, r.sideBtn.y, r.sideBtn.w, r.sideBtn.h, String(group.side).toUpperCase());

    this.drawRowLabel(ctx, 'Delay:', r.box.x + 24, r.box.y + 386);
    this.drawButton(ctx, r.delayMinus.x, r.delayMinus.y, r.delayMinus.w, r.delayMinus.h, '-');
    this.drawButton(ctx, r.delayPlus.x, r.delayPlus.y, r.delayPlus.w, r.delayPlus.h, '+');
    this.drawValue(ctx, this.formatDelay(group.delayMs), r.box.x + 145, r.box.y + 386);

    this.drawRowLabel(ctx, 'Trigger:', r.box.x + 24, r.box.y + 432);
    this.drawButton(ctx, r.triggerBtn.x, r.triggerBtn.y, r.triggerBtn.w, r.triggerBtn.h, wave.trigger);

    this.drawButton(ctx, r.addGroup.x, r.addGroup.y, r.addGroup.w, r.addGroup.h, 'ADD GROUP');
    this.drawButton(ctx, r.removeGroup.x, r.removeGroup.y, r.removeGroup.w, r.removeGroup.h, 'DEL GROUP');
    this.drawButton(ctx, r.addWave.x, r.addWave.y, r.addWave.w, r.addWave.h, 'ADD WAVE');
    this.drawButton(ctx, r.removeWave.x, r.removeWave.y, r.removeWave.w, r.removeWave.h, 'DEL WAVE');
    this.drawButton(ctx, r.copyWave.x, r.copyWave.y, r.copyWave.w, r.copyWave.h, 'COPY WAVE');
  },

  drawFooter(ctx) {
    const panel = this.panelRect();
    const y = panel.y + panel.h - 54;
    this.drawButton(ctx, panel.x + 24, y, 92, 34, 'SAVE');
    this.drawButton(ctx, panel.x + 126, y, 96, 34, 'RESET');
    this.drawButton(ctx, panel.x + 232, y, 116, 34, 'APPLY');
    this.drawButton(ctx, panel.x + 358, y, 112, 34, 'EXPORT');
    this.drawButton(ctx, panel.x + 480, y, 112, 34, 'RESTART');
  },

  drawButton(ctx, x, y, w, h, text) {
    ctx.fillStyle = 'rgba(255,255,255,0.12)';
    ctx.fillRect(x, y, w, h);
    ctx.strokeStyle = 'rgba(255,255,255,0.75)';
    ctx.strokeRect(x, y, w, h);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 13px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(text, x + w / 2, y + h / 2 + 5);
    ctx.textAlign = 'left';
  },

  drawRowLabel(ctx, text, x, y) {
    ctx.font = '14px Arial';
    ctx.fillStyle = '#ccc';
    ctx.fillText(text, x, y);
  },

  drawValue(ctx, text, x, y) {
    ctx.font = 'bold 14px Arial';
    ctx.fillStyle = '#fff';
    ctx.fillText(text, x, y);
  },

  drawStatus(ctx, panel) {
    ctx.font = '13px Arial';
    ctx.fillStyle = performance.now() < this.statusUntil ? '#8cff8c' : '#aaa';
    ctx.fillText('Status: ' + this.statusText, panel.x + 620, panel.y + panel.h - 32);
  },

  panelRect() {
    return { x: 24, y: 24, w: 1050, h: 670 };
  },

  tabRect(index) {
    const panel = this.panelRect();
    return { x: panel.x + 24 + index * 152, y: panel.y + 76, w: 142, h: 34 };
  },

  getClickedTab(point) {
    for (let i = 0; i < this.tabs.length; i++) if (this.inRect(point, this.tabRect(i))) return this.tabs[i];
    return null;
  },

  waveEditorRects() {
    const panel = this.panelRect();
    const x = panel.x + 36;
    const y = panel.y + 124;
    return {
      box: { x, y, w: 700, h: 492 },
      levelPrev: { x: x + 92, y: y + 54, w: 36, h: 26 },
      levelNext: { x: x + 642, y: y + 54, w: 36, h: 26 },
      musicPrev: { x: x + 92, y: y + 96, w: 36, h: 26 },
      musicNext: { x: x + 642, y: y + 96, w: 36, h: 26 },
      wavePrev: { x: x + 92, y: y + 138, w: 36, h: 26 },
      waveNext: { x: x + 190, y: y + 138, w: 36, h: 26 },
      groupPrev: { x: x + 92, y: y + 180, w: 36, h: 26 },
      groupNext: { x: x + 190, y: y + 180, w: 36, h: 26 },
      typeBtn: { x: x + 132, y: y + 226, w: 160, h: 30 },
      countMinus: { x: x + 100, y: y + 272, w: 36, h: 26 },
      countPlus: { x: x + 180, y: y + 272, w: 36, h: 26 },
      sideBtn: { x: x + 132, y: y + 318, w: 160, h: 30 },
      delayMinus: { x: x + 100, y: y + 364, w: 36, h: 26 },
      delayPlus: { x: x + 180, y: y + 364, w: 36, h: 26 },
      triggerBtn: { x: x + 132, y: y + 410, w: 210, h: 30 },
      addGroup: { x: x + 24, y: y + 452, w: 110, h: 34 },
      removeGroup: { x: x + 146, y: y + 452, w: 110, h: 34 },
      addWave: { x: x + 280, y: y + 452, w: 110, h: 34 },
      removeWave: { x: x + 402, y: y + 452, w: 110, h: 34 },
      copyWave: { x: x + 524, y: y + 452, w: 110, h: 34 }
    };
  },

  inRect(p, r) {
    return p.x >= r.x && p.x <= r.x + r.w && p.y >= r.y && p.y <= r.y + r.h;
  },

  getValue(path) {
    return path.split('.').reduce((obj, key) => obj[key], GAME_CONFIG);
  },

  setValue(path, value) {
    const parts = path.split('.');
    let obj = GAME_CONFIG;
    for (let i = 0; i < parts.length - 1; i++) obj = obj[parts[i]];
    obj[parts[parts.length - 1]] = value;
  },

  getEnemyTypes() {
    return Object.keys(GAME_CONFIG.enemies || {});
  },

  getMusicKeys() {
    const keys = Object.keys((Assets.audio && Assets.audio.music) || {});
    return keys.length ? keys : ['levelTheme'];
  },

  changeLevelMusic(direction, game) {
    const level = this.getSelectedLevel();
    const musicKeys = this.getMusicKeys();
    const current = level.music || 'levelTheme';
    const currentIndex = Math.max(0, musicKeys.indexOf(current));
    level.music = musicKeys[this.wrap(currentIndex + direction, musicKeys.length)];
    this.applyLevelMusic(game);
    this.setStatus('Level music: ' + level.music);
  },

  applyLevelMusic(game) {
    const level = this.getSelectedLevel();
    if (game && game.scene && game.scene.getLevelKey && game.scene.getLevelKey() === this.getSelectedLevelKey()) {
      AudioManager.playMusic(level.music || 'levelTheme', true);
    }
  },

  getLevelKeys() {
    this.ensureLevels();
    return GAME_CONFIG.levelOrder || Object.keys(GAME_CONFIG.levels);
  },

  getSelectedLevelKey() {
    const keys = this.getLevelKeys();
    this.selectedLevelIndex = this.wrap(this.selectedLevelIndex, keys.length);
    return keys[this.selectedLevelIndex];
  },

  getSelectedLevel() {
    const key = this.getSelectedLevelKey();
    if (!GAME_CONFIG.levels[key]) GAME_CONFIG.levels[key] = { name: key, waves: [] };
    if (!GAME_CONFIG.levels[key].music) GAME_CONFIG.levels[key].music = 'levelTheme';
    if (!GAME_CONFIG.levels[key].waves || GAME_CONFIG.levels[key].waves.length === 0) {
      GAME_CONFIG.levels[key].waves = [this.createDefaultWave('onEnter')];
    }
    this.selectedWaveIndex = Math.min(this.selectedWaveIndex, GAME_CONFIG.levels[key].waves.length - 1);
    return GAME_CONFIG.levels[key];
  },

  getSelectedWave() {
    const level = this.getSelectedLevel();
    return level.waves[this.selectedWaveIndex];
  },

  getSelectedEnemyGroup(wave) {
    if (!wave.enemies || wave.enemies.length === 0) wave.enemies = [{ type: this.getEnemyTypes()[0] || 'dogRegime', count: 1, side: 'right' }];
    this.selectedGroupIndex = Math.min(this.selectedGroupIndex, wave.enemies.length - 1);
    return wave.enemies[this.selectedGroupIndex];
  },

  formatDelay(delayMs) {
    const seconds = Math.max(0, Number(delayMs) || 0) / 1000;
    return seconds.toFixed(seconds % 1 === 0 ? 0 : 1) + 's';
  },

  syncSelectedLevelWithScene(game) {
    if (!game.scene || typeof game.scene.getLevelKey !== 'function') return;
    const keys = this.getLevelKeys();
    const index = keys.indexOf(game.scene.getLevelKey());
    if (index >= 0) this.selectedLevelIndex = index;
    this.selectedWaveIndex = Math.max(0, game.scene.currentWaveIndex || 0);
    this.selectedGroupIndex = 0;
  },

  createDefaultWave(trigger = 'afterWaveCleared') {
    return { trigger, enemies: [{ type: 'dogRegime', count: 1, side: 'right', delayMs: 0 }] };
  },

  addEnemyGroup(game) {
    const wave = this.getSelectedWave();
    wave.enemies.push({ type: 'dogRegime', count: 1, side: 'right', delayMs: 0 });
    this.selectedGroupIndex = wave.enemies.length - 1;
    this.restartScene(game);
    this.setStatus('Enemy group added');
  },

  removeEnemyGroup(game) {
    const wave = this.getSelectedWave();
    if (wave.enemies.length <= 1) { this.setStatus('Cannot remove last group'); return; }
    wave.enemies.splice(this.selectedGroupIndex, 1);
    this.selectedGroupIndex = Math.max(0, this.selectedGroupIndex - 1);
    this.restartScene(game);
    this.setStatus('Enemy group removed');
  },

  addWave(game) {
    const level = this.getSelectedLevel();
    level.waves.push(this.createDefaultWave('afterWaveCleared'));
    this.selectedWaveIndex = level.waves.length - 1;
    this.selectedGroupIndex = 0;
    this.restartScene(game);
    this.setStatus('Wave added');
  },

  removeWave(game) {
    const level = this.getSelectedLevel();
    if (level.waves.length <= 1) { this.setStatus('Cannot remove last wave'); return; }
    level.waves.splice(this.selectedWaveIndex, 1);
    this.selectedWaveIndex = Math.max(0, this.selectedWaveIndex - 1);
    this.selectedGroupIndex = 0;
    this.restartScene(game);
    this.setStatus('Wave removed');
  },

  copyWave(game) {
    const level = this.getSelectedLevel();
    const copy = JSON.parse(JSON.stringify(this.getSelectedWave()));
    level.waves.splice(this.selectedWaveIndex + 1, 0, copy);
    this.selectedWaveIndex += 1;
    this.selectedGroupIndex = 0;
    this.restartScene(game);
    this.setStatus('Wave copied');
  },

  ensureLevels() {
    if (!GAME_CONFIG.levelOrder) GAME_CONFIG.levelOrder = ['street01', 'street02', 'street03'];
    if (!GAME_CONFIG.levels) GAME_CONFIG.levels = {};
    for (const key of GAME_CONFIG.levelOrder) {
      if (!GAME_CONFIG.levels[key]) GAME_CONFIG.levels[key] = { name: key, music: 'levelTheme', waves: [this.createDefaultWave('onEnter')] };
      if (!GAME_CONFIG.levels[key].music) GAME_CONFIG.levels[key].music = 'levelTheme';
      if (!GAME_CONFIG.levels[key].waves || GAME_CONFIG.levels[key].waves.length === 0) {
        GAME_CONFIG.levels[key].waves = [this.createDefaultWave('onEnter')];
      }
      for (const wave of GAME_CONFIG.levels[key].waves) {
        if (!wave.enemies || wave.enemies.length === 0) wave.enemies = [{ type: 'dogRegime', count: 1, side: 'right' }];
        for (const group of wave.enemies) {
          if (!group.type) group.type = 'dogRegime';
          if (group.count == null) group.count = 1;
          if (!group.side) group.side = 'right';
          if (group.delayMs == null) group.delayMs = 0;
        }
      }
    }
  },

  nextValue(current, values) {
    const index = values.indexOf(current);
    return values[(index + 1) % values.length];
  },

  wrap(index, length) {
    if (length <= 0) return 0;
    return ((index % length) + length) % length;
  },

  roundToStep(value, step) {
    const precision = String(step).includes('.') ? String(step).split('.')[1].length : 0;
    return Number((Math.round(value / step) * step).toFixed(precision));
  },

  save() {
    localStorage.setItem('streetsOfRussia.tuning', JSON.stringify(GAME_CONFIG));
    this.setStatus('Saved to localStorage');
  },

  load() {
    const saved = localStorage.getItem('streetsOfRussia.tuning');
    if (!saved) return;
    try {
      const data = JSON.parse(saved);
      this.deepMerge(GAME_CONFIG, data);
      this.migrateBuildDefaults(data);
      this.migrateConfig();
      this.ensureLevels();
      this.setStatus('Loaded saved tuning');
    } catch (error) {
      console.warn('Failed to load tuning', error);
      this.setStatus('Failed to load saved tuning');
    }
  },

  migrateBuildDefaults(savedConfig) {
    if (!savedConfig || savedConfig.buildVersion === DEFAULT_GAME_CONFIG.buildVersion) return;

    const defaults = {
      buildVersion: DEFAULT_GAME_CONFIG.buildVersion,
      'heroes.alexey.speed': DEFAULT_GAME_CONFIG.heroes.alexey.speed,
      'heroes.anna.speed': DEFAULT_GAME_CONFIG.heroes.anna.speed,
      'heroes.boris.speed': DEFAULT_GAME_CONFIG.heroes.boris.speed,
      'enemies.dogRegime.speed': DEFAULT_GAME_CONFIG.enemies.dogRegime.speed,
      'enemies.zetnik.speed': DEFAULT_GAME_CONFIG.enemies.zetnik.speed,
      'enemies.sucker.speed': DEFAULT_GAME_CONFIG.enemies.sucker.speed,
      'enemies.sucker.slideSpeed': DEFAULT_GAME_CONFIG.enemies.sucker.slideSpeed,
      'enemies.sucker.fastRetreatSpeed': DEFAULT_GAME_CONFIG.enemies.sucker.fastRetreatSpeed,
      'enemies.sucker.fastRetreatMs': DEFAULT_GAME_CONFIG.enemies.sucker.fastRetreatMs,
      'enemies.sucker.hitsBeforeFastRetreat': DEFAULT_GAME_CONFIG.enemies.sucker.hitsBeforeFastRetreat,
      'enemies.bastard.speed': DEFAULT_GAME_CONFIG.enemies.bastard.speed,
      enemyOffscreenMargin: DEFAULT_GAME_CONFIG.enemyOffscreenMargin,
      'enemies.horse.speed': 2.025,
      'enemies.horse.scale': 0.13,
      'enemies.horse.walkScale': 0.95,
      'enemies.horse.visibleHeight': 0,
      'enemies.horse.attackScale': 1,
      'enemies.horse.finalAttackScale': 1.31,
      'enemies.horse.attackWindupMs': 820,
      'enemies.horse.attackActiveMs': 560,
      'enemies.horse.attackRecoveryMs': 400,
      'enemies.horse.minDistanceX': 120,
      'enemies.horse.preferredDistanceX': 190,
      'enemies.horse.attackMinDistanceX': 115,
      'enemies.horse.attackMaxDistanceX': 255,
      'enemies.horse.attackRangeX': 265,
      'enemies.horse.clubReachForward': 310,
      'enemies.gundos.speed': 1.875,
      'enemies.gundos.entranceY': 720,
      'enemies.gundos.arenaBottom': 720,
      'enemies.gundos.deathHoldMs': 5000,
      'enemies.gundos.victoryDelayMs': 4800,
      'levels.street01.interactives.0.hitbox.x': 342,
      'levels.street01.interactives.0.hitbox.y': 272,
      'levels.street01.interactives.0.hitbox.w': 128,
      'levels.street01.interactives.0.hitbox.h': 146
    };

    for (const path of Object.keys(defaults)) {
      const value = defaults[path];
      if (value !== undefined) this.setValue(path, value);
    }
  },

  migrateConfig() {
    const sucker = GAME_CONFIG.enemies && GAME_CONFIG.enemies.sucker;
    if (sucker) {
      if (sucker.attackStartDistance === undefined && sucker.preferredDistance !== undefined) sucker.attackStartDistance = sucker.preferredDistance;
      if (sucker.interruptedRecoveryMs === undefined) sucker.interruptedRecoveryMs = sucker.slideRecoveryMs || 900;
    }
    this.ensureLevels();
  },

  reset(game) {
    this.deepMerge(GAME_CONFIG, JSON.parse(JSON.stringify(DEFAULT_GAME_CONFIG)));
    localStorage.removeItem('streetsOfRussia.tuning');
    this.ensureLevels();
    this.selectedLevelIndex = 0;
    this.selectedWaveIndex = 0;
    this.selectedGroupIndex = 0;
    this.restartScene(game);
    this.applyToCurrentScene(game);
    this.setStatus('Reset to default config');
  },

  exportConfig() {
    const exportData = {
      buildVersion: GAME_CONFIG.buildVersion,
      exportedAt: new Date().toISOString(),
      settings: GAME_CONFIG.settings,
      audio: GAME_CONFIG.audio,
      playerScale: GAME_CONFIG.playerScale,
      enemyScale: GAME_CONFIG.enemyScale,
      walkFrameMs: GAME_CONFIG.walkFrameMs,
      enemyWalkFrameMs: GAME_CONFIG.enemyWalkFrameMs,
      heroes: GAME_CONFIG.heroes,
      enemies: GAME_CONFIG.enemies,
      levelOrder: GAME_CONFIG.levelOrder,
      levels: GAME_CONFIG.levels
    };
    const text = JSON.stringify(exportData, null, 2);
    console.log('STREETS_OF_RUSSIA_TUNING_EXPORT');
    console.log(text);
    this.downloadTextFile('streets-of-russia-dev-export.json', text, 'application/json');

    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text)
        .then(() => this.setStatus('Export downloaded + copied'))
        .catch(() => this.setStatus('Export downloaded + printed'));
    } else {
      this.setStatus('Export downloaded + printed');
    }
  },

  downloadTextFile(filename, text, mimeType = 'text/plain') {
    if (typeof Blob === 'undefined' || typeof URL === 'undefined' || !document.createElement) return false;
    try {
      const blob = new Blob([text], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      link.style.display = 'none';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      return true;
    } catch (error) {
      console.warn('Failed to download export', error);
      return false;
    }
  },

  setStatus(text) {
    this.statusText = text;
    this.statusUntil = performance.now() + 1800;
  },

  deepMerge(target, source) {
    for (const key of Object.keys(source)) {
      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
        if (!target[key]) target[key] = {};
        this.deepMerge(target[key], source[key]);
      } else {
        target[key] = source[key];
      }
    }
  }
};



/* ===== src/devPanelDogAiPatch.js ===== */
(() => {
  if (!window.DevPanel && typeof DevPanel === 'undefined') return;
  const panel = window.DevPanel || DevPanel;
  if (!panel.fieldGroups || !panel.fieldGroups.DOG) return;

  const existing = new Set(panel.fieldGroups.DOG.map(field => field.path));
  const add = field => {
    if (!existing.has(field.path)) {
      panel.fieldGroups.DOG.push(field);
      existing.add(field.path);
    }
  };

  add({ label: 'Min dist X', path: 'enemies.dogRegime.minDistanceX', min: 20, max: 160, step: 2 });
  add({ label: 'Preferred dist X', path: 'enemies.dogRegime.preferredDistanceX', min: 40, max: 240, step: 2 });
  add({ label: 'Attack range X', path: 'enemies.dogRegime.attackRangeX', min: 30, max: 180, step: 2 });
  add({ label: 'Attack range Y', path: 'enemies.dogRegime.attackRangeY', min: 14, max: 90, step: 2 });
  add({ label: 'Max attackers', path: 'enemies.dogRegime.maxAttackers', min: 1, max: 4, step: 1 });
  add({ label: 'Decision min ms', path: 'enemies.dogRegime.decisionMinMs', min: 120, max: 1200, step: 20 });
  add({ label: 'Decision max ms', path: 'enemies.dogRegime.decisionMaxMs', min: 200, max: 2000, step: 20 });
  add({ label: 'Strafe chance', path: 'enemies.dogRegime.strafeChance', min: 0, max: 1, step: 0.05 });
  add({ label: 'Retreat chance', path: 'enemies.dogRegime.retreatChance', min: 0, max: 1, step: 0.05 });
  add({ label: 'Attack chance', path: 'enemies.dogRegime.attackChance', min: 0, max: 1, step: 0.05 });
  add({ label: 'Slot spacing X', path: 'enemies.dogRegime.slotSpacingX', min: 0, max: 180, step: 4 });
  add({ label: 'Slot spacing Y', path: 'enemies.dogRegime.slotSpacingY', min: 0, max: 120, step: 4 });
  add({ label: 'Flank distance X', path: 'enemies.dogRegime.flankDistanceX', min: 60, max: 240, step: 4 });
  add({ label: 'Pressure distance X', path: 'enemies.dogRegime.pressureDistanceX', min: 80, max: 320, step: 4 });

  if (typeof DogRegimeEnemy === 'undefined' || DogRegimeEnemy.prototype.clubReachPatchApplied) return;

  const overlaps = (a, b) => a && b &&
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y;

  const padded = (box, padX = 0, padY = 0) => ({
    x: box.x - padX,
    y: box.y - padY,
    w: box.w + padX * 2,
    h: box.h + padY * 2
  });

  DogRegimeEnemy.prototype.getClubReachBox = function () {
    const reachForward = this.clubReachForward || 142;
    const reachBack = this.clubReachBack || 16;
    return {
      x: this.facing === 1 ? this.x - reachBack : this.x - reachForward,
      y: this.y - 126,
      w: reachForward + reachBack,
      h: 62
    };
  };

  DogRegimeEnemy.prototype.canClubReachPlayer = function (player, anticipation = false) {
    if (!player || typeof player.getBodyBox !== 'function') return false;
    const body = player.getBodyBox();
    const padX = anticipation ? 10 : 0;
    const padY = anticipation ? 8 : 0;
    return overlaps(this.getClubReachBox(), padded(body, padX, padY));
  };

  const originalApplyTuning = DogRegimeEnemy.prototype.applyTuning;
  DogRegimeEnemy.prototype.applyTuning = function (resetHp = false) {
    if (typeof originalApplyTuning === 'function') originalApplyTuning.call(this, resetHp);
    const config = (GAME_CONFIG.enemies && GAME_CONFIG.enemies[this.enemyType]) || {};
    this.clubReachForward = config.clubReachForward || 142;
    this.clubReachBack = config.clubReachBack || 16;
    this.preferredDistanceX = config.preferredDistanceX || 64;
    this.attackMinDistanceX = config.attackMinDistanceX || 30;
    this.attackMaxDistanceX = config.attackMaxDistanceX || 128;
    this.attackRangeX = Math.max(config.attackRangeX || 0, this.attackMaxDistanceX);
    this.attackWindupMs = config.attackWindupMs || GAME_CONFIG.enemyWindupMs;
    this.attackActiveMs = config.attackActiveMs || GAME_CONFIG.enemyActiveMs;
    this.attackRecoveryMs = config.attackRecoveryMs || GAME_CONFIG.enemyRecoveryMs;
  };

  DogRegimeEnemy.prototype.isInAttackRange = function (player) {
    return this.canClubReachPlayer(player, true);
  };

  const originalMoveWithSpacing = DogRegimeEnemy.prototype.moveWithSpacing;
  DogRegimeEnemy.prototype.moveWithSpacing = function (dt, scene, canAttackNow) {
    const player = scene && scene.player;
    if (player && this.intent === 'attack' && !this.canClubReachPlayer(player, true)) {
      const desiredSide = Math.sign(player.x - this.x || this.facing || 1);
      this.facing = desiredSide;
      const moveX = Math.sign(player.x - this.x);
      const moveY = Math.abs(player.y - this.y) > this.attackRangeY * 0.55 ? Math.sign(player.y - this.y) : 0;
      this.applyMovement(moveX, moveY, dt);
      return;
    }
    if (typeof originalMoveWithSpacing === 'function') originalMoveWithSpacing.call(this, dt, scene, canAttackNow);
  };

  DogRegimeEnemy.prototype.updateAttack = function (dt, scene) {
    this.attackTimer += dt;
    const windupMs = this.attackWindupMs || GAME_CONFIG.enemyWindupMs;
    const activeMs = this.attackActiveMs || GAME_CONFIG.enemyActiveMs;
    const recoveryMs = this.attackRecoveryMs || GAME_CONFIG.enemyRecoveryMs;
    const activeStart = windupMs;
    const activeEnd = windupMs + activeMs;

    if (!this.attackHasHit && this.attackTimer >= activeStart && this.attackTimer <= activeEnd) {
      const player = scene.player;
      if (this.canClubReachPlayer(player, false)) {
        const hit = player.receiveDamage(this.damage, {
          source: 'melee',
          knockbackX: this.facing * 18
        });
        if (hit) scene.hitStop = 42;
      }
      this.attackHasHit = true;
    }

    if (this.attackTimer >= windupMs + activeMs + recoveryMs) {
      this.state = 'walk';
      this.intent = Math.random() < 0.58 ? 'retreat' : 'strafe';
      this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
      this.retreatTimer = this.postAttackRetreatMs;
      this.cooldown = this.attackCooldownMinMs + Math.random() * Math.max(1, this.attackCooldownMaxMs - this.attackCooldownMinMs);
      this.attackTimer = 0;
      this.attackHasHit = false;
    }
  };

  const originalDraw = DogRegimeEnemy.prototype.draw;
  DogRegimeEnemy.prototype.draw = function (ctx, debug = false) {
    if (typeof originalDraw === 'function') originalDraw.call(this, ctx, debug);
    if (debug && this.alive && typeof this.getClubReachBox === 'function') {
      const box = this.getClubReachBox();
      ctx.strokeStyle = 'rgba(255,210,0,0.9)';
      ctx.lineWidth = 2;
      ctx.strokeRect(box.x, box.y, box.w, box.h);
    }
  };

  DogRegimeEnemy.prototype.clubReachPatchApplied = true;
})();



/* ===== src/walkZonePatch.js ===== */
/*
 * Configurable walk-zone patch for Streets of Russia.
 * Adds per-level movement bounds that can be tuned from the Developer Panel.
 */
(function () {
  if (typeof GAME_CONFIG === 'undefined') return;

  const EXTRA_BOTTOM_TUNING = 220;

  const DEFAULT_ZONE = {
    left: 70,
    right: 1210,
    top: 515,
    bottom: 675
  };

  const DEFAULT_PLAYER_START = {
    x: 190,
    y: 620
  };

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function num(value, fallback) {
    const n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }

  function bottomTuningMax() {
    return GAME_CONFIG.height + EXTRA_BOTTOM_TUNING;
  }

  function levelKeys() {
    return GAME_CONFIG.levelOrder || Object.keys(GAME_CONFIG.levels || {});
  }

  function ensureLevelArea(level) {
    if (!level) return;
    if (!level.walkZone) level.walkZone = {};
    level.walkZone.left = num(level.walkZone.left, DEFAULT_ZONE.left);
    level.walkZone.right = num(level.walkZone.right, DEFAULT_ZONE.right);
    level.walkZone.top = num(level.walkZone.top, GAME_CONFIG.laneTop || DEFAULT_ZONE.top);
    level.walkZone.bottom = num(level.walkZone.bottom, GAME_CONFIG.laneBottom || DEFAULT_ZONE.bottom);

    if (!level.playerStart) level.playerStart = {};
    level.playerStart.x = num(level.playerStart.x, DEFAULT_PLAYER_START.x);
    level.playerStart.y = num(level.playerStart.y, clamp(DEFAULT_PLAYER_START.y, level.walkZone.top, level.walkZone.bottom));

    if (!level.enemySpawnMargin) level.enemySpawnMargin = {};
    level.enemySpawnMargin.x = num(level.enemySpawnMargin.x, 40);
    level.enemySpawnMargin.y = num(level.enemySpawnMargin.y, 28);
  }

  function ensureAllLevelAreas() {
    if (!GAME_CONFIG.levels) GAME_CONFIG.levels = {};
    for (const key of levelKeys()) ensureLevelArea(GAME_CONFIG.levels[key]);
  }

  function getLevel(scene) {
    if (scene && typeof scene.getLevelConfig === 'function') return scene.getLevelConfig();
    const key = levelKeys()[0];
    return (GAME_CONFIG.levels && GAME_CONFIG.levels[key]) || null;
  }

  function getWalkZone(scene) {
    const level = getLevel(scene);
    ensureLevelArea(level);
    const raw = (level && level.walkZone) || DEFAULT_ZONE;
    const left = clamp(num(raw.left, DEFAULT_ZONE.left), 0, GAME_CONFIG.width - 1);
    const right = clamp(num(raw.right, DEFAULT_ZONE.right), left + 1, GAME_CONFIG.width);
    const top = clamp(num(raw.top, DEFAULT_ZONE.top), 0, bottomTuningMax() - 1);
    const bottom = clamp(num(raw.bottom, DEFAULT_ZONE.bottom), top + 1, bottomTuningMax());
    return { left, right, top, bottom };
  }

  function syncLegacyLane(scene) {
    const zone = getWalkZone(scene);
    GAME_CONFIG.laneTop = zone.top;
    GAME_CONFIG.laneBottom = zone.bottom;
    return zone;
  }

  function getLevelAreaVisuals(level) {
    ensureLevelArea(level);
    const zone = level.walkZone;
    const spawnX = clamp(num(level.enemySpawnMargin.x, 40), 0, 240);
    const spawnY = clamp(num(level.enemySpawnMargin.y, 28), 0, 120);
    const playerStart = {
      x: clamp(num(level.playerStart.x, DEFAULT_PLAYER_START.x), zone.left, zone.right),
      y: clamp(num(level.playerStart.y, DEFAULT_PLAYER_START.y), zone.top, zone.bottom)
    };
    return {
      zone,
      playerStart,
      spawn: {
        leftX: zone.left + spawnX,
        rightX: zone.right - spawnX,
        topY: Math.min(zone.bottom, zone.top + spawnY),
        bottomY: Math.max(zone.top, zone.bottom - spawnY)
      }
    };
  }

  function drawMarkerLabel(ctx, text, x, y, fill) {
    ctx.save();
    ctx.font = 'bold 13px Arial';
    ctx.textAlign = 'center';
    ctx.lineWidth = 4;
    ctx.strokeStyle = 'rgba(0,0,0,0.78)';
    ctx.fillStyle = fill;
    ctx.strokeText(text, x, y);
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function drawLevelAreaOverlay(ctx, level, activeKey) {
    const visual = getLevelAreaVisuals(level);
    const z = visual.zone;
    const p = visual.playerStart;
    const s = visual.spawn;
    const walkColor = activeKey && ['left', 'right', 'top', 'bottom'].includes(activeKey) ? '#d6d6d6' : '#8f8f8f';
    const playerColor = activeKey && ['playerX', 'playerY'].includes(activeKey) ? '#72b7ff' : '#4aa3ff';
    const spawnColor = activeKey && ['spawnX', 'spawnY'].includes(activeKey) ? '#ffcf5a' : '#ffa33b';

    ctx.save();
    ctx.fillStyle = 'rgba(155, 155, 155, 0.13)';
    ctx.fillRect(z.left, z.top, z.right - z.left, z.bottom - z.top);
    ctx.strokeStyle = walkColor;
    ctx.lineWidth = 4;
    ctx.setLineDash([12, 7]);
    ctx.strokeRect(z.left, z.top, z.right - z.left, z.bottom - z.top);
    ctx.setLineDash([]);
    drawMarkerLabel(ctx, 'WALK AREA', (z.left + z.right) / 2, z.top - 10, walkColor);

    ctx.strokeStyle = spawnColor;
    ctx.fillStyle = 'rgba(255, 165, 45, 0.16)';
    ctx.lineWidth = 3;
    ctx.fillRect(s.leftX - 8, s.topY, 16, s.bottomY - s.topY);
    ctx.fillRect(s.rightX - 8, s.topY, 16, s.bottomY - s.topY);
    ctx.beginPath();
    ctx.moveTo(s.leftX, s.topY);
    ctx.lineTo(s.leftX, s.bottomY);
    ctx.moveTo(s.rightX, s.topY);
    ctx.lineTo(s.rightX, s.bottomY);
    ctx.stroke();
    drawMarkerLabel(ctx, 'ENEMY SPAWN', s.rightX, s.topY - 10, spawnColor);

    ctx.fillStyle = playerColor;
    ctx.strokeStyle = 'rgba(0,0,0,0.85)';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(p.x, p.y, 12, 0, Math.PI * 2);
    ctx.stroke();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(p.x - 22, p.y);
    ctx.lineTo(p.x + 22, p.y);
    ctx.moveTo(p.x, p.y - 22);
    ctx.lineTo(p.x, p.y + 22);
    ctx.strokeStyle = playerColor;
    ctx.lineWidth = 2;
    ctx.stroke();
    drawMarkerLabel(ctx, 'PLAYER START', p.x, p.y - 24, playerColor);
    ctx.restore();
  }

  function buildLevelAreaExport() {
    ensureAllLevelAreas();
    const levels = {};
    for (const key of levelKeys()) {
      const level = GAME_CONFIG.levels[key];
      ensureLevelArea(level);
      levels[key] = {
        walkZone: {
          left: level.walkZone.left,
          right: level.walkZone.right,
          top: level.walkZone.top,
          bottom: level.walkZone.bottom
        },
        playerStart: {
          x: level.playerStart.x,
          y: level.playerStart.y
        },
        enemySpawnMargin: {
          x: level.enemySpawnMargin.x,
          y: level.enemySpawnMargin.y
        }
      };
    }
    return {
      buildVersion: GAME_CONFIG.buildVersion,
      exportedAt: new Date().toISOString(),
      levels
    };
  }

  function exportLevelAreas() {
    const data = buildLevelAreaExport();
    const text = JSON.stringify(data, null, 2);
    localStorage.setItem('streetsOfRussia.levelAreas.export', text);
    console.log('STREETS_OF_RUSSIA_LEVEL_AREAS_EXPORT');
    console.log(text);
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).catch(() => {});
    }
    return data;
  }

  ensureAllLevelAreas();

  if (typeof LevelScene !== 'undefined') {
    LevelScene.prototype.getWalkZone = function () {
      return getWalkZone(this);
    };

    LevelScene.prototype.getPlayerStart = function () {
      const level = this.getLevelConfig();
      ensureLevelArea(level);
      const zone = this.getWalkZone();
      return {
        x: clamp(num(level.playerStart.x, DEFAULT_PLAYER_START.x), zone.left, zone.right),
        y: clamp(num(level.playerStart.y, DEFAULT_PLAYER_START.y), zone.top, zone.bottom)
      };
    };

    LevelScene.prototype.clampActorPosition = function (actor, marginX = 0, offscreenMargin = 0) {
      const zone = this.getWalkZone();
      actor.x = clamp(actor.x, zone.left + marginX - offscreenMargin, zone.right - marginX + offscreenMargin);
      actor.y = clamp(actor.y, zone.top, zone.bottom);
    };

    LevelScene.prototype.getSpawnPoint = function (side, index, count) {
      const level = this.getLevelConfig();
      ensureLevelArea(level);
      const zone = this.getWalkZone();
      const marginX = clamp(num(level.enemySpawnMargin.x, 40), 0, 240);
      const marginY = clamp(num(level.enemySpawnMargin.y, 28), 0, 120);
      const safeSide = side || 'right';
      const rowRatio = count <= 1 ? 0.5 : index / Math.max(1, count - 1);
      const usableTop = Math.min(zone.bottom, zone.top + marginY);
      const usableBottom = Math.max(usableTop, zone.bottom - marginY);
      const y = usableTop + rowRatio * (usableBottom - usableTop);

      if (safeSide === 'left') {
        return { x: zone.left + marginX + index * 34, y };
      }

      if (safeSide === 'both') {
        const fromLeft = index % 2 === 0;
        return {
          x: fromLeft ? zone.left + marginX + index * 18 : zone.right - marginX - index * 18,
          y
        };
      }

      return { x: zone.right - marginX - index * 34, y };
    };

    LevelScene.prototype.restartCurrentLevel = function () {
      const start = this.getPlayerStart();
      this.player.x = start.x;
      this.player.y = start.y;
      this.player.releaseFromPin();
      const level = this.getLevelConfig();
      AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
      this.spawnInitialWave();
    };

    LevelScene.prototype.nextScreen = function () {
      if (this.screenIndex < this.images.streets.length - 1) {
        this.screenIndex += 1;
        syncLegacyLane(this);
        const start = this.getPlayerStart();
        this.player.x = start.x;
        this.player.y = start.y;
        this.player.releaseFromPin();
        const level = this.getLevelConfig();
        AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
        this.spawnInitialWave();
      } else {
        this.game.setState('mainMenu');
      }
    };

    const oldLevelUpdate = LevelScene.prototype.update;
    LevelScene.prototype.update = function (dt) {
      const zone = syncLegacyLane(this);
      oldLevelUpdate.call(this, dt);
      if (this.player) this.clampActorPosition(this.player, 70);
      if (this.encounterCleared && this.player && this.player.x > zone.right - 35) this.nextScreen();
    };

    const oldLevelDraw = LevelScene.prototype.draw;
    LevelScene.prototype.draw = function (ctx) {
      syncLegacyLane(this);
      oldLevelDraw.call(this, ctx);

      const showArea = this.debug || (typeof DevPanel !== 'undefined' && DevPanel.open && DevPanel.tab === 'LEVEL AREA');
      if (!showArea) return;

      const level = this.getLevelConfig();
      if (level) drawLevelAreaOverlay(ctx, level, typeof DevPanel !== 'undefined' ? DevPanel.levelAreaActiveKey : null);
    };
  }

  if (typeof Player !== 'undefined') {
    const oldPlayerUpdate = Player.prototype.update;
    Player.prototype.update = function (dt, scene) {
      oldPlayerUpdate.call(this, dt, scene);
      if (scene && typeof scene.clampActorPosition === 'function') scene.clampActorPosition(this, 70);
    };
  }

  if (typeof DogRegimeEnemy !== 'undefined') {
    const oldDogUpdate = DogRegimeEnemy.prototype.update;
    DogRegimeEnemy.prototype.update = function (dt, scene) {
      this.__scene = scene;
      oldDogUpdate.call(this, dt, scene);
      const offscreen = this.alive ? (GAME_CONFIG.enemyOffscreenMargin || 180) : 0;
      if (scene && typeof scene.clampActorPosition === 'function') scene.clampActorPosition(this, 45, offscreen);
    };

    DogRegimeEnemy.prototype.clampToScreen = function () {
      const scene = this.__scene;
      const offscreen = this.alive ? (GAME_CONFIG.enemyOffscreenMargin || 180) : 0;
      if (scene && typeof scene.clampActorPosition === 'function') {
        scene.clampActorPosition(this, 45, offscreen);
        return;
      }
      this.x = clamp(this.x, 45 - offscreen, GAME_CONFIG.width - 45 + offscreen);
      this.y = clamp(this.y, GAME_CONFIG.laneTop, GAME_CONFIG.laneBottom);
    };
  }

  if (typeof SuckerEnemy !== 'undefined') {
    const oldSuckerUpdate = SuckerEnemy.prototype.update;
    SuckerEnemy.prototype.update = function (dt, scene) {
      this.__scene = scene;
      oldSuckerUpdate.call(this, dt, scene);
      const offscreen = this.alive ? (GAME_CONFIG.enemyOffscreenMargin || 180) : 0;
      if (scene && typeof scene.clampActorPosition === 'function') scene.clampActorPosition(this, 45, offscreen);
    };
  }

  if (typeof BastardEnemy !== 'undefined') {
    const oldBastardUpdate = BastardEnemy.prototype.update;
    BastardEnemy.prototype.update = function (dt, scene) {
      this.__scene = scene;
      oldBastardUpdate.call(this, dt, scene);
      if (this.isHealingExit && this.isHealingExit()) return;
      if (scene && typeof scene.clampActorPosition === 'function') scene.clampActorPosition(this, 45);
    };

    const oldBastardTakeHit = BastardEnemy.prototype.takeHit;
    BastardEnemy.prototype.takeHit = function (damage, direction) {
      oldBastardTakeHit.call(this, damage, direction);
      const scene = this.__scene;
      if (this.isHealingExit && this.isHealingExit()) return;
      if (scene && typeof scene.clampActorPosition === 'function') scene.clampActorPosition(this, 45);
    };
  }

  if (typeof DevPanel !== 'undefined') {
    if (!DevPanel.tabs.includes('LEVEL AREA')) DevPanel.tabs.push('LEVEL AREA');

    const oldEnsureLevels = DevPanel.ensureLevels;
    DevPanel.ensureLevels = function () {
      oldEnsureLevels.call(this);
      ensureAllLevelAreas();
    };

    const oldHandleClick = DevPanel.handleClick;
    DevPanel.handleClick = function (point, game) {
      const panel = this.panelRect();
      if (!this.inRect(point, panel)) return;

      const close = { x: panel.x + panel.w - 78, y: panel.y + 14, w: 56, h: 32 };
      if (this.inRect(point, close)) { this.open = false; return; }

      const tab = this.getClickedTab(point);
      if (tab) { this.tab = tab; this.syncSelectedLevelWithScene(game); this.setStatus('Tab: ' + tab); return; }

      if (this.handleFooterClick(point, game)) return;

      if (this.tab === 'LEVEL AREA') {
        this.handleLevelAreaClick(point, game);
        return;
      }

      oldHandleClick.call(this, point, game);
    };

    const oldDraw = DevPanel.draw;
    DevPanel.draw = function (ctx) {
      if (!GAME_CONFIG.adminTuningEnabled) return;
      if (this.open && this.tab === 'LEVEL AREA') {
        const panel = this.panelRect();
        ctx.fillStyle = 'rgba(0,0,0,0.90)';
        ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 2;
        ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);

        ctx.fillStyle = '#fff';
        ctx.font = 'bold 24px Arial';
        ctx.fillText('DEVELOPER PANEL', panel.x + 22, panel.y + 38);
        ctx.font = '13px Arial';
        ctx.fillStyle = '#aaa';
        ctx.fillText('LEVEL AREA: grey box = walking area, blue dot = player start, orange lines = enemy spawn lanes.', panel.x + 22, panel.y + 58);

        this.drawButton(ctx, panel.x + panel.w - 78, panel.y + 14, 56, 32, 'X');
        this.drawTabs(ctx);
        this.drawLevelAreaEditor(ctx);
        this.drawFooter(ctx);
        this.drawStatus(ctx, panel);
        return;
      }
      oldDraw.call(this, ctx);
    };

    DevPanel.levelAreaRects = function () {
      const panel = this.panelRect();
      const x = panel.x + 36;
      const y = panel.y + 124;
      const rows = ['left', 'right', 'top', 'bottom', 'playerX', 'playerY', 'spawnX', 'spawnY'];
      const out = {
        box: { x, y, w: 980, h: 492 },
        preview: { x: x + 744, y: y + 86, w: 210, h: 118 },
        levelPrev: { x: x + 92, y: y + 54, w: 36, h: 26 },
        levelNext: { x: x + 690, y: y + 54, w: 36, h: 26 }
      };
      rows.forEach((name, i) => {
        const rowY = y + 112 + i * 38;
        out[name + 'Minus'] = { x: x + 250, y: rowY - 21, w: 36, h: 26 };
        out[name + 'Plus'] = { x: x + 642, y: rowY - 21, w: 36, h: 26 };
        out[name + 'Bar'] = { x: x + 300, y: rowY - 14, w: 326, h: 12 };
        out[name + 'Y'] = rowY;
      });
      return out;
    };

    DevPanel.getLevelAreaFields = function () {
      const key = this.getSelectedLevelKey();
      return [
        { key: 'left', label: 'Walk area left edge', hint: 'moves the left side of the grey walking box', path: 'levels.' + key + '.walkZone.left', min: 0, max: GAME_CONFIG.width - 100, step: 5 },
        { key: 'right', label: 'Walk area right edge', hint: 'moves the right side of the grey walking box', path: 'levels.' + key + '.walkZone.right', min: 100, max: GAME_CONFIG.width, step: 5 },
        { key: 'top', label: 'Walk area top edge', hint: 'moves the top side of the grey walking box', path: 'levels.' + key + '.walkZone.top', min: 260, max: GAME_CONFIG.height - 20, step: 5 },
        { key: 'bottom', label: 'Walk area bottom edge', hint: 'moves the bottom side of the grey walking box', path: 'levels.' + key + '.walkZone.bottom', min: 320, max: bottomTuningMax(), step: 5 },
        { key: 'playerX', label: 'Player start left/right', hint: 'moves the blue player-start dot horizontally', path: 'levels.' + key + '.playerStart.x', min: 0, max: GAME_CONFIG.width, step: 5 },
        { key: 'playerY', label: 'Player start up/down', hint: 'moves the blue player-start dot vertically', path: 'levels.' + key + '.playerStart.y', min: 260, max: bottomTuningMax(), step: 5 },
        { key: 'spawnX', label: 'Enemy spawn side inset', hint: 'moves orange spawn lines inward from left and right edges', path: 'levels.' + key + '.enemySpawnMargin.x', min: 0, max: 240, step: 5 },
        { key: 'spawnY', label: 'Enemy spawn top/bottom gap', hint: 'shrinks or expands the orange spawn segment vertically', path: 'levels.' + key + '.enemySpawnMargin.y', min: 0, max: 120, step: 2 }
      ];
    };

    DevPanel.drawLevelAreaMiniPreview = function (ctx, r, level, activeKey) {
      const p = r.preview;
      const visual = getLevelAreaVisuals(level);
      const sx = p.w / GAME_CONFIG.width;
      const sy = p.h / GAME_CONFIG.height;
      const tx = x => p.x + x * sx;
      const ty = y => p.y + y * sy;
      const z = visual.zone;
      const s = visual.spawn;
      const start = visual.playerStart;

      ctx.save();
      ctx.fillStyle = 'rgba(0,0,0,0.52)';
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.strokeRect(p.x, p.y, p.w, p.h);

      ctx.fillStyle = 'rgba(150,150,150,0.22)';
      ctx.fillRect(tx(z.left), ty(z.top), (z.right - z.left) * sx, (z.bottom - z.top) * sy);
      ctx.strokeStyle = activeKey && ['left', 'right', 'top', 'bottom'].includes(activeKey) ? '#fff' : '#aaa';
      ctx.lineWidth = 2;
      ctx.strokeRect(tx(z.left), ty(z.top), (z.right - z.left) * sx, (z.bottom - z.top) * sy);

      ctx.strokeStyle = activeKey && ['spawnX', 'spawnY'].includes(activeKey) ? '#ffcf5a' : '#ffa33b';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(tx(s.leftX), ty(s.topY));
      ctx.lineTo(tx(s.leftX), ty(s.bottomY));
      ctx.moveTo(tx(s.rightX), ty(s.topY));
      ctx.lineTo(tx(s.rightX), ty(s.bottomY));
      ctx.stroke();

      ctx.fillStyle = activeKey && ['playerX', 'playerY'].includes(activeKey) ? '#9fd0ff' : '#4aa3ff';
      ctx.beginPath();
      ctx.arc(tx(start.x), ty(start.y), 5, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#ddd';
      ctx.font = '12px Arial';
      ctx.fillText('mini map', p.x, p.y - 8);
      ctx.restore();
    };

    DevPanel.drawLevelAreaEditor = function (ctx) {
      this.ensureLevels();
      const r = this.levelAreaRects();
      const levelKey = this.getSelectedLevelKey();
      const level = this.getSelectedLevel();
      ensureLevelArea(level);
      const fields = this.getLevelAreaFields();

      ctx.fillStyle = 'rgba(255,255,255,0.06)';
      ctx.fillRect(r.box.x, r.box.y, r.box.w, r.box.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.strokeRect(r.box.x, r.box.y, r.box.w, r.box.h);

      ctx.fillStyle = '#fff';
      ctx.font = 'bold 18px Arial';
      ctx.fillText('LEVEL WALK AREA', r.box.x + 20, r.box.y + 32);

      this.drawRowLabel(ctx, 'Level:', r.box.x + 24, r.box.y + 76);
      this.drawButton(ctx, r.levelPrev.x, r.levelPrev.y, r.levelPrev.w, r.levelPrev.h, '<');
      this.drawButton(ctx, r.levelNext.x, r.levelNext.y, r.levelNext.w, r.levelNext.h, '>');
      this.drawValue(ctx, levelKey + ' / ' + level.name, r.box.x + 145, r.box.y + 76);
      this.drawLevelAreaMiniPreview(ctx, r, level, this.levelAreaActiveKey);

      for (const field of fields) {
        const value = this.getValue(field.path);
        const ratio = (value - field.min) / Math.max(1, field.max - field.min);
        const y = r[field.key + 'Y'];
        const active = this.levelAreaActiveKey === field.key;
        const groupColor = ['playerX', 'playerY'].includes(field.key)
          ? '#4aa3ff'
          : ['spawnX', 'spawnY'].includes(field.key)
            ? '#ffa33b'
            : '#cfcfcf';
        ctx.font = '14px Arial';
        ctx.fillStyle = active ? groupColor : '#fff';
        ctx.fillText(field.label, r.box.x + 24, y);
        ctx.fillStyle = '#ccc';
        ctx.fillText(String(value), r.box.x + 218, y);
        this.drawButton(ctx, r[field.key + 'Minus'].x, r[field.key + 'Minus'].y, r[field.key + 'Minus'].w, r[field.key + 'Minus'].h, '-');
        ctx.fillStyle = '#222';
        ctx.fillRect(r[field.key + 'Bar'].x, r[field.key + 'Bar'].y, r[field.key + 'Bar'].w, r[field.key + 'Bar'].h);
        ctx.fillStyle = groupColor;
        ctx.fillRect(r[field.key + 'Bar'].x, r[field.key + 'Bar'].y, r[field.key + 'Bar'].w * clamp(ratio, 0, 1), r[field.key + 'Bar'].h);
        ctx.strokeStyle = active ? groupColor : '#777';
        ctx.strokeRect(r[field.key + 'Bar'].x, r[field.key + 'Bar'].y, r[field.key + 'Bar'].w, r[field.key + 'Bar'].h);
        this.drawButton(ctx, r[field.key + 'Plus'].x, r[field.key + 'Plus'].y, r[field.key + 'Plus'].w, r[field.key + 'Plus'].h, '+');
        if (active && field.hint) {
          ctx.font = '12px Arial';
          ctx.fillStyle = '#bbb';
          ctx.fillText(field.hint, r.box.x + 710, y);
        }
      }

      ctx.font = '13px Arial';
      ctx.fillStyle = '#aaa';
      ctx.fillText('Tip: click any row or +/- button. The same color marker moves on the level and mini map.', r.box.x + 24, r.box.y + 462);
    };

    DevPanel.handleLevelAreaClick = function (point, game) {
      const r = this.levelAreaRects();
      const keys = this.getLevelKeys();
      if (this.inRect(point, r.levelPrev)) { this.selectedLevelIndex = this.wrap(this.selectedLevelIndex - 1, keys.length); this.setStatus('Level: ' + this.getSelectedLevelKey()); return true; }
      if (this.inRect(point, r.levelNext)) { this.selectedLevelIndex = this.wrap(this.selectedLevelIndex + 1, keys.length); this.setStatus('Level: ' + this.getSelectedLevelKey()); return true; }

      const fields = this.getLevelAreaFields();
      for (const field of fields) {
        const minus = r[field.key + 'Minus'];
        const plus = r[field.key + 'Plus'];
        const bar = r[field.key + 'Bar'];
        const row = { x: r.box.x + 18, y: r[field.key + 'Y'] - 24, w: r.box.w - 36, h: 34 };
        if (this.inRect(point, minus)) { this.changeLevelAreaField(field, -field.step, game); return true; }
        if (this.inRect(point, plus)) { this.changeLevelAreaField(field, field.step, game); return true; }
        if (this.inRect(point, bar)) {
          const ratio = clamp((point.x - bar.x) / bar.w, 0, 1);
          const raw = field.min + ratio * (field.max - field.min);
          this.setLevelAreaValue(field, this.roundToStep(raw, field.step), game);
          return true;
        }
        if (this.inRect(point, row)) { this.levelAreaActiveKey = field.key; this.setStatus(field.hint || field.label); return true; }
      }
      return false;
    };

    DevPanel.changeLevelAreaField = function (field, delta, game) {
      const current = this.getValue(field.path);
      this.levelAreaActiveKey = field.key;
      this.setLevelAreaValue(field, current + delta, game);
    };

    DevPanel.setLevelAreaValue = function (field, value, game) {
      const level = this.getSelectedLevel();
      ensureLevelArea(level);
      this.levelAreaActiveKey = field.key;
      const next = clamp(this.roundToStep(value, field.step), field.min, field.max);
      this.setValue(field.path, next);
      this.fixSelectedLevelArea();
      if (game && game.scene && typeof game.scene.getLevelKey === 'function' && game.scene.getLevelKey() === this.getSelectedLevelKey()) {
        syncLegacyLane(game.scene);
        if (game.scene.player) game.scene.clampActorPosition(game.scene.player, 70);
        for (const enemy of game.scene.enemies || []) game.scene.clampActorPosition(enemy, 45);
      }
      this.setStatus(field.label + ': ' + this.getValue(field.path));
    };

    DevPanel.fixSelectedLevelArea = function () {
      const level = this.getSelectedLevel();
      ensureLevelArea(level);
      const z = level.walkZone;
      if (z.right <= z.left + 80) z.right = z.left + 80;
      if (z.bottom <= z.top + 40) z.bottom = z.top + 40;
      z.right = clamp(z.right, z.left + 80, GAME_CONFIG.width);
      z.bottom = clamp(z.bottom, z.top + 40, bottomTuningMax());
      level.playerStart.x = clamp(level.playerStart.x, z.left, z.right);
      level.playerStart.y = clamp(level.playerStart.y, z.top, z.bottom);
    };

    const oldExportConfig = DevPanel.exportConfig;
    DevPanel.exportConfig = function () {
      ensureAllLevelAreas();
      exportLevelAreas();
      oldExportConfig.call(this);
    };
  }

  window.WalkZoneTools = {
    ensureAllLevelAreas,
    ensureLevelArea,
    getWalkZone,
    buildLevelAreaExport,
    exportLevelAreas,
    syncLegacyLane
  };
})();



/* ===== src/devPanelRepairPatch.js ===== */
(function () {
  if (typeof DevPanel === 'undefined' || typeof GAME_CONFIG === 'undefined') return;

  const panel = DevPanel;

  function addTab(name) {
    if (!panel.tabs.includes(name)) panel.tabs.push(name);
  }

  function ensureGroup(name) {
    if (!panel.fieldGroups[name]) panel.fieldGroups[name] = [];
    return panel.fieldGroups[name];
  }

  function addField(groupName, field) {
    const group = ensureGroup(groupName);
    if (!group.some(item => item.path === field.path)) group.push(field);
  }

  function safeGet(path, fallback) {
    try {
      const value = path.split('.').reduce((obj, key) => obj && obj[key], GAME_CONFIG);
      return value == null ? fallback : value;
    } catch (error) {
      return fallback;
    }
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  GAME_CONFIG.adminTuningEnabled = true;
  if (GAME_CONFIG.playerHurtFreezeMs == null) GAME_CONFIG.playerHurtFreezeMs = 280;

  addField('PLAYER', { label: 'Hurt freeze ms', path: 'playerHurtFreezeMs', min: 80, max: 700, step: 10 });

  addTab('ZETNIK');
  addField('ZETNIK', { label: 'Zetnik speed', path: 'enemies.zetnik.speed', min: 0.3, max: 4, step: 0.05 });
  addField('ZETNIK', { label: 'Zetnik HP', path: 'enemies.zetnik.hp', min: 10, max: 400, step: 5 });
  addField('ZETNIK', { label: 'Zetnik damage', path: 'enemies.zetnik.damage', min: 1, max: 80, step: 1 });
  addField('ZETNIK', { label: 'Zetnik scale', path: 'enemies.zetnik.scale', min: 0.05, max: 0.25, step: 0.005 });
  addField('ZETNIK', { label: 'Min dist X', path: 'enemies.zetnik.minDistanceX', min: 20, max: 160, step: 2 });
  addField('ZETNIK', { label: 'Preferred dist X', path: 'enemies.zetnik.preferredDistanceX', min: 40, max: 240, step: 2 });
  addField('ZETNIK', { label: 'Attack range X', path: 'enemies.zetnik.attackRangeX', min: 30, max: 200, step: 2 });
  addField('ZETNIK', { label: 'Attack range Y', path: 'enemies.zetnik.attackRangeY', min: 14, max: 100, step: 2 });
  addField('ZETNIK', { label: 'Max attackers', path: 'enemies.zetnik.maxAttackers', min: 1, max: 5, step: 1 });
  addField('ZETNIK', { label: 'Decision min ms', path: 'enemies.zetnik.decisionMinMs', min: 100, max: 1200, step: 20 });
  addField('ZETNIK', { label: 'Decision max ms', path: 'enemies.zetnik.decisionMaxMs', min: 160, max: 2000, step: 20 });
  addField('ZETNIK', { label: 'Strafe chance', path: 'enemies.zetnik.strafeChance', min: 0, max: 1, step: 0.05 });
  addField('ZETNIK', { label: 'Retreat chance', path: 'enemies.zetnik.retreatChance', min: 0, max: 1, step: 0.05 });
  addField('ZETNIK', { label: 'Attack chance', path: 'enemies.zetnik.attackChance', min: 0, max: 1, step: 0.05 });
  addField('ZETNIK', { label: 'Self remove ms', path: 'enemies.zetnik.selfRemoveDelayMs', min: 1000, max: 30000, step: 500 });

  addTab('BASTARD');
  addField('BASTARD', { label: 'Bastard HP', path: 'enemies.bastard.hp', min: 10, max: 9999, step: 10 });
  addField('BASTARD', { label: 'Bastard speed', path: 'enemies.bastard.speed', min: 0, max: 3, step: 0.05 });
  addField('BASTARD', { label: 'Bastard scale', path: 'enemies.bastard.scale', min: 0.05, max: 0.25, step: 0.005 });
  addField('BASTARD', { label: 'Wander min ms', path: 'enemies.bastard.wanderMinMs', min: 100, max: 4000, step: 50 });
  addField('BASTARD', { label: 'Wander max ms', path: 'enemies.bastard.wanderMaxMs', min: 100, max: 5000, step: 50 });
  addField('BASTARD', { label: 'Idle min ms', path: 'enemies.bastard.idleMinMs', min: 100, max: 4000, step: 50 });
  addField('BASTARD', { label: 'Idle max ms', path: 'enemies.bastard.idleMaxMs', min: 100, max: 5000, step: 50 });
  addField('BASTARD', { label: 'Fallen min ms', path: 'enemies.bastard.fallenMinMs', min: 100, max: 5000, step: 50 });
  addField('BASTARD', { label: 'Fallen max ms', path: 'enemies.bastard.fallenMaxMs', min: 100, max: 6000, step: 50 });
  addField('BASTARD', { label: 'Idle chance', path: 'enemies.bastard.idleChance', min: 0, max: 1, step: 0.05 });
  addField('BASTARD', { label: 'Fall chance', path: 'enemies.bastard.fallChance', min: 0, max: 1, step: 0.01 });
  addField('BASTARD', { label: 'Turn chance', path: 'enemies.bastard.turnChance', min: 0, max: 1, step: 0.05 });
  addField('BASTARD', { label: 'Knockback X', path: 'enemies.bastard.knockbackX', min: 0, max: 180, step: 4 });

  addTab('LEVEL AREA');
  for (const key of GAME_CONFIG.levelOrder || Object.keys(GAME_CONFIG.levels || {})) {
    const level = GAME_CONFIG.levels[key];
    if (!level) continue;
    if (!level.walkZone) level.walkZone = { left: 0, right: GAME_CONFIG.width, top: GAME_CONFIG.laneTop, bottom: GAME_CONFIG.laneBottom };
    if (!level.playerStart) level.playerStart = { x: 190, y: 620 };
    if (!level.enemySpawnMargin) level.enemySpawnMargin = { x: 40, y: 28 };
  }

  function selectedLevelPath(suffix) {
    const key = panel.getSelectedLevelKey ? panel.getSelectedLevelKey() : (GAME_CONFIG.levelOrder && GAME_CONFIG.levelOrder[0]) || 'street01';
    return 'levels.' + key + '.' + suffix;
  }

  panel.panelRect = function () {
    return { x: 24, y: 18, w: 1232, h: 684 };
  };

  panel.tabRect = function (index) {
    const base = this.panelRect();
    const gap = 8;
    const w = Math.floor((base.w - 48 - gap * (this.tabs.length - 1)) / this.tabs.length);
    return { x: base.x + 24 + index * (w + gap), y: base.y + 76, w, h: 34 };
  };

  panel.openFromPauseMenu = function (game) {
    GAME_CONFIG.adminTuningEnabled = true;
    this.open = true;
    this.tab = 'LEVEL WAVES';
    if (typeof this.ensureLevels === 'function') this.ensureLevels();
    if (typeof this.syncSelectedLevelWithScene === 'function') this.syncSelectedLevelWithScene(game);
    this.setStatus('Developer panel opened');
  };

  const oldUpdate = panel.update;
  panel.update = function (game) {
    if (this.open) GAME_CONFIG.adminTuningEnabled = true;
    oldUpdate.call(this, game);
  };

  const oldDraw = panel.draw;
  panel.draw = function (ctx) {
    if (this.open) GAME_CONFIG.adminTuningEnabled = true;
    if (!this.tabs.includes(this.tab)) this.tab = 'LEVEL WAVES';
    oldDraw.call(this, ctx);
  };

  panel.getFieldsForCurrentTab = function () {
    if (this.tab !== 'LEVEL AREA') return this.fieldGroups[this.tab] || [];
    return [
      { label: 'Level left edge', path: selectedLevelPath('walkZone.left'), min: 0, max: GAME_CONFIG.width - 100, step: 10 },
      { label: 'Level right edge', path: selectedLevelPath('walkZone.right'), min: 100, max: GAME_CONFIG.width, step: 10 },
      { label: 'Walk top Y', path: selectedLevelPath('walkZone.top'), min: 360, max: GAME_CONFIG.height + 180, step: 5 },
      { label: 'Walk bottom Y', path: selectedLevelPath('walkZone.bottom'), min: 420, max: GAME_CONFIG.height + 220, step: 5 },
      { label: 'Player start X', path: selectedLevelPath('playerStart.x'), min: 0, max: GAME_CONFIG.width, step: 10 },
      { label: 'Player start Y', path: selectedLevelPath('playerStart.y'), min: 360, max: GAME_CONFIG.height + 220, step: 5 },
      { label: 'Enemy spawn margin X', path: selectedLevelPath('enemySpawnMargin.x'), min: 0, max: 260, step: 5 },
      { label: 'Enemy spawn margin Y', path: selectedLevelPath('enemySpawnMargin.y'), min: 0, max: 160, step: 5 }
    ];
  };

  panel.drawFields = function (ctx) {
    const fields = this.getFieldsForCurrentTab();
    const base = this.panelRect();
    const startY = base.y + 132;
    const rowH = 34;
    const colW = 565;
    const perCol = 14;

    if (this.tab === 'LEVEL AREA') {
      ctx.fillStyle = '#8cff8c';
      ctx.font = 'bold 15px Arial';
      ctx.fillText('Editing level: ' + this.getSelectedLevelKey(), base.x + 36, base.y + 118);
    }

    for (let i = 0; i < fields.length; i++) {
      const col = Math.floor(i / perCol);
      const row = i % perCol;
      this.drawField(ctx, fields[i], base.x + 36 + col * colW, startY + row * rowH);
    }
  };

  panel.drawField = function (ctx, field, x, y) {
    const value = Number(safeGet(field.path, field.min));
    const ratio = clamp((value - field.min) / Math.max(1, field.max - field.min), 0, 1);

    ctx.font = '14px Arial';
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'left';
    ctx.fillText(field.label, x, y);
    ctx.fillStyle = '#d7d7d7';
    ctx.fillText(String(value), x + 205, y);

    this.drawButton(ctx, x + 290, y - 20, 34, 25, '-');
    ctx.fillStyle = '#222';
    ctx.fillRect(x + 335, y - 13, 185, 11);
    ctx.fillStyle = '#55ccff';
    ctx.fillRect(x + 335, y - 13, 185 * ratio, 11);
    ctx.strokeStyle = '#777';
    ctx.strokeRect(x + 335, y - 13, 185, 11);
    this.drawButton(ctx, x + 530, y - 20, 34, 25, '+');
  };

  panel.handleFieldsClick = function (point, game) {
    const fields = this.getFieldsForCurrentTab();
    const base = this.panelRect();
    const startY = base.y + 132;
    const rowH = 34;
    const colW = 565;
    const perCol = 14;

    for (let i = 0; i < fields.length; i++) {
      const col = Math.floor(i / perCol);
      const row = i % perCol;
      const x = base.x + 36 + col * colW;
      const y = startY + row * rowH;
      const field = fields[i];
      const minus = { x: x + 290, y: y - 20, w: 34, h: 25 };
      const plus = { x: x + 530, y: y - 20, w: 34, h: 25 };
      const bar = { x: x + 335, y: y - 13, w: 185, h: 11 };

      if (this.inRect(point, minus)) { this.change(field, -field.step, game); return; }
      if (this.inRect(point, plus)) { this.change(field, field.step, game); return; }
      if (this.inRect(point, bar)) {
        const ratio = clamp((point.x - bar.x) / bar.w, 0, 1);
        const raw = field.min + ratio * (field.max - field.min);
        this.setValue(field.path, this.roundToStep(raw, field.step));
        this.applyToCurrentScene(game);
        this.setStatus('Changed ' + field.label);
        return;
      }
    }
  };

  const oldHandleClick = panel.handleClick;
  panel.handleClick = function (point, game) {
    if (this.tab === 'LEVEL AREA') {
      const tab = this.getClickedTab(point);
      if (tab) { this.tab = tab; this.setStatus('Tab: ' + tab); return; }
      if (this.handleFooterClick(point, game)) return;
      if (typeof this.handleLevelAreaClick === 'function') {
        this.handleLevelAreaClick(point, game);
      } else {
        this.handleFieldsClick(point, game);
      }
      return;
    }
    oldHandleClick.call(this, point, game);
  };
})();



/* ===== src/campaignMap.js ===== */
const CampaignMapScreen = {
  storageKey: 'russiaCleanerCampaignRegionIndex',
  activeIndex: 0,
  images: null,
  loaded: false,

  order: [
    'farEast',
    'siberia',
    'ural',
    'northwestPiter',
    'volga',
    'southSochi',
    'centralMoscow'
  ],

  labels: {
    farEast: 'ДАЛЬНИЙ ВОСТОК',
    siberia: 'СИБИРЬ',
    ural: 'УРАЛ',
    northwestPiter: 'СЕВЕРО-ЗАПАД',
    volga: 'ПОВОЛЖЬЕ',
    southSochi: 'ЮГ РОССИИ',
    centralMoscow: 'МОСКОВСКИЙ РЕГИОН'
  },

  sources: {
    base: 'assets/map/campaign/map_base.png',
    active: {
      farEast: 'assets/map/campaign/active/01_far_east_active.png',
      siberia: 'assets/map/campaign/active/02_siberia_active.png',
      ural: 'assets/map/campaign/active/03_ural_active.png',
      volga: 'assets/map/campaign/active/04_volga_active.png',
      centralMoscow: 'assets/map/campaign/active/05_central_moscow_active.png',
      northwestPiter: 'assets/map/campaign/active/06_northwest_piter_active.png',
      southSochi: 'assets/map/campaign/active/07_south_sochi_active.png'
    },
    completed: {
      farEast: 'assets/map/campaign/completed/01_far_east_completed.png',
      siberia: 'assets/map/campaign/completed/02_siberia_completed.png',
      ural: 'assets/map/campaign/completed/03_ural_completed.png',
      volga: 'assets/map/campaign/completed/04_volga_completed.png',
      centralMoscow: 'assets/map/campaign/completed/05_central_moscow_completed.png',
      northwestPiter: 'assets/map/campaign/completed/06_northwest_piter_completed.png',
      southSochi: 'assets/map/campaign/completed/07_south_sochi_completed.png'
    }
  },

  init() {
    if (GAME_CONFIG.campaignRegions && Array.isArray(GAME_CONFIG.campaignRegions)) {
      this.order = GAME_CONFIG.campaignRegions.map(region => region.mapId).filter(Boolean);
    }
    this.activeIndex = 0;
    this.clearSavedProgress();
    this.images = this.createImageSet(this.sources);
  },

  createImageSet(sources) {
    const makeImage = (src) => {
      if (!src) return null;
      const img = new Image();
      img.onload = () => { this.loaded = true; };
      img.onerror = () => console.warn('Missing campaign map image:', src);
      img.src = src;
      return img;
    };

    const set = {
      base: makeImage(sources.base),
      active: {},
      completed: {}
    };

    for (const id of this.order) {
      set.active[id] = makeImage(sources.active && sources.active[id]);
      set.completed[id] = makeImage(sources.completed && sources.completed[id]);
    }

    return set;
  },

  loadProgress() {
    return 0;
  },

  saveProgress() {
    // Сохранения кампании пока отключены: прогресс живёт только до перезагрузки страницы.
  },

  clearSavedProgress() {
    try {
      localStorage.removeItem(this.storageKey);
    } catch (error) {}
  },

  resetProgress() {
    this.activeIndex = 0;
    this.clearSavedProgress();
  },

  getActiveRegionId() {
    return this.order[this.activeIndex] || this.order[this.order.length - 1];
  },

  completeActiveRegion() {
    if (this.activeIndex < this.order.length - 1) {
      this.activeIndex += 1;
    }
  },

  update(game, dt) {
    const click = Input.consumePointer();

    if (Input.consume('escape')) {
      game.setState('mainMenu');
      return;
    }

    if (Input.consume('r')) {
      this.resetProgress();
      AudioManager.playSfx('menuSelect', 0.7);
      return;
    }

    if (Input.consume('enter') || Input.consume('space') || click) {
      AudioManager.unlock();
      AudioManager.playSfx('menuSelect', 0.85);
      game.setState('characterSelect');
    }
  },

  draw(ctx) {
    ctx.save();

    ctx.fillStyle = '#010815';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    this.drawImageStretch(ctx, this.images && this.images.base);

    for (let i = 0; i < this.activeIndex; i++) {
      const id = this.order[i];
      this.drawImageStretch(ctx, this.images.completed[id]);
    }

    const activeId = this.getActiveRegionId();
    const pulse = 0.72 + Math.sin(performance.now() / 180) * 0.18;
    ctx.globalAlpha = pulse;
    this.drawImageStretch(ctx, this.images.active[activeId]);
    ctx.globalAlpha = 1;

    this.drawPanel(ctx, activeId);
    ctx.restore();
  },

  drawImageStretch(ctx, image) {
    if (!image || !image.complete || image.naturalWidth <= 0) return;
    ctx.drawImage(image, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
  },

  drawPanel(ctx, activeId) {
    const panelX = 40;
    const panelY = GAME_CONFIG.height - 160;
    const panelW = GAME_CONFIG.width - 80;
    const panelH = 126;

    ctx.fillStyle = 'rgba(0, 10, 24, 0.78)';
    ctx.fillRect(panelX, panelY, panelW, panelH);
    ctx.strokeStyle = '#55d5ff';
    ctx.lineWidth = 2;
    ctx.strokeRect(panelX, panelY, panelW, panelH);

    ctx.font = 'bold 30px Arial';
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'left';
    ctx.fillText('КАРТА СОПРОТИВЛЕНИЯ', panelX + 28, panelY + 42);

    ctx.font = 'bold 22px Arial';
    ctx.fillStyle = '#c8f7ff';
    ctx.fillText(this.labels[activeId] || activeId, panelX + 30, panelY + 76);

    ctx.font = '18px Arial';
    ctx.fillStyle = '#d8e8f2';
    ctx.fillText('Enter / Space / клик — начать миссию', panelX + 30, panelY + 108);

    ctx.textAlign = 'right';
    ctx.fillStyle = '#89f0ff';
    ctx.fillText('Прогресс: ' + this.activeIndex + ' / ' + (this.order.length - 1), panelX + panelW - 28, panelY + 108);
    ctx.textAlign = 'left';
  }
};



/* ===== src/campaignRuntime.js ===== */
(function () {
  if (typeof window === 'undefined' || typeof GAME_CONFIG === 'undefined') return;

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function normalizeRegionId(regionId) {
    return String(regionId || '').replace(/[^a-z0-9]/gi, '').toLowerCase();
  }

  function getLevelOrder() {
    return Array.isArray(GAME_CONFIG.levelOrder) ? GAME_CONFIG.levelOrder : [];
  }

  function getRegionDefinitions() {
    if (Array.isArray(GAME_CONFIG.campaignRegions) && GAME_CONFIG.campaignRegions.length) {
      return GAME_CONFIG.campaignRegions.filter(region => region && region.mapId && Array.isArray(region.levels));
    }

    const grouped = [];
    const byRegion = {};
    for (const key of getLevelOrder()) {
      const level = GAME_CONFIG.levels && GAME_CONFIG.levels[key];
      const regionId = getLevelRegionId(level);
      if (!regionId) continue;
      if (!byRegion[regionId]) {
        byRegion[regionId] = { mapId: regionId, levelRegion: regionId, levels: [] };
        grouped.push(byRegion[regionId]);
      }
      byRegion[regionId].levels.push(key);
    }
    return grouped;
  }

  function findRegionDefinition(regionId) {
    const wanted = normalizeRegionId(regionId);
    if (!wanted) return null;
    return getRegionDefinitions().find(region => (
      normalizeRegionId(region.mapId) === wanted ||
      normalizeRegionId(region.levelRegion) === wanted ||
      normalizeRegionId(region.id) === wanted
    )) || null;
  }

  function getLevelByIndex(index) {
    const key = getLevelOrder()[index];
    return key && GAME_CONFIG.levels ? GAME_CONFIG.levels[key] : null;
  }

  function getLevelRegionId(level) {
    return level && (level.region || level.regionKey || level.area || level.chapter) || '';
  }

  function getActiveRegionIndex(game) {
    const map = game && game.campaignMap;
    return map && Number.isFinite(map.activeIndex) ? map.activeIndex : 0;
  }

  function getActiveRegionId(game) {
    const map = game && game.campaignMap;
    const activeIndex = getActiveRegionIndex(game);
    const route = getRegionDefinitions();
    if (route[activeIndex]) return route[activeIndex].mapId;
    return map && Array.isArray(map.order) ? map.order[activeIndex] || map.order[0] || '' : '';
  }

  function getRegionStartIndexById(regionId) {
    const order = getLevelOrder();
    const definition = findRegionDefinition(regionId);
    if (definition && definition.levels && definition.levels.length) {
      const configuredIndex = order.indexOf(definition.levels[0]);
      if (configuredIndex >= 0) return configuredIndex;
    }

    const wanted = normalizeRegionId(regionId);
    if (!wanted) return 0;
    for (let index = 0; index < order.length; index++) {
      if (normalizeRegionId(getLevelRegionId(getLevelByIndex(index))) === wanted) return index;
    }

    return 0;
  }

  function getRegionStartIndexByScreen(screenIndex) {
    const order = getLevelOrder();
    if (!order.length) return 0;
    const currentIndex = clamp(Number(screenIndex) || 0, 0, order.length - 1);
    const currentKey = order[currentIndex];
    const definition = getRegionDefinitions().find(region => region.levels.includes(currentKey));
    if (definition && definition.levels.length) {
      const configuredIndex = order.indexOf(definition.levels[0]);
      return configuredIndex >= 0 ? configuredIndex : currentIndex;
    }

    const regionId = getLevelRegionId(getLevelByIndex(currentIndex));
    if (!regionId) return currentIndex;
    let startIndex = currentIndex;
    for (let index = currentIndex - 1; index >= 0; index -= 1) {
      const levelRegionId = getLevelRegionId(getLevelByIndex(index));
      if (levelRegionId !== regionId) break;
      startIndex = index;
    }
    return startIndex;
  }

  function getRegionEndIndexByStart(startIndex) {
    const order = getLevelOrder();
    if (!order.length) return 0;
    const safeStart = clamp(Number(startIndex) || 0, 0, order.length - 1);
    const startKey = order[safeStart];
    const definition = getRegionDefinitions().find(region => region.levels.includes(startKey));
    if (definition && definition.levels.length) {
      let endIndex = safeStart;
      for (const key of definition.levels) {
        const index = order.indexOf(key);
        if (index >= 0) endIndex = Math.max(endIndex, index);
      }
      return endIndex;
    }

    const regionId = getLevelRegionId(getLevelByIndex(safeStart));
    if (!regionId) return safeStart;
    let endIndex = safeStart;
    for (let index = safeStart + 1; index < order.length; index += 1) {
      const levelRegionId = getLevelRegionId(getLevelByIndex(index));
      if (levelRegionId !== regionId) break;
      endIndex = index;
    }
    return endIndex;
  }

  function getActiveRegionStartIndex(game) {
    const order = getLevelOrder();
    if (!order.length) return 0;
    const byId = getRegionStartIndexById(getActiveRegionId(game));
    if (byId || normalizeRegionId(getActiveRegionId(game))) return byId;
    return clamp(getActiveRegionIndex(game) * 3, 0, order.length - 1);
  }

  function getLocalScreenIndex(game) {
    const scene = game && game.scene;
    if (!scene || !Number.isFinite(scene.screenIndex)) return 0;
    const startIndex = getRegionStartIndexByScreen(scene.screenIndex);
    const endIndex = getRegionEndIndexByStart(startIndex);
    return clamp(scene.screenIndex - startIndex, 0, Math.max(0, endIndex - startIndex));
  }

  function getAbsoluteScreenIndexForSave(game, save) {
    const order = getLevelOrder();
    if (!order.length) return 0;
    const route = getRegionDefinitions();
    const mapOrder = game && game.campaignMap && Array.isArray(game.campaignMap.order) ? game.campaignMap.order : route.map(region => region.mapId);
    const regionIndex = clamp(Number(save && save.campaign && save.campaign.currentRegionIndex) || 0, 0, Math.max(0, mapOrder.length - 1));
    const regionId = (route[regionIndex] && route[regionIndex].mapId) || mapOrder[regionIndex] || save && save.campaign && save.campaign.currentRegion || '';
    const startIndex = getRegionStartIndexById(regionId) || clamp(regionIndex * 3, 0, order.length - 1);
    const endIndex = getRegionEndIndexByStart(startIndex);
    const localIndex = clamp(Number(save && save.campaign && save.campaign.currentScreen) || 0, 0, Math.max(0, endIndex - startIndex));
    return clamp(startIndex + localIndex, 0, order.length - 1);
  }

  function resetGundosSceneState(scene) {
    if (!scene) return;
    if (scene.stopGundosVoice) scene.stopGundosVoice();
    scene.gundosIntroActive = false;
    scene.gundosIntroLocked = false;
    scene.gundosArenaActive = false;
    scene.gundosVictoryPending = false;
    scene.gundosVictoryDelayMs = 0;
    scene.activeGundos = null;
    scene.gundosFloatTexts = [];
  }

  function placePlayerAtLevelStart(scene) {
    if (!scene || !scene.player) return;
    const level = scene.getLevelConfig ? scene.getLevelConfig() : null;
    const start = level && level.playerStart || { x: 190, y: 620 };
    scene.player.x = Number(start.x) || 190;
    scene.player.y = Number(start.y) || 620;
    scene.player.facing = scene.player.x > GAME_CONFIG.width / 2 ? -1 : 1;
    scene.player.state = 'idle';
    if (scene.player.releaseFromPin) scene.player.releaseFromPin();
  }

  function setSceneScreen(scene, screenIndex, options) {
    if (!scene) return;
    const order = getLevelOrder();
    const maxIndex = Math.max(0, order.length - 1);
    const targetIndex = clamp(Number(screenIndex) || 0, 0, maxIndex);
    resetGundosSceneState(scene);
    scene.screenIndex = targetIndex;
    placePlayerAtLevelStart(scene);
    if (!options || options.spawn !== false) {
      if (scene.spawnInitialWave) scene.spawnInitialWave();
    }
  }

  function startActiveRegionScene(game) {
    if (!game || !game.scene) return;
    const targetIndex = getActiveRegionStartIndex(game);
    if (game.scene.screenIndex === targetIndex) {
      placePlayerAtLevelStart(game.scene);
      return;
    }
    setSceneScreen(game.scene, targetIndex);
  }

  window.CampaignRuntime = {
    clamp,
    normalizeRegionId,
    getLevelOrder,
    getRegionDefinitions,
    findRegionDefinition,
    getLevelRegionId,
    getActiveRegionIndex,
    getActiveRegionId,
    getRegionStartIndexById,
    getRegionStartIndexByScreen,
    getRegionEndIndexByStart,
    getActiveRegionStartIndex,
    getLocalScreenIndex,
    getAbsoluteScreenIndexForSave,
    resetGundosSceneState,
    placePlayerAtLevelStart,
    setSceneScreen,
    startActiveRegionScene
  };
})();



/* ===== src/campaignFlow.js ===== */
(function () {
  if (typeof window === 'undefined') return;

  function getCampaignProgress(game) {
    return game && game.campaignMap && Number.isFinite(game.campaignMap.activeIndex)
      ? game.campaignMap.activeIndex
      : 0;
  }

  function canContinue(game) {
    if (!game) return false;
    if (game.loadCampaignSave && game.loadCampaignSave()) return true;
    return !!(game.runInProgress || game.scene || getCampaignProgress(game) > 0);
  }

  function getMenuItems(game) {
    const items = [];
    if (canContinue(game)) items.push({ key: 'continue', label: 'ПРОДОЛЖИТЬ' });
    items.push({ key: 'newGame', label: 'НОВАЯ ИГРА' });
    items.push({ key: 'bestiary', label: 'ТВАРИ' });
    items.push({ key: 'settings', label: 'НАСТРОЙКИ' });
    return items;
  }

  function openCharacterSelect(game, mode) {
    if (!game) return;
    game.runInProgress = true;
    game.resumeTarget = mode === 'campaignStart' ? 'campaignMap' : game.resumeTarget;
    game.characterSelectMode = mode || 'campaignStart';
    if (typeof CharacterSelect !== 'undefined') {
      CharacterSelect.infoOpen = false;
      CharacterSelect.footerFocus = null;
      CharacterSelect.gameRef = game;
    }
    game.setState('characterSelect');
  }

  function backFromCharacterSelect(game) {
    if (!game) return;
    if (typeof AudioManager !== 'undefined') AudioManager.playSfx('menuSelect', 0.65);
    const mode = game.characterSelectMode;
    game.characterSelectMode = null;

    if ((mode === 'casualty' || mode === 'switchHero') && game.scene) {
      game.setState('level');
      return;
    }

    if (mode === 'campaignStart') {
      game.resumeTarget = 'campaignMap';
      game.setState('campaignMap');
      return;
    }

    game.setState('mainMenu');
  }

  function confirmCharacterSelect(select, game) {
    if (!select || !game) return;
    const heroKey = select.heroes[select.selectedIndex];
    if (select.isHeroDisabled && select.isHeroDisabled(game, heroKey)) {
      if (typeof AudioManager !== 'undefined') AudioManager.playSfx('menuBack', 0.65);
      return;
    }

    game.selectedHero = heroKey;
    if (typeof AudioManager !== 'undefined') AudioManager.playSfx('menuSelect', 0.85);

    if ((game.characterSelectMode === 'casualty' || game.characterSelectMode === 'switchHero') && game.resumeAfterHeroDefeat) {
      game.resumeAfterHeroDefeat(heroKey);
      return;
    }

    if (game.characterSelectMode === 'retryRegion' && game.startRetryRegion) {
      game.startRetryRegion(heroKey);
      return;
    }

    game.characterSelectMode = null;
    game.runInProgress = true;
    game.resumeTarget = 'level';
    if (game.resetTeamRun) game.resetTeamRun();
    game.startLevel();
  }

  function resetRunForNewCampaign(game) {
    if (!game) return;
    if (game.clearCampaignSave) game.clearCampaignSave();
    game.runInProgress = true;
    game.resumeTarget = 'campaignMap';
    game.scene = null;
    game.paused = false;
    game.characterSelectMode = null;
    game.casualtyRespawn = null;
    game.regionStory = null;
    game.gameOverSelection = 0;
    game.gameOverRegionStartIndex = 0;
    game.gundosAudioPauseState = false;
    if (game.campaignMap && game.campaignMap.resetProgress) game.campaignMap.resetProgress();
    if (game.resetTeamRun) game.resetTeamRun();
    if (typeof CharacterSelect !== 'undefined') {
      CharacterSelect.infoOpen = false;
      CharacterSelect.footerFocus = null;
      CharacterSelect.selectedIndex = 0;
      CharacterSelect.gameRef = game;
    }
  }

  function startNewCampaign(game) {
    resetRunForNewCampaign(game);
    if (game.startIntro) game.startIntro();
    else game.setState('campaignMap');
  }

  function continueCampaignRun(game) {
    if (!canContinue(game)) return false;

    if (typeof AudioManager !== 'undefined') {
      AudioManager.unlock();
      AudioManager.playSfx('menuSelect', 0.85);
    }

    game.paused = false;
    game.characterSelectMode = null;

    if (game.resumeTarget === 'campaignMap' || !game.scene) {
      game.setState('campaignMap');
      if (game.ensureMenuMusic) game.ensureMenuMusic();
      return true;
    }

    game.setState('level');
    const level = game.scene && game.scene.getLevelConfig ? game.scene.getLevelConfig() : null;
    if (typeof AudioManager !== 'undefined') {
      AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
    }
    return true;
  }

  window.CampaignFlow = {
    canContinue,
    getMenuItems,
    openCharacterSelect,
    backFromCharacterSelect,
    confirmCharacterSelect,
    resetRunForNewCampaign,
    startNewCampaign,
    continueCampaignRun
  };
})();



/* ===== src/mobileControls.js ===== */
const MobileControls = {
  active: false,
  heldKeys: {},
  moveOrigin: null,
  moveTouchId: null,

  topSafeY() {
    return 96;
  },

  attackButton() {
    return { x: GAME_CONFIG.width - 92, y: 164, r: 44, hitR: 104 };
  },

  movementStartZone() {
    return { x: 0, y: this.topSafeY(), w: GAME_CONFIG.width * 0.58, h: GAME_CONFIG.height - this.topSafeY() };
  },

  shouldShow(game) {
    return !!(Responsive.isTouchDevice && game && game.state === 'level' && game.scene);
  },

  setHeldKey(key, value) {
    if (this.heldKeys[key] === value) return;
    this.heldKeys[key] = value;
    Input.setVirtualKey(key, value);
  },

  releaseHeldKeys() {
    for (const key of Object.keys(this.heldKeys)) {
      if (this.heldKeys[key]) Input.setVirtualKey(key, false);
    }
    this.heldKeys = {};
  },

  applyDesiredKeys(desired) {
    const keys = ['arrowleft', 'arrowright', 'arrowup', 'arrowdown', 'space'];
    for (const key of keys) this.setHeldKey(key, !!desired[key]);
  },

  pointInRect(point, rect) {
    return point && point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h;
  },

  pointInCircle(point, circle, radiusOverride) {
    const r = radiusOverride || circle.r;
    const dx = point.x - circle.x;
    const dy = point.y - circle.y;
    return dx * dx + dy * dy <= r * r;
  },

  resetTouchState() {
    this.moveOrigin = null;
    this.moveTouchId = null;
  },

  getTouches() {
    return Input.touches && Input.touches.length ? Input.touches : [];
  },

  getTouchById(id) {
    if (id == null) return null;
    return this.getTouches().find(touch => touch.id === id) || null;
  },

  findNewMoveTouch() {
    const attack = this.attackButton();
    return this.getTouches().find(touch => (
      touch.justDown &&
      this.pointInRect(touch, this.movementStartZone()) &&
      !this.pointInCircle(touch, attack, attack.hitR)
    )) || null;
  },

  hasAttackTouch() {
    const attack = this.attackButton();
    const touches = this.getTouches();
    for (let i = 0; i < touches.length; i++) {
      const touch = touches[i];
      if (touch.y < this.topSafeY()) continue;
      if (this.pointInCircle(touch, attack, attack.hitR)) return true;
    }
    return false;
  },

  update(game) {
    this.active = this.shouldShow(game);
    if (!this.active) {
      this.resetTouchState();
      this.releaseHeldKeys();
      return;
    }

    const desired = {};

    if (this.hasAttackTouch()) desired.space = true;

    let moveTouch = this.getTouchById(this.moveTouchId);
    if (!moveTouch) {
      this.moveTouchId = null;
      this.moveOrigin = null;
      moveTouch = this.findNewMoveTouch();
      if (moveTouch) {
        this.moveTouchId = moveTouch.id;
        this.moveOrigin = { x: moveTouch.x, y: moveTouch.y };
      }
    }

    if (moveTouch && this.moveOrigin) {
      const dx = moveTouch.x - this.moveOrigin.x;
      const dy = moveTouch.y - this.moveOrigin.y;
      const distance = Math.hypot(dx, dy);
      const dead = 16;

      if (distance > dead) {
        const nx = dx / Math.max(1, distance);
        const ny = dy / Math.max(1, distance);
        const horizontal = Math.abs(nx);
        const vertical = Math.abs(ny);

        if (horizontal > 0.20) desired[nx < 0 ? 'arrowleft' : 'arrowright'] = true;
        if (vertical > 0.28) desired[ny < 0 ? 'arrowup' : 'arrowdown'] = true;
      }
    }

    this.applyDesiredKeys(desired);
  },

  getStick() {
    const origin = this.moveOrigin || { x: 160, y: GAME_CONFIG.height - 132 };
    return { x: origin.x, y: origin.y, r: 78, knobR: 30 };
  },

  getDpad() {
    return this.getStick();
  },

  getAttackButton() {
    const button = this.attackButton();
    return { x: button.x, y: button.y, r: button.hitR };
  },

  draw(ctx, game) {
    if (!this.shouldShow(game)) return;

    const moveTouch = this.getTouchById(this.moveTouchId);
    const stick = this.getStick();
    const attack = this.attackButton();
    let knobX = stick.x;
    let knobY = stick.y;

    if (moveTouch && this.moveOrigin) {
      const dx = moveTouch.x - stick.x;
      const dy = moveTouch.y - stick.y;
      const distance = Math.hypot(dx, dy);
      const max = stick.r - stick.knobR;
      const ratio = distance > max ? max / Math.max(1, distance) : 1;
      knobX = stick.x + dx * ratio;
      knobY = stick.y + dy * ratio;
    }

    ctx.save();

    if (this.moveOrigin) {
      ctx.fillStyle = 'rgba(255,255,255,0.055)';
      ctx.strokeStyle = 'rgba(255,255,255,0.24)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(stick.x, stick.y, stick.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = 'rgba(255,255,255,0.18)';
      ctx.strokeStyle = 'rgba(255,255,255,0.34)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(knobX, knobY, stick.knobR, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }

    const attackPressed = this.hasAttackTouch();
    ctx.fillStyle = attackPressed ? 'rgba(150,0,0,0.28)' : 'rgba(150,0,0,0.11)';
    ctx.strokeStyle = attackPressed ? 'rgba(255,255,255,0.48)' : 'rgba(255,255,255,0.20)';
    ctx.lineWidth = attackPressed ? 4 : 2;
    ctx.beginPath();
    ctx.arc(attack.x, attack.y, attack.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.font = 'bold 17px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'rgba(255,255,255,0.52)';
    ctx.strokeStyle = 'rgba(0,0,0,0.55)';
    ctx.lineWidth = 3;
    ctx.strokeText('УДАР', attack.x, attack.y);
    ctx.fillText('УДАР', attack.x, attack.y);

    ctx.restore();
  }
};



/* ===== src/mobileApp.js ===== */
const MobileApp = {
  enabled: false,
  lastTap: null,
  debug: /mobiledebug=1/.test(window.location.search),
  paused: false,

  isMobile() {
    return !!(Responsive && Responsive.isTouchDevice);
  },

  attach(game) {
    this.enabled = this.isMobile();
    if (!this.enabled || !game || game.mobileAppAttached) return;
    game.mobileAppAttached = true;
    this.patchGame(game);
  },

  patchGame(game) {
    const originalUpdate = game.update.bind(game);
    const originalDraw = game.draw.bind(game);
    const mobile = this;

    game.update = function (dt) {
      if (!mobile.enabled) {
        originalUpdate(dt);
        return;
      }

      if (mobile.updateStandalone(this, dt)) return;
      originalUpdate(dt);
    };

    game.draw = function () {
      if (mobile.enabled && mobile.drawStandalone(this.ctx, this)) return;
      originalDraw();
      if (mobile.enabled) mobile.drawOverlay(this.ctx, this);
    };
  },

  updateStandalone(game, dt) {
    const click = Input.consumePointer();
    if (click) {
      this.lastTap = { x: Math.round(click.x), y: Math.round(click.y), state: game.state };
      if (game.handleSpeakerClick && game.handleSpeakerClick(click)) return true;
    }

    if (game.state === 'splash') {
      if (click || Input.consumeAnyKey()) {
        AudioManager.unlock();
        AudioManager.playSfx('menuSelect', 0.75);
        game.setState('mainMenu');
      }
      return true;
    }

    if (game.state === 'mainMenu') {
      if (click) this.handleMainMenuTap(game, click);
      return true;
    }

    if (game.state === 'settings') {
      if (click) this.handleSettingsTap(game, click);
      return true;
    }

    if (game.state === 'characterSelect') {
      if (click) this.handleCharacterTap(game, click);
      return true;
    }

    if (game.state === 'intro') {
      if (click) {
        if (this.inRect(click, this.skipIntroBox())) {
          if (game.finishIntro) game.finishIntro();
          return true;
        }
        Input.restorePointer(click);
      }
      if (game.updateIntro) game.updateIntro(dt);
      return true;
    }

    if (game.state === 'campaignMap') {
      if (click) {
        AudioManager.unlock();
        AudioManager.playSfx('menuSelect', 0.85);
        game.setState('characterSelect');
        return true;
      }
      if (game.campaignMap && game.campaignMap.update) game.campaignMap.update(game, dt);
      return true;
    }

    if (game.state === 'level') {
      if (click && this.inRect(click, this.pauseBox())) {
        this.paused = !this.paused;
        AudioManager.playSfx('menuSelect', 0.65);
        return true;
      }
      if (this.paused) return true;
      if (click) Input.restorePointer(click);
    } else if (click) {
      Input.restorePointer(click);
    }

    return false;
  },

  drawStandalone(ctx, game) {
    if (game.state === 'splash') {
      this.drawMobileSplash(ctx, game);
      this.drawDebug(ctx, game);
      return true;
    }
    if (game.state === 'mainMenu') {
      this.drawMobileMainMenu(ctx, game);
      this.drawDebug(ctx, game);
      return true;
    }
    if (game.state === 'settings') {
      this.drawMobileSettings(ctx, game);
      this.drawDebug(ctx, game);
      return true;
    }
    if (game.state === 'characterSelect') {
      this.drawMobileCharacterSelect(ctx, game);
      this.drawDebug(ctx, game);
      return true;
    }
    if (game.state === 'intro') {
      this.drawMobileIntro(ctx, game);
      this.drawDebug(ctx, game);
      return true;
    }
    if (game.state === 'campaignMap') {
      this.drawMobileCampaignMap(ctx, game);
      this.drawDebug(ctx, game);
      return true;
    }
    return false;
  },

  drawOverlay(ctx, game) {
    if (game.state === 'level') {
      this.drawPauseButton(ctx);
      if (this.paused) this.drawPauseOverlay(ctx, game);
    }
    this.drawDebug(ctx, game);
  },

  rect(x, y, w, h) { return { x, y, w, h }; },
  inRect(point, rect) { return point && point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h; },

  pauseBox() { return this.rect(20, 18, 92, 62); },
  skipIntroBox() { return this.rect(1015, 628, 225, 64); },

  mainMenuRects() {
    return [this.rect(220, 250, 840, 86), this.rect(220, 355, 840, 86), this.rect(220, 460, 840, 86)];
  },

  settingsControlRects(index) {
    const y = 140 + index * 84;
    return {
      row: this.rect(100, y, 1080, 76),
      minus: this.rect(100, y, 92, 76),
      plus: this.rect(1088, y, 92, 76),
      label: this.rect(210, y, 860, 76)
    };
  },

  characterRects() {
    return {
      heroes: [this.rect(80, 126, 330, 410), this.rect(475, 126, 330, 410), this.rect(870, 126, 330, 410)],
      info: [this.rect(92, 138, 58, 58), this.rect(487, 138, 58, 58), this.rect(882, 138, 58, 58)],
      confirm: this.rect(235, 595, 490, 90),
      back: this.rect(760, 595, 285, 90)
    };
  },

  handleMainMenuTap(game, click) {
    const rects = this.mainMenuRects();
    for (let i = 0; i < rects.length; i++) {
      if (!this.inRect(click, rects[i])) continue;
      AudioManager.unlock();
      AudioManager.playSfx('menuSelect', 0.85);
      if (i === 0) {
        if (game.startIntro) game.startIntro();
        else game.setState('characterSelect');
      }
      if (i === 1) game.setState('mainMenu');
      if (i === 2) game.setState('settings');
      return true;
    }
    return false;
  },

  handleSettingsTap(game, click) {
    const items = (Menu && Menu.settingsItems) || [];
    for (let i = 0; i < items.length; i++) {
      const r = this.settingsControlRects(i);
      if (!this.inRect(click, r.row)) continue;
      AudioManager.unlock();
      Menu.settingsIndex = i;
      const direction = this.inRect(click, r.minus) ? -1 : 1;
      Menu.changeSetting(i, game, direction);
      return true;
    }
    return false;
  },

  handleCharacterTap(game, click) {
    if (typeof CharacterSelect === 'undefined') return false;
    const rects = this.characterRects();

    for (let i = 0; i < rects.info.length; i++) {
      if (!this.inRect(click, rects.info[i])) continue;
      CharacterSelect.setSelection(i);
      CharacterSelect.openInfo();
      return true;
    }

    if (CharacterSelect.infoOpen) {
      CharacterSelect.closeInfo();
      return true;
    }

    for (let i = 0; i < rects.heroes.length; i++) {
      if (!this.inRect(click, rects.heroes[i])) continue;
      CharacterSelect.setSelection(i);
      CharacterSelect.footerFocus = null;
      return true;
    }

    if (this.inRect(click, rects.confirm)) { CharacterSelect.confirm(game); return true; }
    if (this.inRect(click, rects.back)) { AudioManager.playSfx('menuSelect', 0.65); game.setState('mainMenu'); return true; }
    return false;
  },

  drawBackground(ctx, game, alpha = 0.62) {
    const bg = game.images && game.images.main;
    if (bg) ctx.drawImage(bg, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    else { ctx.fillStyle = '#050508'; ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height); }
    ctx.fillStyle = 'rgba(0,0,0,' + alpha + ')';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
  },

  drawButton(ctx, box, label, active = false, fontSize = 34) {
    ctx.save();
    ctx.fillStyle = active ? 'rgba(130,0,0,0.78)' : 'rgba(0,0,0,0.58)';
    ctx.strokeStyle = active ? 'rgba(255,255,255,0.94)' : 'rgba(255,255,255,0.62)';
    ctx.lineWidth = active ? 5 : 3;
    ctx.fillRect(box.x, box.y, box.w, box.h);
    ctx.strokeRect(box.x, box.y, box.w, box.h);
    ctx.font = 'bold ' + fontSize + 'px Arial';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff'; ctx.strokeStyle = '#000'; ctx.lineWidth = 5;
    ctx.strokeText(label, box.x + box.w / 2, box.y + box.h / 2 + 2);
    ctx.fillText(label, box.x + box.w / 2, box.y + box.h / 2 + 2);
    ctx.restore();
  },

  drawMobileSplash(ctx, game) {
    this.drawBackground(ctx, game, 0.22);
    this.drawButton(ctx, this.rect(250, 548, 780, 96), 'НАЖМИТЕ НА ЭКРАН', true, 33);
    game.drawSpeaker(ctx);
  },

  drawMobileMainMenu(ctx, game) {
    this.drawBackground(ctx, game, 0.54);
    const rects = this.mainMenuRects();
    const labels = ['НОВАЯ ИГРА', 'ТВАРИ', 'НАСТРОЙКИ'];
    ctx.save(); ctx.font = 'bold 52px Arial'; ctx.textAlign = 'center'; ctx.fillStyle = '#fff'; ctx.strokeStyle = '#000'; ctx.lineWidth = 7;
    ctx.strokeText('STREETS OF RUSSIA', GAME_CONFIG.width / 2, 162); ctx.fillText('STREETS OF RUSSIA', GAME_CONFIG.width / 2, 162); ctx.restore();
    for (let i = 0; i < rects.length; i++) this.drawButton(ctx, rects[i], labels[i], i === 0, 34);
    game.drawSpeaker(ctx);
  },

  drawMobileSettings(ctx, game) {
    this.drawBackground(ctx, game, 0.70);
    ctx.save(); ctx.font = 'bold 42px Arial'; ctx.textAlign = 'center'; ctx.fillStyle = '#fff'; ctx.strokeStyle = '#000'; ctx.lineWidth = 6;
    ctx.strokeText('НАСТРОЙКИ', GAME_CONFIG.width / 2, 90); ctx.fillText('НАСТРОЙКИ', GAME_CONFIG.width / 2, 90); ctx.restore();
    const items = (Menu && Menu.settingsItems) || [];
    for (let i = 0; i < items.length; i++) {
      const r = this.settingsControlRects(i);
      const label = Menu && Menu.getSettingsLabel ? Menu.getSettingsLabel(i) : items[i];
      this.drawButton(ctx, r.row, label, i === Menu.settingsIndex, 23);
      if (items[i].indexOf('ГРОМКОСТЬ') >= 0 || items[i] === 'СЛОЖНОСТЬ') {
        this.drawButton(ctx, r.minus, '−', false, 38);
        this.drawButton(ctx, r.plus, '+', false, 38);
      }
    }
    game.drawSpeaker(ctx);
  },

  drawMobileCharacterSelect(ctx, game) {
    this.drawBackground(ctx, game, 0.68);
    ctx.save(); ctx.font = 'bold 40px Arial'; ctx.textAlign = 'center'; ctx.fillStyle = '#fff'; ctx.strokeStyle = '#000'; ctx.lineWidth = 6;
    ctx.strokeText('ВЫБЕРИТЕ ПЕРСОНАЖА', GAME_CONFIG.width / 2, 72); ctx.fillText('ВЫБЕРИТЕ ПЕРСОНАЖА', GAME_CONFIG.width / 2, 72); ctx.restore();
    const rects = this.characterRects();
    for (let i = 0; i < CharacterSelect.heroes.length; i++) this.drawMobileHeroCard(ctx, game, CharacterSelect.heroes[i], i, rects.heroes[i]);
    this.drawButton(ctx, rects.confirm, 'ПОДТВЕРДИТЬ', true, 32);
    this.drawButton(ctx, rects.back, 'НАЗАД', false, 30);
    if (CharacterSelect.infoOpen) CharacterSelect.drawInfoModal(ctx, game.images);
    game.drawSpeaker(ctx);
  },

  drawMobileHeroCard(ctx, game, heroKey, index, box) {
    const hero = GAME_CONFIG.heroes[heroKey];
    const selected = index === CharacterSelect.selectedIndex;
    ctx.save();
    ctx.fillStyle = selected ? 'rgba(90,0,0,0.68)' : 'rgba(0,0,0,0.52)';
    ctx.strokeStyle = selected ? '#fff' : 'rgba(255,255,255,0.55)';
    ctx.lineWidth = selected ? 5 : 3;
    ctx.fillRect(box.x, box.y, box.w, box.h); ctx.strokeRect(box.x, box.y, box.w, box.h);
    const heroImages = game.images.heroes && game.images.heroes[heroKey];
    const portrait = this.rect(box.x + 32, box.y + 54, box.w - 64, 225);
    if (heroImages && heroImages.idle) {
      const img = heroImages.idle;
      const scale = Math.min(portrait.w / img.width, portrait.h / img.height);
      const w = img.width * scale; const h = img.height * scale;
      ctx.drawImage(img, portrait.x + portrait.w / 2 - w / 2, portrait.y + portrait.h - h, w, h);
    }
    ctx.font = 'bold 24px Arial'; ctx.textAlign = 'center'; ctx.fillStyle = hero.color || '#fff'; ctx.strokeStyle = '#000'; ctx.lineWidth = 4;
    ctx.strokeText(hero.name.toUpperCase(), box.x + box.w / 2, box.y + 322); ctx.fillText(hero.name.toUpperCase(), box.x + box.w / 2, box.y + 322);
    this.drawButton(ctx, this.characterRects().info[index], 'i', false, 26);
    ctx.restore();
  },

  drawMobileIntro(ctx, game) {
    if (game.drawIntro) game.drawIntro(ctx);
    this.drawButton(ctx, this.skipIntroBox(), 'ДАЛЬШЕ', false, 24);
    game.drawSpeaker(ctx);
  },

  drawMobileCampaignMap(ctx, game) {
    if (game.campaignMap && game.campaignMap.draw) game.campaignMap.draw(ctx);
    this.drawButton(ctx, this.rect(430, 620, 420, 70), 'НАЧАТЬ УРОВЕНЬ', true, 28);
    game.drawSpeaker(ctx);
  },

  drawPauseButton(ctx) { this.drawButton(ctx, this.pauseBox(), 'Ⅱ', false, 34); },
  drawPauseOverlay(ctx, game) {
    ctx.fillStyle = 'rgba(0,0,0,0.58)'; ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    this.drawButton(ctx, this.rect(390, 250, 500, 90), 'ПРОДОЛЖИТЬ', true, 34);
    this.drawButton(ctx, this.rect(390, 370, 500, 90), 'В МЕНЮ', false, 34);
  },

  drawDebug(ctx, game) {
    if (!this.debug) return;
    ctx.save(); ctx.fillStyle = 'rgba(0,0,0,0.74)'; ctx.fillRect(12, 620, 540, 86);
    ctx.fillStyle = '#00ff99'; ctx.font = '18px monospace'; ctx.fillText('MOBILE state: ' + game.state, 24, 648);
    if (this.lastTap) ctx.fillText('tap: ' + this.lastTap.x + ', ' + this.lastTap.y + ' from ' + this.lastTap.state, 24, 674);
    ctx.restore();
  }
};


/* ===== src/mobileSafeUxPatch.js ===== */
(function () {
  if (typeof MobileApp === 'undefined') return;

  const mobile = MobileApp;
  mobile.introTouchDrag = null;
  mobile.wakeLock = null;
  mobile.mobilePauseOpen = false;
  mobile.mobileBestiaryIndex = 0;

  mobile.requestGameWakeLock = async function () {
    if (!('wakeLock' in navigator)) return;
    if (this.wakeLock) return;
    try {
      this.wakeLock = await navigator.wakeLock.request('screen');
      this.wakeLock.addEventListener('release', () => { this.wakeLock = null; });
    } catch (error) { this.wakeLock = null; }
  };

  mobile.releaseGameWakeLock = async function () {
    if (!this.wakeLock) return;
    try { await this.wakeLock.release(); } catch (error) {}
    this.wakeLock = null;
  };

  mobile.syncGameWakeLock = function (game) {
    const activeStates = ['intro', 'campaignMap', 'characterSelect', 'level', 'settings', 'bestiary'];
    if (game && activeStates.includes(game.state)) this.requestGameWakeLock();
    else this.releaseGameWakeLock();
  };

  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible' && window.game && MobileApp.enabled) {
      MobileApp.syncGameWakeLock(window.game);
    }
  });

  mobile.handleIntroTouchScroll = function (game) {
    if (!game || !game.intro || !game.intro.readyToContinue || !Input.pointer) return false;
    if (Input.pointer.down) {
      const p = Input.pointer;
      if (!this.introTouchDrag) {
        this.introTouchDrag = { y: p.y, moved: false };
        return false;
      }
      const dy = p.y - this.introTouchDrag.y;
      if (Math.abs(dy) >= 4) {
        const direction = dy < 0 ? 1 : -1;
        const steps = Math.max(1, Math.round(Math.abs(dy) / 32));
        if (game.scrollIntroReader) game.scrollIntroReader(direction * steps);
        this.introTouchDrag.y = p.y;
        this.introTouchDrag.moved = true;
        return true;
      }
      return false;
    }
    this.introTouchDrag = null;
    return false;
  };

  mobile.menuBox = function () { return this.rect(14, 16, 104, 56); };
  mobile.mobilePauseRects = function () {
    return {
      resume: this.rect(390, 145, 500, 62),
      settings: this.rect(390, 225, 500, 62),
      bestiary: this.rect(390, 305, 500, 62),
      developer: this.rect(390, 385, 500, 62),
      mainMenu: this.rect(390, 465, 500, 62)
    };
  };

  mobile.bestiaryRects = function () {
    return {
      prev: this.rect(110, 595, 190, 70),
      next: this.rect(980, 595, 190, 70),
      back: this.rect(420, 595, 440, 70)
    };
  };

  mobile.getBestiaryTypes = function () {
    const preferred = ['dogRegime', 'zetnik', 'sucker', 'bastard', 'horse'];
    const configTypes = Object.keys((typeof GAME_CONFIG !== 'undefined' && GAME_CONFIG.enemies) || {});
    const combined = preferred.concat(configTypes);
    return combined.filter((type, index) => combined.indexOf(type) === index && ((GAME_CONFIG.enemies || {})[type] || type === 'horse'));
  };

  mobile.getEnemyLabel = function (type) {
    const names = {
      dogRegime: 'ПЁС РЕЖИМА',
      zetnik: 'ЗЕТНИК',
      sucker: 'ПРИСОСКА',
      bastard: 'ТВАРЬ',
      horse: 'HORSE'
    };
    return names[type] || String(type).toUpperCase();
  };

  mobile.openDeveloperPanelFromMobile = function (game) {
    if (typeof DevPanel === 'undefined') return;
    this.mobilePauseOpen = false;
    this.paused = false;
    if (game) game.paused = false;
    GAME_CONFIG.adminTuningEnabled = true;
    if (typeof DevPanel.openFromPauseMenu === 'function') DevPanel.openFromPauseMenu(game);
    else {
      DevPanel.open = true;
      DevPanel.tab = 'LEVEL WAVES';
      if (typeof DevPanel.ensureLevels === 'function') DevPanel.ensureLevels();
      if (typeof DevPanel.syncSelectedLevelWithScene === 'function') DevPanel.syncSelectedLevelWithScene(game);
    }
    AudioManager.playSfx('menuSelect', 0.65);
  };

  mobile.handleMobileLevelMenuTap = function (game, click) {
    if (!click) return false;
    if (game && game.handleSpeakerClick && game.handleSpeakerClick(click)) return true;

    if (!this.mobilePauseOpen) {
      if (this.inRect(click, this.menuBox())) {
        this.mobilePauseOpen = true;
        this.paused = true;
        AudioManager.playSfx('menuSelect', 0.65);
        return true;
      }
      return false;
    }

    const rects = this.mobilePauseRects();
    if (this.inRect(click, rects.resume)) {
      this.mobilePauseOpen = false;
      this.paused = false;
      AudioManager.playSfx('menuSelect', 0.65);
      return true;
    }
    if (this.inRect(click, rects.settings)) {
      this.mobilePauseOpen = false;
      this.paused = false;
      if (game) game.setState('settings');
      AudioManager.playSfx('menuSelect', 0.65);
      return true;
    }
    if (this.inRect(click, rects.bestiary)) {
      this.mobilePauseOpen = false;
      this.paused = false;
      this.mobileBestiaryIndex = 0;
      if (game && game.openBestiary) game.openBestiary('level');
      else if (game) game.setState('bestiary');
      return true;
    }
    if (this.inRect(click, rects.developer)) {
      this.openDeveloperPanelFromMobile(game);
      return true;
    }
    if (this.inRect(click, rects.mainMenu)) {
      this.mobilePauseOpen = false;
      this.paused = false;
      if (game) {
        game.paused = false;
        game.setState('mainMenu');
      }
      AudioManager.playSfx('menuSelect', 0.65);
      return true;
    }

    return true;
  };

  mobile.handleBestiaryTap = function (game, click) {
    if (!click) return false;
    if (game && game.handleSpeakerClick && game.handleSpeakerClick(click)) return true;
    const types = this.getBestiaryTypes();
    const rects = this.bestiaryRects();
    if (this.inRect(click, rects.prev)) {
      this.mobileBestiaryIndex = (this.mobileBestiaryIndex + types.length - 1) % Math.max(1, types.length);
      AudioManager.playSfx('menuMove', 0.7);
      return true;
    }
    if (this.inRect(click, rects.next)) {
      this.mobileBestiaryIndex = (this.mobileBestiaryIndex + 1) % Math.max(1, types.length);
      AudioManager.playSfx('menuMove', 0.7);
      return true;
    }
    if (this.inRect(click, rects.back)) {
      if (game) game.setState('level');
      AudioManager.playSfx('menuSelect', 0.65);
      return true;
    }
    return true;
  };

  mobile.drawMobileMenuButton = function (ctx) {
    this.drawButton(ctx, this.menuBox(), 'МЕНЮ', false, 18);
  };

  mobile.drawMobileLevelMenu = function (ctx) {
    if (!this.mobilePauseOpen) return;
    const rects = this.mobilePauseRects();
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.62)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.font = 'bold 46px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 7;
    ctx.strokeText('ПАУЗА', GAME_CONFIG.width / 2, 105);
    ctx.fillText('ПАУЗА', GAME_CONFIG.width / 2, 105);
    ctx.restore();
    this.drawButton(ctx, rects.resume, 'ВЕРНУТЬСЯ В ИГРУ', true, 25);
    this.drawButton(ctx, rects.settings, 'НАСТРОЙКИ', false, 27);
    this.drawButton(ctx, rects.bestiary, 'ТВАРИ', false, 28);
    this.drawButton(ctx, rects.developer, 'РЕЖИМ РАЗРАБОТЧИКА', false, 22);
    this.drawButton(ctx, rects.mainMenu, 'ГЛАВНОЕ МЕНЮ', false, 26);
  };

  mobile.drawMobileBestiary = function (ctx, game) {
    this.drawBackground(ctx, game, 0.72);
    const types = this.getBestiaryTypes();
    if (!types.length) return;
    this.mobileBestiaryIndex = Math.max(0, Math.min(types.length - 1, this.mobileBestiaryIndex));
    const type = types[this.mobileBestiaryIndex];
    const enemyImages = game.images && game.images.enemies && game.images.enemies[type];
    const img = enemyImages && (enemyImages.idle || (enemyImages.walk && enemyImages.walk[0]) || enemyImages.dead);

    ctx.save();
    ctx.font = 'bold 44px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 7;
    ctx.strokeText('ТВАРИ', GAME_CONFIG.width / 2, 92);
    ctx.fillText('ТВАРИ', GAME_CONFIG.width / 2, 92);

    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(260, 130, 760, 420);
    ctx.strokeStyle = 'rgba(255,255,255,0.55)';
    ctx.lineWidth = 3;
    ctx.strokeRect(260, 130, 760, 420);

    ctx.font = 'bold 34px Arial';
    ctx.fillStyle = '#fff';
    ctx.strokeText(this.getEnemyLabel(type), GAME_CONFIG.width / 2, 185);
    ctx.fillText(this.getEnemyLabel(type), GAME_CONFIG.width / 2, 185);

    if (img) {
      const maxW = 360;
      const maxH = 265;
      const scale = Math.min(maxW / img.width, maxH / img.height);
      const w = img.width * scale;
      const h = img.height * scale;
      ctx.drawImage(img, GAME_CONFIG.width / 2 - w / 2, 505 - h, w, h);
    }

    ctx.font = '20px Arial';
    ctx.fillStyle = '#d8d8d8';
    ctx.fillText(String(this.mobileBestiaryIndex + 1) + ' / ' + String(types.length), GAME_CONFIG.width / 2, 525);
    ctx.restore();

    const rects = this.bestiaryRects();
    this.drawButton(ctx, rects.prev, 'НАЗАД', false, 24);
    this.drawButton(ctx, rects.back, 'ВЕРНУТЬСЯ В ИГРУ', true, 25);
    this.drawButton(ctx, rects.next, 'ВПЕРЁД', false, 24);
    if (game.drawSpeaker) game.drawSpeaker(ctx);
  };

  const originalUpdateStandalone = mobile.updateStandalone;
  mobile.updateStandalone = function (game, dt) {
    if (this.enabled) this.syncGameWakeLock(game);
    if (this.enabled && game && game.state === 'intro') this.handleIntroTouchScroll(game);

    if (this.enabled && game && game.state === 'bestiary') {
      const click = Input.consumePointer();
      if (click) this.handleBestiaryTap(game, click);
      return true;
    }

    if (this.enabled && game && game.state === 'level') {
      if (typeof DevPanel !== 'undefined' && DevPanel.open) {
        DevPanel.update(game);
        return true;
      }
      const click = Input.consumePointer();
      if (click && this.handleMobileLevelMenuTap(game, click)) return true;
      if (this.mobilePauseOpen) return true;
      if (click) Input.restorePointer(click);
    }

    return originalUpdateStandalone.call(this, game, dt);
  };

  const originalDrawStandalone = mobile.drawStandalone;
  mobile.drawStandalone = function (ctx, game) {
    if (this.enabled && game && game.state === 'bestiary') {
      this.drawMobileBestiary(ctx, game);
      this.drawDebug(ctx, game);
      return true;
    }
    return originalDrawStandalone.call(this, ctx, game);
  };

  const originalDrawOverlay = mobile.drawOverlay;
  mobile.drawOverlay = function (ctx, game) {
    if (game && game.state === 'level') {
      this.drawMobileMenuButton(ctx);
      if (game.drawSpeaker) game.drawSpeaker(ctx);
      this.drawMobileLevelMenu(ctx);
      if (typeof DevPanel !== 'undefined' && DevPanel.open) DevPanel.draw(ctx);
      this.drawDebug(ctx, game);
      return;
    }
    originalDrawOverlay.call(this, ctx, game);
  };

  mobile.drawMobileIntro = function (ctx, game) {
    if (game && game.drawIntro) game.drawIntro(ctx);
    game.drawSpeaker(ctx);
  };

  mobile.drawMobileCampaignMap = function (ctx, game) {
    if (game.campaignMap && game.campaignMap.draw) game.campaignMap.draw(ctx);
    game.drawSpeaker(ctx);
  };
})();



/* ===== src/game.js ===== */
class GameApp {
  constructor() {
    this.canvas = document.getElementById('game');
    this.ctx = this.canvas.getContext('2d');
    this.state = 'loading';
    this.selectedHero = 'boris';
    this.images = {};
    this.scene = null;
    this.lastTime = performance.now();
    this.runtimeError = null;
    this.runtimeErrorTimer = 0;
    this.suckerPinHintShown = false;
  }

  async init() {
    Responsive.init(this.canvas, this.ctx);
    Input.init(this.canvas);
    AudioManager.init();
    DevPanel.init();

    requestAnimationFrame((time) => this.loop(time));

    this.images = await this.loadImages();
    this.setState('splash');
  }

  async loadImages() {
    const paths = {
      main: Assets.backgrounds.main,
      street0: Assets.backgrounds.level1[0],
      street1: Assets.backgrounds.level1[1],
      street2: Assets.backgrounds.level1[2],

      borisIdle: Assets.boris.idle,
      borisWalk0: Assets.boris.walk[0],
      borisWalk1: Assets.boris.walk[1],
      borisWalk2: Assets.boris.walk[2],
      borisPunch0: Assets.boris.punch[0],
      borisPunch1: Assets.boris.punch[1],
      borisPunch2: Assets.boris.punch[2],
      borisKnockdown: Assets.boris.knockdown,

      alexeyIdle: Assets.alexey.idle,
      alexeyWalk0: Assets.alexey.walk[0],
      alexeyWalk1: Assets.alexey.walk[1],
      alexeyWalk2: Assets.alexey.walk[2],
      alexeyPunch0: Assets.alexey.punch[0],
      alexeyPunch1: Assets.alexey.punch[1],
      alexeyPunch2: Assets.alexey.punch[2],
      alexeyKnockdown: Assets.alexey.knockdown,

      annaIdle: Assets.anna.idle,
      annaWalk0: Assets.anna.walk[0],
      annaWalk1: Assets.anna.walk[1],
      annaWalk2: Assets.anna.walk[2],
      annaPunch0: Assets.anna.punch[0],
      annaPunch1: Assets.anna.punch[1],
      annaPunch2: Assets.anna.punch[2],
      annaKnockdown: Assets.anna.knockdown,

      dogIdle: Assets.dog.idle,
      dogWalk0: Assets.dog.walk[0],
      dogWalk1: Assets.dog.walk[1],
      dogAttack0: Assets.dog.attack[0],
      dogAttack1: Assets.dog.attack[1],
      dogDead: Assets.dog.dead,

      zetnikIdle: Assets.zetnik.idle,
      zetnikWalk0: Assets.zetnik.walk[0],
      zetnikWalk1: Assets.zetnik.walk[1],
      zetnikWalk2: Assets.zetnik.walk[2],
      zetnikAttack0: Assets.zetnik.attack[0],
      zetnikAttack1: Assets.zetnik.attack[1],
      zetnikDead: Assets.zetnik.dead,

      suckerIdle: Assets.sucker.idle,
      suckerWalk0: Assets.sucker.walk[0],
      suckerWalk1: Assets.sucker.walk[1],
      suckerAttack0: Assets.sucker.attack[0],
      suckerAttack1: Assets.sucker.attack[1],
      suckerSlide: Assets.sucker.slide,
      suckerBite0: Assets.sucker.bite[0],
      suckerBite1: Assets.sucker.bite[1],
      suckerDead: Assets.sucker.dead,

      bastardIdle: Assets.bastard.idle,
      bastardFall: Assets.bastard.fall,
      bastardWalk0: Assets.bastard.walk[0],
      bastardWalk1: Assets.bastard.walk[1],
      bastardWalk2: Assets.bastard.walk[2],

      pickupMedkit: Assets.pickups && Assets.pickups.medkit,
      pickupPirozhok: Assets.pickups && Assets.pickups.pirozhok,
      pickupTea: Assets.pickups && Assets.pickups.tea
    };

    const loaded = {};
    const entries = Object.entries(paths);
    await Promise.all(entries.map(([key, src]) => new Promise((resolve) => {
      const img = new Image();
      img.onload = () => { loaded[key] = img; resolve(); };
      img.onerror = () => { console.warn('Missing image:', src); loaded[key] = null; resolve(); };
      img.src = src;
    })));

    loaded.streets = [loaded.street0, loaded.street1, loaded.street2];
    if (GAME_CONFIG.levelOrder && GAME_CONFIG.levels) {
      const dynamicStreets = await this.loadLevelBackgrounds(loaded.streets);
      if (dynamicStreets.length) loaded.streets = dynamicStreets;
    }

    loaded.heroes = {
      boris: {
        idle: loaded.borisIdle,
        walk: [loaded.borisWalk0, loaded.borisWalk1, loaded.borisWalk2],
        punch: [loaded.borisPunch0, loaded.borisPunch1, loaded.borisPunch2],
        knockdown: loaded.borisKnockdown || loaded.borisIdle
      },
      alexey: {
        idle: loaded.alexeyIdle || loaded.borisIdle,
        walk: [loaded.alexeyWalk0 || loaded.borisWalk0, loaded.alexeyWalk1 || loaded.borisWalk1, loaded.alexeyWalk2 || loaded.borisWalk2],
        punch: [loaded.alexeyPunch0 || loaded.borisPunch0, loaded.alexeyPunch1 || loaded.borisPunch1, loaded.alexeyPunch2 || loaded.borisPunch2],
        knockdown: loaded.alexeyKnockdown || loaded.alexeyIdle || loaded.borisIdle
      },
      anna: {
        idle: loaded.annaIdle || loaded.borisIdle,
        walk: [loaded.annaWalk0 || loaded.borisWalk0, loaded.annaWalk1 || loaded.borisWalk1, loaded.annaWalk2 || loaded.borisWalk2],
        punch: [loaded.annaPunch0 || loaded.borisPunch0, loaded.annaPunch1 || loaded.borisPunch1, loaded.annaPunch2 || loaded.borisPunch2],
        knockdown: loaded.annaKnockdown || loaded.annaIdle || loaded.borisKnockdown || loaded.borisIdle
      }
    };

    loaded.borisWalk = loaded.heroes.boris.walk;
    loaded.borisPunch = loaded.heroes.boris.punch;

    loaded.dogWalk = [loaded.dogWalk0, loaded.dogWalk1];
    loaded.dogAttack = [loaded.dogAttack0, loaded.dogAttack1];

    loaded.enemies = {
      dogRegime: {
        idle: loaded.dogIdle,
        walk: [loaded.dogWalk0, loaded.dogWalk1],
        attack: [loaded.dogAttack0, loaded.dogAttack1],
        dead: loaded.dogDead
      },
      zetnik: {
        idle: loaded.zetnikIdle || loaded.zetnikWalk0 || loaded.dogIdle,
        walk: [
          loaded.zetnikWalk0 || loaded.zetnikIdle || loaded.dogWalk0,
          loaded.zetnikWalk1 || loaded.zetnikIdle || loaded.dogWalk1,
          loaded.zetnikWalk2 || loaded.zetnikIdle || loaded.dogWalk0
        ],
        attack: [loaded.zetnikAttack0 || loaded.zetnikIdle || loaded.dogAttack0, loaded.zetnikAttack1 || loaded.zetnikAttack0 || loaded.dogAttack1],
        dead: loaded.zetnikDead || loaded.zetnikAttack0 || loaded.zetnikIdle || loaded.dogDead
      },
      sucker: {
        idle: loaded.suckerIdle || loaded.dogIdle,
        walk: [loaded.suckerWalk0 || loaded.dogWalk0, loaded.suckerWalk1 || loaded.dogWalk1],
        attack: [loaded.suckerAttack0 || loaded.dogAttack0, loaded.suckerAttack1 || loaded.dogAttack1],
        slide: loaded.suckerSlide || loaded.suckerAttack0 || loaded.dogAttack0,
        bite: [loaded.suckerBite0 || loaded.suckerAttack0 || loaded.dogAttack0, loaded.suckerBite1 || loaded.suckerAttack1 || loaded.dogAttack1],
        dead: loaded.suckerDead || loaded.dogDead
      },
      bastard: {
        idle: loaded.bastardIdle || loaded.dogIdle,
        fall: loaded.bastardFall || loaded.dogDead || loaded.bastardIdle || loaded.dogIdle,
        walk: [
          loaded.bastardWalk0 || loaded.bastardIdle || loaded.dogWalk0,
          loaded.bastardWalk1 || loaded.bastardIdle || loaded.dogWalk1,
          loaded.bastardWalk2 || loaded.bastardIdle || loaded.dogWalk0
        ]
      }
    };

    loaded.pickups = {
      medkit: loaded.pickupMedkit,
      pirozhok: loaded.pickupPirozhok,
      tea: loaded.pickupTea
    };

    await this.loadLevelInteractiveImages(loaded);

    return loaded;
  }

  async loadLevelInteractiveImages(loaded) {
    loaded.levelInteractiveBackgrounds = loaded.levelInteractiveBackgrounds || {};
    loaded.levelInteractiveImages = loaded.levelInteractiveImages || {};

    const cache = {};
    const loadImage = (src, label) => new Promise((resolve) => {
      if (!src) {
        resolve(null);
        return;
      }
      if (cache[src]) {
        resolve(cache[src]);
        return;
      }
      const img = new Image();
      img.onload = () => {
        cache[src] = img;
        resolve(img);
      };
      img.onerror = () => {
        console.warn('Missing level interactive image:', label || src);
        resolve(null);
      };
      img.src = src;
    });

    const requests = [];
    for (const level of Object.values(GAME_CONFIG.levels || {})) {
      for (const item of level.interactives || []) {
        if (item.altBackground && !loaded.levelInteractiveBackgrounds[item.altBackground]) {
          requests.push(loadImage(item.altBackground, item.altBackground).then((image) => {
            loaded.levelInteractiveBackgrounds[item.altBackground] = image;
          }));
        }
        if (item.image && !loaded.levelInteractiveImages[item.image]) {
          requests.push(loadImage(item.image, item.image).then((image) => {
            loaded.levelInteractiveImages[item.image] = image;
          }));
        }
      }
    }

    await Promise.all(requests);
  }

  async loadLevelBackgrounds(fallbackStreets = []) {
    const order = GAME_CONFIG.levelOrder || [];
    const result = [];
    let previous = fallbackStreets[0] || null;
    const cache = {};

    const loadImage = (src) => new Promise((resolve) => {
      if (!src) {
        resolve(null);
        return;
      }
      if (cache[src]) {
        resolve(cache[src]);
        return;
      }
      const img = new Image();
      img.onload = () => {
        cache[src] = img;
        resolve(img);
      };
      img.onerror = () => {
        console.warn('Missing level background:', src);
        resolve(null);
      };
      img.src = src;
    });

    for (let i = 0; i < order.length; i++) {
      const key = order[i];
      const level = GAME_CONFIG.levels && GAME_CONFIG.levels[key];
      const src = level && level.background;
      const image = await loadImage(src);
      previous = image || previous || fallbackStreets[i] || fallbackStreets[0] || null;
      result.push(previous);
    }

    return result;
  }

  getMenuMusicKey() {
    return (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.menu) || 'menuTheme';
  }

  isMenuState(state) {
    return state === 'mainMenu' ||
      state === 'settings' ||
      state === 'characterSelect' ||
      state === 'campaignMap' ||
      state === 'playerNameEntry' ||
      state === 'regionStory';
  }

  isIntroState(state) {
    return state === 'intro';
  }

  pauseAndResetAudio(audio) {
    if (!audio) return;
    try {
      audio.pause();
      audio.currentTime = 0;
    } catch (error) {}
  }

  stopIntroAudioForStateChange() {
    const intro = this.intro;
    if (!intro) return;

    if (this.stopIntroVoiceOnly) this.stopIntroVoiceOnly();
    else if (this.stopIntroVoice) this.stopIntroVoice();
    this.pauseAndResetAudio(intro.music);
    intro.voiceStarted = false;
  }

  stopManagedMusicForStateChange() {
    if (!AudioManager.currentMusic) return;
    const managedKeys = [
      this.getMenuMusicKey(),
      'menuTheme',
      'levelTheme',
      'bossTheme'
    ];
    if (AudioManager.currentMusicKey && !managedKeys.includes(AudioManager.currentMusicKey)) return;
    AudioManager.stopMusic();
  }

  ensureMenuMusic() {
    if (this.isIntroState(this.state) || this.state === 'level' || this.state === 'splash') return;
    this.stopIntroAudioForStateChange();
    AudioManager.playMusic(this.getMenuMusicKey(), false, true);
  }

  setState(nextState) {
    const previousState = this.state;
    this.state = nextState;
    this.updateMusicForState(previousState, nextState);
    this.syncMusicPauseState();
  }

  syncMusicPauseState() {
    if (!AudioManager.setMusicPauseReason) return;
    const devOpen = typeof DevPanel !== 'undefined' && DevPanel.open;
    const gamePaused = this.state === 'level' && !!this.paused;
    AudioManager.setMusicPauseReason('game-pause', gamePaused || devOpen);
  }

  updateMusicForState(previousState, nextState) {
    if (this.isIntroState(nextState)) {
      this.stopManagedMusicForStateChange();
      return;
    }

    if (this.isIntroState(previousState) && !this.isIntroState(nextState)) {
      this.stopIntroAudioForStateChange();
    }

    if (nextState === 'level') {
      this.stopIntroAudioForStateChange();
      if (AudioManager.currentMusicKey === this.getMenuMusicKey()) AudioManager.stopMusic();
      return;
    }

    if (this.isMenuState(nextState)) {
      this.stopIntroAudioForStateChange();
      if (!this.isMenuState(previousState) || AudioManager.currentMusicKey !== this.getMenuMusicKey()) {
        this.ensureMenuMusic();
      }
      return;
    }
  }

  startLevel() {
    this.scene = new LevelScene(this, this.images);
    if (window.CampaignRuntime) window.CampaignRuntime.startActiveRegionScene(this);
    else if (this.scene.spawnInitialWave) this.scene.spawnInitialWave();
    this.setState('level');
    const levelKey = this.scene && this.scene.getLevelKey ? this.scene.getLevelKey() : null;
    const level = levelKey && GAME_CONFIG.levels ? GAME_CONFIG.levels[levelKey] : null;
    AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme', true);
  }

  update(dt) {
    this.syncMusicPauseState();
    DevPanel.update(this);
    this.syncMusicPauseState();

    const click = Input.consumePointer();
    if (click && this.handleSpeakerClick(click)) return;

    if (DevPanel.open) return;

    if (this.state === 'splash') {
      if (Input.consumeAnyKey() || click) {
        AudioManager.unlock();
        this.ensureMenuMusic();
        AudioManager.playSfx('menuSelect');
        this.setState('mainMenu');
      }
    } else if (this.state === 'mainMenu') {
      if (click) Input.restorePointer(click);
      Menu.update(this);
    } else if (this.state === 'settings') {
      if (click) Input.restorePointer(click);
      Menu.updateSettings(this);
    } else if (this.state === 'characterSelect') {
      if (click) Input.restorePointer(click);
      CharacterSelect.update(this);
    } else if (this.state === 'level' && this.scene) {
      if (click) Input.restorePointer(click);
      if (typeof MobileControls !== 'undefined') MobileControls.update(this);
      this.scene.update(dt);
    } else if (typeof MobileControls !== 'undefined') {
      MobileControls.update(this);
    }

    this.syncMusicPauseState();
  }

  getSpeakerRect() {
    return { x: GAME_CONFIG.width - 72, y: 16, w: 48, h: 48 };
  }

  handleSpeakerClick(point) {
    const r = this.getSpeakerRect();
    if (point.x < r.x || point.x > r.x + r.w || point.y < r.y || point.y > r.y + r.h) return false;
    AudioManager.unlock();
    AudioManager.toggleMusic();
    AudioManager.playSfx('menuSelect', 0.7);
    return true;
  }

  drawSpeaker(ctx) {
    const r = this.getSpeakerRect();
    const on = GAME_CONFIG.settings.musicEnabled !== false;
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.48)';
    ctx.fillRect(r.x, r.y, r.w, r.h);
    ctx.strokeStyle = on ? 'rgba(255,255,255,0.85)' : 'rgba(255,80,80,0.95)';
    ctx.lineWidth = 2;
    ctx.strokeRect(r.x, r.y, r.w, r.h);

    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(r.x + 12, r.y + 22);
    ctx.lineTo(r.x + 20, r.y + 22);
    ctx.lineTo(r.x + 31, r.y + 12);
    ctx.lineTo(r.x + 31, r.y + 36);
    ctx.lineTo(r.x + 20, r.y + 26);
    ctx.lineTo(r.x + 12, r.y + 26);
    ctx.closePath();
    ctx.fill();

    if (on) {
      ctx.strokeStyle = '#fff';
      ctx.beginPath();
      ctx.arc(r.x + 31, r.y + 24, 7, -0.75, 0.75);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(r.x + 31, r.y + 24, 13, -0.65, 0.65);
      ctx.stroke();
    } else {
      ctx.strokeStyle = '#ff5555';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(r.x + 12, r.y + 12);
      ctx.lineTo(r.x + 36, r.y + 36);
      ctx.moveTo(r.x + 36, r.y + 12);
      ctx.lineTo(r.x + 12, r.y + 36);
      ctx.stroke();
    }
    ctx.restore();
  }

  draw() {
    const ctx = this.ctx;
    ctx.clearRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    if (this.state === 'loading') {
      this.drawLoading(ctx);
    } else if (this.state === 'splash') {
      Menu.drawSplash(ctx, this.images);
    } else if (this.state === 'mainMenu') {
      Menu.draw(ctx, this.images);
    } else if (this.state === 'settings') {
      Menu.drawSettings(ctx, this.images);
    } else if (this.state === 'characterSelect') {
      CharacterSelect.draw(ctx, this.images);
    } else if (this.state === 'level' && this.scene) {
      this.scene.draw(ctx);
    }

    if (typeof MobileControls !== 'undefined') MobileControls.draw(ctx, this);
    this.drawSpeaker(ctx);
    DevPanel.draw(ctx);
    this.drawRuntimeError(ctx);
  }

  reportRuntimeError(error, phase) {
    const message = error && (error.stack || error.message) ? (error.stack || error.message) : String(error);
    this.runtimeError = `${phase}: ${message}`;
    this.runtimeErrorTimer = 6000;
    console.error('[Streets runtime]', phase, error);
  }

  drawRuntimeError(ctx) {
    if (!this.runtimeError || this.runtimeErrorTimer <= 0) return;
    const text = this.runtimeError.split('\n')[0].slice(0, 140);
    ctx.save();
    ctx.fillStyle = 'rgba(20, 0, 0, 0.88)';
    ctx.fillRect(18, GAME_CONFIG.height - 86, GAME_CONFIG.width - 36, 68);
    ctx.strokeStyle = '#ff5c5c';
    ctx.lineWidth = 2;
    ctx.strokeRect(18, GAME_CONFIG.height - 86, GAME_CONFIG.width - 36, 68);
    ctx.fillStyle = '#ffd2d2';
    ctx.font = 'bold 18px Arial';
    ctx.fillText('Runtime error - игра продолжает кадры, смотри консоль', 34, GAME_CONFIG.height - 58);
    ctx.font = '14px Arial';
    ctx.fillText(text, 34, GAME_CONFIG.height - 34);
    ctx.restore();
  }

  drawLoading(ctx) {
    ctx.fillStyle = '#050505';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 34px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('ЗАГРУЗКА...', GAME_CONFIG.width / 2, GAME_CONFIG.height / 2);
    ctx.textAlign = 'left';
  }

  drawRotateWarning(ctx) {
    ctx.fillStyle = '#050505';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 42px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('ПОВЕРНИТЕ ТЕЛЕФОН', GAME_CONFIG.width / 2, 320);
    ctx.font = '24px Arial';
    ctx.fillText('Игра работает в горизонтальном режиме', GAME_CONFIG.width / 2, 370);
    ctx.textAlign = 'left';
  }

  loop(time) {
    const dt = Math.min(45, time - this.lastTime);
    this.lastTime = time;
    try {
      if (this.runtimeErrorTimer > 0) this.runtimeErrorTimer -= dt;
      this.update(dt);
      this.draw();
      Input.endFrame();
    } catch (error) {
      this.reportRuntimeError(error, 'loop');
      try {
        this.draw();
        Input.endFrame();
      } catch (drawError) {
        console.error('[Streets runtime] error overlay failed', drawError);
      }
    }
    requestAnimationFrame((nextTime) => this.loop(nextTime));
  }
}

window.addEventListener('load', () => {
  const game = new GameApp();
  game.init();
});



/* ===== src/levelInteractives.js ===== */
(function () {
  if (typeof GameApp === 'undefined' || typeof LevelScene === 'undefined') return;

  function getInteractivesForLevel(level) {
    return Array.isArray(level && level.interactives) ? level.interactives : [];
  }

  function isVehicleObstacle(item) {
    return item && item.type === 'vehicleObstacle';
  }

  function getVehicleObstacles(level) {
    return getInteractivesForLevel(level).filter(isVehicleObstacle);
  }

  function getPosterState(scene, item) {
    if (!scene.levelInteractiveState) scene.levelInteractiveState = {};
    const key = scene.getLevelKey() + ':' + item.id;
    if (!scene.levelInteractiveState[key]) {
      scene.levelInteractiveState[key] = {
        hits: 0,
        replaced: false,
        flashMs: 0
      };
    }
    return scene.levelInteractiveState[key];
  }

  function isAttackActive(player) {
    if (!player || player.state !== 'attack' || !player.getAttackData) return false;
    const data = player.getAttackData();
    return player.attackTimer >= data.activeStart && player.attackTimer <= data.activeEnd;
  }

  function canHitPoster(scene, item, state) {
    const player = scene && scene.player;
    if (!player || state.replaced || player.attackHasHit || !isAttackActive(player)) return false;
    const attackBox = player.getHitbox && player.getHitbox();
    const posterBox = item.hitbox;
    if (!attackBox || !posterBox) return false;

    // Background objects are reached from their foot line, not by overlapping
    // the artwork high above the pavement.
    const reachesPoster = attackBox.x < posterBox.x + posterBox.w &&
      attackBox.x + attackBox.w > posterBox.x;
    return reachesPoster && Combat.actorOnLane(
      player,
      item.laneY,
      item.laneTolerance || GAME_CONFIG.yHitTolerance
    );
  }

  function hitPoster(scene, item, state) {
    state.hits += 1;
    state.flashMs = 150;
    scene.player.attackHasHit = true;
    scene.hitStop = Math.max(scene.hitStop || 0, GAME_CONFIG.playerHitStopMs || 55);

    if (state.hits >= (item.hitsToReplace || 3)) {
      state.replaced = true;
      state.flashMs = 0;
      if (!state.pickupDropped && item.dropPickup && scene.dropPickup) {
        const rect = item.hitbox || item.effectRect || {};
        const x = Number.isFinite(item.dropX) ? item.dropX : (rect.x || 0) + (rect.w || 0) / 2;
        const y = Number.isFinite(item.dropY) ? item.dropY : (item.laneY || GAME_CONFIG.laneBottom);
        scene.dropPickup(item.dropPickup, x, y);
        state.pickupDropped = true;
      }
      AudioManager.playSfx('enemyDown', 0.82, { playbackRate: 0.92, startAt: 0.02 });
      return;
    }

    AudioManager.playSfx('hit', 0.76, {
      playbackRate: 0.82 + state.hits * 0.08,
      startAt: 0.015
    });
  }

  function drawCrackLine(ctx, rect, points, alpha, width) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = '#ecf7ff';
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.shadowColor = 'rgba(255,255,255,0.65)';
    ctx.shadowBlur = 4;
    ctx.beginPath();
    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      const x = rect.x + p[0] * rect.w;
      const y = rect.y + p[1] * rect.h;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawPosterDamage(ctx, item, state) {
    const rect = item.effectRect || item.hitbox;
    const damageLevel = Math.min(2, state.hits);
    if (damageLevel <= 0) return;

    ctx.save();
    ctx.beginPath();
    ctx.rect(rect.x, rect.y, rect.w, rect.h);
    ctx.clip();

    const flash = Math.max(0, Math.min(1, (state.flashMs || 0) / 150));
    ctx.globalAlpha = 0.16 + flash * 0.18;
    ctx.fillStyle = '#f4f0e7';
    ctx.fillRect(rect.x, rect.y, rect.w, rect.h);

    ctx.globalAlpha = 0.22 + damageLevel * 0.08;
    ctx.fillStyle = '#151515';
    ctx.beginPath();
    ctx.ellipse(rect.x + rect.w * 0.52, rect.y + rect.h * 0.55, rect.w * 0.35, rect.h * 0.24, -0.18, 0, Math.PI * 2);
    ctx.fill();

    drawCrackLine(ctx, rect, [[0.46, 0.18], [0.55, 0.34], [0.49, 0.48], [0.58, 0.66], [0.51, 0.86]], 0.86, 2.1);
    drawCrackLine(ctx, rect, [[0.52, 0.36], [0.32, 0.42], [0.18, 0.55]], 0.72, 1.6);
    drawCrackLine(ctx, rect, [[0.52, 0.38], [0.72, 0.30], [0.88, 0.22]], 0.64, 1.35);

    if (damageLevel >= 2) {
      drawCrackLine(ctx, rect, [[0.28, 0.18], [0.39, 0.34], [0.31, 0.52], [0.44, 0.73], [0.38, 0.92]], 0.82, 1.7);
      drawCrackLine(ctx, rect, [[0.62, 0.18], [0.66, 0.36], [0.58, 0.52], [0.71, 0.68], [0.67, 0.90]], 0.76, 1.55);
      ctx.globalAlpha = 0.28;
      ctx.strokeStyle = '#070707';
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.ellipse(rect.x + rect.w * 0.50, rect.y + rect.h * 0.56, rect.w * 0.28, rect.h * 0.20, -0.24, 0, Math.PI * 2);
      ctx.stroke();
    }

    ctx.restore();
  }

  function getActorObstacleBox(actor) {
    if (!actor) return null;
    if (typeof actor.getPushbox === 'function') {
      const box = actor.getPushbox();
      if (box && Number.isFinite(box.x) && Number.isFinite(box.y) && Number.isFinite(box.w) && Number.isFinite(box.h)) return box;
    }

    const radiusX = actor.bodyRadiusX || GAME_CONFIG.enemyBodyRadiusX || 42;
    const radiusY = actor.bodyRadiusY || GAME_CONFIG.enemyBodyRadiusY || 20;
    return {
      x: actor.x - radiusX,
      y: actor.y - radiusY,
      w: radiusX * 2,
      h: radiusY * 2
    };
  }

  function resolveActorFromObstacle(scene, actor, obstacle) {
    if (!scene || !actor || !obstacle || !obstacle.blockBox) return;
    const actorBox = getActorObstacleBox(actor);
    const block = obstacle.blockBox;
    if (!actorBox || !Combat.overlap(actorBox, block)) return;

    const leftPush = block.x - (actorBox.x + actorBox.w);
    const rightPush = block.x + block.w - actorBox.x;
    const upPush = block.y - (actorBox.y + actorBox.h);
    const downPush = block.y + block.h - actorBox.y;
    const options = [
      { dx: leftPush, dy: 0, amount: Math.abs(leftPush), axis: 'x' },
      { dx: rightPush, dy: 0, amount: Math.abs(rightPush), axis: 'x' },
      { dx: 0, dy: upPush, amount: Math.abs(upPush), axis: 'y' },
      { dx: 0, dy: downPush, amount: Math.abs(downPush), axis: 'y' }
    ];

    let chosen = options.sort((a, b) => a.amount - b.amount)[0];
    if (actor !== scene.player && scene.player && actor.alive !== false) {
      const obstacleCenterY = block.y + block.h / 2;
      const preferUp = scene.player.y < obstacleCenterY;
      const vertical = preferUp ? options[2] : options[3];
      const zone = scene.getWalkZone ? scene.getWalkZone() : { top: GAME_CONFIG.laneTop, bottom: GAME_CONFIG.laneBottom };
      const nextY = actor.y + vertical.dy;
      if (nextY >= zone.top && nextY <= zone.bottom) chosen = vertical;
    }

    actor.x += chosen.dx;
    actor.y += chosen.dy;
  }

  function drawVehicleObstacle(scene, ctx, item) {
    const rect = item && item.drawRect;
    if (!rect) return;
    const image = item.image && scene.images.levelInteractiveImages && scene.images.levelInteractiveImages[item.image];
    if (image) {
      ctx.drawImage(image, rect.x, rect.y, rect.w, rect.h);
    } else {
      ctx.save();
      ctx.fillStyle = 'rgba(20,45,75,0.82)';
      ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.lineWidth = 2;
      ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
      ctx.restore();
    }
  }

  LevelScene.prototype.resolveObstacleCollisions = function (actor) {
    const level = this.getLevelConfig();
    for (const obstacle of getVehicleObstacles(level)) {
      resolveActorFromObstacle(this, actor, obstacle);
    }
  };

  LevelScene.prototype.drawLevelForegroundObjects = function (ctx) {
    const level = this.getLevelConfig();
    for (const item of getVehicleObstacles(level)) {
      drawVehicleObstacle(this, ctx, item);
    }
  };

  const previousUpdate = LevelScene.prototype.update;
  LevelScene.prototype.update = function (dt) {
    previousUpdate.call(this, dt);
    if (this.player) this.resolveObstacleCollisions(this.player);
    for (const enemy of this.enemies || []) {
      if (enemy && !enemy.remove) this.resolveObstacleCollisions(enemy);
    }
  };

  LevelScene.prototype.getLevelBackgroundImage = function () {
    const level = this.getLevelConfig();
    for (const item of getInteractivesForLevel(level)) {
      if (item.type !== 'breakablePoster') continue;
      const state = getPosterState(this, item);
      if (state.replaced && item.altBackground) {
        const replacement = this.images.levelInteractiveBackgrounds && this.images.levelInteractiveBackgrounds[item.altBackground];
        if (replacement) return replacement;
      }
    }

    return this.images.streets[this.screenIndex] || this.images.streets[0];
  };

  LevelScene.prototype.updateLevelInteractives = function (dt) {
    const level = this.getLevelConfig();
    for (const item of getInteractivesForLevel(level)) {
      if (item.type !== 'breakablePoster') continue;
      const state = getPosterState(this, item);
      if (state.flashMs > 0) state.flashMs = Math.max(0, state.flashMs - dt);
      if (canHitPoster(this, item, state)) hitPoster(this, item, state);
    }
  };

  LevelScene.prototype.drawLevelBackgroundEffects = function (ctx) {
    const level = this.getLevelConfig();
    const showObjectEditor = typeof DevPanel !== 'undefined' && DevPanel.open && DevPanel.tab === 'OBJECTS';
    if (level && level.bossFireWall && (this.debug || showObjectEditor)) {
      const wall = level.bossFireWall;
      ctx.save();
      ctx.strokeStyle = 'rgba(255, 115, 32, 0.95)';
      ctx.lineWidth = 3;
      ctx.setLineDash([10, 6]);
      ctx.strokeRect(wall.x, wall.y, wall.w, wall.h);
      ctx.setLineDash([]);
      ctx.fillStyle = 'rgba(255, 115, 32, 0.9)';
      ctx.font = 'bold 13px Arial';
      ctx.fillText('GUNDOS FIRE WALL', wall.x + 8, wall.y - 8);
      ctx.restore();
    }
    for (const item of getInteractivesForLevel(level)) {
      if (isVehicleObstacle(item)) {
        if (this.debug || showObjectEditor) {
          ctx.save();
          if (item.drawRect) {
            ctx.strokeStyle = 'rgba(80, 190, 255, 0.9)';
            ctx.lineWidth = 2;
            ctx.strokeRect(item.drawRect.x, item.drawRect.y, item.drawRect.w, item.drawRect.h);
          }
          if (item.blockBox) {
            ctx.strokeStyle = 'rgba(255, 230, 90, 0.95)';
            ctx.lineWidth = 3;
            ctx.strokeRect(item.blockBox.x, item.blockBox.y, item.blockBox.w, item.blockBox.h);
          }
          ctx.restore();
        }
        continue;
      }

      if (item.type !== 'breakablePoster') continue;
      const state = getPosterState(this, item);
      if (!state.replaced) drawPosterDamage(ctx, item, state);

      if (this.debug || showObjectEditor) {
        ctx.save();
        ctx.strokeStyle = showObjectEditor ? 'rgba(255, 230, 90, 0.95)' : 'rgba(255, 230, 90, 0.75)';
        ctx.lineWidth = showObjectEditor ? 3 : 2;
        ctx.strokeRect(item.hitbox.x, item.hitbox.y, item.hitbox.w, item.hitbox.h);
        if (item.effectRect) {
          ctx.strokeStyle = 'rgba(80, 190, 255, 0.9)';
          ctx.strokeRect(item.effectRect.x, item.effectRect.y, item.effectRect.w, item.effectRect.h);
        }
        if (Number.isFinite(item.laneY)) {
          ctx.strokeStyle = 'rgba(80,255,120,0.85)';
          ctx.beginPath();
          ctx.moveTo(item.hitbox.x - 24, item.laneY);
          ctx.lineTo(item.hitbox.x + item.hitbox.w + 24, item.laneY);
          ctx.stroke();
        }
        ctx.restore();
      }
    }
  };

  if (typeof DevPanel !== 'undefined' && !DevPanel.objectEditorPatchApplied) {
    if (!DevPanel.tabs.includes('OBJECTS')) DevPanel.tabs.push('OBJECTS');
    DevPanel.selectedObjectLevelIndex = DevPanel.selectedObjectLevelIndex || 0;
    DevPanel.selectedObjectIndex = DevPanel.selectedObjectIndex || 0;
    DevPanel.selectedObjectBoxKey = DevPanel.selectedObjectBoxKey || 'hitbox';

    DevPanel.getObjectLevelKeys = function () {
      return GAME_CONFIG.levelOrder || Object.keys(GAME_CONFIG.levels || {});
    };

    DevPanel.getSelectedObjectLevelKey = function () {
      const keys = this.getObjectLevelKeys();
      if (!keys.length) return null;
      this.selectedObjectLevelIndex = this.wrap ? this.wrap(this.selectedObjectLevelIndex, keys.length) :
        ((this.selectedObjectLevelIndex % keys.length) + keys.length) % keys.length;
      return keys[this.selectedObjectLevelIndex];
    };

    DevPanel.getSelectedObjectLevel = function () {
      const key = this.getSelectedObjectLevelKey();
      return key && GAME_CONFIG.levels ? GAME_CONFIG.levels[key] : null;
    };

    DevPanel.getSelectedObjectList = function () {
      const level = this.getSelectedObjectLevel();
      const objects = getInteractivesForLevel(level).slice();
      if (level && level.bossFireWall) {
        objects.push({
          id: 'gundosFireWall',
          type: 'fireWall',
          hitbox: level.bossFireWall
        });
      }
      return objects;
    };

    DevPanel.getSelectedObject = function () {
      const list = this.getSelectedObjectList();
      if (!list.length) return null;
      this.selectedObjectIndex = this.wrap ? this.wrap(this.selectedObjectIndex, list.length) :
        ((this.selectedObjectIndex % list.length) + list.length) % list.length;
      return list[this.selectedObjectIndex];
    };

    DevPanel.getSelectedObjectBox = function () {
      const item = this.getSelectedObject();
      if (!item) return null;
      const keys = this.objectBoxKeys(item);
      if (!keys.includes(this.selectedObjectBoxKey)) this.selectedObjectBoxKey = keys[0];
      if (this.selectedObjectBoxKey === 'lane') return item;
      if (!item[this.selectedObjectBoxKey]) item[this.selectedObjectBoxKey] = { x: 0, y: 0, w: 40, h: 40 };
      return item[this.selectedObjectBoxKey];
    };

    DevPanel.objectEditorRects = function () {
      const panel = this.panelRect();
      const x = panel.x + 36;
      const y = panel.y + 118;
      return {
        box: { x, y, w: 980, h: 496 },
        levelPrev: { x: x + 112, y: y + 24, w: 36, h: 28 },
        levelNext: { x: x + 620, y: y + 24, w: 36, h: 28 },
        objectPrev: { x: x + 112, y: y + 64, w: 36, h: 28 },
        objectNext: { x: x + 620, y: y + 64, w: 36, h: 28 },
        boxPrev: { x: x + 112, y: y + 104, w: 36, h: 28 },
        boxNext: { x: x + 620, y: y + 104, w: 36, h: 28 }
      };
    };

    DevPanel.objectBoxKeys = function (item) {
      const keys = [];
      if (item && item.hitbox) keys.push('hitbox');
      if (item && item.drawRect) keys.push('drawRect');
      if (item && item.blockBox) keys.push('blockBox');
      if (item && item.effectRect) keys.push('effectRect');
      if (item && Number.isFinite(item.laneY)) keys.push('lane');
      if (!keys.length) keys.push('hitbox');
      return keys;
    };

    DevPanel.selectNextObjectBox = function (delta) {
      const item = this.getSelectedObject();
      const keys = this.objectBoxKeys(item);
      const index = Math.max(0, keys.indexOf(this.selectedObjectBoxKey));
      this.selectedObjectBoxKey = keys[((index + delta) % keys.length + keys.length) % keys.length];
    };

    const originalHandleClick = DevPanel.objectOriginalHandleClick || DevPanel.handleClick;
    DevPanel.objectOriginalHandleClick = originalHandleClick;
    DevPanel.handleClick = function (point, game) {
      const panel = this.panelRect();
      if (!this.inRect(point, panel)) return;
      const close = { x: panel.x + panel.w - 78, y: panel.y + 14, w: 56, h: 32 };
      if (this.inRect(point, close)) { this.open = false; return; }
      const tab = this.getClickedTab(point);
      if (tab) { this.tab = tab; this.setStatus('Tab: ' + tab); return; }
      if (this.handleFooterClick(point, game)) return;
      if (this.tab === 'OBJECTS') { this.handleObjectEditorClick(point, game); return; }
      originalHandleClick.call(this, point, game);
    };

    DevPanel.handleObjectEditorClick = function (point, game) {
      const r = this.objectEditorRects();
      const list = this.getSelectedObjectList();
      if (this.inRect(point, r.levelPrev)) { this.selectedObjectLevelIndex--; this.selectedObjectIndex = 0; this.setStatus('Object level: ' + this.getSelectedObjectLevelKey()); return true; }
      if (this.inRect(point, r.levelNext)) { this.selectedObjectLevelIndex++; this.selectedObjectIndex = 0; this.setStatus('Object level: ' + this.getSelectedObjectLevelKey()); return true; }
      if (this.inRect(point, r.objectPrev) && list.length) { this.selectedObjectIndex--; this.setStatus('Object changed'); return true; }
      if (this.inRect(point, r.objectNext) && list.length) { this.selectedObjectIndex++; this.setStatus('Object changed'); return true; }
      if (this.inRect(point, r.boxPrev)) { this.selectNextObjectBox(-1); this.setStatus('Object box: ' + this.selectedObjectBoxKey); return true; }
      if (this.inRect(point, r.boxNext)) { this.selectNextObjectBox(1); this.setStatus('Object box: ' + this.selectedObjectBoxKey); return true; }

      const box = this.getSelectedObjectBox();
      if (!box) return false;
      const props = this.selectedObjectBoxKey === 'lane' ? ['laneY', 'laneTolerance'] : ['x', 'y', 'w', 'h'];
      for (let i = 0; i < props.length; i++) {
        const y = r.box.y + 178 + i * 46;
        const minus = { x: r.box.x + 118, y: y - 22, w: 34, h: 28 };
        const plus = { x: r.box.x + 452, y: y - 22, w: 34, h: 28 };
        const bar = { x: r.box.x + 166, y: y - 13, w: 270, h: 12 };
        const prop = props[i];
        const min = prop === 'w' || prop === 'h' ? 4 : 0;
        const max = prop === 'w' ? GAME_CONFIG.width : prop === 'h' ? GAME_CONFIG.height : GAME_CONFIG.height;
        const step = prop === 'laneTolerance' ? 2 : 4;
        if (this.inRect(point, minus)) { box[prop] = Math.max(min, Math.round((Number(box[prop]) || 0) - step)); this.applyToCurrentScene(game); this.setStatus(prop + ': ' + box[prop]); return true; }
        if (this.inRect(point, plus)) { box[prop] = Math.min(max, Math.round((Number(box[prop]) || 0) + step)); this.applyToCurrentScene(game); this.setStatus(prop + ': ' + box[prop]); return true; }
        if (this.inRect(point, bar)) {
          const ratio = Math.max(0, Math.min(1, (point.x - bar.x) / bar.w));
          box[prop] = Math.round(min + ratio * (max - min));
          this.applyToCurrentScene(game);
          this.setStatus(prop + ': ' + box[prop]);
          return true;
        }
      }
      return false;
    };

    const originalDraw = DevPanel.objectOriginalDraw || DevPanel.draw;
    DevPanel.objectOriginalDraw = originalDraw;
    DevPanel.draw = function (ctx) {
      if (!GAME_CONFIG.adminTuningEnabled) return;
      if (!this.open || this.tab !== 'OBJECTS') { originalDraw.call(this, ctx); return; }
      const panel = this.panelRect();
      ctx.fillStyle = 'rgba(0,0,0,0.92)';
      ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 24px Arial';
      ctx.fillText('DEVELOPER PANEL', panel.x + 22, panel.y + 38);
      ctx.font = '13px Arial';
      ctx.fillStyle = '#aaa';
      ctx.fillText('Object editor: yellow = hitbox, blue = visual effect, green line = lane.', panel.x + 22, panel.y + 58);
      this.drawButton(ctx, panel.x + panel.w - 78, panel.y + 14, 56, 32, 'X');
      this.drawTabs(ctx);
      this.drawObjectEditor(ctx);
      this.drawFooter(ctx);
      this.drawStatus(ctx, panel);
    };

    DevPanel.drawObjectEditor = function (ctx) {
      const r = this.objectEditorRects();
      const item = this.getSelectedObject();
      const box = this.getSelectedObjectBox();
      ctx.fillStyle = 'rgba(255,255,255,0.06)';
      ctx.fillRect(r.box.x, r.box.y, r.box.w, r.box.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.strokeRect(r.box.x, r.box.y, r.box.w, r.box.h);

      const levelKey = this.getSelectedObjectLevelKey() || 'none';
      ctx.fillStyle = '#ccc';
      ctx.font = '14px Arial';
      ctx.fillText('Level:', r.box.x + 24, r.box.y + 43);
      this.drawButton(ctx, r.levelPrev.x, r.levelPrev.y, r.levelPrev.w, r.levelPrev.h, '<');
      this.drawButton(ctx, r.levelNext.x, r.levelNext.y, r.levelNext.w, r.levelNext.h, '>');
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 15px Arial';
      ctx.fillText(levelKey, r.box.x + 160, r.box.y + 43);

      ctx.fillStyle = '#ccc';
      ctx.font = '14px Arial';
      ctx.fillText('Object:', r.box.x + 24, r.box.y + 83);
      this.drawButton(ctx, r.objectPrev.x, r.objectPrev.y, r.objectPrev.w, r.objectPrev.h, '<');
      this.drawButton(ctx, r.objectNext.x, r.objectNext.y, r.objectNext.w, r.objectNext.h, '>');
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 15px Arial';
      ctx.fillText(item ? (item.id || item.type || 'object') : 'no objects', r.box.x + 160, r.box.y + 83);

      ctx.fillStyle = '#ccc';
      ctx.font = '14px Arial';
      ctx.fillText('Box:', r.box.x + 24, r.box.y + 123);
      this.drawButton(ctx, r.boxPrev.x, r.boxPrev.y, r.boxPrev.w, r.boxPrev.h, '<');
      this.drawButton(ctx, r.boxNext.x, r.boxNext.y, r.boxNext.w, r.boxNext.h, '>');
      ctx.fillStyle = this.selectedObjectBoxKey === 'hitbox' ? '#ffe65a' : this.selectedObjectBoxKey === 'effectRect' ? '#50beff' : '#50ff78';
      ctx.font = 'bold 15px Arial';
      ctx.fillText(String(this.selectedObjectBoxKey).toUpperCase(), r.box.x + 160, r.box.y + 123);

      if (!box) return;
      const props = this.selectedObjectBoxKey === 'lane' ? ['laneY', 'laneTolerance'] : ['x', 'y', 'w', 'h'];
      for (let i = 0; i < props.length; i++) {
        const prop = props[i];
        const value = Number(box[prop]) || 0;
        const min = prop === 'w' || prop === 'h' ? 4 : 0;
        const max = prop === 'w' ? GAME_CONFIG.width : prop === 'h' ? GAME_CONFIG.height : GAME_CONFIG.height;
        const ratio = (value - min) / Math.max(1, max - min);
        const y = r.box.y + 178 + i * 46;
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 14px Arial';
        ctx.fillText(prop, r.box.x + 24, y);
        ctx.fillStyle = '#ccc';
        ctx.fillText(String(value), r.box.x + 104, y);
        this.drawButton(ctx, r.box.x + 118, y - 22, 34, 28, '-');
        ctx.fillStyle = '#222';
        ctx.fillRect(r.box.x + 166, y - 13, 270, 12);
        ctx.fillStyle = '#55ccff';
        ctx.fillRect(r.box.x + 166, y - 13, 270 * Math.max(0, Math.min(1, ratio)), 12);
        ctx.strokeStyle = '#777';
        ctx.strokeRect(r.box.x + 166, y - 13, 270, 12);
        this.drawButton(ctx, r.box.x + 452, y - 22, 34, 28, '+');
      }

      ctx.fillStyle = '#aaa';
      ctx.font = '12px Arial';
      ctx.fillText('Use EXPORT to print the current level object JSON, then I can lock it into config.', r.box.x + 24, r.box.y + 392);
    };

    const originalExportConfig = DevPanel.objectOriginalExportConfig || DevPanel.exportConfig;
    DevPanel.objectOriginalExportConfig = originalExportConfig;
    DevPanel.exportConfig = function () {
      originalExportConfig.call(this);
      console.log('STREETS_OF_RUSSIA_OBJECTS_ONLY');
      console.log(JSON.stringify(GAME_CONFIG.levels, null, 2));
    };

    DevPanel.objectEditorPatchApplied = true;
  }
}());



/* ===== src/horseEnemyPatch.js ===== */
(function () {
  if (typeof GAME_CONFIG === 'undefined' || typeof Assets === 'undefined') return;

  const HORSE_FOLDER = 'assets/enemies/horse';
  const HORSE_ASSET_VERSION = 'horse-rebuilt-6';
  const horseFrame = name => HORSE_FOLDER + '/' + name + '.png?v=' + HORSE_ASSET_VERSION;

  Assets.horse = Object.assign({
    idle: horseFrame('idle'),
    walk: [
      horseFrame('walk01'),
      horseFrame('walk02'),
      horseFrame('walk03')
    ],
    attack: [
      horseFrame('idle'),
      horseFrame('Whiplash'),
      horseFrame('WhiplashFinal')
    ],
    dead: horseFrame('knockdown')
  }, Assets.horse || {});

  GAME_CONFIG.enemies.horse = Object.assign({
    name: 'Horse',
    hp: 125,
    speed: 2.025,
    damage: 14,
    scale: 0.13,
    walkScale: 0.95,
    visibleHeight: 0,
    attackScale: 1,
    finalAttackScale: 1.31,
    finalAttackFootAlign: 0.5,
    attackWindupMs: 680,
    attackActiveMs: 430,
    attackRecoveryMs: 320,
    whiplashFinalSfxLeadMs: 80,
    whiplashFinalSfxStartAt: 0.24,
    bossMusic: false,
    bossMusicKey: 'bossTheme',
    minDistanceX: 120,
    preferredDistanceX: 190,
    tooFarDistanceX: 310,
    attackMinDistanceX: 115,
    attackMaxDistanceX: 255,
    attackRangeX: 265,
    attackRangeY: 38,
    clubReachForward: 310,
    clubReachBack: 18,
    maxAttackers: 1,
    decisionMinMs: 340,
    decisionMaxMs: 920,
    strafeChance: 0.5,
    retreatChance: 0.26,
    attackChance: 0.46,
    closeRetreatChance: 0.78,
    postAttackRetreatMs: 760,
    slotSpacingX: 50,
    slotSpacingY: 44,
    flankDistanceX: 190,
    pressureDistanceX: 225
  }, GAME_CONFIG.enemies.horse || {});

  if (typeof DevPanel !== 'undefined') {
    if (DevPanel.tabs && !DevPanel.tabs.includes('HORSE')) DevPanel.tabs.push('HORSE');
    if (!DevPanel.fieldGroups) DevPanel.fieldGroups = {};
    if (!DevPanel.fieldGroups.HORSE) DevPanel.fieldGroups.HORSE = [];

    const fields = [
      { label: 'Horse speed', path: 'enemies.horse.speed', min: 0.3, max: 4, step: 0.05 },
      { label: 'Horse HP', path: 'enemies.horse.hp', min: 10, max: 500, step: 5 },
      { label: 'Horse damage', path: 'enemies.horse.damage', min: 1, max: 90, step: 1 },
      { label: 'Horse scale', path: 'enemies.horse.scale', min: 0.05, max: 0.35, step: 0.005 },
      { label: 'Min dist X', path: 'enemies.horse.minDistanceX', min: 20, max: 180, step: 2 },
      { label: 'Preferred dist X', path: 'enemies.horse.preferredDistanceX', min: 40, max: 260, step: 2 },
      { label: 'Attack range X', path: 'enemies.horse.attackRangeX', min: 30, max: 220, step: 2 },
      { label: 'Attack range Y', path: 'enemies.horse.attackRangeY', min: 14, max: 110, step: 2 },
      { label: 'Max attackers', path: 'enemies.horse.maxAttackers', min: 1, max: 5, step: 1 },
      { label: 'Decision min ms', path: 'enemies.horse.decisionMinMs', min: 100, max: 1400, step: 20 },
      { label: 'Decision max ms', path: 'enemies.horse.decisionMaxMs', min: 160, max: 2200, step: 20 },
      { label: 'Strafe chance', path: 'enemies.horse.strafeChance', min: 0, max: 1, step: 0.05 },
      { label: 'Retreat chance', path: 'enemies.horse.retreatChance', min: 0, max: 1, step: 0.05 },
      { label: 'Attack chance', path: 'enemies.horse.attackChance', min: 0, max: 1, step: 0.05 },
      { label: 'Final foot align', path: 'enemies.horse.finalAttackFootAlign', min: 0, max: 1, step: 0.05 },
      { label: 'Slot spacing X', path: 'enemies.horse.slotSpacingX', min: 0, max: 200, step: 4 },
      { label: 'Slot spacing Y', path: 'enemies.horse.slotSpacingY', min: 0, max: 140, step: 4 },
      { label: 'Flank distance X', path: 'enemies.horse.flankDistanceX', min: 60, max: 280, step: 4 },
      { label: 'Pressure distance X', path: 'enemies.horse.pressureDistanceX', min: 80, max: 360, step: 4 }
    ];

    for (const field of fields) {
      if (!DevPanel.fieldGroups.HORSE.some(item => item.path === field.path)) {
        DevPanel.fieldGroups.HORSE.push(field);
      }
    }
  }

  function loadOptionalImage(src) {
    return new Promise((resolve) => {
      if (!src) {
        resolve(null);
        return;
      }
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => {
        console.warn('Missing horse image:', src);
        resolve(null);
      };
      img.src = src;
    });
  }

  if (typeof GameApp !== 'undefined' && !GameApp.prototype.horseEnemyPatchApplied) {
    const originalLoadImages = GameApp.prototype.loadImages;
    GameApp.prototype.loadImages = async function () {
      const loaded = await originalLoadImages.call(this);
      const horse = Assets.horse || {};

      const idle = await loadOptionalImage(horse.idle);
      const walk0 = await loadOptionalImage(horse.walk && horse.walk[0]);
      const walk1 = await loadOptionalImage(horse.walk && horse.walk[1]);
      const walk2 = await loadOptionalImage(horse.walk && horse.walk[2]);
      const attack0 = await loadOptionalImage(horse.attack && horse.attack[0]);
      const attack1 = await loadOptionalImage(horse.attack && horse.attack[1]);
      const dead = await loadOptionalImage(horse.dead);
      const attack2 = await loadOptionalImage(horse.attack && horse.attack[2]);

      if (!loaded.enemies) loaded.enemies = {};
      const dog = loaded.enemies.dogRegime || {};
      loaded.enemies.horse = {
        idle: idle || walk0 || dog.idle,
        walk: [
          walk0 || idle || (dog.walk && dog.walk[0]) || dog.idle,
          walk1 || idle || (dog.walk && dog.walk[1]) || dog.idle,
          walk2 || walk0 || idle || (dog.walk && dog.walk[0]) || dog.idle
        ],
        attack: [
          attack0 || idle || (dog.attack && dog.attack[0]) || dog.idle,
          attack1 || attack0 || idle || (dog.attack && dog.attack[1]) || dog.idle,
          attack2 || attack1 || attack0 || idle || (dog.attack && dog.attack[1]) || dog.idle
        ],
        dead: dead || walk2 || idle || dog.dead || dog.idle
      };

      return loaded;
    };

    GameApp.prototype.horseEnemyPatchApplied = true;
  }

  function getAlphaBounds(img) {
    if (!img) return null;
    if (img.__alphaBounds) return img.__alphaBounds;
    try {
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth || img.width;
      canvas.height = img.naturalHeight || img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(img, 0, 0);
      const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
      let minX = canvas.width;
      let minY = canvas.height;
      let maxX = -1;
      let maxY = -1;
      for (let y = 0; y < canvas.height; y++) {
        for (let x = 0; x < canvas.width; x++) {
          if (data[(y * canvas.width + x) * 4 + 3] <= 8) continue;
          if (x < minX) minX = x;
          if (y < minY) minY = y;
          if (x > maxX) maxX = x;
          if (y > maxY) maxY = y;
        }
      }
      img.__alphaBounds = maxX >= 0
        ? { minX, minY, maxX, maxY, w: maxX - minX + 1, h: maxY - minY + 1, bottomGap: canvas.height - 1 - maxY }
        : { minX: 0, minY: 0, maxX: canvas.width - 1, maxY: canvas.height - 1, w: canvas.width, h: canvas.height, bottomGap: 0 };
    } catch (error) {
      img.__alphaBounds = { minX: 0, minY: 0, maxX: img.width - 1, maxY: img.height - 1, w: img.width, h: img.height, bottomGap: 0 };
    }
    return img.__alphaBounds;
  }

  function getFootCenterX(img) {
    if (!img) return 0;
    if (img.__footCenterX != null) return img.__footCenterX;
    const bounds = getAlphaBounds(img);
    if (!bounds) {
      img.__footCenterX = img.width / 2;
      return img.__footCenterX;
    }
    try {
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth || img.width;
      canvas.height = img.naturalHeight || img.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(img, 0, 0);
      const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
      const startY = Math.max(bounds.minY, bounds.maxY - Math.max(18, Math.round(bounds.h * 0.08)));
      let weightedX = 0;
      let weight = 0;
      for (let y = startY; y <= bounds.maxY; y++) {
        for (let x = bounds.minX; x <= bounds.maxX; x++) {
          const alpha = data[(y * canvas.width + x) * 4 + 3];
          if (alpha <= 20) continue;
          weightedX += x * alpha;
          weight += alpha;
        }
      }
      img.__footCenterX = weight > 0 ? weightedX / weight : (bounds.minX + bounds.maxX) / 2;
    } catch (error) {
      img.__footCenterX = (bounds.minX + bounds.maxX) / 2;
    }
    return img.__footCenterX;
  }

  if (typeof DogRegimeEnemy !== 'undefined' && !DogRegimeEnemy.prototype.horseWhiplashFramePatchApplied) {
    const previousGetImage = DogRegimeEnemy.prototype.getImage;
    DogRegimeEnemy.prototype.getImage = function () {
      if (this.enemyType === 'horse' && this.state === 'attack') {
        const enemyImages = this.getEnemyImages();
        const attack = enemyImages.attack || [];
        const windupMs = this.attackWindupMs || GAME_CONFIG.enemyWindupMs;
        const activeMs = this.attackActiveMs || GAME_CONFIG.enemyActiveMs;
        if (this.attackTimer < windupMs) return attack[0] || enemyImages.idle;
        if (attack[2] && this.attackTimer >= windupMs + activeMs * 0.45) return attack[2];
        return attack[1] || attack[0] || enemyImages.idle;
      }
      return previousGetImage.call(this);
    };

    const previousGetFrameScale = DogRegimeEnemy.prototype.getFrameScale;
    DogRegimeEnemy.prototype.getFrameScale = function (img, baseScale) {
      if (this.enemyType !== 'horse') {
        return previousGetFrameScale ? previousGetFrameScale.call(this, img, baseScale) : (
          this.state === 'attack' ? baseScale * (this.attackScale || 1) : baseScale
        );
      }

      const horseConfig = GAME_CONFIG.enemies.horse || {};
      if (this.state === 'walk') return baseScale * (horseConfig.walkScale || 0.95);
      if (this.state === 'attack') {
        const attack = (this.getEnemyImages().attack || []);
        if (attack[2] && img === attack[2]) return baseScale * (horseConfig.finalAttackScale || 1.31);
      }
      return baseScale;
    };

    DogRegimeEnemy.prototype.getDrawOffsetX = function (img, frameScale) {
      if (this.enemyType === 'horse' && this.state === 'attack') {
        const attack = this.getEnemyImages().attack || [];
        if (attack[2] && img === attack[2]) {
          const bounds = getAlphaBounds(img);
          const reference = attack[1] || attack[0] || img;
          const baseScale = this.scale || GAME_CONFIG.enemyScale;
          const referenceScale = reference === img ? frameScale : this.getFrameScale(reference, baseScale);
          const targetFootX = (getFootCenterX(reference) - reference.width / 2) * referenceScale;
          const currentFootX = (getFootCenterX(img) - img.width / 2) * frameScale;
          const align = Math.max(0, Math.min(1, (GAME_CONFIG.enemies.horse || {}).finalAttackFootAlign == null ? 0.5 : (GAME_CONFIG.enemies.horse || {}).finalAttackFootAlign));
          return (targetFootX - currentFootX) * align;
        }
      }
      return 0;
    };

    const previousGetDrawOffsetY = DogRegimeEnemy.prototype.getDrawOffsetY;
    DogRegimeEnemy.prototype.getDrawOffsetY = function (img, frameScale) {
      if (this.enemyType === 'horse') {
        if (this.state === 'attack') {
          const attack = this.getEnemyImages().attack || [];
          if (attack[2] && img === attack[2]) {
            const bounds = getAlphaBounds(img);
            return bounds ? bounds.bottomGap * frameScale : 0;
          }
        }
        return 0;
      }
      return previousGetDrawOffsetY ? previousGetDrawOffsetY.call(this, img, frameScale) : 0;
    };

    DogRegimeEnemy.prototype.horseWhiplashFramePatchApplied = true;
  }

  if (typeof DogRegimeEnemy !== 'undefined' && !DogRegimeEnemy.prototype.horseTacticsPatchApplied) {
    const previousChooseIntent = DogRegimeEnemy.prototype.chooseIntent;
    DogRegimeEnemy.prototype.chooseIntent = function (scene, canAttackNow, inAttackRange, frontThreat = false, absX = Infinity) {
      if (this.enemyType !== 'horse') {
        return previousChooseIntent.call(this, scene, canAttackNow, inAttackRange, frontThreat, absX);
      }

      const roll = Math.random();
      if (frontThreat || absX < this.minDistanceX) {
        this.intent = roll < 0.72 ? 'retreat' : 'strafe';
        this.retreatTimer = 260 + Math.random() * 260;
        this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
      } else if (canAttackNow && inAttackRange && this.cooldown <= 0 && roll < this.attackChance) {
        this.intent = 'attack';
      } else if (absX > this.attackMaxDistanceX) {
        this.intent = roll < 0.72 ? 'approach' : 'flank';
      } else if (roll < 0.5) {
        this.intent = 'strafe';
        this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
      } else if (roll < 0.75) {
        this.intent = 'hold';
      } else {
        this.intent = 'retreat';
        this.retreatTimer = 180 + Math.random() * 220;
      }

      this.decisionTimer = this.decisionMinMs + Math.random() * Math.max(1, this.decisionMaxMs - this.decisionMinMs);
    };

    DogRegimeEnemy.prototype.horseTacticsPatchApplied = true;
  }
})();



/* ===== src/horseAssetsFixPatch.js ===== */
(function () {
  if (typeof GAME_CONFIG === 'undefined' || typeof Assets === 'undefined') return;

  const FOLDER = 'assets/enemies/horse';
  const HORSE_ASSET_VERSION = 'horse-rebuilt-6';
  const KO_KEY = 'horseKo';
  const KO_FILE = FOLDER + '/' + ['de', 'ath'].join('') + '.mp3';
  const WHIPLASH_FINAL_KEY = 'horseWhiplashFinal';
  const WHIPLASH_FINAL_FILE = FOLDER + '/WhiplashFinal.mp3';

  function frame(name) {
    return FOLDER + '/' + name + '.png?v=' + HORSE_ASSET_VERSION;
  }

  Assets.horse = Object.assign(Assets.horse || {}, {
    idle: frame('idle'),
    walk: [
      frame('walk01'),
      frame('walk02'),
      frame('walk03')
    ],
    attack: [
      frame('idle'),
      [frame('Whiplash'), frame('Whiplash2'), frame('Whiplash3')],
      [frame('WhiplashFinal'), frame('Whiplash'), frame('Whiplash2'), frame('Whiplash3')]
    ]
  });
  Assets.horse.finalFrame = frame('knockdown');
  Assets.horse.appear = FOLDER + '/Appear.mp3';
  Assets.horse.koSound = KO_FILE;
  Assets.horse.whiplashFinalSound = WHIPLASH_FINAL_FILE;

  if (Assets.enemyAppear) Assets.enemyAppear.horse = Assets.horse.appear;
  if (Assets.audio && Assets.audio.sfx) {
    Assets.audio.sfx[KO_KEY] = KO_FILE;
    Assets.audio.sfx[WHIPLASH_FINAL_KEY] = WHIPLASH_FINAL_FILE;
  }

  function loadFirstExistingImage(srcOrList) {
    const list = Array.isArray(srcOrList) ? srcOrList : [srcOrList];
    return new Promise((resolve) => {
      let index = 0;
      function tryNext() {
        const src = list[index++];
        if (!src) return resolve(null);
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = tryNext;
        img.src = src;
      }
      tryNext();
    });
  }

  if (typeof AudioManager !== 'undefined' && !AudioManager.horseKoPatchApplied) {
    const previousInit = AudioManager.init;
    AudioManager.init = function () {
      previousInit.call(this);
      if (!this.sfx[KO_KEY] && this.createAudio) {
        this.sfx[KO_KEY] = this.createAudio(KO_FILE, false);
      }
      if (!this.sfx[WHIPLASH_FINAL_KEY] && this.createAudio) {
        this.sfx[WHIPLASH_FINAL_KEY] = this.createAudio(WHIPLASH_FINAL_FILE, false);
      }
    };
    AudioManager.horseKoPatchApplied = true;
  }

  if (typeof DogRegimeEnemy !== 'undefined' && !DogRegimeEnemy.prototype.horseKoPatchApplied) {
    const previousTakeHit = DogRegimeEnemy.prototype.takeHit;
    DogRegimeEnemy.prototype.takeHit = function (damage, direction, knockback) {
      const wasAlive = this.alive;
      previousTakeHit.call(this, damage, direction, knockback);
      if (wasAlive && !this.alive && this.enemyType === 'horse') {
        AudioManager.playSfx(KO_KEY, 0.95, { startAt: 0.01 });
      }
    };
    DogRegimeEnemy.prototype.horseKoPatchApplied = true;
  }

  if (typeof GameApp !== 'undefined' && !GameApp.prototype.horseWalkOnlyPatchApplied) {
    const previousLoadImages = GameApp.prototype.loadImages;
    GameApp.prototype.loadImages = async function () {
      const loaded = await previousLoadImages.call(this);
      const horse = Assets.horse || {};

      const walk0 = await loadFirstExistingImage(horse.walk && horse.walk[0]);
      const walk1 = await loadFirstExistingImage(horse.walk && horse.walk[1]);
      const walk2 = await loadFirstExistingImage(horse.walk && horse.walk[2]);
      const idle = await loadFirstExistingImage(horse.idle) || walk0;
      const action0 = await loadFirstExistingImage(horse.attack && horse.attack[0]);
      const action1 = await loadFirstExistingImage(horse.attack && horse.attack[1]);
      const action2 = await loadFirstExistingImage(horse.attack && horse.attack[2]);
      const finalFrame = await loadFirstExistingImage(horse.finalFrame);

      if (!loaded.enemies) loaded.enemies = {};
      loaded.enemies.horse = {
        idle: idle || walk0 || walk1 || walk2,
        walk: [
          walk0 || idle,
          walk1 || walk0 || idle,
          walk2 || walk1 || walk0 || idle
        ],
        attack: [
          action0 || walk1 || walk0 || idle,
          action1 || walk2 || walk1 || walk0 || idle,
          action2 || action1 || walk2 || walk1 || walk0 || idle
        ]
      };
      loaded.enemies.horse['de' + 'ad'] = finalFrame || walk2 || walk1 || walk0 || idle;
      loaded.enemies.horse.dead = loaded.enemies.horse['de' + 'ad'];
      return loaded;
    };

    GameApp.prototype.horseWalkOnlyPatchApplied = true;
  }
})();



/* ===== src/mobileBootstrap.js ===== */
(function () {
  if (typeof GameApp === 'undefined' || typeof MobileApp === 'undefined') return;
  if (GameApp.prototype.mobileBootstrapPatched) return;

  GameApp.prototype.mobileBootstrapPatched = true;

  function loadHitboxEditorPatch() {
    if (window.__hitboxEditorPatchRequested) return;
    window.__hitboxEditorPatchRequested = true;
    var script = document.createElement('script');
    script.src = 'src/hitboxEditorPatch.js?v=anatomy-hitboxes-3';
    script.defer = true;
    document.body.appendChild(script);
  }

  function applySmartDogDefaults() {
    if (typeof GAME_CONFIG === 'undefined' || !GAME_CONFIG.enemies || !GAME_CONFIG.enemies.dogRegime) return;
    var dog = GAME_CONFIG.enemies.dogRegime;
    if (dog.smartAiVersion >= 4) return;
    Object.assign(dog, {
      smartAiVersion: 4,
      minDistanceX: 44,
      preferredDistanceX: 64,
      tooFarDistanceX: 150,
      attackMinDistanceX: 30,
      attackMaxDistanceX: 128,
      attackRangeX: 128,
      attackRangeY: 42,
      clubReachForward: 142,
      clubReachBack: 16,
      maxAttackers: 1,
      decisionMinMs: 120,
      decisionMaxMs: 280,
      strafeChance: 0.32,
      retreatChance: 0.16,
      attackChance: 0.86,
      closeRetreatChance: 0.32,
      playerAttackFearDistance: 86,
      postAttackRetreatMs: 220,
      attackCooldownMinMs: 300,
      attackCooldownMaxMs: 520,
      backstabChance: 0.78,
      flankDistanceX: 112,
      pressureDistanceX: 160
    });
  }

  function patchMobileEnemyRoster() {
    if (typeof HUD === 'undefined' || HUD.mobileEnemyRosterPatchApplied) return;

    HUD.getEnemyRosterLayout = function () {
      var isMobile = typeof Responsive !== 'undefined' && Responsive.isTouchDevice;
      if (isMobile) {
        return { maxVisible: 4, cardW: 166, cardH: 42, gap: 5, x: 18, y: 100, portrait: 32, font: 'bold 13px Arial', nameMax: 14 };
      }
      return { maxVisible: 6, cardW: 170, cardH: 46, gap: 6, x: GAME_CONFIG.width - 188, y: 96, portrait: 36, font: 'bold 13px Arial', nameMax: 15 };
    };

    HUD.drawEnemyRoster = function (ctx, scene) {
      var enemies = (scene.enemies || []).filter(function (enemy) { return enemy && enemy.alive && !enemy.remove; });
      if (enemies.length === 0) return;

      var layout = this.getEnemyRosterLayout();
      var visibleEnemies = enemies.slice(0, layout.maxVisible);

      for (var i = 0; i < visibleEnemies.length; i++) {
        var enemy = visibleEnemies[i];
        var y = layout.y + i * (layout.cardH + layout.gap);
        var config = (GAME_CONFIG.enemies && GAME_CONFIG.enemies[enemy.enemyType]) || {};
        var name = config.name || enemy.enemyType || 'Враг';
        var portrait = this.getEnemyPortraitImage(scene, enemy);
        var pad = Math.max(4, Math.round((layout.cardH - layout.portrait) / 2));

        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.78)';
        ctx.fillRect(layout.x, y, layout.cardW, layout.cardH);
        ctx.strokeStyle = 'rgba(255,255,255,0.56)';
        ctx.lineWidth = 2;
        ctx.strokeRect(layout.x, y, layout.cardW, layout.cardH);

        ctx.fillStyle = 'rgba(255,255,255,0.12)';
        ctx.fillRect(layout.x + pad, y + pad, layout.portrait, layout.portrait);
        if (portrait) this.drawEnemyPortrait(ctx, portrait, layout.x + pad, y + pad, layout.portrait);

        ctx.fillStyle = '#fff';
        ctx.font = layout.font;
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 3;
        var label = this.shorten(name, layout.nameMax);
        var tx = layout.x + pad * 2 + layout.portrait;
        var ty = y + layout.cardH / 2 + 1;
        ctx.strokeText(label, tx, ty);
        ctx.fillText(label, tx, ty);
        ctx.restore();
      }

      if (enemies.length > layout.maxVisible) {
        var moreY = layout.y + layout.maxVisible * (layout.cardH + layout.gap);
        ctx.fillStyle = 'rgba(0,0,0,0.65)';
        ctx.fillRect(layout.x, moreY, layout.cardW, 22);
        ctx.fillStyle = '#ddd';
        ctx.font = 'bold 11px Arial';
        ctx.fillText('+' + String(enemies.length - layout.maxVisible) + ' ещё', layout.x + 10, moreY + 15);
      }
    };

    HUD.mobileEnemyRosterPatchApplied = true;
  }

  loadHitboxEditorPatch();
  applySmartDogDefaults();
  patchMobileEnemyRoster();

  var originalEnsureMenuMusic = GameApp.prototype.ensureMenuMusic;
  GameApp.prototype.ensureMenuMusic = function () {
    if (MobileApp && MobileApp.isMobile && MobileApp.isMobile() && this.state === 'splash') return;
    originalEnsureMenuMusic.call(this);
  };

  var originalInit = GameApp.prototype.init;
  GameApp.prototype.init = async function () {
    window.game = this;
    await originalInit.call(this);
    window.game = this;
    loadHitboxEditorPatch();
    applySmartDogDefaults();
    patchMobileEnemyRoster();
    if (MobileApp && MobileApp.attach) MobileApp.attach(this);
  };

  var originalDrawOverlay = MobileApp.drawOverlay;
  MobileApp.drawOverlay = function (ctx, game) {
    if (typeof originalDrawOverlay === 'function') originalDrawOverlay.call(this, ctx, game);
    if (game && game.state === 'level' && game.scene && typeof HUD !== 'undefined' && typeof HUD.drawEnemyRoster === 'function') {
      HUD.drawEnemyRoster(ctx, game.scene);
    }
  };
})();



/* ===== src/campaignMapPatch.js ===== */
(function () {
  if (typeof CampaignMapScreen === 'undefined') {
    console.warn('CampaignMapScreen is not loaded');
    return;
  }

  const INTRO_TEXT = `Эта страна могла быть счастливой.

Люди могли бы смотреть в завтрашний день без страха.
Смеяться. Строить планы. Говорить правду.
Жить свободно.

Но этому не дали случиться.

Шаг за шагом страну захватила преступная группировка тварей.
Они протянули свои грязные руки во власть, в суды, в средства массовой информации, в полицию, в армию — и в головы людей.
Как раковая опухоль, они пустили метастазы по телу страны.

Чиновники стали послушными марионетками.
Полиция перестала защищать людей и превратилась в дубинку режима.
Закон стал оружием.
Телевизор стал машиной лжи.
А правда — преступлением.

Годы страха, пропаганды и насилия превратили страну в огромную тюрьму.

Улицы заполнили силовики, доносчики, продажные чиновники и зомбированные толпы.
Тех, кто не согласен, ломают, давят, убивают или заставляют исчезнуть.

Казалось, надежды больше нет.

Лучшие давно покинули этот мир.
Те, кто говорил правду.
Те, кто не боялся.
Те, кто отдал свои жизни за свободу.

Но у людей осталось кое-что,
чего не отнять ни силой, ни болью, ни ложью.

Вера в светлое будущее.

И эта вера совершила невозможное.

Трое героев, когда-то отдавшие свои жизни в борьбе за свободу, вернулись.
Они стали ответом на отчаянный крик страны.

Теперь они выходят на улицы России,
чтобы пробиться через страх, ложь и насилие
и вернуть людям свободу.

На улицах этой замученной страны начинается их путь.
Путь очищения страны от тварей, паразитирующих на её теле.

Это больше не просто борьба.

Это последняя надежда.

Это Streets of Russia.`;

  const INTRO_BACKGROUND = 'assets/backgrounds/Intro.png';
  const INTRO_TYPEWRITER_SOUND = 'assets/audio/sfx/typewriter-key.mp3';
  const INTRO_VOICE = 'assets/audio/music/intro-voice.mp3';
  const INTRO_TYPE_SPEED = 24; // fallback characters per second when voice is unavailable
  const INTRO_FAST_MULTIPLIER = 7;
  const INTRO_LINE_HOLD = 0.18;
  const INTRO_BLANK_LINE_TIME = 0.34;
  const INTRO_TYPE_Y = 455;
  const INTRO_END_HOLD_SECONDS = 5;
  const INTRO_END_FADE_SECONDS = 1.8;
  const INTRO_SEEN_KEY = 'streetsOfRussiaIntroSeen';
  const INTRO_TYPE_CLICK_MIN_INTERVAL = 42;
  const INTRO_TYPE_CLICK_EVERY_CHARS = 2;
  const INTRO_READER_LINE_HEIGHT = 32;
  const INTRO_READER_SCROLL_STEP = 42;

  function loadPatchImage(src) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => {
        console.warn('Missing image:', src);
        resolve(null);
      };
      img.src = src;
    });
  }

  function loadPatchAudio(src, loop = false, volume = 0.35) {
    const audio = new Audio();
    audio.src = src;
    audio.preload = 'auto';
    audio.loop = loop;
    audio.volume = volume;
    audio.addEventListener('error', () => {
      console.warn('Missing audio:', src);
    });
    return audio;
  }

  function wrapText(ctx, text, maxWidth) {
    const lines = [];
    const paragraphs = text.split('\n');

    for (const paragraph of paragraphs) {
      if (!paragraph.trim()) {
        lines.push('');
        continue;
      }

      const words = paragraph.split(' ');
      let line = '';

      for (const word of words) {
        const testLine = line ? line + ' ' + word : word;
        if (ctx.measureText(testLine).width > maxWidth && line) {
          lines.push(line);
          line = word;
        } else {
          line = testLine;
        }
      }

      if (line) lines.push(line);
    }

    return lines;
  }

  function lineDuration(line) {
    if (!line || !line.trim()) return INTRO_BLANK_LINE_TIME;
    return Math.max(0.55, line.length / INTRO_TYPE_SPEED + INTRO_LINE_HOLD);
  }

  function getTimelineDuration(lines) {
    return lines.reduce((sum, line) => sum + lineDuration(line), INTRO_END_HOLD_SECONDS + INTRO_END_FADE_SECONDS);
  }

  function getTimelineState(lines, timeSeconds) {
    let t = Math.max(0, timeSeconds);

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const duration = lineDuration(line);

      if (t <= duration) {
        const typingPart = Math.max(0.01, duration - INTRO_LINE_HOLD);
        const progress = Math.min(1, t / typingPart);
        const chars = line && line.trim() ? Math.floor(line.length * progress) : 0;
        return {
          phase: 'typing',
          lineIndex: i,
          charInLine: Math.min(line.length, chars),
          endElapsed: 0,
          complete: false
        };
      }

      t -= duration;
    }

    return {
      phase: 'ending',
      lineIndex: Math.max(0, lines.length - 1),
      charInLine: lines.length ? lines[lines.length - 1].length : 0,
      endElapsed: t,
      complete: t >= INTRO_END_HOLD_SECONDS + INTRO_END_FADE_SECONDS
    };
  }

  function getTypedCursor(lines, state) {
    let cursor = 0;
    for (let i = 0; i < state.lineIndex; i++) {
      cursor += (lines[i] || '').length + 1;
    }
    return cursor + state.charInLine;
  }

  function getStartButtonRect() {
    return { x: GAME_CONFIG.width / 2 - 130, y: GAME_CONFIG.height - 86, w: 260, h: 52 };
  }

  function pointInRect(point, rect) {
    return point && point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h;
  }

  const originalLoadImages = GameApp.prototype.loadImages;
  GameApp.prototype.loadImages = async function () {
    const loaded = await originalLoadImages.call(this);
    loaded.intro = await loadPatchImage(INTRO_BACKGROUND);
    return loaded;
  };

  const originalInit = GameApp.prototype.init;
  GameApp.prototype.init = async function () {
    CampaignMapScreen.init();
    this.campaignMap = CampaignMapScreen;
    this.intro = {
      text: INTRO_TEXT,
      time: 0,
      firstRun: false,
      fastForward: false,
      readyToContinue: false,
      readerScroll: 0,
      layoutLines: [],
      totalTimelineDuration: 0,
      lastTypedCursor: 0,
      lastTypeSoundAt: 0,
      audioContext: null,
      typewriterSound: loadPatchAudio(INTRO_TYPEWRITER_SOUND, false, 0.35),
      typewriterSoundMissing: false,
      voice: loadPatchAudio(INTRO_VOICE, false, 0.72),
      voiceMissing: false,
      voiceStarted: false,
      music: null,
      musicMissing: true,
      wheelBound: false
    };
    this.intro.voice.addEventListener('loadedmetadata', () => {
      console.log('[CAMPAIGN INTRO] Voice loaded:', INTRO_VOICE, 'duration:', this.intro.voice.duration);
    });
    this.intro.voice.addEventListener('play', () => {
      this.intro.voiceStarted = true;
    });
    this.intro.voice.addEventListener('ended', () => {
      this.intro.voiceStarted = false;
      this.intro.time = this.intro.totalTimelineDuration || this.intro.time;
      this.intro.readyToContinue = true;
    });
    this.intro.voice.addEventListener('error', () => {
      this.intro.voiceMissing = true;
      console.warn('[CAMPAIGN INTRO] Missing intro voice:', INTRO_VOICE);
    });
    await originalInit.call(this);
  };

  const originalIsMenuState = GameApp.prototype.isMenuState;
  GameApp.prototype.isMenuState = function (state) {
    return state === 'campaignMap' || originalIsMenuState.call(this, state);
  };

  GameApp.prototype.hasSeenIntro = function () {
    try {
      return localStorage.getItem(INTRO_SEEN_KEY) === 'yes';
    } catch (error) {
      return false;
    }
  };

  GameApp.prototype.markIntroSeen = function () {
    try {
      localStorage.setItem(INTRO_SEEN_KEY, 'yes');
    } catch (error) {}
  };

  GameApp.prototype.bindIntroWheel = function () {
    if (this.intro.wheelBound) return;
    this.intro.wheelBound = true;
    this.canvas.addEventListener('wheel', (event) => {
      if (this.state !== 'intro' || !this.intro.readyToContinue) return;
      event.preventDefault();
      this.scrollIntroReader(event.deltaY > 0 ? 1 : -1);
    }, { passive: false });
  };

  GameApp.prototype.syncIntroVoiceVolume = function () {
    const voice = this.intro && this.intro.voice;
    if (!voice) return;
    voice.volume = AudioManager.isMusicOn() ? 0.72 : 0;
  };

  GameApp.prototype.playIntroVoice = function () {
    const voice = this.intro.voice;
    if (!voice || this.intro.voiceMissing) return;

    try {
      AudioManager.stopMusic();
      this.syncIntroVoiceVolume();
      voice.currentTime = 0;
      voice.play().catch((error) => {
        this.intro.voiceStarted = false;
        console.warn('[CAMPAIGN INTRO] Voice autoplay blocked or failed:', error);
      });
    } catch (error) {
      this.intro.voiceMissing = true;
      console.warn('[CAMPAIGN INTRO] Cannot play intro voice:', error);
    }
  };

  GameApp.prototype.stopIntroVoice = function () {
    const voice = this.intro.voice;
    if (!voice) return;
    try {
      voice.pause();
      voice.currentTime = 0;
    } catch (error) {}
    this.intro.voiceStarted = false;
  };

  GameApp.prototype.playIntroMusic = function () {
    this.playIntroVoice();
  };

  GameApp.prototype.stopIntroMusic = function () {
    this.stopIntroVoice();
  };

  GameApp.prototype.startIntro = function () {
    this.intro.time = 0;
    this.intro.firstRun = !this.hasSeenIntro();
    this.intro.fastForward = false;
    this.intro.readyToContinue = false;
    this.intro.readerScroll = 0;
    this.intro.lastTypedCursor = 0;
    this.intro.lastTypeSoundAt = 0;
    this.intro.voiceStarted = false;
    if (this.intro.typewriterSound) this.intro.typewriterSound.load();
    if (this.intro.voice) this.intro.voice.load();
    this.bindIntroWheel();
    AudioManager.stopMusic();
    this.setState('intro');
    this.playIntroVoice();
  };

  GameApp.prototype.finishIntro = function () {
    this.markIntroSeen();
    this.stopIntroVoice();
    this.setState('campaignMap');
    this.ensureMenuMusic();
  };

  GameApp.prototype.playGeneratedIntroTypeClick = function () {
    try {
      const AudioCtor = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtor) return;
      if (!this.intro.audioContext) this.intro.audioContext = new AudioCtor();
      const audioCtx = this.intro.audioContext;
      if (audioCtx.state === 'suspended') audioCtx.resume().catch(() => {});

      const t = audioCtx.currentTime;
      const oscillator = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      const filter = audioCtx.createBiquadFilter();

      oscillator.type = 'square';
      oscillator.frequency.value = 900 + Math.random() * 520;
      filter.type = 'highpass';
      filter.frequency.value = 550;
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.026, t + 0.004);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.028);

      oscillator.connect(filter);
      filter.connect(gain);
      gain.connect(audioCtx.destination);
      oscillator.start(t);
      oscillator.stop(t + 0.03);
    } catch (error) {}
  };

  GameApp.prototype.playIntroTypeClick = function (typedCursor) {
    if (!typedCursor || typedCursor <= this.intro.lastTypedCursor) return;
    if (this.intro.fastForward) {
      this.intro.lastTypedCursor = typedCursor;
      return;
    }
    if (typedCursor % INTRO_TYPE_CLICK_EVERY_CHARS !== 0) {
      this.intro.lastTypedCursor = typedCursor;
      return;
    }
    if (AudioManager && AudioManager.isSfxOn && !AudioManager.isSfxOn()) {
      this.intro.lastTypedCursor = typedCursor;
      return;
    }

    const now = performance.now();
    if (now - this.intro.lastTypeSoundAt < INTRO_TYPE_CLICK_MIN_INTERVAL) {
      this.intro.lastTypedCursor = typedCursor;
      return;
    }

    const realSound = this.intro.typewriterSound;
    if (realSound && !this.intro.typewriterSoundMissing) {
      try {
        const click = realSound.cloneNode(true);
        click.volume = 0.28;
        click.currentTime = 0;
        click.play().catch(() => {
          this.intro.typewriterSoundMissing = true;
          this.playGeneratedIntroTypeClick();
        });
      } catch (error) {
        this.intro.typewriterSoundMissing = true;
        this.playGeneratedIntroTypeClick();
      }
    } else {
      this.playGeneratedIntroTypeClick();
    }

    this.intro.lastTypeSoundAt = now;
    this.intro.lastTypedCursor = typedCursor;
  };

  GameApp.prototype.getIntroReaderLimits = function () {
    const totalHeight = this.intro.layoutLines.length * INTRO_READER_LINE_HEIGHT;
    const visibleHeight = GAME_CONFIG.height - 230;
    return { max: Math.max(0, totalHeight - visibleHeight) };
  };

  GameApp.prototype.scrollIntroReader = function (direction) {
    const limits = this.getIntroReaderLimits();
    this.intro.readerScroll = Math.max(0, Math.min(limits.max, this.intro.readerScroll + direction * INTRO_READER_SCROLL_STEP));
  };

  GameApp.prototype.getIntroVoiceProgress = function () {
    const voice = this.intro && this.intro.voice;
    if (!voice || this.intro.voiceMissing || !this.intro.voiceStarted) return null;
    const duration = Number.isFinite(voice.duration) && voice.duration > 0 ? voice.duration : 0;
    if (!duration || !Number.isFinite(voice.currentTime)) return null;
    return Math.max(0, Math.min(1, voice.currentTime / duration));
  };

  GameApp.prototype.updateIntro = function (dt) {
    const click = Input.consumePointer();
    const anyKey = Input.consumeAnyKey();
    const requestedAction = !!(click || anyKey);

    this.syncIntroVoiceVolume();

    if (click && this.handleSpeakerClick(click)) return;

    if (this.intro.readyToContinue) {
      if (click && pointInRect(click, getStartButtonRect())) {
        this.finishIntro();
        return;
      }

      if (Input.consume('arrowup') || Input.consume('w')) this.scrollIntroReader(-1);
      if (Input.consume('arrowdown') || Input.consume('s')) this.scrollIntroReader(1);
      if (Input.consume('pageup')) this.scrollIntroReader(-4);
      if (Input.consume('pagedown')) this.scrollIntroReader(4);

      if (Input.consume('enter') || Input.consume('space')) this.finishIntro();
      return;
    }

    if (!this.intro.firstRun && requestedAction) {
      this.intro.fastForward = true;
    }

    const voiceProgress = this.getIntroVoiceProgress();
    if (voiceProgress != null && this.intro.totalTimelineDuration > 0 && !this.intro.fastForward) {
      this.intro.time = voiceProgress * this.intro.totalTimelineDuration;
      return;
    }

    const multiplier = this.intro.fastForward ? INTRO_FAST_MULTIPLIER : 1;
    this.intro.time += (dt / 1000) * multiplier;
  };

  GameApp.prototype.drawIntroReader = function (ctx, lines, maxWidth) {
    const panelX = 150;
    const panelY = 88;
    const panelW = GAME_CONFIG.width - 300;
    const panelH = GAME_CONFIG.height - 190;

    ctx.fillStyle = 'rgba(0, 0, 0, 0.58)';
    ctx.fillRect(panelX - 20, panelY - 20, panelW + 40, panelH + 40);
    ctx.strokeStyle = 'rgba(255,255,255,0.55)';
    ctx.lineWidth = 2;
    ctx.strokeRect(panelX - 20, panelY - 20, panelW + 40, panelH + 40);

    ctx.save();
    ctx.beginPath();
    ctx.rect(panelX, panelY, panelW, panelH);
    ctx.clip();

    ctx.font = 'bold 24px Arial';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.shadowColor = '#000';
    ctx.shadowBlur = 8;
    ctx.lineWidth = 5;
    ctx.strokeStyle = '#000';
    ctx.fillStyle = '#f4f4f4';

    for (let i = 0; i < lines.length; i++) {
      const y = panelY + i * INTRO_READER_LINE_HEIGHT - this.intro.readerScroll;
      if (y < panelY - INTRO_READER_LINE_HEIGHT || y > panelY + panelH) continue;
      ctx.strokeText(lines[i], panelX, y);
      ctx.fillText(lines[i], panelX, y);
    }

    ctx.restore();

    const limits = this.getIntroReaderLimits();
    if (limits.max > 0) {
      const barX = panelX + panelW + 16;
      const barY = panelY;
      const barH = panelH;
      const thumbH = Math.max(40, barH * (panelH / (panelH + limits.max)));
      const thumbY = barY + (barH - thumbH) * (this.intro.readerScroll / limits.max);

      ctx.fillStyle = 'rgba(255,255,255,0.18)';
      ctx.fillRect(barX, barY, 6, barH);
      ctx.fillStyle = 'rgba(255,255,255,0.75)';
      ctx.fillRect(barX, thumbY, 6, thumbH);
    }

    const btn = getStartButtonRect();
    ctx.fillStyle = 'rgba(120, 0, 0, 0.88)';
    ctx.fillRect(btn.x, btn.y, btn.w, btn.h);
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 3;
    ctx.strokeRect(btn.x, btn.y, btn.w, btn.h);
    ctx.font = 'bold 28px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 5;
    ctx.strokeText('НАЧАТЬ', btn.x + btn.w / 2, btn.y + 34);
    ctx.fillText('НАЧАТЬ', btn.x + btn.w / 2, btn.y + 34);

    ctx.font = 'bold 17px Arial';
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(255,255,255,0.72)';
    ctx.fillText('Колесо мыши / ↑↓ — читать текст', GAME_CONFIG.width - 34, GAME_CONFIG.height - 18);
    ctx.textAlign = 'left';
  };

  GameApp.prototype.drawIntro = function (ctx) {
    const bg = this.images.intro;

    if (bg) {
      ctx.drawImage(bg, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    } else {
      ctx.fillStyle = '#050505';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    }

    ctx.fillStyle = 'rgba(0, 0, 0, 0.50)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    ctx.font = 'bold 25px Arial';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';

    const textX = 150;
    const lineHeight = 34;
    const maxWidth = GAME_CONFIG.width - 300;
    const clipTop = 76;
    const clipBottom = GAME_CONFIG.height - 84;
    const lines = wrapText(ctx, this.intro.text, maxWidth);
    this.intro.layoutLines = lines;
    this.intro.totalTimelineDuration = getTimelineDuration(lines);

    const state = getTimelineState(lines, this.intro.time);
    if (state.complete) {
      this.intro.readyToContinue = true;
    }

    if (this.intro.readyToContinue) {
      this.drawIntroReader(ctx, lines, maxWidth);
      return;
    }

    const typedCursor = getTypedCursor(lines, state);
    if (state.phase === 'typing' && state.charInLine > 0) {
      this.playIntroTypeClick(typedCursor);
    }

    const fadeAlpha = state.phase === 'ending'
      ? Math.max(0, 1 - Math.max(0, state.endElapsed - INTRO_END_HOLD_SECONDS) / INTRO_END_FADE_SECONDS)
      : 1;

    ctx.save();
    ctx.globalAlpha = fadeAlpha;
    ctx.beginPath();
    ctx.rect(textX, clipTop, maxWidth, clipBottom - clipTop);
    ctx.clip();

    ctx.shadowColor = '#000';
    ctx.shadowBlur = 8;
    ctx.lineWidth = 5;
    ctx.strokeStyle = '#000';
    ctx.fillStyle = '#f4f4f4';

    for (let i = 0; i <= state.lineIndex && i < lines.length; i++) {
      let line = lines[i];
      if (state.phase === 'typing' && i === state.lineIndex) {
        line = line.slice(0, state.charInLine);
      }

      const y = INTRO_TYPE_Y - (state.lineIndex - i) * lineHeight;
      if (y < clipTop - lineHeight || y > clipBottom) continue;

      ctx.strokeText(line, textX, y);
      ctx.fillText(line, textX, y);
    }

    if (state.phase === 'typing') {
      const currentLine = lines[state.lineIndex] || '';
      const typedLine = currentLine.slice(0, state.charInLine);
      const caretX = textX + ctx.measureText(typedLine).width + 8;
      const caretY = INTRO_TYPE_Y + 3;
      if (Math.floor(this.intro.time * 4) % 2 === 0) {
        ctx.fillStyle = '#ff2b2b';
        ctx.fillRect(caretX, caretY, 12, 25);
      }
    }

    ctx.restore();

    const fade = ctx.createLinearGradient(0, 0, 0, GAME_CONFIG.height);
    fade.addColorStop(0, 'rgba(0,0,0,0.84)');
    fade.addColorStop(0.18, 'rgba(0,0,0,0)');
    fade.addColorStop(0.74, 'rgba(0,0,0,0)');
    fade.addColorStop(1, 'rgba(0,0,0,0.90)');
    ctx.fillStyle = fade;
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    ctx.font = 'bold 18px Arial';
    ctx.textAlign = 'right';
    ctx.fillStyle = 'rgba(255,255,255,0.70)';

    let hint = '';
    if (this.intro.firstRun) {
      hint = state.phase === 'ending' ? 'Интро завершается...' : 'Первый запуск: интро нужно досмотреть до конца';
    } else if (this.intro.fastForward) {
      hint = state.phase === 'ending' ? 'Интро завершается...' : 'Ускоренная перемотка интро...';
    } else {
      hint = 'Нажмите любую кнопку, чтобы ускорить интро';
    }

    ctx.fillText(hint, GAME_CONFIG.width - 34, GAME_CONFIG.height - 30);
    ctx.textAlign = 'left';
  };

  const originalUpdate = GameApp.prototype.update;
  GameApp.prototype.update = function (dt) {
    if (Responsive.isPortrait) return;

    if (this.state === 'intro') {
      DevPanel.update(this);
      if (DevPanel.open) return;
      this.updateIntro(dt);
      return;
    }

    if (this.state !== 'splash' && this.state !== 'loading') {
      const click = Input.consumePointer();
      if (click) {
        if (this.handleSpeakerClick(click)) return;
        Input.restorePointer(click);
      }
    }

    if (this.state !== 'campaignMap') {
      originalUpdate.call(this, dt);
      return;
    }

    DevPanel.update(this);

    const click = Input.consumePointer();
    if (click) Input.restorePointer(click);

    if (DevPanel.open) return;

    this.campaignMap.update(this, dt);
  };

  const originalDraw = GameApp.prototype.draw;
  GameApp.prototype.draw = function () {
    if (this.state === 'intro') {
      const ctx = this.ctx;
      ctx.clearRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

      if (Responsive.isPortrait) {
        this.drawRotateWarning(ctx);
        return;
      }

      this.drawIntro(ctx);
      this.drawSpeaker(ctx);
      DevPanel.draw(ctx);
      return;
    }

    if (this.state !== 'campaignMap') {
      originalDraw.call(this);
      return;
    }

    const ctx = this.ctx;
    ctx.clearRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    if (Responsive.isPortrait) {
      this.drawRotateWarning(ctx);
      return;
    }

    this.campaignMap.draw(ctx);
    this.drawSpeaker(ctx);
    DevPanel.draw(ctx);
  };

  const originalMenuActivate = Menu.activate;
  Menu.activate = function (game) {
    const item = this.items[this.selectedIndex];
    if (item === 'НОВАЯ ИГРА') {
      AudioManager.playSfx('menuSelect', 0.85);
      game.startIntro();
      return;
    }

    originalMenuActivate.call(this, game);
  };

  GameApp.prototype.getSpeakerHitRect = function () {
    return { x: GAME_CONFIG.width - 112, y: 0, w: 112, h: 96 };
  };

  GameApp.prototype.handleSpeakerClick = function (point) {
    if (this.state === 'splash' || this.state === 'loading') return false;

    const r = this.getSpeakerHitRect();
    if (point.x < r.x || point.x > r.x + r.w || point.y < r.y || point.y > r.y + r.h) return false;

    AudioManager.unlock();
    const musicOn = AudioManager.toggleMusic();

    if (this.state === 'intro') {
      this.syncIntroVoiceVolume();
      if (musicOn && this.intro.voice && this.intro.voice.paused && !this.intro.readyToContinue) {
        this.intro.voice.play().catch(() => {});
      }
    } else if (musicOn && this.isMenuState(this.state)) {
      this.ensureMenuMusic();
    }

    AudioManager.playSfx('menuSelect', 0.7);
    return true;
  };

  GameApp.prototype.drawSpeaker = function (ctx) {
    if (this.state === 'splash' || this.state === 'loading') return;

    const r = this.getSpeakerRect();
    const on = GAME_CONFIG.settings.musicEnabled !== false;

    ctx.save();
    ctx.fillStyle = 'rgba(8, 8, 10, 0.68)';
    ctx.fillRect(r.x, r.y, r.w, r.h);

    ctx.strokeStyle = on ? 'rgba(255,255,255,0.88)' : 'rgba(255,65,65,0.96)';
    ctx.lineWidth = 2;
    ctx.strokeRect(r.x, r.y, r.w, r.h);

    ctx.fillStyle = on ? '#ffffff' : '#bdbdbd';

    ctx.beginPath();
    ctx.moveTo(r.x + 9, r.y + 21);
    ctx.lineTo(r.x + 17, r.y + 21);
    ctx.lineTo(r.x + 30, r.y + 11);
    ctx.lineTo(r.x + 30, r.y + 37);
    ctx.lineTo(r.x + 17, r.y + 27);
    ctx.lineTo(r.x + 9, r.y + 27);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = on ? '#ffffff' : '#bdbdbd';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(r.x + 31, r.y + 24, 7, -0.8, 0.8);
    ctx.stroke();

    if (on) {
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(r.x + 31, r.y + 24, 14, -0.72, 0.72);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(r.x + 31, r.y + 24, 20, -0.62, 0.62);
      ctx.stroke();
    } else {
      ctx.strokeStyle = '#ff2b2b';
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(r.x + 8, r.y + 40);
      ctx.lineTo(r.x + 40, r.y + 8);
      ctx.stroke();
    }

    ctx.restore();
  };

  const originalNextScreen = LevelScene.prototype.nextScreen;
  LevelScene.prototype.nextScreen = function () {
    const order = GAME_CONFIG.levelOrder || [];
    const currentKey = order[this.screenIndex];
    const nextKey = order[this.screenIndex + 1];
    const currentLevel = currentKey && GAME_CONFIG.levels && GAME_CONFIG.levels[currentKey];
    const nextLevel = nextKey && GAME_CONFIG.levels && GAME_CONFIG.levels[nextKey];
    const currentRegion = currentLevel && (currentLevel.region || currentLevel.regionKey || currentLevel.area || currentLevel.chapter);
    const nextRegion = nextLevel && (nextLevel.region || nextLevel.regionKey || nextLevel.area || nextLevel.chapter);

    if (this.screenIndex < this.images.streets.length - 1 && currentRegion && nextRegion && currentRegion === nextRegion) {
      originalNextScreen.call(this);
      return;
    }

    this.game.completeCampaignRegion();
  };

  GameApp.prototype.completeCampaignRegion = function () {
    this.campaignMap.completeActiveRegion();
    this.setState('campaignMap');
    this.ensureMenuMusic();
  };
})();



/* ===== src/introTextSourcePatch.js ===== */
(function () {
  if (typeof GameApp === 'undefined') {
    console.warn('Intro text source patch skipped: GameApp is not loaded.');
    return;
  }

  const FALLBACK_INTRO_TEXT = 'Ошибка загрузки introContent.js';

  function getIntroText() {
    const text = window.STREETS_INTRO_TEXT;
    if (typeof text !== 'string' || !text.trim()) {
      console.error('[CAMPAIGN INTRO] window.STREETS_INTRO_TEXT is missing or empty. Check src/introContent.js script order.');
      return FALLBACK_INTRO_TEXT;
    }

    console.log('[CAMPAIGN INTRO] Intro text loaded from window.STREETS_INTRO_TEXT. Length:', text.length);
    console.log('[CAMPAIGN INTRO] Intro text preview:', text.slice(0, 160));
    return text;
  }

  function applyIntroText(game) {
    if (!game || !game.intro) return;
    game.intro.text = getIntroText();
    game.intro.layoutLines = [];
    game.intro.readerScroll = 0;
    game.intro.readyToContinue = false;
    console.log('[CAMPAIGN INTRO] intro.text replaced from src/introContent.js');
  }

  const originalInit = GameApp.prototype.init;
  GameApp.prototype.init = async function () {
    await originalInit.call(this);
    applyIntroText(this);
  };

  const originalStartIntro = GameApp.prototype.startIntro;
  GameApp.prototype.startIntro = function () {
    applyIntroText(this);
    originalStartIntro.call(this);
  };
})();



/* ===== src/globalQualityPatch.js ===== */
(function () {
  if (typeof GameApp === 'undefined') return;

  function loadOptionalImage(src) {
    return new Promise((resolve) => {
      if (!src) {
        resolve(null);
        return;
      }
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => {
        console.warn('Missing image:', src);
        resolve(null);
      };
      img.src = src;
    });
  }

  const originalLoadImages = GameApp.prototype.loadImages;
  GameApp.prototype.loadImages = async function () {
    const loaded = await originalLoadImages.call(this);
    const fly = await loadOptionalImage(Assets.zetnik && Assets.zetnik.fly);
    const preparing = await loadOptionalImage(Assets.zetnik && Assets.zetnik.preparing);
    const crashed = await loadOptionalImage(Assets.zetnik && Assets.zetnik.crashed);

    if (loaded.enemies && loaded.enemies.zetnik) {
      loaded.enemies.zetnik.preparing = preparing || loaded.enemies.zetnik.attack[0] || loaded.enemies.zetnik.idle;
      loaded.enemies.zetnik.fly = fly || loaded.enemies.zetnik.attack[0] || loaded.enemies.zetnik.idle;
      loaded.enemies.zetnik.crashed = crashed || loaded.enemies.zetnik.dead || loaded.enemies.zetnik.attack[0] || loaded.enemies.zetnik.idle;
      loaded.enemies.zetnik.dead = loaded.enemies.zetnik.crashed;
    }
    return loaded;
  };

  const originalHandleSpeakerClick = GameApp.prototype.handleSpeakerClick;
  GameApp.prototype.handleSpeakerClick = function (point) {
    const rect = this.getSpeakerHitRect ? this.getSpeakerHitRect() : this.getSpeakerRect();
    if (!rect || !point) return false;
    if (point.x < rect.x || point.x > rect.x + rect.w || point.y < rect.y || point.y > rect.y + rect.h) return false;

    AudioManager.unlock();
    const musicOn = AudioManager.toggleMusic();

    if (this.state === 'intro' && this.intro) {
      if (this.syncIntroVoiceVolume) this.syncIntroVoiceVolume();
      if (!musicOn && this.intro.voice) {
        this.intro.voice.volume = 0;
      }
      if (musicOn && this.intro.voice && this.intro.voice.paused && !this.intro.readyToContinue) {
        this.intro.voice.play().catch(() => {});
      }
    } else if (musicOn && this.isMenuState && this.isMenuState(this.state)) {
      this.ensureMenuMusic();
    }

    AudioManager.playSfx('menuSelect', 0.7);
    return true;
  };

  const originalUpdate = GameApp.prototype.update;
  GameApp.prototype.update = function (dt) {
    if (this.state === 'intro') {
      const click = Input.consumePointer();
      if (click) {
        if (this.handleSpeakerClick(click)) return;
        Input.restorePointer(click);
      }
    }

    originalUpdate.call(this, dt);
  };

  const originalDraw = GameApp.prototype.draw;
  GameApp.prototype.draw = function () {
    originalDraw.call(this);

    if (Responsive.isPortrait || this.state === 'loading') return;
    if (this.state === 'intro' || this.state === 'splash') {
      this.drawSpeaker(this.ctx);
    }
  };
})();



/* ===== src/introFlow.js ===== */
(function () {
  if (typeof GameApp === 'undefined' || typeof AudioManager === 'undefined') return;

  const INTRO_MUSIC = 'assets/audio/music/intro-theme.mp3';
  const INTRO_MUSIC_VOLUME = 0.42;
  const INTRO_VOICE_VOLUME = 0.72;
  const INTRO_SKIP_REVEAL_SECONDS = 0.9;
  const INTRO_VOICE_TEXT_SCALE = 0.90;
  const INTRO_FINAL_PAUSE_TRIM_SECONDS = 0.5;
  const INTRO_FINAL_PAUSE_TRIM_START_PROGRESS = 0.88;
  const INTRO_END_TEXT_HOLD_SECONDS = 3.0;
  const INTRO_TEXT_FADE_SECONDS = 1.45;
  const INTRO_BUTTON_FADE_SECONDS = 0.85;
  const TYPE_CLICK_MIN_INTERVAL_MS = 165;
  const TYPE_CLICK_EVERY_CHARS = 5;

  const INTRO_TYPE_X = 150;
  const INTRO_TYPE_Y = 455;
  const INTRO_LINE_HEIGHT = 34;
  const INTRO_CLIP_TOP = 76;
  const INTRO_CLIP_BOTTOM = GAME_CONFIG.height - 84;

  function createAudio(src, loop, volume) {
    const audio = new Audio();
    audio.src = src;
    audio.preload = 'auto';
    audio.loop = loop;
    audio.volume = volume;
    audio.addEventListener('error', () => console.warn('[INTRO AUDIO FLOW] Missing audio:', src));
    return audio;
  }

  function getStartButtonRect() {
    return { x: GAME_CONFIG.width / 2 - 125, y: GAME_CONFIG.height - 70, w: 250, h: 48 };
  }

  function pointInRect(point, rect) {
    return point && point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h;
  }

  function smoothStep(t) {
    const x = Math.max(0, Math.min(1, t));
    return x * x * (3 - 2 * x);
  }

  function mapVoiceProgressToTextTime(progress, totalTimelineDuration) {
    const p = Math.max(0, Math.min(1, progress));
    const baseTime = p * INTRO_VOICE_TEXT_SCALE * totalTimelineDuration;
    const trimT = smoothStep((p - INTRO_FINAL_PAUSE_TRIM_START_PROGRESS) / (1 - INTRO_FINAL_PAUSE_TRIM_START_PROGRESS));
    const trim = trimT * INTRO_FINAL_PAUSE_TRIM_SECONDS;
    return Math.min(totalTimelineDuration, baseTime + trim);
  }

  function getIntroEndFadeAlpha(game) {
    if (!game.intro || !game.intro.finalFadeActive) return 1;
    const t = Math.max(0, Math.min(1, game.intro.finalFadeElapsed / INTRO_TEXT_FADE_SECONDS));
    return 1 - smoothStep(t);
  }

  function getIntroButtonAlpha(game) {
    if (!game.intro || !game.intro.readyToContinue) return 0;
    const t = Math.max(0, Math.min(1, (game.intro.buttonFadeElapsed || 0) / INTRO_BUTTON_FADE_SECONDS));
    return smoothStep(t);
  }

  function ensureIntroMusic(game) {
    if (!game.intro) return;
    if (game.intro.music) return;

    game.intro.music = createAudio(INTRO_MUSIC, true, INTRO_MUSIC_VOLUME);
    AudioManager.registerExternalAudio(game.intro.music, { owner: 'intro', channel: 'music' });
    game.intro.musicMissing = false;
  }

  function installIntroVoiceEndHold(game) {
    if (!game.intro || !game.intro.voice || game.intro.endHoldListenerInstalled) return;

    game.intro.endHoldListenerInstalled = true;
    game.intro.voice.addEventListener('ended', () => {
      if (!game.intro || game.intro.voiceSkipped) return;
      game.intro.voiceStarted = false;
      game.intro.finalNaturalFinishActive = true;
      game.intro.finalHoldActive = false;
      game.intro.finalHoldRemaining = 0;
      game.intro.finalFadeActive = false;
      game.intro.finalFadeElapsed = 0;
      game.intro.readyToContinue = false;
      game.intro.buttonFadeElapsed = 0;
      game.intro.readerScroll = 0;
    });
  }

  const originalInit = GameApp.prototype.init;
  GameApp.prototype.init = async function () {
    await originalInit.call(this);
    if (this.intro && this.intro.voice) {
      AudioManager.registerExternalAudio(this.intro.voice, { owner: 'intro', channel: 'sfx' });
    }
    ensureIntroMusic(this);
    installIntroVoiceEndHold(this);
  };

  GameApp.prototype.syncIntroAudioVolumes = function () {
    if (!this.intro) return;
    const musicEnabled = AudioManager.isMusicOn();
    const voiceEnabled = AudioManager.isSfxOn();

    if (this.intro.music) {
      const baseMusicVolume = AudioManager.getMusicVolume ? AudioManager.getMusicVolume() : INTRO_MUSIC_VOLUME;
      this.intro.music.volume = musicEnabled ? Math.max(0, Math.min(1, baseMusicVolume)) : 0;
    }

    if (this.intro.voice) {
      this.intro.voice.volume = voiceEnabled ? INTRO_VOICE_VOLUME : 0;
    }
  };

  GameApp.prototype.playIntroBackgroundMusic = function () {
    ensureIntroMusic(this);
    const music = this.intro && this.intro.music;
    if (!music || this.intro.musicMissing) return;

    try {
      this.syncIntroAudioVolumes();
      music.currentTime = 0;
      music.play().catch((error) => {
        this.intro.musicMissing = true;
        console.warn('[INTRO AUDIO FLOW] Intro background music failed:', error);
      });
    } catch (error) {
      this.intro.musicMissing = true;
      console.warn('[INTRO AUDIO FLOW] Cannot play intro background music:', error);
    }
  };

  GameApp.prototype.stopIntroBackgroundMusic = function () {
    const music = this.intro && this.intro.music;
    if (!music) return;
    try {
      music.pause();
      music.currentTime = 0;
    } catch (error) {}
  };

  GameApp.prototype.playIntroVoice = function () {
    const voice = this.intro && this.intro.voice;
    if (!voice || this.intro.voiceMissing || this.intro.voiceSkipped) return;

    try {
      this.syncIntroAudioVolumes();
      voice.currentTime = 0;
      voice.play().catch((error) => {
        this.intro.voiceStarted = false;
        console.warn('[INTRO AUDIO FLOW] Intro voice failed:', error);
      });
    } catch (error) {
      this.intro.voiceMissing = true;
      console.warn('[INTRO AUDIO FLOW] Cannot play intro voice:', error);
    }
  };

  GameApp.prototype.stopIntroVoiceOnly = function () {
    const voice = this.intro && this.intro.voice;
    if (!voice) return;
    try {
      voice.pause();
      voice.currentTime = 0;
    } catch (error) {}
    this.intro.voiceStarted = false;
  };

  GameApp.prototype.stopIntroVoice = function () {
    this.stopIntroVoiceOnly();
  };

  GameApp.prototype.stopIntroMusic = function () {
    this.stopIntroVoiceOnly();
    this.stopIntroBackgroundMusic();
  };

  GameApp.prototype.startIntro = function () {
    if (!this.intro) return;

    ensureIntroMusic(this);
    installIntroVoiceEndHold(this);
    AudioManager.stopMusic();

    this.intro.time = 0;
    this.intro.firstRun = !this.hasSeenIntro || !this.hasSeenIntro();
    this.intro.fastForward = false;
    this.intro.skipRequested = false;
    this.intro.skipElapsed = 0;
    this.intro.voiceSkipped = false;
    this.intro.finalNaturalFinishActive = false;
    this.intro.finalHoldActive = false;
    this.intro.finalHoldRemaining = 0;
    this.intro.finalFadeActive = false;
    this.intro.finalFadeElapsed = 0;
    this.intro.readyToContinue = false;
    this.intro.buttonFadeElapsed = 0;
    this.intro.readerScroll = 0;
    this.intro.lastTypedCursor = 0;
    this.intro.lastTypeSoundAt = 0;
    this.intro.voiceStarted = false;

    if (this.intro.typewriterSound) this.intro.typewriterSound.load();
    if (this.intro.voice) this.intro.voice.load();
    if (this.intro.music) this.intro.music.load();
    if (this.bindIntroWheel) this.bindIntroWheel();

    this.setState('intro');
    this.playIntroBackgroundMusic();
    this.playIntroVoice();
  };

  GameApp.prototype.finishIntro = function () {
    if (this.markIntroSeen) this.markIntroSeen();
    this.stopIntroVoiceOnly();
    this.stopIntroBackgroundMusic();
    this.setState('campaignMap');
    this.ensureMenuMusic();
  };

  GameApp.prototype.getIntroVoiceProgress = function () {
    const voice = this.intro && this.intro.voice;
    if (!voice || this.intro.voiceMissing || this.intro.voiceSkipped || !this.intro.voiceStarted) return null;
    const duration = Number.isFinite(voice.duration) && voice.duration > 0 ? voice.duration : 0;
    if (!duration || !Number.isFinite(voice.currentTime)) return null;
    return Math.max(0, Math.min(1, voice.currentTime / duration));
  };

  GameApp.prototype.requestIntroSkip = function () {
    if (!this.intro || this.intro.readyToContinue) return;
    this.stopIntroVoiceOnly();
    this.intro.voiceSkipped = true;
    this.intro.fastForward = true;
    this.intro.skipRequested = true;
    this.intro.skipElapsed = 0;
    this.intro.finalNaturalFinishActive = false;
    this.intro.finalHoldActive = false;
    this.intro.finalHoldRemaining = 0;
    this.intro.finalFadeActive = false;
    this.intro.finalFadeElapsed = 0;
    this.intro.buttonFadeElapsed = 0;
    this.intro.lastTypedCursor = Number.MAX_SAFE_INTEGER;
  };

  const originalGeneratedTypeClick = GameApp.prototype.playGeneratedIntroTypeClick;
  GameApp.prototype.playGeneratedIntroTypeClick = function () {
    if (this.intro && this.intro.fastForward) return;

    try {
      const AudioCtor = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtor) return;
      if (!this.intro.audioContext) this.intro.audioContext = new AudioCtor();
      const audioCtx = this.intro.audioContext;
      AudioManager.registerAudioContext(audioCtx);
      if (audioCtx.state === 'suspended') audioCtx.resume().catch(() => {});

      const t = audioCtx.currentTime;
      const oscillator = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      const filter = audioCtx.createBiquadFilter();

      oscillator.type = 'square';
      oscillator.frequency.value = 760 + Math.random() * 180;
      filter.type = 'highpass';
      filter.frequency.value = 480;
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.032, t + 0.006);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.075);

      oscillator.connect(filter);
      filter.connect(gain);
      gain.connect(audioCtx.destination);
      oscillator.start(t);
      oscillator.stop(t + 0.08);
    } catch (error) {
      if (originalGeneratedTypeClick) originalGeneratedTypeClick.call(this);
    }
  };

  GameApp.prototype.playIntroTypeClick = function (typedCursor) {
    if (!this.intro || this.intro.fastForward) return;
    if (!typedCursor || typedCursor <= this.intro.lastTypedCursor) return;
    if (typedCursor % TYPE_CLICK_EVERY_CHARS !== 0) {
      this.intro.lastTypedCursor = typedCursor;
      return;
    }
    if (AudioManager.isSfxOn && !AudioManager.isSfxOn()) {
      this.intro.lastTypedCursor = typedCursor;
      return;
    }

    const now = performance.now();
    if (now - this.intro.lastTypeSoundAt < TYPE_CLICK_MIN_INTERVAL_MS) {
      this.intro.lastTypedCursor = typedCursor;
      return;
    }

    const realSound = this.intro.typewriterSound;
    if (realSound && !this.intro.typewriterSoundMissing) {
      try {
        const click = realSound.cloneNode(true);
        click.volume = 0.22;
        click.currentTime = 0;
        AudioManager.registerExternalAudio(click, { owner: 'intro', channel: 'sfx', resume: false });
        click.play().catch(() => {
          this.intro.typewriterSoundMissing = true;
          this.playGeneratedIntroTypeClick();
        });
      } catch (error) {
        this.intro.typewriterSoundMissing = true;
        this.playGeneratedIntroTypeClick();
      }
    } else {
      this.playGeneratedIntroTypeClick();
    }

    this.intro.lastTypeSoundAt = now;
    this.intro.lastTypedCursor = typedCursor;
  };

  GameApp.prototype.updateIntro = function (dt) {
    if (!this.intro) return;

    const click = Input.consumePointer();
    const anyKey = Input.consumeAnyKey();
    const requestedAction = !!(click || anyKey);

    this.syncIntroAudioVolumes();

    if (click && this.handleSpeakerClick(click)) return;

    if (this.intro.finalNaturalFinishActive) {
      this.intro.readyToContinue = false;
      this.intro.time = Math.min(this.intro.totalTimelineDuration || this.intro.time, this.intro.time + dt / 1000);
      if (this.intro.totalTimelineDuration > 0 && this.intro.time >= this.intro.totalTimelineDuration) {
        this.intro.finalNaturalFinishActive = false;
        this.intro.finalHoldActive = true;
        this.intro.finalHoldRemaining = INTRO_END_TEXT_HOLD_SECONDS;
      }
      return;
    }

    if (this.intro.finalHoldActive) {
      this.intro.readyToContinue = false;
      this.intro.time = this.intro.totalTimelineDuration || this.intro.time;
      this.intro.finalHoldRemaining -= dt / 1000;
      if (this.intro.finalHoldRemaining <= 0) {
        this.intro.finalHoldActive = false;
        this.intro.finalFadeActive = true;
        this.intro.finalFadeElapsed = 0;
      }
      return;
    }

    if (this.intro.finalFadeActive) {
      this.intro.readyToContinue = false;
      this.intro.time = this.intro.totalTimelineDuration || this.intro.time;
      this.intro.finalFadeElapsed += dt / 1000;
      if (this.intro.finalFadeElapsed >= INTRO_TEXT_FADE_SECONDS) {
        this.intro.finalFadeActive = false;
        this.intro.readyToContinue = true;
        this.intro.buttonFadeElapsed = 0;
        this.intro.readerScroll = 0;
      }
      return;
    }

    if (this.intro.readyToContinue) {
      this.intro.buttonFadeElapsed = Math.min(INTRO_BUTTON_FADE_SECONDS, (this.intro.buttonFadeElapsed || 0) + dt / 1000);
      if (click && pointInRect(click, getStartButtonRect())) {
        this.finishIntro();
        return;
      }

      if (Input.consume('enter') || Input.consume('space')) this.finishIntro();
      return;
    }

    if (requestedAction) this.requestIntroSkip();

    const voiceProgress = this.getIntroVoiceProgress();
    if (voiceProgress != null && this.intro.totalTimelineDuration > 0) {
      this.intro.time = mapVoiceProgressToTextTime(voiceProgress, this.intro.totalTimelineDuration);
      return;
    }

    if (this.intro.skipRequested && this.intro.totalTimelineDuration > 0) {
      this.intro.skipElapsed += dt / 1000;
      const remaining = Math.max(0, this.intro.totalTimelineDuration - this.intro.time);
      const step = Math.max(remaining / Math.max(0.01, INTRO_SKIP_REVEAL_SECONDS), this.intro.totalTimelineDuration * 0.5);
      this.intro.time = Math.min(this.intro.totalTimelineDuration, this.intro.time + step * (dt / 1000));
      if (this.intro.time >= this.intro.totalTimelineDuration) {
        this.intro.readyToContinue = true;
        this.intro.buttonFadeElapsed = 0;
        this.intro.readerScroll = 0;
      }
      return;
    }

    this.intro.time += dt / 1000;
  };

  GameApp.prototype.drawIntroStartButton = function (ctx, alpha) {
    if (alpha <= 0) return;

    const btn = getStartButtonRect();
    const pulse = 0.35 + 0.65 * Math.abs(Math.sin(performance.now() / 330));
    const centerX = btn.x + btn.w / 2;
    const centerY = btn.y + btn.h / 2;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = 'rgba(120, 0, 0, 0.88)';
    ctx.fillRect(btn.x, btn.y, btn.w, btn.h);
    ctx.strokeStyle = `rgba(255,255,255,${0.55 + pulse * 0.45})`;
    ctx.lineWidth = 3 + pulse * 2;
    ctx.strokeRect(btn.x, btn.y, btn.w, btn.h);

    ctx.font = 'bold 26px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#ffffff';
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 5;
    ctx.strokeText('НАЧАТЬ', centerX, centerY);
    ctx.fillText('НАЧАТЬ', centerX, centerY);
    ctx.restore();
  };

  GameApp.prototype.drawFinalIntroText = function (ctx, lines, alpha) {
    if (alpha <= 0) return;

    const lastIndex = Math.max(0, lines.length - 1);
    const maxWidth = GAME_CONFIG.width - 300;

    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.rect(INTRO_TYPE_X, INTRO_CLIP_TOP, maxWidth, INTRO_CLIP_BOTTOM - INTRO_CLIP_TOP);
    ctx.clip();

    ctx.font = 'bold 25px Arial';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.shadowColor = '#000';
    ctx.shadowBlur = 8;
    ctx.lineWidth = 5;
    ctx.strokeStyle = '#000';
    ctx.fillStyle = '#f4f4f4';

    for (let i = 0; i < lines.length; i++) {
      const y = INTRO_TYPE_Y - (lastIndex - i) * INTRO_LINE_HEIGHT;
      if (y < INTRO_CLIP_TOP - INTRO_LINE_HEIGHT || y > INTRO_CLIP_BOTTOM) continue;
      ctx.strokeText(lines[i], INTRO_TYPE_X, y);
      ctx.fillText(lines[i], INTRO_TYPE_X, y);
    }

    ctx.restore();
  };

  GameApp.prototype.drawIntroReader = function (ctx, lines, maxWidth) {
    const isFinalOnly = this.intro.finalNaturalFinishActive || this.intro.finalHoldActive || this.intro.finalFadeActive;

    if (isFinalOnly) {
      this.drawFinalIntroText(ctx, lines, getIntroEndFadeAlpha(this));
      return;
    }

    this.drawIntroStartButton(ctx, getIntroButtonAlpha(this));
  };

  const originalHandleSpeakerClick = GameApp.prototype.handleSpeakerClick;
  GameApp.prototype.handleSpeakerClick = function (point) {
    if (!point || this.state === 'splash' || this.state === 'loading') return false;

    const rect = this.getSpeakerHitRect ? this.getSpeakerHitRect() : this.getSpeakerRect();
    if (!rect || point.x < rect.x || point.x > rect.x + rect.w || point.y < rect.y || point.y > rect.y + rect.h) return false;

    AudioManager.unlock();
    const musicOn = AudioManager.toggleMusic();

    if (this.state === 'intro') {
      this.syncIntroAudioVolumes();
      if (musicOn) {
        if (this.intro.music && this.intro.music.paused) this.intro.music.play().catch(() => {});
        if (this.intro.voice && !this.intro.voiceSkipped && this.intro.voice.paused && !this.intro.readyToContinue) {
          this.intro.voice.play().catch(() => {});
        }
      }
      AudioManager.playSfx('menuSelect', 0.7);
      return true;
    }

    if (originalHandleSpeakerClick) return originalHandleSpeakerClick.call(this, point);
    return false;
  };
})();



/* ===== src/pauseMenuPatch.js ===== */
(function () {
  if (typeof GameApp === 'undefined') return;

  const PAUSE_ITEMS = ['resume', 'switchHero', 'bestiary', 'developer', 'menu'];
  const GOIDA_SFX = {
    z: { key: 'hotkeyZ', src: 'assets/sounds/Z.mp3' },
    x: { key: 'hotkeyX', src: 'assets/sounds/X.mp3' }
  };

  function pauseRect() {
    return { x: 14, y: 16, w: 88, h: 52 };
  }

  function resumeRect() {
    return { x: 390, y: 148, w: 500, h: 62 };
  }

  function switchHeroRect() {
    return { x: 390, y: 222, w: 500, h: 62 };
  }

  function bestiaryRect() {
    return { x: 390, y: 296, w: 500, h: 62 };
  }

  function developerRect() {
    return { x: 390, y: 370, w: 500, h: 62 };
  }

  function menuRect() {
    return { x: 390, y: 444, w: 500, h: 62 };
  }

  function getPauseItemRects() {
    return [
      { key: 'resume', label: 'ПРОДОЛЖИТЬ', rect: resumeRect(), fontSize: 30 },
      { key: 'switchHero', label: 'СМЕНИТЬ ПЕРСОНАЖА', rect: switchHeroRect(), fontSize: 28 },
      { key: 'bestiary', label: 'ТВАРИ', rect: bestiaryRect(), fontSize: 28 },
      { key: 'developer', label: 'РЕЖИМ РАЗРАБОТЧИКА', rect: developerRect(), fontSize: 25 },
      { key: 'menu', label: 'В МЕНЮ', rect: menuRect(), fontSize: 30 }
    ];
  }

  function inRect(p, r) {
    return p && p.x >= r.x && p.x <= r.x + r.w && p.y >= r.y && p.y <= r.y + r.h;
  }

  function drawButton(ctx, r, label, active, fontSize) {
    ctx.save();
    ctx.fillStyle = active ? 'rgba(130,0,0,0.86)' : 'rgba(0,0,0,0.58)';
    ctx.strokeStyle = active ? '#ffffff' : 'rgba(255,255,255,0.70)';
    ctx.lineWidth = active ? 5 : 3;
    ctx.fillRect(r.x, r.y, r.w, r.h);
    ctx.strokeRect(r.x, r.y, r.w, r.h);

    if (active) {
      ctx.fillStyle = 'rgba(255,255,255,0.9)';
      ctx.font = 'bold 28px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('▶', r.x + 34, r.y + r.h / 2 + 1);
    }

    ctx.font = 'bold ' + (fontSize || 30) + 'px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 5;
    ctx.strokeText(label, r.x + r.w / 2, r.y + r.h / 2 + 2);
    ctx.fillText(label, r.x + r.w / 2, r.y + r.h / 2 + 2);
    ctx.restore();
  }

  function ensurePauseSelection(game) {
    if (!Number.isFinite(game.pauseSelection)) game.pauseSelection = 0;
    game.pauseSelection = Math.max(0, Math.min(PAUSE_ITEMS.length - 1, game.pauseSelection));
  }

  function setPaused(game, paused) {
    game.paused = paused;
    if (paused) game.pauseSelection = 0;
  }

  function startQuickHeroSwitch(game) {
    if (!game || !game.scene || !game.scene.player) return;
    const player = game.scene.player;
    game.paused = false;
    game.casualtyRespawn = {
      screenIndex: game.scene.screenIndex,
      x: Math.max(90, Math.min(GAME_CONFIG.width - 140, player.x)),
      y: Math.max(GAME_CONFIG.laneTop + 20, Math.min(GAME_CONFIG.laneBottom - 10, player.y)),
      facing: player.facing || 1
    };
    game.characterSelectMode = 'switchHero';
    if (typeof CharacterSelect !== 'undefined') {
      CharacterSelect.infoOpen = false;
      CharacterSelect.footerFocus = null;
      CharacterSelect.selectedIndex = CharacterSelect.heroes.indexOf(player.heroKey || game.selectedHero || 'boris');
      if (CharacterSelect.selectedIndex < 0) CharacterSelect.selectedIndex = 0;
    }
    game.setState('characterSelect');
    AudioManager.playSfx('menuSelect', 0.75);
  }

  function canQuickHeroSwitch(game) {
    if (!game || !game.scene || !game.scene.player) return false;
    const player = game.scene.player;
    if (player.hp <= 0 || player.dead) return false;
    const heroes = (typeof CharacterSelect !== 'undefined' && CharacterSelect.heroes) || Object.keys(GAME_CONFIG.heroes || {});
    return heroes.some((key) => key !== player.heroKey && !(game.defeatedHeroes && game.defeatedHeroes[key]));
  }

  function playGoidaSfx(game, buttonKey) {
    const sound = GOIDA_SFX[buttonKey];
    if (!sound || typeof AudioManager === 'undefined') return false;

    const now = performance.now();
    if (game.lastGoidaSfxAt && now - game.lastGoidaSfxAt < 450) return true;
    game.lastGoidaSfxAt = now;

    AudioManager.playOptionalSfx(sound.key, 1, {
      src: sound.src,
      startAt: 0.01
    });
    return true;
  }

  function openDeveloperPanel(game) {
    if (typeof DevPanel === 'undefined') return;
    setPaused(game, false);
    GAME_CONFIG.adminTuningEnabled = true;

    if (typeof DevPanel.openFromPauseMenu === 'function') {
      DevPanel.openFromPauseMenu(game);
    } else {
      DevPanel.open = true;
      DevPanel.tab = 'LEVEL WAVES';
      if (typeof DevPanel.ensureLevels === 'function') DevPanel.ensureLevels();
      if (typeof DevPanel.syncSelectedLevelWithScene === 'function') DevPanel.syncSelectedLevelWithScene(game);
    }

    AudioManager.playSfx('menuSelect', 0.65);
  }

  function activatePauseItem(game, key) {
    if (key === 'resume') {
      setPaused(game, false);
      AudioManager.playSfx('menuSelect', 0.65);
      return;
    }
    if (key === 'switchHero') {
      startQuickHeroSwitch(game);
      return;
    }
    if (key === 'bestiary') {
      setPaused(game, false);
      if (game.openBestiary) game.openBestiary('level');
      return;
    }
    if (key === 'developer') {
      openDeveloperPanel(game);
      return;
    }
    if (key === 'menu') {
      setPaused(game, false);
      game.setState('mainMenu');
      AudioManager.playSfx('menuSelect', 0.65);
    }
  }

  const originalUpdate = GameApp.prototype.update;
  GameApp.prototype.update = function (dt) {
    if (this.state === 'level') {
      if (Input.consume('escape')) {
        setPaused(this, !this.paused);
        AudioManager.playSfx('menuSelect', 0.65);
        return;
      }

      if (this.paused) {
        ensurePauseSelection(this);

        if (Input.consume('arrowup') || Input.consume('w')) {
          this.pauseSelection = (this.pauseSelection + PAUSE_ITEMS.length - 1) % PAUSE_ITEMS.length;
          AudioManager.playSfx('menuMove', 0.7);
          return;
        }

        if (Input.consume('arrowdown') || Input.consume('s')) {
          this.pauseSelection = (this.pauseSelection + 1) % PAUSE_ITEMS.length;
          AudioManager.playSfx('menuMove', 0.7);
          return;
        }

        if (Input.consume('enter') || Input.consume('space')) {
          activatePauseItem(this, PAUSE_ITEMS[this.pauseSelection]);
          return;
        }
      }

      const click = Input.consumePointer();
      if (click) {
        if (inRect(click, pauseRect())) {
          setPaused(this, !this.paused);
          AudioManager.playSfx('menuSelect', 0.65);
          return;
        }

        if (this.paused) {
          const items = getPauseItemRects();
          for (let i = 0; i < items.length; i++) {
            if (!inRect(click, items[i].rect)) continue;
            this.pauseSelection = i;
            activatePauseItem(this, items[i].key);
            return;
          }
        }

        Input.restorePointer(click);
      }

      if (this.paused) return;

      if (Input.consume('c') && canQuickHeroSwitch(this)) {
        startQuickHeroSwitch(this);
        return;
      }

      if (Input.consume('z')) {
        playGoidaSfx(this, 'z');
        return;
      }

      if (Input.consume('x')) {
        playGoidaSfx(this, 'x');
        return;
      }
    }

    originalUpdate.call(this, dt);
  };

  const originalDraw = GameApp.prototype.draw;
  GameApp.prototype.draw = function () {
    originalDraw.call(this);
    if (this.state !== 'level') return;

    const ctx = this.ctx;
    drawButton(ctx, pauseRect(), 'MENU', false, 18);

    if (!this.paused) return;
    ensurePauseSelection(this);

    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,0.58)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.font = 'bold 46px Arial';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 7;
    ctx.strokeText('ПАУЗА', GAME_CONFIG.width / 2, 148);
    ctx.fillText('ПАУЗА', GAME_CONFIG.width / 2, 148);
    ctx.font = '18px Arial';
    ctx.fillStyle = 'rgba(255,255,255,0.72)';
    ctx.fillText('↑/↓ — выбор   Enter/Space — подтвердить   Esc — назад', GAME_CONFIG.width / 2, 540);
    ctx.restore();

    const items = getPauseItemRects();
    for (let i = 0; i < items.length; i++) {
      drawButton(ctx, items[i].rect, items[i].label, i === this.pauseSelection, items[i].fontSize);
    }
  };
})();



/* ===== src/desktopUXPatch.js ===== */
(function () {
  if (typeof GAME_CONFIG !== 'undefined') {
    GAME_CONFIG.adminTuningEnabled = /devpanel=1/.test(window.location.search);
  }

  function inRect(point, rect) {
    return point && point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h;
  }

  function drawButton(ctx, rect, text, active, fontSize) {
    ctx.save();
    ctx.fillStyle = active ? 'rgba(255,255,255,0.16)' : 'rgba(0,0,0,0.50)';
    ctx.strokeStyle = active ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.62)';
    ctx.lineWidth = active ? 4 : 2;
    ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
    ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
    ctx.font = 'bold ' + (fontSize || 24) + 'px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 4;
    ctx.strokeText(text, rect.x + rect.w / 2, rect.y + rect.h / 2 + 1);
    ctx.fillText(text, rect.x + rect.w / 2, rect.y + rect.h / 2 + 1);
    ctx.restore();
  }

  if (typeof Menu !== 'undefined') {
    const originalMenuUpdate = Menu.update;
    Menu.update = function (game) {
      const pointer = Input.pointer;
      if (!Responsive.isTouchDevice && pointer) {
        for (let i = 0; i < this.items.length; i++) {
          const box = this.getItemBox(i);
          if (inRect(pointer, box)) {
            if (this.selectedIndex !== i) this.selectedIndex = i;
            break;
          }
        }
      }
      originalMenuUpdate.call(this, game);
    };
  }

  if (typeof CharacterSelect !== 'undefined') {
    CharacterSelect.drawTitle = function (ctx, text, y) {
      ctx.font = 'bold 34px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'alphabetic';
      ctx.fillStyle = '#fff';
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 5;
      ctx.strokeText(text, GAME_CONFIG.width / 2, 104);
      ctx.fillText(text, GAME_CONFIG.width / 2, 104);
      ctx.textAlign = 'left';
    };
  }

  if (typeof CampaignMapScreen !== 'undefined') {
    CampaignMapScreen.update = function (game, dt) {
      const click = Input.consumePointer();
      if (Input.consume('escape')) {
        game.setState('mainMenu');
        return;
      }

      const startButton = this.getDesktopStartButton();
      if (Input.consume('enter') || Input.consume('space') || inRect(click, startButton)) {
        AudioManager.unlock();
        AudioManager.playSfx('menuSelect', 0.85);
        game.setState('characterSelect');
        return;
      }
    };

    CampaignMapScreen.getDesktopPanelRect = function () {
      return { x: 70, y: GAME_CONFIG.height - 128, w: GAME_CONFIG.width - 140, h: 92 };
    };

    CampaignMapScreen.getDesktopStartButton = function () {
      const panel = this.getDesktopPanelRect();
      return { x: panel.x + panel.w - 250, y: panel.y + 24, w: 200, h: 44 };
    };

    CampaignMapScreen.drawPanel = function (ctx, activeId) {
      const panel = this.getDesktopPanelRect();
      const completedCount = this.activeIndex;
      const total = this.order.length;
      const label = this.labels[activeId] || '';
      const start = this.getDesktopStartButton();

      ctx.fillStyle = 'rgba(0, 8, 22, 0.72)';
      ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
      ctx.strokeStyle = 'rgba(60, 220, 255, 0.78)';
      ctx.lineWidth = 2;
      ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);

      ctx.textAlign = 'left';
      ctx.textBaseline = 'alphabetic';
      ctx.fillStyle = '#dff8ff';
      ctx.strokeStyle = '#001019';
      ctx.lineWidth = 4;
      ctx.font = 'bold 22px Arial';
      ctx.strokeText('КАРТА СОПРОТИВЛЕНИЯ', panel.x + 26, panel.y + 31);
      ctx.fillText('КАРТА СОПРОТИВЛЕНИЯ', panel.x + 26, panel.y + 31);

      ctx.font = 'bold 24px Arial';
      ctx.fillStyle = '#fff';
      ctx.strokeText(label, panel.x + 26, panel.y + 64);
      ctx.fillText(label, panel.x + 26, panel.y + 64);

      const barW = 230;
      const barH = 16;
      const barX = start.x - barW - 42;
      const barY = panel.y + 34;
      ctx.fillStyle = 'rgba(255,255,255,0.12)';
      ctx.fillRect(barX, barY, barW, barH);
      ctx.fillStyle = '#c8f7ff';
      ctx.fillRect(barX, barY, barW * (completedCount / Math.max(1, total)), barH);
      ctx.strokeStyle = 'rgba(255,255,255,0.55)';
      ctx.strokeRect(barX, barY, barW, barH);

      ctx.font = 'bold 16px Arial';
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText('ПРОГРЕСС ' + completedCount + ' / ' + total, barX + barW / 2, barY + 42);

      drawButton(ctx, start, 'НАЧАТЬ', true, 21);
      ctx.textAlign = 'left';
    };
  }

  if (typeof HUD !== 'undefined') {
    HUD.getLevelProgress = function (scene) {
      const total = scene.images && scene.images.streets ? scene.images.streets.length : 1;
      const local = scene.encounterCleared ? 1 : 0.35;
      return Math.max(0, Math.min(1, (scene.screenIndex + local) / Math.max(1, total)));
    };

    HUD.draw = function (ctx, scene) {
      ctx.fillStyle = 'rgba(0,0,0,0.62)';
      ctx.fillRect(0, 0, GAME_CONFIG.width, 86);

      const menuBox = { x: 14, y: 16, w: 88, h: 52 };
      drawButton(ctx, menuBox, 'MENU', false, 18);

      const order = ['alexey', 'anna', 'boris'];
      for (let i = 0; i < order.length; i++) {
        const key = order[i];
        const hero = GAME_CONFIG.heroes[key];
        const x = 122 + i * 190;
        const active = scene.player.heroKey === key;

        ctx.fillStyle = active ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.04)';
        ctx.fillRect(x, 12, 170, 60);

        ctx.fillStyle = hero.color;
        ctx.fillRect(x + 8, 18, 38, 38);
        ctx.fillStyle = '#111';
        ctx.font = 'bold 13px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(hero.name[0], x + 27, 43);
        ctx.textAlign = 'left';

        ctx.fillStyle = '#fff';
        ctx.font = 'bold 13px Arial';
        ctx.fillText(hero.name, x + 54, 28);

        const hp = active ? scene.player.hp : hero.hp;
        const pct = Math.max(0, hp / hero.hp);
        ctx.fillStyle = '#222';
        ctx.fillRect(x + 54, 38, 98, 12);
        ctx.fillStyle = pct > 0.55 ? 'lime' : pct > 0.25 ? 'yellow' : 'red';
        ctx.fillRect(x + 54, 38, 98 * pct, 12);
        ctx.strokeStyle = '#777';
        ctx.strokeRect(x + 54, 38, 98, 12);
      }

      if (this.drawSupportButtons) {
        this.drawSupportButtons(ctx, scene, 745, 22);
      }
      if (this.drawLowHpSwitchHint) {
        this.drawLowHpSwitchHint(ctx, scene);
      }
      if (this.drawSuckerPinHint) {
        this.drawSuckerPinHint(ctx, scene);
      }
    };
  }

  if (typeof GameApp !== 'undefined') {
    GameApp.prototype.getSpeakerRect = function () {
      return { x: GAME_CONFIG.width - 70, y: 16, w: 48, h: 48 };
    };

    GameApp.prototype.getSpeakerHitRect = function () {
      return { x: GAME_CONFIG.width - 96, y: 0, w: 96, h: 92 };
    };

    GameApp.prototype.handleSpeakerClick = function (point) {
      if (this.state === 'splash' || this.state === 'loading') return false;
      const r = this.getSpeakerHitRect ? this.getSpeakerHitRect() : this.getSpeakerRect();
      if (!inRect(point, r)) return false;
      AudioManager.unlock();
      if (AudioManager.toggleSound) AudioManager.toggleSound();
      else AudioManager.toggleMusic();
      if (this.state === 'intro' && this.syncIntroVoiceVolume) this.syncIntroVoiceVolume();
      AudioManager.playSfx('menuSelect', 0.7);
      return true;
    };

    GameApp.prototype.drawSpeaker = function (ctx) {
      if (this.state === 'splash' || this.state === 'loading') return;
      const r = this.getSpeakerRect();
      const on = AudioManager.isSoundOn ? AudioManager.isSoundOn() : GAME_CONFIG.settings.musicEnabled !== false;

      ctx.save();
      ctx.fillStyle = 'rgba(8, 8, 10, 0.68)';
      ctx.fillRect(r.x, r.y, r.w, r.h);
      ctx.strokeStyle = on ? 'rgba(255,255,255,0.88)' : 'rgba(255,65,65,0.96)';
      ctx.lineWidth = 2;
      ctx.strokeRect(r.x, r.y, r.w, r.h);

      ctx.fillStyle = on ? '#ffffff' : '#bdbdbd';
      ctx.beginPath();
      ctx.moveTo(r.x + 10, r.y + 22);
      ctx.lineTo(r.x + 19, r.y + 22);
      ctx.lineTo(r.x + 31, r.y + 12);
      ctx.lineTo(r.x + 31, r.y + 36);
      ctx.lineTo(r.x + 19, r.y + 26);
      ctx.lineTo(r.x + 10, r.y + 26);
      ctx.closePath();
      ctx.fill();

      if (on) {
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(r.x + 31, r.y + 24, 7, -0.75, 0.75); ctx.stroke();
        ctx.beginPath(); ctx.arc(r.x + 31, r.y + 24, 13, -0.65, 0.65); ctx.stroke();
      } else {
        ctx.strokeStyle = '#ff5555';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.moveTo(r.x + 11, r.y + 11);
        ctx.lineTo(r.x + 37, r.y + 37);
        ctx.moveTo(r.x + 37, r.y + 11);
        ctx.lineTo(r.x + 11, r.y + 37);
        ctx.stroke();
      }
      ctx.restore();
    };
  }
})();



/* ===== src/desktopRefinementPatch.js ===== */
(function () {
  function inRect(point, rect) {
    return point && point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h;
  }

  function drawButton(ctx, rect, text, active, fontSize) {
    ctx.save();
    ctx.fillStyle = active ? 'rgba(255,255,255,0.17)' : 'rgba(0,0,0,0.48)';
    ctx.strokeStyle = active ? 'rgba(255,255,255,0.96)' : 'rgba(255,255,255,0.62)';
    ctx.lineWidth = active ? 4 : 2;
    ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
    ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
    ctx.font = 'bold ' + (fontSize || 24) + 'px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 4;
    ctx.strokeText(text, rect.x + rect.w / 2, rect.y + rect.h / 2 + 1);
    ctx.fillText(text, rect.x + rect.w / 2, rect.y + rect.h / 2 + 1);
    ctx.restore();
  }

  if (typeof Menu !== 'undefined') {
    Menu.getSettingsControlRects = function (index) {
      const box = this.getSettingsBox(index);
      return {
        row: box,
        minus: { x: box.x - 74, y: box.y, w: 58, h: box.h },
        plus: { x: box.x + box.w + 16, y: box.y, w: 58, h: box.h }
      };
    };

    Menu.updateSettings = function (game) {
      if (Input.consume('escape')) {
        AudioManager.playSfx('menuSelect', 0.75);
        game.setState('mainMenu');
        return;
      }
      if (Input.consume('arrowup') || Input.consume('w')) {
        this.settingsIndex = (this.settingsIndex + this.settingsItems.length - 1) % this.settingsItems.length;
        AudioManager.playSfx('menuMove', 0.75);
      }
      if (Input.consume('arrowdown') || Input.consume('s')) {
        this.settingsIndex = (this.settingsIndex + 1) % this.settingsItems.length;
        AudioManager.playSfx('menuMove', 0.75);
      }
      if (Input.consume('arrowleft') || Input.consume('a')) this.changeSetting(this.settingsIndex, game, -1);
      if (Input.consume('arrowright') || Input.consume('d')) this.changeSetting(this.settingsIndex, game, 1);

      const click = Input.consumePointer();
      if (click) {
        AudioManager.unlock();
        for (let i = 0; i < this.settingsItems.length; i++) {
          const item = this.settingsItems[i];
          const r = this.getSettingsControlRects(i);
          if (inRect(click, r.minus)) {
            this.settingsIndex = i;
            this.changeSetting(i, game, -1);
            return;
          }
          if (inRect(click, r.plus)) {
            this.settingsIndex = i;
            this.changeSetting(i, game, 1);
            return;
          }
          if (inRect(click, r.row)) {
            this.settingsIndex = i;
            if (item === 'НАЗАД') this.changeSetting(i, game, 1);
            return;
          }
        }
      }

      if (Input.consume('enter') || Input.consume('space')) {
        AudioManager.unlock();
        this.changeSetting(this.settingsIndex, game, 1);
      }
    };

    Menu.drawSettings = function (ctx, images) {
      ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      ctx.fillStyle = 'rgba(0, 0, 0, 0.65)';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

      ctx.font = 'bold 42px Arial';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#fff';
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 5;
      ctx.strokeText('НАСТРОЙКИ', GAME_CONFIG.width / 2, 135);
      ctx.fillText('НАСТРОЙКИ', GAME_CONFIG.width / 2, 135);

      for (let i = 0; i < this.settingsItems.length; i++) {
        const box = this.getSettingsBox(i);
        const r = this.getSettingsControlRects(i);
        const active = i === this.settingsIndex;
        const item = this.settingsItems[i];
        const label = this.getSettingsLabel(i);
        drawButton(ctx, box, label, active, 24);
        if (item !== 'НАЗАД') {
          drawButton(ctx, r.minus, '−', false, 32);
          drawButton(ctx, r.plus, '+', false, 32);
        }
      }

      ctx.font = '18px Arial';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#ddd';
      ctx.fillText('W/S или ↑/↓ — выбрать строку. A/D или ←/→ — изменить. Enter — подтвердить.', GAME_CONFIG.width / 2, 660);
      ctx.textAlign = 'left';
    };
  }

  if (typeof CharacterSelect !== 'undefined') {
    CharacterSelect.getConfirmBox = function () {
      return { x: 720, y: 628, w: 180, h: 46 };
    };

    CharacterSelect.getBackBox = function () {
      return { x: 390, y: 628, w: 180, h: 46 };
    };

    const originalMoveFooterFocus = CharacterSelect.moveFooterFocus;
    CharacterSelect.moveFooterFocus = function (direction) {
      this.footerFocus = this.footerFocus === 'back' ? 'confirm' : 'back';
      AudioManager.playSfx('menuMove', 0.7, { playbackRate: direction < 0 ? 0.95 : 1.05 });
    };

    const originalDraw = CharacterSelect.draw;
    CharacterSelect.draw = function (ctx, images) {
      ctx.fillStyle = '#08080d';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      ctx.fillStyle = 'rgba(0,0,0,0.58)';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

      this.drawTitle(ctx, 'ВЫБЕРИТЕ ПЕРСОНАЖА', 104);

      for (let i = 0; i < this.heroes.length; i++) {
        this.drawCard(ctx, images, this.heroes[i], i, i === this.selectedIndex && !this.footerFocus);
      }

      const back = this.getBackBox();
      const confirm = this.getConfirmBox();
      this.drawButton(ctx, back.x, back.y, back.w, back.h, 'НАЗАД', this.footerFocus === 'back');
      this.drawButton(ctx, confirm.x, confirm.y, confirm.w, confirm.h, 'ДАЛЕЕ', this.footerFocus === 'confirm' || !this.footerFocus);

      ctx.font = '18px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'alphabetic';
      ctx.fillStyle = 'rgba(255,255,255,0.72)';
      ctx.fillText('←/→ или A/D — выбрать   ↑/↓ или W/S — кнопки   Enter — подтвердить   I — информация', GAME_CONFIG.width / 2, 704);
      ctx.textAlign = 'left';

      if (this.infoOpen) this.drawInfoModal(ctx, images);
    };
  }

  if (typeof GameApp !== 'undefined') {
    const previousUpdateIntro = GameApp.prototype.updateIntro;
    GameApp.prototype.updateIntro = function (dt) {
      if (this.intro && this.intro.readyToContinue) {
        const click = Input.consumePointer();
        this.syncIntroAudioVolumes && this.syncIntroAudioVolumes();
        if (click && this.handleSpeakerClick(click)) return;

        const start = { x: GAME_CONFIG.width / 2 - 130, y: GAME_CONFIG.height - 86, w: 260, h: 52 };
        if (click && inRect(click, start)) {
          this.finishIntro();
          return;
        }

        if (Input.consume('arrowup') || Input.consume('w')) this.scrollIntroReader && this.scrollIntroReader(-1);
        if (Input.consume('arrowdown') || Input.consume('s')) this.scrollIntroReader && this.scrollIntroReader(1);
        if (Input.consume('pageup')) this.scrollIntroReader && this.scrollIntroReader(-4);
        if (Input.consume('pagedown')) this.scrollIntroReader && this.scrollIntroReader(4);
        if (Input.consume('enter') || Input.consume('space')) this.finishIntro();
        return;
      }

      previousUpdateIntro.call(this, dt);
    };

    GameApp.prototype.drawIntroReader = function (ctx, lines, maxWidth) {
      if (!this.intro || !this.intro.readyToContinue) {
        if (this.drawIntroStartButton) this.drawIntroStartButton(ctx, 0);
        return;
      }

      const panelX = 150;
      const panelY = 88;
      const panelW = GAME_CONFIG.width - 300;
      const panelH = GAME_CONFIG.height - 190;
      const lineHeight = 32;

      this.intro.layoutLines = lines;

      ctx.fillStyle = 'rgba(0, 0, 0, 0.66)';
      ctx.fillRect(panelX - 20, panelY - 20, panelW + 40, panelH + 40);
      ctx.strokeStyle = 'rgba(255,255,255,0.58)';
      ctx.lineWidth = 2;
      ctx.strokeRect(panelX - 20, panelY - 20, panelW + 40, panelH + 40);

      ctx.save();
      ctx.beginPath();
      ctx.rect(panelX, panelY, panelW, panelH);
      ctx.clip();
      ctx.font = 'bold 24px Arial';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.shadowColor = '#000';
      ctx.shadowBlur = 8;
      ctx.lineWidth = 5;
      ctx.strokeStyle = '#000';
      ctx.fillStyle = '#f4f4f4';

      for (let i = 0; i < lines.length; i++) {
        const y = panelY + i * lineHeight - (this.intro.readerScroll || 0);
        if (y < panelY - lineHeight || y > panelY + panelH) continue;
        ctx.strokeText(lines[i], panelX, y);
        ctx.fillText(lines[i], panelX, y);
      }
      ctx.restore();

      const totalHeight = lines.length * lineHeight;
      const maxScroll = Math.max(0, totalHeight - panelH);
      if (maxScroll > 0) {
        const barX = panelX + panelW + 16;
        const barY = panelY;
        const barH = panelH;
        const thumbH = Math.max(40, barH * (panelH / totalHeight));
        const thumbY = barY + (barH - thumbH) * ((this.intro.readerScroll || 0) / maxScroll);
        ctx.fillStyle = 'rgba(255,255,255,0.18)';
        ctx.fillRect(barX, barY, 6, barH);
        ctx.fillStyle = 'rgba(255,255,255,0.75)';
        ctx.fillRect(barX, thumbY, 6, thumbH);
      }

      const btn = { x: GAME_CONFIG.width / 2 - 130, y: GAME_CONFIG.height - 86, w: 260, h: 52 };
      drawButton(ctx, btn, 'НАЧАТЬ', true, 28);

      ctx.font = 'bold 17px Arial';
      ctx.textAlign = 'right';
      ctx.fillStyle = 'rgba(255,255,255,0.72)';
      ctx.fillText('Колесо мыши / ↑↓ — читать текст', GAME_CONFIG.width - 34, GAME_CONFIG.height - 18);
      ctx.textAlign = 'left';
    };
  }

  if (typeof HUD !== 'undefined') {
    const previousDraw = HUD.draw;
    HUD.draw = function (ctx, scene) {
      previousDraw.call(this, ctx, scene);
    };
  }
})();



/* ===== src/exitArrowPatch.js ===== */
(function () {
  if (typeof LevelScene === 'undefined') return;

  const HERO_ORDER = ['alexey', 'anna', 'boris'];

  function arrowPolygon(x, y, w, h) {
    const head = w * 0.24;
    return [
      [x, y], [x + w - head, y], [x + w - head, y - h * 0.18],
      [x + w, y + h / 2], [x + w - head, y + h + h * 0.18],
      [x + w - head, y + h], [x, y + h]
    ];
  }

  function drawPolygon(ctx, points) {
    ctx.beginPath();
    points.forEach(([px, py], i) => i ? ctx.lineTo(px, py) : ctx.moveTo(px, py));
    ctx.closePath();
  }

  function pointInPolygon(px, py, points) {
    let inside = false;
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
      const xi = points[i][0];
      const yi = points[i][1];
      const xj = points[j][0];
      const yj = points[j][1];
      const intersect = ((yi > py) !== (yj > py)) &&
        (px < (xj - xi) * (py - yi) / ((yj - yi) || 0.0001) + xi);
      if (intersect) inside = !inside;
    }
    return inside;
  }

  function drawLedDot(ctx, x, y, r, color, glow, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.shadowColor = glow;
    ctx.shadowBlur = 4;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function drawExitLedArrow(ctx, x, y, phase) {
    const w = 90;
    const h = 32;
    const poly = arrowPolygon(x, y, w, h);
    const pulse = 0.5 + 0.5 * Math.sin(phase);

    ctx.save();
    ctx.shadowColor = 'rgba(80, 160, 255, 0.95)';
    ctx.shadowBlur = 8 + pulse * 6;
    ctx.fillStyle = 'rgba(30, 90, 190, 0.20)';
    drawPolygon(ctx, poly);
    ctx.fill();

    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(11, 13, 18, 0.92)';
    ctx.strokeStyle = 'rgba(215, 225, 240, 0.92)';
    ctx.lineWidth = 1.5;
    drawPolygon(ctx, poly);
    ctx.fill();
    ctx.stroke();

    const innerPad = 4;
    const innerPoly = arrowPolygon(x + innerPad, y + innerPad, w - innerPad * 2, h - innerPad * 2);
    ctx.fillStyle = 'rgba(2, 5, 9, 0.78)';
    ctx.strokeStyle = 'rgba(70, 82, 96, 0.92)';
    ctx.lineWidth = 1;
    drawPolygon(ctx, innerPoly);
    ctx.fill();
    ctx.stroke();

    const rows = 6;
    const cols = 18;
    const dotR = 1.75;
    const startX = x + innerPad + 6;
    const endX = x + w - innerPad - 7;
    const startY = y + innerPad + 4;
    const rowGap = (h - innerPad * 2 - 8) / Math.max(1, rows - 1);
    const colGap = (endX - startX) / Math.max(1, cols - 1);

    for (let row = 0; row < rows; row++) {
      let color = '#f7f8ff';
      let glow = 'rgba(245, 248, 255, 0.95)';
      if (row >= 2 && row <= 3) {
        color = '#0b74ff';
        glow = 'rgba(20, 145, 255, 1)';
      }
      for (let col = 0; col < cols; col++) {
        const cx = startX + col * colGap;
        const cy = startY + row * rowGap;
        if (!pointInPolygon(cx, cy, innerPoly)) continue;
        const wave = 0.76 + 0.24 * Math.sin(phase + col * 0.38 + row * 0.8);
        drawLedDot(ctx, cx, cy, dotR, color, glow, wave);
      }
    }

    ctx.shadowColor = 'rgba(70, 160, 255, 0.95)';
    ctx.shadowBlur = 4 + pulse * 4;
    ctx.strokeStyle = 'rgba(150, 210, 255, 0.92)';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(x + w - 18, y - 3);
    ctx.lineTo(x + w, y + h / 2);
    ctx.lineTo(x + w - 18, y + h + 3);
    ctx.stroke();
    ctx.restore();
  }

  function clampValue(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function drawLines(ctx, lines, x, y, lineHeight) {
    lines.forEach((line, index) => ctx.fillText(line, x, y + index * lineHeight));
  }

  LevelScene.prototype.nextScreen = function () {
    const order = GAME_CONFIG.levelOrder || [];
    const currentKey = order[this.screenIndex];
    const nextKey = order[this.screenIndex + 1];
    const currentLevel = currentKey && GAME_CONFIG.levels && GAME_CONFIG.levels[currentKey];
    const nextLevel = nextKey && GAME_CONFIG.levels && GAME_CONFIG.levels[nextKey];
    const currentRegion = currentLevel && (currentLevel.region || currentLevel.regionKey || currentLevel.area || currentLevel.chapter);
    const nextRegion = nextLevel && (nextLevel.region || nextLevel.regionKey || nextLevel.area || nextLevel.chapter);

    if (this.screenIndex < this.images.streets.length - 1 && currentRegion && nextRegion && currentRegion === nextRegion) {
      if (this.game && this.game.addPeopleSupport) this.game.addPeopleSupport(12);
      this.screenIndex += 1;
      this.player.x = 82;
      this.player.y = 620;
      this.player.facing = 1;
      this.player.releaseFromPin();
      const level = this.getLevelConfig();
      AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
      this.spawnInitialWave();
    } else {
      if (this.game && this.game.completeCampaignRegion) this.game.completeCampaignRegion();
      else this.game.setState('mainMenu');
    }
  };

  LevelScene.prototype.draw = function (ctx) {
    const bg = this.getLevelBackgroundImage
      ? this.getLevelBackgroundImage()
      : this.images.streets[this.screenIndex] || this.images.streets[0];
    if (bg) ctx.drawImage(bg, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    else {
      ctx.fillStyle = '#222';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    }
    if (this.drawLevelBackgroundEffects) this.drawLevelBackgroundEffects(ctx);

    ctx.fillStyle = 'rgba(255,255,255,0.025)';
    ctx.fillRect(0, GAME_CONFIG.laneTop, GAME_CONFIG.width, GAME_CONFIG.laneBottom - GAME_CONFIG.laneTop);
    if (this.drawLevelForegroundObjects) this.drawLevelForegroundObjects(ctx);

    const entities = [{ type: 'player', y: this.player.y, ref: this.player }];
    for (const enemy of this.enemies) entities.push({ type: 'enemy', y: enemy.y, ref: enemy });
    entities.sort((a, b) => a.y - b.y);
    for (const entity of entities) entity.ref.draw(ctx, this.debug);
    for (const pickup of this.pickups || []) {
      if (!pickup || pickup.remove || typeof pickup.draw !== 'function') continue;
      pickup.draw(ctx);
    }

    if (this.encounterCleared) {
      const phase = performance.now() / 260;
      drawExitLedArrow(ctx, GAME_CONFIG.width - 128, 388, phase);
    }

    HUD.draw(ctx, this);

    if (this.debug) {
      ctx.strokeStyle = 'rgba(255,255,255,0.25)';
      ctx.lineWidth = 2;
      ctx.strokeRect(0, GAME_CONFIG.laneTop, GAME_CONFIG.width, GAME_CONFIG.laneBottom - GAME_CONFIG.laneTop);
    }
  };

  if (typeof CharacterSelect !== 'undefined') {
    const originalDrawCard = CharacterSelect.drawCard;
    const originalDrawInfoIcon = CharacterSelect.drawInfoIcon;

    CharacterSelect.getGame = function () {
      return this.gameRef || null;
    };

    CharacterSelect.isHeroDisabled = function (game, heroKey) {
      return !!(game && game.defeatedHeroes && game.defeatedHeroes[heroKey]);
    };

    CharacterSelect.findFirstAvailableIndex = function (game) {
      for (let i = 0; i < this.heroes.length; i++) {
        if (!this.isHeroDisabled(game, this.heroes[i])) return i;
      }
      return 0;
    };

    CharacterSelect.moveSelection = function (direction, game) {
      const activeGame = game || this.getGame();
      for (let step = 0; step < this.heroes.length; step++) {
        this.selectedIndex = (this.selectedIndex + direction + this.heroes.length) % this.heroes.length;
        if (!this.isHeroDisabled(activeGame, this.heroes[this.selectedIndex])) break;
      }
      AudioManager.playSfx('menuMove', 0.85, { playbackRate: direction < 0 ? 0.95 : 1.05 });
    };

    CharacterSelect.setSelection = function (index, game) {
      const activeGame = game || this.getGame();
      if (this.isHeroDisabled(activeGame, this.heroes[index])) {
        AudioManager.playSfx('menuBack', 0.55);
        return false;
      }
      if (index === this.selectedIndex) return true;
      this.selectedIndex = index;
      AudioManager.playSfx('menuMove', 0.85);
      return true;
    };

    CharacterSelect.confirm = function (game) {
      const heroKey = this.heroes[this.selectedIndex];
      if (this.isHeroDisabled(game, heroKey)) {
        AudioManager.playSfx('menuBack', 0.65);
        return;
      }
      game.selectedHero = heroKey;
      AudioManager.playSfx('menuSelect', 0.85);
      if ((game.characterSelectMode === 'casualty' || game.characterSelectMode === 'switchHero') && game.resumeAfterHeroDefeat) {
        game.resumeAfterHeroDefeat(heroKey);
      } else if (game.characterSelectMode === 'retryRegion' && game.startRetryRegion) {
        game.startRetryRegion(heroKey);
      } else {
        if (game.resetTeamRun) game.resetTeamRun();
        game.startLevel();
      }
    };

    CharacterSelect.update = function (game) {
      this.gameRef = game;
      if (this.isHeroDisabled(game, this.heroes[this.selectedIndex])) {
        this.selectedIndex = this.findFirstAvailableIndex(game);
      }

      if (this.infoOpen) {
        if (Input.consume('escape') || Input.consume('i') || Input.consume('backspace') || Input.consume('enter') || Input.consume('space')) {
          this.closeInfo();
          return;
        }
        const infoClick = Input.consumePointer();
        if (infoClick) this.closeInfo();
        return;
      }

      if (Input.consume('arrowdown') || Input.consume('s')) {
        this.footerFocus = 'confirm';
        AudioManager.playSfx('menuMove', 0.65);
      }
      if (Input.consume('arrowup') || Input.consume('w')) {
        if (this.footerFocus) AudioManager.playSfx('menuMove', 0.65);
        this.footerFocus = null;
      }
      if (Input.consume('arrowleft') || Input.consume('a')) {
        if (this.footerFocus) this.moveFooterFocus(-1);
        else this.moveSelection(-1, game);
      }
      if (Input.consume('arrowright') || Input.consume('d')) {
        if (this.footerFocus) this.moveFooterFocus(1);
        else this.moveSelection(1, game);
      }

      if (Input.consume('i')) this.openInfo();
      if (Input.consume('escape')) {
        AudioManager.playSfx('menuSelect', 0.65);
        const mode = game.characterSelectMode;
        game.characterSelectMode = null;
        game.setState((mode === 'casualty' || mode === 'switchHero') && game.scene ? 'level' : 'mainMenu');
        return;
      }

      const click = Input.consumePointer();
      if (click) {
        for (let i = 0; i < this.heroes.length; i++) {
          const info = this.getInfoButtonBox(i);
          if (this.isPointInCircle(click, info)) {
            this.selectedIndex = i;
            this.footerFocus = null;
            this.openInfo();
            return;
          }
          const box = this.getCardBox(i);
          if (this.isPointInBox(click, box)) {
            this.setSelection(i, game);
            this.footerFocus = null;
          }
        }

        if (this.isPointInBox(click, this.getBackBox())) {
          AudioManager.playSfx('menuSelect', 0.65);
          const mode = game.characterSelectMode;
          game.characterSelectMode = null;
          game.setState((mode === 'casualty' || mode === 'switchHero') && game.scene ? 'level' : 'mainMenu');
          return;
        }
        if (this.isPointInBox(click, this.getConfirmBox())) {
          this.confirm(game);
          return;
        }
      }

      if (Input.consume('enter') || Input.consume('space')) {
        if (this.footerFocus === 'back') {
          AudioManager.playSfx('menuSelect', 0.65);
          const mode = game.characterSelectMode;
          game.characterSelectMode = null;
          game.setState((mode === 'casualty' || mode === 'switchHero') && game.scene ? 'level' : 'mainMenu');
        } else {
          this.confirm(game);
        }
      }
    };

    CharacterSelect.draw = function (ctx, images) {
      ctx.fillStyle = '#08080d';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      ctx.fillStyle = 'rgba(0,0,0,0.58)';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

      const mode = this.gameRef && this.gameRef.characterSelectMode;
      const title = mode === 'casualty'
        ? 'ВЫБЕРИТЕ, КТО ПРОДОЛЖИТ БОРЬБУ'
        : (mode === 'retryRegion' ? 'ВЫБЕРИТЕ ГЕРОЯ ДЛЯ НОВОЙ ПОПЫТКИ' : (mode === 'switchHero' ? 'СМЕНИТЬ ПЕРСОНАЖА' : 'ВЫБЕРИТЕ ПЕРСОНАЖА'));
      this.drawTitle(ctx, title, 104);

      for (let i = 0; i < this.heroes.length; i++) {
        const disabled = this.isHeroDisabled(this.gameRef, this.heroes[i]);
        this.drawCard(ctx, images, this.heroes[i], i, i === this.selectedIndex && !disabled);
      }

      const back = this.getBackBox();
      const confirm = this.getConfirmBox();
      this.drawButton(ctx, back.x, back.y, back.w, back.h, 'НАЗАД', this.footerFocus === 'back');
      this.drawButton(ctx, confirm.x, confirm.y, confirm.w, confirm.h, mode === 'casualty' ? 'ПРОДОЛЖИТЬ' : (mode === 'switchHero' ? 'СМЕНИТЬ' : 'ДАЛЕЕ'), this.footerFocus === 'confirm' || !this.footerFocus);

      ctx.font = '18px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'alphabetic';
      ctx.fillStyle = 'rgba(255,255,255,0.72)';
      ctx.fillText('←/→ или A/D — выбрать   ↑/↓ или W/S — кнопки   Enter — подтвердить   I — информация', GAME_CONFIG.width / 2, 704);
      ctx.textAlign = 'left';

      if (this.infoOpen) this.drawInfoModal(ctx, images);
    };

    CharacterSelect.drawCard = function (ctx, images, heroKey, index, selected) {
      originalDrawCard.call(this, ctx, images, heroKey, index, selected);
      if (!this.isHeroDisabled(this.gameRef, heroKey)) return;
      const box = this.getCardBox(index);
      ctx.save();
      ctx.fillStyle = 'rgba(0,0,0,0.64)';
      ctx.fillRect(box.x, box.y, box.w, box.h);
      ctx.strokeStyle = 'rgba(150,150,150,0.75)';
      ctx.lineWidth = 4;
      ctx.strokeRect(box.x, box.y, box.w, box.h);
      ctx.fillStyle = 'rgba(220,220,220,0.88)';
      ctx.font = 'bold 38px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('ВЫБЫЛ', box.x + box.w / 2, box.y + box.h / 2);
      ctx.font = '18px Arial';
      ctx.fillStyle = 'rgba(255,255,255,0.62)';
      ctx.fillText('нельзя выбрать', box.x + box.w / 2, box.y + box.h / 2 + 44);
      ctx.restore();
    };

    CharacterSelect.drawInfoIcon = function (ctx, index, selected, color) {
      originalDrawInfoIcon.call(this, ctx, index, selected, color);
    };
  }

  if (typeof HUD !== 'undefined') {
    HUD.draw = function (ctx, scene) {
      const game = scene.game;
      if (game && game.ensureRunState) game.ensureRunState();

      ctx.fillStyle = 'rgba(0,0,0,0.66)';
      ctx.fillRect(0, 0, GAME_CONFIG.width, 92);

      for (let i = 0; i < HERO_ORDER.length; i++) {
        const key = HERO_ORDER[i];
        const hero = GAME_CONFIG.heroes[key];
        const x = 122 + i * 205;
        const active = scene.player.heroKey === key;
        const defeated = !!(game && game.defeatedHeroes && game.defeatedHeroes[key]);

        ctx.fillStyle = active ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.04)';
        ctx.fillRect(x, 12, 180, 60);

        ctx.fillStyle = defeated ? '#555' : hero.color;
        ctx.fillRect(x + 8, 18, 42, 42);
        ctx.fillStyle = '#111';
        ctx.font = 'bold 14px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(hero.name[0], x + 29, 44);
        ctx.textAlign = 'left';

        ctx.fillStyle = defeated ? 'rgba(255,255,255,0.42)' : '#fff';
        ctx.font = 'bold 14px Arial';
        ctx.fillText(hero.name, x + 58, 28);

        const hp = defeated ? 0 : (active ? scene.player.hp : hero.hp);
        const pct = Math.max(0, hp / hero.hp);
        ctx.fillStyle = '#222';
        ctx.fillRect(x + 58, 38, 108, 12);
        ctx.fillStyle = defeated ? '#666' : (pct > 0.55 ? 'lime' : pct > 0.25 ? 'yellow' : 'red');
        ctx.fillRect(x + 58, 38, 108 * pct, 12);
        ctx.strokeStyle = defeated ? '#555' : '#777';
        ctx.strokeRect(x + 58, 38, 108, 12);

        if (defeated) {
          ctx.font = 'bold 11px Arial';
          ctx.fillStyle = 'rgba(255,255,255,0.55)';
          ctx.fillText('ВЫБЫЛ', x + 58, 64);
        }
      }

      if (this.drawSupportButtons) {
        this.drawSupportButtons(ctx, scene, 755, 22);
      }
      if (this.drawLowHpSwitchHint) {
        this.drawLowHpSwitchHint(ctx, scene);
      }
      if (this.drawSuckerPinHint) {
        this.drawSuckerPinHint(ctx, scene);
      }
    };
  }

  if (typeof GameApp !== 'undefined') {
    const buttons = [
      { key: 'retry', label: 'ПОПРОБОВАТЬ СНОВА' },
      { key: 'support', label: 'ПОДДЕРЖАТЬ ТЕХ, КТО БОРЕТСЯ' },
      { key: 'menu', label: 'ГЛАВНОЕ МЕНЮ' }
    ];

    const heroDefeatQuotes = {
      alexey: {
        author: '— Алексей Навальный',
        lines: ['«Моё послание на случай, если меня убьют,', 'очень простое: не сдавайтесь.', 'Не надо, нельзя сдаваться».']
      },
      boris: {
        author: '— Борис Немцов',
        lines: ['«Если бы я боялся Путина по-настоящему,', 'я бы не занимался этим делом».']
      },
      anna: {
        author: '— Анна Политковская',
        lines: ['«Мы позволили им увидеть наш страх.', 'И этим только сделали их сильнее.', 'КГБ уважает только сильных.', 'Слабых оно пожирает».']
      }
    };

    GameApp.prototype.ensureRunState = function () {
      if (!this.defeatedHeroes) this.defeatedHeroes = { alexey: false, anna: false, boris: false };
      if (this.peopleSupport == null) this.peopleSupport = 25;
    };

    GameApp.prototype.resetTeamRun = function () {
      this.defeatedHeroes = { alexey: false, anna: false, boris: false };
      this.peopleSupport = 25;
      this.characterSelectMode = null;
      this.casualtyRespawn = null;
      this.gameOverRegionStartIndex = 0;
    };

    GameApp.prototype.addPeopleSupport = function (amount) {
      this.ensureRunState();
      this.peopleSupport = clampValue(this.peopleSupport + amount, 0, 100);
    };

    GameApp.prototype.getAliveHeroes = function () {
      this.ensureRunState();
      return HERO_ORDER.filter(key => !this.defeatedHeroes[key]);
    };

    GameApp.prototype.getHeroDefeatQuote = function () {
      return heroDefeatQuotes[this.gameOverHero] || heroDefeatQuotes.alexey;
    };

    GameApp.prototype.getCurrentRegionStartIndex = function (scene) {
      if (window.CampaignRuntime && scene) return window.CampaignRuntime.getRegionStartIndexByScreen(scene.screenIndex);
      const levelOrder = Array.isArray(GAME_CONFIG.levelOrder) ? GAME_CONFIG.levelOrder : [];
      if (!scene || !levelOrder.length) return 0;
      const currentIndex = clampValue(Number(scene.screenIndex) || 0, 0, levelOrder.length - 1);
      const currentKey = levelOrder[currentIndex];
      const currentLevel = (GAME_CONFIG.levels && GAME_CONFIG.levels[currentKey]) || {};
      const regionKey = currentLevel.region || currentLevel.regionKey || currentLevel.area || currentLevel.chapter;
      if (!regionKey) return Number.isFinite(scene.regionStartIndex) ? clampValue(scene.regionStartIndex, 0, levelOrder.length - 1) : 0;
      let startIndex = currentIndex;
      for (let i = currentIndex - 1; i >= 0; i -= 1) {
        const key = levelOrder[i];
        const level = (GAME_CONFIG.levels && GAME_CONFIG.levels[key]) || {};
        const levelRegion = level.region || level.regionKey || level.area || level.chapter;
        if (levelRegion !== regionKey) break;
        startIndex = i;
      }
      return startIndex;
    };

    GameApp.prototype.sendHeroToTeamSelect = function (scene, fallenHero) {
      this.ensureRunState();
      this.defeatedHeroes[fallenHero] = true;
      this.addPeopleSupport(-10);
      this.gameOverRegionStartIndex = this.getCurrentRegionStartIndex(scene);
      this.casualtyRespawn = {
        screenIndex: scene.screenIndex,
        x: clampValue(scene.player.x, 90, GAME_CONFIG.width - 140),
        y: clampValue(scene.player.y, GAME_CONFIG.laneTop + 20, GAME_CONFIG.laneBottom - 10),
        facing: scene.player.facing || 1
      };
      this.characterSelectMode = 'casualty';
      const alive = this.getAliveHeroes();
      if (alive.length <= 0) return false;
      CharacterSelect.infoOpen = false;
      CharacterSelect.footerFocus = null;
      CharacterSelect.selectedIndex = CharacterSelect.heroes.indexOf(alive[0]);
      this.setState('characterSelect');
      AudioManager.playSfx('playerDown', 0.8);
      return true;
    };

    GameApp.prototype.openGameOver = function (scene) {
      if (this.state === 'gameOver') return;
      this.gameOverSelection = 0;
      this.gameOverRegionStartIndex = this.getCurrentRegionStartIndex(scene);
      this.gameOverHero = HERO_ORDER[Math.floor(Math.random() * HERO_ORDER.length)];
      this.characterSelectMode = null;
      this.setState('gameOver');
      AudioManager.playSfx('playerDown', 0.8);
    };

    GameApp.prototype.handleHeroDefeat = function (scene) {
      if (!scene || !scene.player || this.state === 'gameOver') return;
      const fallenHero = scene.player.heroKey || this.selectedHero || 'boris';
      this.ensureRunState();
      if (this.defeatedHeroes[fallenHero]) return;
      const willHaveAlive = HERO_ORDER.some(key => key !== fallenHero && !this.defeatedHeroes[key]);
      if (willHaveAlive) {
        this.sendHeroToTeamSelect(scene, fallenHero);
      } else {
        this.defeatedHeroes[fallenHero] = true;
        this.addPeopleSupport(-15);
        this.openGameOver(scene);
      }
    };

    GameApp.prototype.resumeAfterHeroDefeat = function (heroKey) {
      this.ensureRunState();
      if (this.defeatedHeroes[heroKey]) return;
      this.selectedHero = heroKey;
      if (!this.scene) this.scene = new LevelScene(this, this.images);
      const respawn = this.casualtyRespawn || {
        screenIndex: this.scene.screenIndex,
        x: 190,
        y: 620,
        facing: 1
      };
      this.scene.screenIndex = respawn.screenIndex;
      const replacement = new Player(heroKey, this.images);
      replacement.x = respawn.x;
      replacement.y = respawn.y;
      replacement.facing = respawn.facing;
      if (replacement.releaseFromPin) replacement.releaseFromPin();
      this.scene.player = replacement;
      this.casualtyRespawn = null;
      this.characterSelectMode = null;
      this.paused = false;
      this.setState('level');
      const level = this.scene.getLevelConfig ? this.scene.getLevelConfig() : null;
      AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme', true);
    };

    GameApp.prototype.startRetryRegion = function (heroKey) {
      this.ensureRunState();
      this.selectedHero = heroKey;
      this.scene = new LevelScene(this, this.images);
      const levelOrder = Array.isArray(GAME_CONFIG.levelOrder) ? GAME_CONFIG.levelOrder : [];
      const maxIndex = Math.max(0, levelOrder.length - 1);
      const targetIndex = clampValue(Number(this.gameOverRegionStartIndex) || 0, 0, maxIndex);
      this.scene.player = new Player(heroKey, this.images);
      if (window.CampaignRuntime) window.CampaignRuntime.setSceneScreen(this.scene, targetIndex, { spawn: false });
      else {
        this.scene.screenIndex = targetIndex;
        const startLevel = this.scene.getLevelConfig ? this.scene.getLevelConfig() : null;
        const start = (startLevel && startLevel.playerStart) || { x: 190, y: 620 };
        this.scene.player.x = start.x;
        this.scene.player.y = start.y;
        if (this.scene.player.releaseFromPin) this.scene.player.releaseFromPin();
      }
      const level = this.scene.getLevelConfig ? this.scene.getLevelConfig() : null;
      if (this.scene.spawnInitialWave) this.scene.spawnInitialWave();
      this.characterSelectMode = null;
      this.paused = false;
      this.setState('level');
      AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme', true);
    };

    GameApp.prototype.getGameOverButtonRects = function () {
      const width = 470;
      const height = 54;
      const gap = 16;
      const startY = 500;
      const x = GAME_CONFIG.width / 2 - width / 2;
      return buttons.map((button, index) => ({ ...button, x, y: startY + index * (height + gap), w: width, h: height }));
    };

    GameApp.prototype.restartFromCurrentRegion = function () {
      const savedRegionStart = this.gameOverRegionStartIndex || 0;
      this.resetTeamRun();
      this.gameOverRegionStartIndex = savedRegionStart;
      this.characterSelectMode = 'retryRegion';
      this.scene = null;
      CharacterSelect.infoOpen = false;
      CharacterSelect.footerFocus = null;
      CharacterSelect.selectedIndex = CharacterSelect.heroes.indexOf(this.selectedHero || 'boris');
      if (CharacterSelect.selectedIndex < 0) CharacterSelect.selectedIndex = 0;
      this.setState('characterSelect');
      this.ensureMenuMusic();
    };

    GameApp.prototype.activateGameOverButton = function (key) {
      AudioManager.unlock();
      AudioManager.playSfx('menuSelect', 0.85);
      if (key === 'retry') return this.restartFromCurrentRegion();
      if (key === 'support') return window.open('support.html', '_blank', 'noopener,noreferrer');
      if (key === 'menu') {
        this.scene = null;
        this.characterSelectMode = null;
        this.setState('mainMenu');
        this.ensureMenuMusic();
      }
    };

    GameApp.prototype.updateGameOver = function (click) {
      const rects = this.getGameOverButtonRects();
      if (Input.consume('arrowup') || Input.consume('w')) {
        this.gameOverSelection = (this.gameOverSelection + rects.length - 1) % rects.length;
        AudioManager.playSfx('menuMove', 0.7);
      }
      if (Input.consume('arrowdown') || Input.consume('s')) {
        this.gameOverSelection = (this.gameOverSelection + 1) % rects.length;
        AudioManager.playSfx('menuMove', 0.7);
      }
      if (Input.consume('enter') || Input.consume('space')) return this.activateGameOverButton(rects[this.gameOverSelection].key);
      if (!click) return;
      const clickedIndex = rects.findIndex((button) => click.x >= button.x && click.x <= button.x + button.w && click.y >= button.y && click.y <= button.y + button.h);
      if (clickedIndex >= 0) {
        this.gameOverSelection = clickedIndex;
        this.activateGameOverButton(rects[clickedIndex].key);
      }
    };

    GameApp.prototype.drawGameOver = function (ctx) {
      const w = GAME_CONFIG.width;
      const h = GAME_CONFIG.height;
      const bg = this.scene && this.scene.images && this.scene.images.streets ? this.scene.images.streets[this.scene.screenIndex] || this.scene.images.streets[0] : null;
      if (bg) ctx.drawImage(bg, 0, 0, w, h);
      else {
        ctx.fillStyle = '#050505';
        ctx.fillRect(0, 0, w, h);
      }

      const gradient = ctx.createLinearGradient(0, 0, 0, h);
      gradient.addColorStop(0, 'rgba(0,0,0,0.86)');
      gradient.addColorStop(0.45, 'rgba(18,0,0,0.82)');
      gradient.addColorStop(1, 'rgba(0,0,0,0.92)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, w, h);

      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = 'rgba(255,255,255,0.08)';
      ctx.fillRect(190, 72, 900, 420);
      ctx.strokeStyle = 'rgba(255,255,255,0.18)';
      ctx.lineWidth = 2;
      ctx.strokeRect(190, 72, 900, 420);

      ctx.fillStyle = '#f4d8a8';
      ctx.font = 'bold 42px Arial';
      drawLines(ctx, ['ОНИ ПОБЕЖДАЮТ ТОЛЬКО ТОГДА,', 'КОГДА ТЫ СДАЁШЬСЯ…'], w / 2, 145, 52);

      const quote = this.getHeroDefeatQuote();
      const lineHeight = quote.lines.length >= 4 ? 34 : 38;
      const quoteY = quote.lines.length >= 4 ? 286 : 304;
      ctx.fillStyle = '#ffffff';
      ctx.font = quote.lines.length >= 4 ? '26px Arial' : '28px Arial';
      drawLines(ctx, quote.lines, w / 2, quoteY, lineHeight);
      ctx.fillStyle = 'rgba(255,255,255,0.84)';
      ctx.font = '24px Arial';
      ctx.fillText(quote.author, w / 2, quoteY + quote.lines.length * lineHeight + 26);

      this.getGameOverButtonRects().forEach((button, index) => {
        const selected = index === this.gameOverSelection;
        ctx.fillStyle = selected ? 'rgba(244,216,168,0.95)' : 'rgba(0,0,0,0.68)';
        ctx.fillRect(button.x, button.y, button.w, button.h);
        ctx.strokeStyle = selected ? '#ffffff' : 'rgba(255,255,255,0.42)';
        ctx.lineWidth = selected ? 3 : 2;
        ctx.strokeRect(button.x, button.y, button.w, button.h);
        ctx.fillStyle = selected ? '#140000' : '#ffffff';
        ctx.font = 'bold 22px Arial';
        ctx.fillText(button.label, button.x + button.w / 2, button.y + button.h / 2 + 1);
      });

      ctx.fillStyle = 'rgba(255,255,255,0.58)';
      ctx.font = '17px Arial';
      ctx.fillText('↑/↓ — выбор   Enter — подтвердить', w / 2, 695);
      ctx.restore();
    };

    const originalGameUpdate = GameApp.prototype.update;
    GameApp.prototype.update = function (dt) {
      if (this.state === 'gameOver') {
        DevPanel.update(this);
        const click = Input.consumePointer();
        if (click && this.handleSpeakerClick(click)) return;
        if (DevPanel.open) return;
        this.updateGameOver(click);
        return;
      }
      originalGameUpdate.call(this, dt);
    };

    const originalGameDraw = GameApp.prototype.draw;
    GameApp.prototype.draw = function () {
      if (this.state === 'gameOver') {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
        this.drawGameOver(ctx);
        this.drawSpeaker(ctx);
        DevPanel.draw(ctx);
        return;
      }
      originalGameDraw.call(this);
    };

    const originalSceneUpdate = LevelScene.prototype.update;
    LevelScene.prototype.update = function (dt) {
      const wasCleared = this.encounterCleared;
      originalSceneUpdate.call(this, dt);
      if (!wasCleared && this.encounterCleared && this.game && this.game.addPeopleSupport) {
        this.game.addPeopleSupport(8);
      }
      if (this.player && this.player.hp <= 0) this.game.handleHeroDefeat(this);
    };
  }
})();



/* ===== src/teamStatePatch.js ===== */
(function () {
  if (typeof GameApp === 'undefined') return;

  const TEAM_HEROES = ['alexey', 'anna', 'boris'];

  function getHeroMaxHp(heroKey) {
    const hero = GAME_CONFIG.heroes && GAME_CONFIG.heroes[heroKey];
    return hero && Number(hero.hp) ? Number(hero.hp) : 100;
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function defaultHeroHp() {
    return {
      alexey: getHeroMaxHp('alexey'),
      anna: getHeroMaxHp('anna'),
      boris: getHeroMaxHp('boris')
    };
  }

  GameApp.prototype.ensureTeamHpState = function () {
    if (!this.heroHp) this.heroHp = defaultHeroHp();
    for (const key of TEAM_HEROES) {
      const maxHp = getHeroMaxHp(key);
      if (this.heroHp[key] == null || Number.isNaN(Number(this.heroHp[key]))) this.heroHp[key] = maxHp;
      this.heroHp[key] = clamp(Number(this.heroHp[key]), 0, maxHp);
    }
  };

  GameApp.prototype.saveCurrentHeroHp = function () {
    if (!this.scene || !this.scene.player) return;
    this.ensureTeamHpState();
    const key = this.scene.player.heroKey || this.selectedHero;
    if (!key || !TEAM_HEROES.includes(key)) return;
    this.heroHp[key] = clamp(Number(this.scene.player.hp) || 0, 0, getHeroMaxHp(key));
  };

  GameApp.prototype.applySavedHeroHp = function (player, heroKey) {
    this.ensureTeamHpState();
    const maxHp = getHeroMaxHp(heroKey);
    player.hp = clamp(this.heroHp[heroKey] == null ? maxHp : Number(this.heroHp[heroKey]), 1, maxHp);
  };

  const previousEnsureRunState = GameApp.prototype.ensureRunState;
  GameApp.prototype.ensureRunState = function () {
    if (previousEnsureRunState) previousEnsureRunState.call(this);
    this.ensureTeamHpState();
  };

  const previousResetTeamRun = GameApp.prototype.resetTeamRun;
  GameApp.prototype.resetTeamRun = function () {
    if (previousResetTeamRun) previousResetTeamRun.call(this);
    this.heroHp = defaultHeroHp();
  };

  const previousSendHeroToTeamSelect = GameApp.prototype.sendHeroToTeamSelect;
  GameApp.prototype.sendHeroToTeamSelect = function (scene, fallenHero) {
    this.ensureTeamHpState();
    if (fallenHero && TEAM_HEROES.includes(fallenHero)) this.heroHp[fallenHero] = 0;
    return previousSendHeroToTeamSelect.call(this, scene, fallenHero);
  };

  const previousHandleHeroDefeat = GameApp.prototype.handleHeroDefeat;
  GameApp.prototype.handleHeroDefeat = function (scene) {
    if (scene && scene.player) {
      this.ensureTeamHpState();
      const fallenHero = scene.player.heroKey || this.selectedHero;
      if (fallenHero && TEAM_HEROES.includes(fallenHero)) this.heroHp[fallenHero] = 0;
    }
    return previousHandleHeroDefeat.call(this, scene);
  };

  const previousResumeAfterHeroDefeat = GameApp.prototype.resumeAfterHeroDefeat;
  GameApp.prototype.resumeAfterHeroDefeat = function (heroKey) {
    const previousHero = this.scene && this.scene.player ? this.scene.player.heroKey : null;
    const switchingWithoutDeath = this.characterSelectMode === 'switchHero';
    if (switchingWithoutDeath && previousHero && previousHero !== heroKey) this.saveCurrentHeroHp();

    previousResumeAfterHeroDefeat.call(this, heroKey);

    if (this.scene && this.scene.player && this.scene.player.heroKey === heroKey) {
      this.applySavedHeroHp(this.scene.player, heroKey);
    }
  };

  const previousStartRetryRegion = GameApp.prototype.startRetryRegion;
  GameApp.prototype.startRetryRegion = function (heroKey) {
    this.heroHp = defaultHeroHp();
    previousStartRetryRegion.call(this, heroKey);
    if (this.scene && this.scene.player && this.scene.player.heroKey === heroKey) {
      this.applySavedHeroHp(this.scene.player, heroKey);
    }
  };

  const previousStartLevel = GameApp.prototype.startLevel;
  GameApp.prototype.startLevel = function () {
    this.resetTeamRun();
    previousStartLevel.call(this);
    if (this.scene && this.campaignMap && Number.isFinite(this.campaignMap.activeIndex)) {
      const targetIndex = window.CampaignRuntime
        ? window.CampaignRuntime.getActiveRegionStartIndex(this)
        : Math.max(0, Math.min(this.scene.images.streets.length - 1, this.campaignMap.activeIndex * 3));
      if (this.scene.screenIndex !== targetIndex) {
        if (window.CampaignRuntime) window.CampaignRuntime.setSceneScreen(this.scene, targetIndex);
        else {
          this.scene.screenIndex = targetIndex;
          if (this.scene.spawnInitialWave) this.scene.spawnInitialWave();
        }
      }
    }
    if (this.scene && this.scene.player) {
      this.applySavedHeroHp(this.scene.player, this.scene.player.heroKey || this.selectedHero);
    }
  };

  if (typeof HUD !== 'undefined') {
    HUD.draw = function (ctx, scene) {
      const game = scene.game;
      if (game && game.ensureRunState) game.ensureRunState();

      ctx.fillStyle = 'rgba(0,0,0,0.66)';
      ctx.fillRect(0, 0, GAME_CONFIG.width, 92);

      for (let i = 0; i < TEAM_HEROES.length; i++) {
        const key = TEAM_HEROES[i];
        const hero = GAME_CONFIG.heroes[key];
        const x = 122 + i * 205;
        const active = scene.player.heroKey === key;
        const defeated = !!(game && game.defeatedHeroes && game.defeatedHeroes[key]);
        const savedHp = game && game.heroHp ? game.heroHp[key] : getHeroMaxHp(key);
        const hp = defeated ? 0 : (active ? scene.player.hp : savedHp);
        const pct = Math.max(0, Math.min(1, hp / getHeroMaxHp(key)));

        ctx.fillStyle = active ? 'rgba(255,255,255,0.12)' : 'rgba(255,255,255,0.04)';
        ctx.fillRect(x, 12, 180, 60);

        ctx.fillStyle = defeated ? '#555' : hero.color;
        ctx.fillRect(x + 8, 18, 42, 42);
        ctx.fillStyle = '#111';
        ctx.font = 'bold 14px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(hero.name[0], x + 29, 44);
        ctx.textAlign = 'left';

        ctx.fillStyle = defeated ? 'rgba(255,255,255,0.42)' : '#fff';
        ctx.font = 'bold 14px Arial';
        ctx.fillText(hero.name, x + 58, 28);

        ctx.fillStyle = '#222';
        ctx.fillRect(x + 58, 38, 108, 12);
        ctx.fillStyle = defeated ? '#666' : (pct > 0.55 ? 'lime' : pct > 0.25 ? 'yellow' : 'red');
        ctx.fillRect(x + 58, 38, 108 * pct, 12);
        ctx.strokeStyle = defeated ? '#555' : '#777';
        ctx.strokeRect(x + 58, 38, 108, 12);

        if (defeated) {
          ctx.font = 'bold 11px Arial';
          ctx.fillStyle = 'rgba(255,255,255,0.55)';
          ctx.fillText('ВЫБЫЛ', x + 58, 64);
        }
      }

      if (this.drawSupportButtons) {
        this.drawSupportButtons(ctx, scene, 755, 22);
      }
      if (this.drawLowHpSwitchHint) {
        this.drawLowHpSwitchHint(ctx, scene);
      }
      if (this.drawSuckerPinHint) {
        this.drawSuckerPinHint(ctx, scene);
      }
    };
  }
})();



/* ===== src/runProgressPatch.js ===== */
(function () {
  if (typeof GameApp === 'undefined' || typeof Menu === 'undefined') return;

  function inRect(point, rect) {
    return point && point.x >= rect.x && point.x <= rect.x + rect.w && point.y >= rect.y && point.y <= rect.y + rect.h;
  }

  function getCampaignProgress(game) {
    return game && game.campaignMap && Number.isFinite(game.campaignMap.activeIndex)
      ? game.campaignMap.activeIndex
      : 0;
  }

  function canContinue(game) {
    if (window.CampaignFlow) return window.CampaignFlow.canContinue(game);
    return !!(game && (game.runInProgress || game.scene || getCampaignProgress(game) > 0));
  }

  function getMenuItems(game) {
    if (window.CampaignFlow) return window.CampaignFlow.getMenuItems(game);
    const items = [];
    if (canContinue(game)) items.push({ key: 'continue', label: 'ПРОДОЛЖИТЬ' });
    items.push({ key: 'newGame', label: 'НОВАЯ ИГРА' });
    items.push({ key: 'bestiary', label: 'ТВАРИ' });
    items.push({ key: 'settings', label: 'НАСТРОЙКИ' });
    return items;
  }

  function setCharacterSelectForCampaign(game) {
    if (window.CampaignFlow) {
      window.CampaignFlow.openCharacterSelect(game, 'campaignStart');
      return;
    }
    game.runInProgress = true;
    game.resumeTarget = 'campaignMap';
    game.characterSelectMode = 'campaignStart';
    if (typeof CharacterSelect !== 'undefined') {
      CharacterSelect.infoOpen = false;
      CharacterSelect.footerFocus = null;
      CharacterSelect.gameRef = game;
    }
    game.setState('characterSelect');
  }

  const previousSetState = GameApp.prototype.setState;
  GameApp.prototype.setState = function (nextState) {
    const previousState = this.state;

    if (nextState === 'mainMenu') {
      if (previousState === 'level' && this.scene) this.resumeTarget = 'level';
      if (previousState === 'campaignMap') this.resumeTarget = 'campaignMap';
    }

    previousSetState.call(this, nextState);
  };

  GameApp.prototype.startNewCampaign = function () {
    if (window.CampaignFlow) {
      window.CampaignFlow.startNewCampaign(this);
      return;
    }
    this.runInProgress = true;
    this.resumeTarget = 'campaignMap';
    this.scene = null;
    this.paused = false;
    this.characterSelectMode = null;
    this.casualtyRespawn = null;
    if (this.campaignMap && this.campaignMap.resetProgress) this.campaignMap.resetProgress();
    if (this.resetTeamRun) this.resetTeamRun();
    if (this.startIntro) this.startIntro();
    else this.setState('campaignMap');
  };

  GameApp.prototype.continueCampaignRun = function () {
    if (window.CampaignFlow) return window.CampaignFlow.continueCampaignRun(this);
    if (!canContinue(this)) return false;

    AudioManager.unlock();
    AudioManager.playSfx('menuSelect', 0.85);

    if (this.resumeTarget === 'campaignMap' || !this.scene) {
      this.paused = false;
      this.characterSelectMode = null;
      this.setState('campaignMap');
      this.ensureMenuMusic();
      return true;
    }

    this.paused = false;
    this.characterSelectMode = null;
    this.setState('level');
    const level = this.scene && this.scene.getLevelConfig ? this.scene.getLevelConfig() : null;
    AudioManager.playMusic((level && level.music) || (GAME_CONFIG.audio && GAME_CONFIG.audio.music && GAME_CONFIG.audio.music.level) || 'levelTheme');
    return true;
  };

  if (typeof CampaignMapScreen !== 'undefined') {
    const previousCompleteActiveRegion = CampaignMapScreen.completeActiveRegion;
    CampaignMapScreen.completeActiveRegion = function () {
      previousCompleteActiveRegion.call(this);
      if (window.game) {
        window.game.runInProgress = true;
        window.game.resumeTarget = 'campaignMap';
        window.game.scene = null;
      }
    };

    CampaignMapScreen.update = function (game) {
      const click = Input.consumePointer();
      if (Input.consume('escape')) {
        game.runInProgress = true;
        game.resumeTarget = 'campaignMap';
        game.setState('mainMenu');
        return;
      }

      const startButton = this.getDesktopStartButton ? this.getDesktopStartButton() : null;
      if (Input.consume('enter') || Input.consume('space') || click && (!startButton || inRect(click, startButton))) {
        AudioManager.unlock();
        AudioManager.playSfx('menuSelect', 0.85);
        setCharacterSelectForCampaign(game);
      }
    };
  }

  Menu.getRuntimeItems = function (game) {
    return getMenuItems(game);
  };

  Menu.getItemBox = function (index, game) {
    const count = getMenuItems(game || window.game).length;
    const startY = count >= 4 ? 256 : 300;
    return { x: 485, y: startY + index * 70, w: 310, h: 54 };
  };

  Menu.update = function (game) {
    const items = this.getRuntimeItems(game);
    if (this.selectedIndex >= items.length) this.selectedIndex = items.length - 1;
    if (this.selectedIndex < 0) this.selectedIndex = 0;

    if (!Responsive.isTouchDevice && Input.pointer) {
      for (let i = 0; i < items.length; i++) {
        if (inRect(Input.pointer, this.getItemBox(i, game))) {
          this.selectedIndex = i;
          break;
        }
      }
    }

    if (Input.consume('arrowup') || Input.consume('w')) {
      this.selectedIndex = (this.selectedIndex + items.length - 1) % items.length;
      AudioManager.playSfx('menuMove', 0.75);
    }
    if (Input.consume('arrowdown') || Input.consume('s')) {
      this.selectedIndex = (this.selectedIndex + 1) % items.length;
      AudioManager.playSfx('menuMove', 0.75);
    }

    const click = Input.consumePointer();
    if (click) {
      AudioManager.unlock();
      for (let i = 0; i < items.length; i++) {
        if (!inRect(click, this.getItemBox(i, game))) continue;
        this.selectedIndex = i;
        this.activate(game);
        return;
      }
    }

    if (Input.consume('enter') || Input.consume('space')) {
      AudioManager.unlock();
      this.activate(game);
    }
  };

  Menu.activate = function (game) {
    const items = this.getRuntimeItems(game);
    const item = items[this.selectedIndex];
    if (!item) return;

    if (item.key === 'continue') {
      game.continueCampaignRun();
      return;
    }

    AudioManager.playSfx('menuSelect', 0.85);

    if (item.key === 'newGame') {
      game.startNewCampaign();
      return;
    }

    if (item.key === 'settings') game.setState('settings');
  };

  Menu.draw = function (ctx, images) {
    ctx.drawImage(images.main, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
    ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
    ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

    const items = this.getRuntimeItems(window.game);
    if (this.selectedIndex >= items.length) this.selectedIndex = items.length - 1;
    if (this.selectedIndex < 0) this.selectedIndex = 0;

    for (let i = 0; i < items.length; i++) {
      const box = this.getItemBox(i, window.game);
      const active = i === this.selectedIndex;
      ctx.fillStyle = active ? 'rgba(255,255,255,0.16)' : 'rgba(0,0,0,0.28)';
      ctx.strokeStyle = active ? '#ffffff' : 'rgba(255,255,255,0.45)';
      ctx.lineWidth = active ? 4 : 2;
      ctx.fillRect(box.x, box.y, box.w, box.h);
      ctx.strokeRect(box.x, box.y, box.w, box.h);
      ctx.font = 'bold 28px Arial';
      ctx.textAlign = 'center';
      ctx.fillStyle = '#ffffff';
      ctx.strokeStyle = '#000000';
      ctx.lineWidth = 4;
      ctx.strokeText(items[i].label, box.x + box.w / 2, box.y + 36);
      ctx.fillText(items[i].label, box.x + box.w / 2, box.y + 36);
    }
    ctx.textAlign = 'left';
  };

  if (typeof CharacterSelect !== 'undefined') {
    function goBack(game) {
      if (window.CampaignFlow) {
        window.CampaignFlow.backFromCharacterSelect(game);
        return;
      }
      AudioManager.playSfx('menuSelect', 0.65);
      const mode = game.characterSelectMode;
      game.characterSelectMode = null;

      if ((mode === 'casualty' || mode === 'switchHero') && game.scene) {
        game.setState('level');
        return;
      }

      if (mode === 'campaignStart') {
        game.resumeTarget = 'campaignMap';
        game.setState('campaignMap');
        return;
      }

      game.setState('mainMenu');
    }

    CharacterSelect.confirm = function (game) {
      if (window.CampaignFlow) {
        window.CampaignFlow.confirmCharacterSelect(this, game);
        return;
      }
      const heroKey = this.heroes[this.selectedIndex];
      if (this.isHeroDisabled && this.isHeroDisabled(game, heroKey)) {
        AudioManager.playSfx('menuBack', 0.65);
        return;
      }

      game.selectedHero = heroKey;
      AudioManager.playSfx('menuSelect', 0.85);

      if ((game.characterSelectMode === 'casualty' || game.characterSelectMode === 'switchHero') && game.resumeAfterHeroDefeat) {
        game.resumeAfterHeroDefeat(heroKey);
        return;
      }

      if (game.characterSelectMode === 'retryRegion' && game.startRetryRegion) {
        game.startRetryRegion(heroKey);
        return;
      }

      game.characterSelectMode = null;
      game.runInProgress = true;
      game.resumeTarget = 'level';
      if (game.resetTeamRun) game.resetTeamRun();
      game.startLevel();
    };

    CharacterSelect.update = function (game) {
      this.gameRef = game;
      if (this.isHeroDisabled && this.isHeroDisabled(game, this.heroes[this.selectedIndex])) {
        this.selectedIndex = this.findFirstAvailableIndex ? this.findFirstAvailableIndex(game) : 0;
      }

      if (this.infoOpen) {
        if (Input.consume('escape') || Input.consume('i') || Input.consume('backspace') || Input.consume('enter') || Input.consume('space')) {
          this.closeInfo();
          return;
        }
        const infoClick = Input.consumePointer();
        if (infoClick) this.closeInfo();
        return;
      }

      if (Input.consume('arrowdown') || Input.consume('s')) {
        this.footerFocus = 'confirm';
        AudioManager.playSfx('menuMove', 0.65);
      }
      if (Input.consume('arrowup') || Input.consume('w')) {
        if (this.footerFocus) AudioManager.playSfx('menuMove', 0.65);
        this.footerFocus = null;
      }
      if (Input.consume('arrowleft') || Input.consume('a')) {
        if (this.footerFocus) this.moveFooterFocus(-1);
        else this.moveSelection(-1, game);
      }
      if (Input.consume('arrowright') || Input.consume('d')) {
        if (this.footerFocus) this.moveFooterFocus(1);
        else this.moveSelection(1, game);
      }

      if (Input.consume('i')) this.openInfo();
      if (Input.consume('escape')) {
        goBack(game);
        return;
      }

      const click = Input.consumePointer();
      if (click) {
        for (let i = 0; i < this.heroes.length; i++) {
          const info = this.getInfoButtonBox(i);
          if (this.isPointInCircle(click, info)) {
            this.selectedIndex = i;
            this.footerFocus = null;
            this.openInfo();
            return;
          }
          const box = this.getCardBox(i);
          if (this.isPointInBox(click, box)) {
            this.setSelection(i, game);
            this.footerFocus = null;
          }
        }

        if (this.isPointInBox(click, this.getBackBox())) {
          goBack(game);
          return;
        }
        if (this.isPointInBox(click, this.getConfirmBox())) {
          this.confirm(game);
          return;
        }
      }

      if (Input.consume('enter') || Input.consume('space')) {
        if (this.footerFocus === 'back') goBack(game);
        else this.confirm(game);
      }
    };
  }
})();



/* ===== src/fullscreenPatch.js ===== */
(function () {
  const FullscreenPatch = {
    button: null,
    hint: null,

    isMobile() {
      return window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    },

    isFullscreen() {
      return document.fullscreenElement || document.webkitFullscreenElement || document.msFullscreenElement;
    },

    async requestFullscreen() {
      const root = document.documentElement;
      try {
        if (root.requestFullscreen) await root.requestFullscreen();
        else if (root.webkitRequestFullscreen) root.webkitRequestFullscreen();
        else if (root.msRequestFullscreen) root.msRequestFullscreen();
      } catch (error) {
        console.warn('Fullscreen request failed:', error);
      }

      try {
        if (screen.orientation && screen.orientation.lock) await screen.orientation.lock('landscape');
      } catch (error) {
        // Browsers may reject orientation lock unless fullscreen is supported. The game still works.
      }

      setTimeout(() => {
        if (this.canResizeGame()) Responsive.resize();
        this.updateVisibility();
      }, 120);
    },

    async exitFullscreen() {
      try {
        if (document.exitFullscreen) await document.exitFullscreen();
        else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
        else if (document.msExitFullscreen) document.msExitFullscreen();
      } catch (error) {
        console.warn('Exit fullscreen failed:', error);
      }
      setTimeout(() => this.updateVisibility(), 120);
    },

    createButton() {
      const button = document.createElement('button');
      button.type = 'button';
      button.id = 'fullscreenButton';
      button.textContent = 'НА ВЕСЬ ЭКРАН';
      button.setAttribute('aria-label', 'Включить полноэкранный режим');
      button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        this.requestFullscreen();
      });
      document.body.appendChild(button);
      this.button = button;
    },

    createHint() {
      const hint = document.createElement('div');
      hint.id = 'rotateHint';
      hint.textContent = 'Поверните телефон горизонтально';
      document.body.appendChild(hint);
      this.hint = hint;
    },

    updateVisibility() {
      const mobile = this.isMobile();
      const fullscreen = !!this.isFullscreen();
      const portrait = window.innerHeight > window.innerWidth && window.innerWidth < 900;

      document.body.classList.toggle('is-fullscreen', fullscreen);
      document.body.classList.toggle('is-mobile-device', mobile);
      document.body.classList.toggle('is-portrait-mobile', mobile && portrait);

      if (this.button) {
        this.button.style.display = mobile && !fullscreen ? 'block' : 'none';
      }

      if (this.hint) {
        this.hint.style.display = mobile && portrait ? 'block' : 'none';
      }

      if (this.canResizeGame()) Responsive.resize();
    },

    canResizeGame() {
      return typeof Responsive !== 'undefined' && Responsive.canvas && Responsive.ctx && typeof Responsive.resize === 'function';
    },

    init() {
      this.createButton();
      this.createHint();
      this.updateVisibility();
      window.addEventListener('resize', () => this.updateVisibility());
      window.addEventListener('orientationchange', () => setTimeout(() => this.updateVisibility(), 180));
      document.addEventListener('fullscreenchange', () => this.updateVisibility());
      document.addEventListener('webkitfullscreenchange', () => this.updateVisibility());
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => FullscreenPatch.init());
  } else {
    FullscreenPatch.init();
  }

  window.FullscreenPatch = FullscreenPatch;
})();



/* ===== src/bestiaryPatch.js ===== */
(function () {
  if (typeof GameApp === 'undefined' || typeof Menu === 'undefined') return;

  const ENEMIES = [
    { type: 'dogRegime', label: 'dog-regime' },
    { type: 'zetnik', label: 'zetnik' },
    { type: 'sucker', label: 'sucker' },
    { type: 'bastard', label: 'bastard' },
    { type: 'horse', label: 'horse' },
    { type: 'gundos', label: 'gundos' }
  ];

  const BestiaryScreen = {
    index: 0,

    getEntries(game) {
      return ENEMIES.filter((entry) => (
        game && game.images && game.images.enemies && game.images.enemies[entry.type]
      ));
    },

    getRects() {
      return {
        prev: { x: 110, y: 595, w: 190, h: 70 },
        next: { x: 980, y: 595, w: 190, h: 70 },
        back: { x: 420, y: 595, w: 440, h: 70 }
      };
    },

    inRect(point, rect) {
      return point && point.x >= rect.x && point.x <= rect.x + rect.w &&
        point.y >= rect.y && point.y <= rect.y + rect.h;
    },

    move(game, direction) {
      const entries = this.getEntries(game);
      if (!entries.length) return;
      this.index = (this.index + direction + entries.length) % entries.length;
      AudioManager.playSfx('menuMove', 0.7);
    },

    close(game) {
      const target = game.bestiaryReturnState === 'level' && game.scene ? 'level' : 'mainMenu';
      game.paused = false;
      game.setState(target);
      AudioManager.playSfx('menuSelect', 0.65);
    },

    update(game, click) {
      if (Input.consume('escape') || Input.consume('backspace')) {
        this.close(game);
        return;
      }
      if (Input.consume('arrowleft') || Input.consume('a')) this.move(game, -1);
      if (Input.consume('arrowright') || Input.consume('d')) this.move(game, 1);

      if (!click) return;
      const rects = this.getRects();
      if (this.inRect(click, rects.prev)) this.move(game, -1);
      else if (this.inRect(click, rects.next)) this.move(game, 1);
      else if (this.inRect(click, rects.back)) this.close(game);
    },

    drawButton(ctx, rect, label, active) {
      ctx.fillStyle = active ? 'rgba(130,0,0,0.86)' : 'rgba(0,0,0,0.62)';
      ctx.strokeStyle = active ? '#fff' : 'rgba(255,255,255,0.68)';
      ctx.lineWidth = active ? 4 : 3;
      ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
      ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
      ctx.font = 'bold 24px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = '#fff';
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 5;
      ctx.strokeText(label, rect.x + rect.w / 2, rect.y + rect.h / 2 + 1);
      ctx.fillText(label, rect.x + rect.w / 2, rect.y + rect.h / 2 + 1);
    },

    draw(ctx, game) {
      const bg = game.images && game.images.main;
      if (bg) ctx.drawImage(bg, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      else {
        ctx.fillStyle = '#050508';
        ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      }
      ctx.fillStyle = 'rgba(0,0,0,0.74)';
      ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);

      const entries = this.getEntries(game);
      if (!entries.length) return;
      this.index = Math.max(0, Math.min(entries.length - 1, this.index));
      const entry = entries[this.index];
      const enemyImages = game.images.enemies[entry.type];
      const image = enemyImages.idle ||
        (enemyImages.walk && enemyImages.walk[0]) ||
        enemyImages.dead;

      ctx.save();
      ctx.textAlign = 'center';
      ctx.fillStyle = '#fff';
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 7;
      ctx.font = 'bold 44px Arial';
      ctx.strokeText('BESTIARY', GAME_CONFIG.width / 2, 78);
      ctx.fillText('BESTIARY', GAME_CONFIG.width / 2, 78);

      ctx.fillStyle = 'rgba(0,0,0,0.58)';
      ctx.fillRect(260, 110, 760, 455);
      ctx.strokeStyle = 'rgba(255,255,255,0.55)';
      ctx.lineWidth = 3;
      ctx.strokeRect(260, 110, 760, 455);

      ctx.font = 'bold 38px Arial';
      ctx.strokeStyle = '#000';
      ctx.lineWidth = 6;
      ctx.strokeText(entry.label, GAME_CONFIG.width / 2, 168);
      ctx.fillText(entry.label, GAME_CONFIG.width / 2, 168);

      if (image) {
        const maxW = 430;
        const maxH = 330;
        const scale = Math.min(maxW / image.width, maxH / image.height);
        const width = image.width * scale;
        const height = image.height * scale;
        ctx.drawImage(image, GAME_CONFIG.width / 2 - width / 2, 515 - height, width, height);
      }

      ctx.font = '20px Arial';
      ctx.fillStyle = '#d8d8d8';
      ctx.fillText(String(this.index + 1) + ' / ' + String(entries.length), GAME_CONFIG.width / 2, 542);
      ctx.restore();

      const rects = this.getRects();
      this.drawButton(ctx, rects.prev, 'НАЗАД', false);
      this.drawButton(
        ctx,
        rects.back,
        game.bestiaryReturnState === 'level' ? 'ВЕРНУТЬСЯ В ИГРУ' : 'ГЛАВНОЕ МЕНЮ',
        true
      );
      this.drawButton(ctx, rects.next, 'ВПЕРЁД', false);
    }
  };

  window.BestiaryScreen = BestiaryScreen;

  GameApp.prototype.openBestiary = function (returnState) {
    this.bestiaryReturnState = returnState === 'level' && this.scene ? 'level' : 'mainMenu';
    BestiaryScreen.index = 0;
    this.setState('bestiary');
    AudioManager.playSfx('menuSelect', 0.75);
  };

  const previousUpdate = GameApp.prototype.update;
  GameApp.prototype.update = function (dt) {
    if (this.state === 'bestiary') {
      const click = Input.consumePointer();
      if (click && this.handleSpeakerClick(click)) return;
      BestiaryScreen.update(this, click);
      return;
    }
    previousUpdate.call(this, dt);
  };

  const previousDraw = GameApp.prototype.draw;
  GameApp.prototype.draw = function () {
    if (this.state === 'bestiary') {
      this.ctx.clearRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      BestiaryScreen.draw(this.ctx, this);
      this.drawSpeaker(this.ctx);
      return;
    }
    previousDraw.call(this);
  };

  const previousActivate = Menu.activate;
  Menu.activate = function (game) {
    const items = this.getRuntimeItems ? this.getRuntimeItems(game) : [];
    const item = items[this.selectedIndex];
    if (item && item.key === 'bestiary') {
      game.openBestiary('mainMenu');
      return;
    }
    previousActivate.call(this, game);
  };

  if (typeof MobileApp !== 'undefined') {
    const previousMainMenuTap = MobileApp.handleMainMenuTap;
    MobileApp.handleMainMenuTap = function (game, click) {
      const rects = this.mainMenuRects();
      if (rects[1] && this.inRect(click, rects[1])) {
        game.openBestiary('mainMenu');
        return true;
      }
      return previousMainMenuTap.call(this, game, click);
    };

    MobileApp.handleBestiaryTap = function (game, click) {
      BestiaryScreen.update(game, click);
      return true;
    };

    MobileApp.drawMobileBestiary = function (ctx, game) {
      BestiaryScreen.draw(ctx, game);
      if (game.drawSpeaker) game.drawSpeaker(ctx);
    };
  }
})();



/* ===== src/gundosEnemyPatch.js ===== */
(function () {
  if (typeof GAME_CONFIG === 'undefined' || typeof Assets === 'undefined') return;

  const FOLDER = 'assets/enemies/gundos';
  const ASSET_VERSION = 'gundos-finale-2';
  const INTRO_DURATION_MS = 56425;
  const DEVIL_LEAD_MS = 2000;

  function versioned(file) {
    return FOLDER + '/' + file + '?v=' + ASSET_VERSION;
  }

  Assets.gundos = {
    walk: [versioned('walk0.png'), versioned('walk1.png')],
    swing: versioned('swing.png'),
    devil: versioned('devil.png'),
    knockdownBody: versioned('knockdownBody.png'),
    fireWall: 'assets/effects/gundos-fire-wall.png?v=' + ASSET_VERSION,
    appear: versioned('Appear.mp3')
  };

  GAME_CONFIG.enemies.gundos = Object.assign({
    name: 'gundos',
    hp: 6,
    speed: 1.875,
    scale: 0.266,
    damage: 0,
    blocksWaveClear: true,
    canAttack: false,
    canDie: true,
    introDurationMs: INTRO_DURATION_MS,
    devilLeadMs: DEVIL_LEAD_MS,
    entranceTargetX: 1040,
    entranceY: 720,
    zetnikSpawnMinMs: 1450,
    zetnikSpawnMaxMs: 2450,
    maxZetniks: 3,
    guardZetniks: 3,
    medicSpawnMs: 1200,
    medicRespawnMs: 12500,
    fireballSpawnMinMs: 1250,
    fireballSpawnMaxMs: 2350,
    zetnikHitDamage: 1,
    arenaMoveSpeed: 0,
    arenaTop: 540,
    arenaBottom: 720,
    deathHoldMs: 5000,
    victoryDelayMs: 4800
  }, GAME_CONFIG.enemies.gundos || {});

  function migrateIntroSequence() {
    const config = GAME_CONFIG.enemies.gundos;
    if (Number(config.introSequenceVersion) >= 8) return;
    Object.assign(config, {
      introSequenceVersion: 8,
      speed: 1.875,
      hp: 6,
      scale: 0.266,
      devilLeadMs: DEVIL_LEAD_MS,
      entranceTargetX: 1040,
      entranceY: 720,
      zetnikSpawnMinMs: 1450,
      zetnikSpawnMaxMs: 2450,
      maxZetniks: 3,
      guardZetniks: 3,
      medicSpawnMs: 1200,
      medicRespawnMs: 12500,
      fireballSpawnMinMs: 1250,
      fireballSpawnMaxMs: 2350,
      zetnikHitDamage: 1,
      arenaMoveSpeed: 0,
      arenaTop: 540,
      arenaBottom: 720,
      deathHoldMs: 5000,
      victoryDelayMs: 4800
    });
    delete config.swingLeadMs;
    delete config.patrolLeft;
    delete config.patrolRight;
    delete config.patrolTop;
    delete config.patrolBottom;
  }

  function configureFarEastFinale() {
    if (!GAME_CONFIG.levels) return;
    const street02 = GAME_CONFIG.levels.street02;
    const street03 = GAME_CONFIG.levels.street03;

    if (street02 && Array.isArray(street02.waves) &&
        !street02.waves.some(wave => (wave.enemies || []).some(group => group.type === 'sucker'))) {
      street02.waves.push({
        trigger: 'afterWaveCleared',
        enemies: [{ type: 'sucker', count: 1, side: 'right' }]
      });
    }

    if (street03) {
      street03.waves = [{
        trigger: 'onEnter',
        enemies: [{ type: 'gundos', count: 1, side: 'right' }]
      }];
    }
  }

  migrateIntroSequence();
  configureFarEastFinale();

  if (typeof DevPanel !== 'undefined') {
    const previousLoad = DevPanel.load;
    DevPanel.load = function () {
      if (previousLoad) previousLoad.call(this);
      migrateIntroSequence();
      configureFarEastFinale();
    };

    if (DevPanel.tabs && !DevPanel.tabs.includes('GUNDOS')) DevPanel.tabs.push('GUNDOS');
    if (!DevPanel.fieldGroups) DevPanel.fieldGroups = {};
    if (!DevPanel.fieldGroups.GUNDOS) DevPanel.fieldGroups.GUNDOS = [];
    const fields = [
      { label: 'Gundos speed', path: 'enemies.gundos.speed', min: 0.1, max: 3, step: 0.05 },
      { label: 'Gundos scale', path: 'enemies.gundos.scale', min: 0.1, max: 0.7, step: 0.01 },
      { label: 'Gundos HP', path: 'enemies.gundos.hp', min: 1, max: 20, step: 1 },
      { label: 'Entrance target X', path: 'enemies.gundos.entranceTargetX', min: 600, max: 1200, step: 10 },
      { label: 'Entrance Y', path: 'enemies.gundos.entranceY', min: 350, max: 820, step: 5 },
      { label: 'Devil lead ms', path: 'enemies.gundos.devilLeadMs', min: 0, max: 10000, step: 250 },
      { label: 'Zetnik min spawn', path: 'enemies.gundos.zetnikSpawnMinMs', min: 500, max: 6000, step: 100 },
      { label: 'Zetnik max spawn', path: 'enemies.gundos.zetnikSpawnMaxMs', min: 500, max: 8000, step: 100 },
      { label: 'Max Zetniks', path: 'enemies.gundos.maxZetniks', min: 1, max: 8, step: 1 },
      { label: 'Arena move speed', path: 'enemies.gundos.arenaMoveSpeed', min: 0, max: 2.5, step: 0.05 }
    ];
    for (const field of fields) {
      if (!DevPanel.fieldGroups.GUNDOS.some(item => item.path === field.path)) {
        DevPanel.fieldGroups.GUNDOS.push(field);
      }
    }
  }

  function loadImage(src) {
    return new Promise((resolve) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => {
        console.warn('Missing Gundos image:', src);
        resolve(null);
      };
      image.src = src;
    });
  }

  class GundosFireball {
    constructor(x, y, boss, laneY) {
      this.enemyType = 'gundosFireball';
      this.x = x;
      this.y = y;
      this.laneY = laneY == null ? y : laneY;
      this.boss = boss || null;
      this.radius = 23;
      this.speed = 5.7;
      this.alive = true;
      this.remove = false;
      this.blocksWaveClear = false;
      this.nonPhysical = true;
      this.canBeHit = false;
      this.spin = Math.random() * Math.PI * 2;
    }

    update(dt, scene) {
      const frameScale = Math.max(0.65, Math.min(1.55, dt / 16.67));
      this.x -= this.speed * frameScale;
      this.spin += dt * 0.012;
      const player = scene && scene.player;
      const playerBody = player && player.getBodyBox ? player.getBodyBox() : null;
      const hitsAssignedLane = player && Combat.actorOnLane(
        player,
        this.laneY,
        GAME_CONFIG.yHitTolerance
      );
      if (player && player.hp > 0 && hitsAssignedLane && Combat.overlap(this.getHurtbox(), playerBody)) {
        const hit = player.receiveDamage(8, {
          source: 'ranged',
          knockbackX: -46,
          hitStunMs: 160,
          invulnerableMs: 260
        });
        this.remove = true;
        if (hit) {
          if (scene) scene.hitStop = Math.max(scene.hitStop || 0, 55);
          AudioManager.playSfx('bossAppear', 0.35, { playbackRate: 1.35, startAt: 0.01 });
        }
      }
      if (this.x < -80) this.remove = true;
    }

    getHurtbox() {
      return { x: this.x - this.radius, y: this.y - this.radius, w: this.radius * 2, h: this.radius * 2 };
    }

    draw(ctx, debug) {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.spin);
      const gradient = ctx.createRadialGradient(0, 0, 3, 0, 0, this.radius);
      gradient.addColorStop(0, '#fff3a6');
      gradient.addColorStop(0.38, '#ff9b21');
      gradient.addColorStop(1, 'rgba(255,42,10,0.08)');
      ctx.shadowColor = '#ff5a1f';
      ctx.shadowBlur = 22;
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,220,90,0.9)';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, this.radius * 0.62, -0.4, Math.PI * 1.3);
      ctx.stroke();
      ctx.restore();

      if (debug) {
        const hb = this.getHurtbox();
        ctx.strokeStyle = 'rgba(255,90,0,0.95)';
        ctx.strokeRect(hb.x, hb.y, hb.w, hb.h);
      }
    }

    takeHit() {}
  }

  if (typeof GameApp !== 'undefined') {
    const previousLoadImages = GameApp.prototype.loadImages;
    GameApp.prototype.loadImages = async function () {
      const loaded = await previousLoadImages.call(this);
      const walk0 = await loadImage(Assets.gundos.walk[0]);
      const walk1 = await loadImage(Assets.gundos.walk[1]);
      const swing = await loadImage(Assets.gundos.swing);
      const devil = await loadImage(Assets.gundos.devil);
      const knockdownBody = await loadImage(Assets.gundos.knockdownBody);
      const fireWall = await loadImage(Assets.gundos.fireWall);
      if (!loaded.enemies) loaded.enemies = {};
      loaded.enemies.gundos = {
        idle: walk0 || walk1,
        walk: [walk0 || walk1, walk1 || walk0],
        swing: swing || walk1 || walk0,
        devil: devil || swing || walk1 || walk0,
        knockdownBody: knockdownBody || devil || swing || walk1 || walk0,
        dead: knockdownBody || devil || swing || walk1 || walk0,
        fireWall
      };
      return loaded;
    };
  }

  class GundosEnemy {
    constructor(x, y, images, id) {
      this.enemyType = 'gundos';
      this.id = id;
      this.images = images;
      this.x = x;
      this.y = y;
      this.facing = -1;
      this.alive = true;
      this.remove = false;
      this.blocksWaveClear = true;
      this.maxHp = this.getConfig().hp;
      this.hp = this.maxHp;
      this.state = 'introWalk';
      this.walkFrame = 0;
      this.walkTimer = 0;
      this.introElapsed = 0;
      this.voice = null;
      this.voiceStarted = false;
      this.voiceEnded = false;
      this.transformed = false;
      this.introFinished = false;
      this.previousMusicVolume = null;
      this.spawnTimer = 900;
      this.deathTimer = 0;
      this.arenaMoveDirection = Math.random() < 0.5 ? -1 : 1;
      this.voicePausedByGame = false;
      this.guardSpawned = false;
      this.medicSpawnedOnce = false;
      this.medicSpawnTimer = this.getConfig().medicSpawnMs || 1200;
      this.fireballTimer = 1600;
    }

    getConfig() {
      return GAME_CONFIG.enemies.gundos;
    }

    startVoice() {
      try {
        this.voice = new Audio();
        this.voice.src = Assets.gundos.appear;
        this.voice.preload = 'auto';
        this.voice.loop = false;
        this.voice.volume = AudioManager.getSfxVolume(1);
        AudioManager.registerExternalAudio(this.voice, { owner: 'gundos', channel: 'sfx' });
        this.voice.addEventListener('ended', () => {
          this.voiceEnded = true;
        });
        this.voice.addEventListener('error', () => {
          this.voice = null;
        });
        const result = this.voice.play();
        if (result && result.then) {
          result.then(() => { this.voiceStarted = true; }).catch(() => {});
        } else {
          this.voiceStarted = true;
        }
        if (AudioManager.currentMusic) {
          this.previousMusicVolume = AudioManager.currentMusic.volume;
          AudioManager.currentMusic.volume = Math.min(0.12, AudioManager.getMusicVolume() * 0.28);
        }
      } catch (error) {
        this.voice = null;
      }
    }

    getIntroProgressMs() {
      if (this.voice && this.voiceStarted && Number.isFinite(this.voice.currentTime)) {
        return this.voice.currentTime * 1000;
      }
      return this.introElapsed;
    }

    walkToEntrance(dt, scene) {
      const config = this.getConfig();
      const dx = config.entranceTargetX - this.x;
      const dy = config.entranceY - this.y;
      const distance = Math.hypot(dx, dy);
      if (distance <= 4) {
        this.x = config.entranceTargetX;
        this.y = config.entranceY;
        this.state = 'swing';
        this.facing = -1;
        if (scene) {
          scene.gundosIntroActive = true;
          scene.gundosIntroLocked = false;
          scene.gundosArenaActive = true;
          scene.activeGundos = this;
          this.ensureGuardWall(scene);
        }
        this.startVoice();
        return;
      }

      const frameScale = Math.max(0.7, Math.min(1.6, dt / 16.67));
      this.x += dx / distance * config.speed * frameScale;
      this.y += dy / distance * config.speed * GAME_CONFIG.ySpeedMultiplier * frameScale;
      if (Math.abs(dx) > 3) this.facing = dx >= 0 ? 1 : -1;

      this.walkTimer += dt;
      if (this.walkTimer >= 360) {
        this.walkTimer -= 360;
        this.walkFrame = 1 - this.walkFrame;
      }
    }

    transform(scene) {
      if (this.transformed) return;
      this.transformed = true;
      this.state = 'devil';
      this.facing = -1;
      AudioManager.playSfx('bossAppear', 0.95);
    }

    finishIntro(scene) {
      if (this.introFinished) return;
      this.introFinished = true;
      if (!this.transformed) this.transform(scene);
      if (AudioManager.currentMusic) AudioManager.currentMusic.volume = AudioManager.getMusicVolume();
      if (scene) {
        scene.gundosIntroActive = false;
        scene.gundosIntroLocked = false;
        scene.gundosArenaActive = true;
        if (scene.releaseGundosGuardWall) scene.releaseGundosGuardWall();
      }
    }

    ensureGuardWall(scene) {
      if (this.guardSpawned || !scene || !scene.spawnGundosGuardWall) return;
      this.guardSpawned = true;
      scene.spawnGundosGuardWall(this);
    }

    stopVoice() {
      if (!this.voice) return;
      const voice = this.voice;
      try {
        voice.pause();
        voice.currentTime = 0;
      } catch (error) {}
      this.voice = null;
      AudioManager.unregisterExternalAudio(voice);
      if (AudioManager.currentMusic) AudioManager.currentMusic.volume = AudioManager.getMusicVolume();
    }

    pauseVoice() {
      if (!this.voice || this.voice.paused || this.voice.ended) return;
      try {
        this.voice.pause();
        this.voicePausedByGame = true;
      } catch (error) {}
    }

    resumeVoice() {
      if (!this.voice || !this.voicePausedByGame || this.voice.ended) return;
      this.voicePausedByGame = false;
      try {
        this.voice.volume = AudioManager.getSfxVolume(1);
        this.voice.play().catch(() => {});
      } catch (error) {}
    }

    update(dt, scene) {
      if (!this.alive) {
        this.deathTimer += dt;
        if (this.deathTimer > (this.getConfig().deathHoldMs || 5000) + 1200) this.remove = true;
        return;
      }

      scene.gundosIntroActive = true;

      if (this.state === 'introWalk') {
        scene.gundosIntroLocked = true;
        this.walkToEntrance(dt, scene);
        return;
      }

      scene.gundosIntroLocked = false;
      scene.gundosArenaActive = true;
      scene.activeGundos = this;
      if (!this.introFinished) {
        this.ensureGuardWall(scene);
        this.updateIntroMedic(dt, scene);
      } else {
        this.enforceFireRing(scene);
        this.updateZetnikPressure(dt, scene);
        this.updateFireballs(dt, scene);
      }

      this.introElapsed += dt;
      if (this.voice) this.voice.volume = AudioManager.getSfxVolume(1);

      const config = this.getConfig();
      const elapsed = this.getIntroProgressMs();
      const duration = this.voice && Number.isFinite(this.voice.duration) && this.voice.duration > 0
        ? this.voice.duration * 1000
        : config.introDurationMs;
      const devilAt = Math.max(0, duration - config.devilLeadMs);

      if (elapsed >= devilAt) this.transform(scene);
      if (this.voiceEnded || elapsed >= duration) this.finishIntro(scene);
    }

    updateIntroMedic(dt, scene) {
      if (!scene || !scene.spawnGundosMedicBastard) return;
      if (this.medicSpawnedOnce) return;
      const activeMedic = (scene.enemies || []).some(enemy =>
        enemy && enemy.alive && !enemy.remove && enemy.enemyType === 'bastard' && enemy.gundosMedic
      );
      if (activeMedic) return;
      this.medicSpawnTimer -= dt;
      if (this.medicSpawnTimer > 0) return;
      scene.spawnGundosMedicBastard(this);
      this.medicSpawnedOnce = true;
      this.medicSpawnTimer = this.getConfig().medicRespawnMs || 12500;
    }

    updateArenaMovement(dt) {
      const config = this.getConfig();
      const top = config.arenaTop || 540;
      const bottom = config.arenaBottom || 675;
      const speed = config.arenaMoveSpeed == null ? 0.6 : config.arenaMoveSpeed;
      this.y += this.arenaMoveDirection * speed * Math.max(0.65, Math.min(1.55, dt / 16.67));
      if (this.y <= top) {
        this.y = top;
        this.arenaMoveDirection = 1;
      } else if (this.y >= bottom) {
        this.y = bottom;
        this.arenaMoveDirection = -1;
      }
    }

    enforceFireRing(scene) {
      if (!this.transformed || !scene || !scene.player) return;
      const player = scene.player;
      const wall = this.getFireWallRect(scene);
      const inWallLane = player.y >= wall.y - 16 && player.y <= wall.y + wall.h + 18;
      const crossesWall = player.x > wall.x - 38 && player.x < wall.x + wall.w + 38;
      if (!inWallLane || !crossesWall) return;
      player.x = wall.x - 38;
      if (player.state !== 'knockdown' && player.state !== 'pinned') {
        player.startHitStun(90, 180);
        player.flash = Math.max(player.flash || 0, 180);
      }
    }

    updateFireballs(dt, scene) {
      if (!scene || !scene.spawnGundosFireball) return;
      const config = this.getConfig();
      this.fireballTimer -= dt;
      if (this.fireballTimer > 0) return;
      scene.spawnGundosFireball(this);
      const min = config.fireballSpawnMinMs || 1250;
      const max = Math.max(min, config.fireballSpawnMaxMs || 2350);
      this.fireballTimer = min + Math.random() * (max - min);
    }

    updateZetnikPressure(dt, scene) {
      const config = this.getConfig();
      this.spawnTimer -= dt;
      if (this.spawnTimer > 0) return;

      const active = (scene.enemies || []).filter(enemy =>
        enemy && enemy.alive && enemy.enemyType === 'zetnik' && enemy.gundosMinion && !enemy.remove
      ).length;
      if (active < (config.maxZetniks || 3) && scene.spawnGundosZetnik) {
        scene.spawnGundosZetnik(this);
      }

      const min = config.zetnikSpawnMinMs || 1450;
      const max = Math.max(min, config.zetnikSpawnMaxMs || 2450);
      this.spawnTimer = min + Math.random() * (max - min);
    }

    receiveZetnikHit(zetnik, scene) {
      if (!this.alive) return;
      const config = this.getConfig();
      this.hp = Math.max(0, this.hp - (config.zetnikHitDamage || 1));
      this.flash = 220;
      AudioManager.playSfx('zetnikCrash', 1, { playbackRate: 0.82, startAt: 0.01 });
      if (scene) scene.hitStop = Math.max(scene.hitStop || 0, 80);
      if (this.hp <= 0) this.defeat(scene);
    }

    defeat(scene) {
      if (!this.alive) return;
      this.alive = false;
      this.blocksWaveClear = false;
      this.deathTimer = 0;
      this.stopVoice();
      if (scene) {
        scene.gundosIntroActive = false;
        scene.gundosIntroLocked = false;
        scene.gundosArenaActive = false;
        scene.activeGundos = null;
        if (scene.startGundosVictoryDelay) scene.startGundosVictoryDelay();
      }
      AudioManager.playSfx('enemyDown', 1, { playbackRate: 0.82, startAt: 0.01 });
    }

    takeHit() {
      this.flash = 120;
    }

    getBodyBox() {
      const box = GAME_CONFIG.hitboxes && GAME_CONFIG.hitboxes.enemies &&
        GAME_CONFIG.hitboxes.enemies.gundos && GAME_CONFIG.hitboxes.enemies.gundos.body;
      if (box) return { x: this.x + box.x, y: this.y + box.y, w: box.w, h: box.h };
      return { x: this.x - 35, y: this.y - 125, w: 70, h: 125 };
    }

    getHurtbox() {
      return this.getBodyBox();
    }

    getPushbox() {
      const box = GAME_CONFIG.hitboxes && GAME_CONFIG.hitboxes.enemies &&
        GAME_CONFIG.hitboxes.enemies.gundos && GAME_CONFIG.hitboxes.enemies.gundos.pushbox;
      if (box) return { x: this.x + box.x, y: this.y + box.y, w: box.w, h: box.h };
      return { x: this.x - 48, y: this.y - 22, w: 96, h: 42 };
    }

    getImage() {
      const set = this.images.enemies.gundos;
      if (!this.alive) return set.knockdownBody || set.dead || set.devil;
      if (this.state === 'devil') return set.devil;
      if (this.state === 'swing') return set.swing;
      return set.walk[this.walkFrame] || set.idle;
    }

    draw(ctx, debug) {
      const image = this.getImage();
      if (!image) return;
      const scale = this.alive ? this.getConfig().scale : this.getConfig().scale * 0.85;
      const width = image.width * scale;
      const height = image.height * scale;
      const drawOffsetY = !this.alive ? 199 * scale : 0;
      ctx.save();
      if (!this.alive) {
        const holdMs = this.getConfig().deathHoldMs || 5000;
        ctx.globalAlpha = Math.max(0, 1 - Math.max(0, this.deathTimer - holdMs) / 1200);
      }
      else if (this.flash > 0) {
        this.flash = Math.max(0, this.flash - 16);
        ctx.globalAlpha = 0.55;
      }
      ctx.translate(this.x, this.y);
      if (this.facing < 0) ctx.scale(-1, 1);
      ctx.drawImage(image, -width / 2, -height + drawOffsetY, width, height);
      ctx.restore();
      this.drawHealthBar(ctx);

      if (debug) {
        const body = this.getBodyBox();
        ctx.strokeStyle = '#ffcc00';
        ctx.lineWidth = 2;
        ctx.strokeRect(body.x, body.y, body.w, body.h);
      }
    }

    drawFireWall(ctx, scene) {
      const set = this.images.enemies.gundos || {};
      const img = set.fireWall;
      const wall = this.getFireWallRect(scene);
      ctx.save();
      if (img) {
        ctx.globalAlpha = 0.94;
        ctx.drawImage(img, wall.x, wall.y, wall.w, wall.h);
      } else {
        const gradient = ctx.createLinearGradient(wall.x, wall.y, wall.x + wall.w, wall.y);
        gradient.addColorStop(0, 'rgba(255,70,15,0.15)');
        gradient.addColorStop(0.5, 'rgba(255,210,60,0.95)');
        gradient.addColorStop(1, 'rgba(255,70,15,0.15)');
        ctx.shadowColor = '#ff4a17';
        ctx.shadowBlur = 24;
        ctx.fillStyle = gradient;
        ctx.fillRect(wall.x, wall.y + wall.h * 0.42, wall.w, Math.max(20, wall.h * 0.16));
      }
      ctx.restore();
    }

    getFireWallRect(scene) {
      const level = scene && scene.getLevelConfig ? scene.getLevelConfig() : null;
      const configured = level && level.bossFireWall;
      if (configured && Number.isFinite(configured.x) && Number.isFinite(configured.y) &&
          Number.isFinite(configured.w) && Number.isFinite(configured.h)) {
        return configured;
      }

      const zone = scene && scene.getWalkZone ? scene.getWalkZone() : {
        left: 0,
        top: GAME_CONFIG.laneTop,
        bottom: GAME_CONFIG.laneBottom
      };
      const x = Math.max((zone.left || 0) + 18, this.x - 520);
      return {
        x,
        y: zone.top - 12,
        w: Math.max(220, this.x - x - 18),
        h: zone.bottom - zone.top + 36
      };
    }

    drawHealthBar(ctx) {
      if (!this.alive) return;
      const maxHp = Math.max(1, this.maxHp || this.getConfig().hp || 1);
      const ratio = Math.max(0, Math.min(1, this.hp / maxHp));
      const w = 360;
      const h = 18;
      const x = GAME_CONFIG.width / 2 - w / 2;
      const y = 94;
      ctx.save();
      ctx.fillStyle = 'rgba(0,0,0,0.72)';
      ctx.fillRect(x - 3, y - 3, w + 6, h + 6);
      ctx.fillStyle = '#5f1010';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#ff3b30';
      ctx.fillRect(x, y, w * ratio, h);
      ctx.strokeStyle = 'rgba(255,255,255,0.8)';
      ctx.lineWidth = 1;
      ctx.strokeRect(x, y, w, h);
      ctx.font = 'bold 14px Arial';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = '#fff0d0';
      ctx.fillText('GUNDOS', GAME_CONFIG.width / 2, y + h / 2 + 1);
      ctx.restore();
    }
  }

  window.GundosEnemy = GundosEnemy;

  if (typeof LevelScene !== 'undefined') {
    const previousPlayEnemyAppearSound = LevelScene.prototype.playEnemyAppearSound;
    LevelScene.prototype.playEnemyAppearSound = function (type) {
      if (type === 'gundos') return;
      return previousPlayEnemyAppearSound.call(this, type);
    };

    const previousCreateEnemy = LevelScene.prototype.createEnemy;
    LevelScene.prototype.createEnemy = function (type, x, y, id) {
      if (type === 'gundos') return new GundosEnemy(x, y, this.images, id);
      return previousCreateEnemy.call(this, type, x, y, id);
    };

    const previousSpawnInitialWave = LevelScene.prototype.spawnInitialWave;
    LevelScene.prototype.spawnInitialWave = function () {
      for (const enemy of this.enemies || []) {
        if (enemy && enemy.enemyType === 'gundos' && enemy.stopVoice) enemy.stopVoice();
      }
      this.gundosIntroActive = false;
      this.gundosIntroLocked = false;
      this.gundosArenaActive = false;
      this.activeGundos = null;
      this.gundosFloatTexts = [];
      this.gundosVictoryDelayMs = 0;
      this.gundosVictoryPending = false;
      previousSpawnInitialWave.call(this);
    };

    const previousMaterializeWave = LevelScene.prototype.materializeWave;
    LevelScene.prototype.materializeWave = function (wave) {
      if ((wave.enemies || []).some(group => group.type === 'gundos')) {
        this.gundosIntroActive = true;
        this.gundosIntroLocked = true;
        this.gundosArenaActive = false;
        this.activeGundos = null;
        const zone = this.getWalkZone ? this.getWalkZone() : {
          left: 0,
          right: GAME_CONFIG.width,
          top: GAME_CONFIG.laneTop,
          bottom: GAME_CONFIG.laneBottom
        };
        this.player.x = zone.left + 160;
        this.player.y = Math.min(zone.bottom - 20, Math.max(zone.top + 20, 620));
        this.player.facing = 1;
        this.player.state = 'idle';
      }
      previousMaterializeWave.call(this, wave);
    };

    LevelScene.prototype.getGundosLanes = function () {
      const zone = this.getWalkZone ? this.getWalkZone() : {
        top: GAME_CONFIG.laneTop,
        bottom: GAME_CONFIG.laneBottom
      };
      const top = zone.top + 24;
      const bottom = zone.bottom - 26;
      const mid = (top + bottom) / 2;
      return [top, mid, bottom];
    };

    LevelScene.prototype.spawnGundosZetnik = function (boss) {
      const lanes = this.getGundosLanes();
      const y = lanes[Math.floor(Math.random() * lanes.length)];
      const id = this.enemies.length + Math.floor(Math.random() * 1000);
      const x = Math.min(GAME_CONFIG.width + 110, (boss && boss.x ? boss.x + 180 : GAME_CONFIG.width + 80));
      const enemy = new ZetnikEnemy(x, y, this.images, id);
      if (enemy.setupGundosMinion) enemy.setupGundosMinion(boss);
      this.enemies.push(enemy);
      this.playEnemyAppearSound('zetnik');
      return enemy;
    };

    LevelScene.prototype.spawnGundosFireball = function (boss) {
      const lanes = this.getGundosLanes();
      const laneY = lanes[Math.floor(Math.random() * lanes.length)];
      const y = laneY - 88;
      const x = (boss ? boss.x : GAME_CONFIG.width - 120) - 82;
      const ball = new GundosFireball(x, y, boss, laneY);
      this.enemies.push(ball);
      AudioManager.playSfx('punch', 0.28, { playbackRate: 0.68, startAt: 0.01 });
      return ball;
    };

    LevelScene.prototype.startGundosVictoryDelay = function () {
      if (this.gundosVictoryPending) return;
      this.gundosVictoryPending = true;
      this.gundosVictoryDelayMs = (GAME_CONFIG.enemies.gundos && GAME_CONFIG.enemies.gundos.victoryDelayMs) || 4800;
      this.encounterActive = false;
      this.encounterCleared = false;
      this.nonBlockingWaveTimer = 0;
      this.pendingWave = null;
      this.pendingWaveTimer = 0;
    };

    LevelScene.prototype.spawnGundosGuardWall = function (boss) {
      const lanes = this.getGundosLanes();
      const count = Math.max(1, (GAME_CONFIG.enemies.gundos && GAME_CONFIG.enemies.gundos.guardZetniks) || 3);
      const start = Math.max(0, Math.floor((lanes.length - count) / 2));
      for (let index = 0; index < count; index++) {
        const lane = lanes[Math.min(lanes.length - 1, start + index)];
        const id = this.enemies.length + Math.floor(Math.random() * 1000);
        const x = (boss ? boss.x : GAME_CONFIG.width - 220) - 138 - index * 10;
        const enemy = new ZetnikEnemy(x, lane, this.images, id);
        if (enemy.setupGundosGuard) enemy.setupGundosGuard(boss, x, lane);
        this.enemies.push(enemy);
      }
      this.playEnemyAppearSound('zetnik');
    };

    LevelScene.prototype.spawnGundosMedicBastard = function (boss) {
      const zone = this.getWalkZone ? this.getWalkZone() : {
        left: 0,
        top: GAME_CONFIG.laneTop,
        bottom: GAME_CONFIG.laneBottom
      };
      const id = this.enemies.length + Math.floor(Math.random() * 1000);
      const y = Math.min(zone.bottom - 26, Math.max(zone.top + 28, (this.player && this.player.y) || 620));
      const enemy = new BastardEnemy(-70, y, this.images, id);
      const targetX = Math.min(zone.left + 315, (boss ? boss.x - 520 : 315));
      if (enemy.setupGundosMedic) enemy.setupGundosMedic(targetX, y);
      this.enemies.push(enemy);
      this.playEnemyAppearSound('bastard');
      return enemy;
    };

    LevelScene.prototype.addGundosFloatText = function (text, x, y, color) {
      if (!this.gundosFloatTexts) this.gundosFloatTexts = [];
      this.gundosFloatTexts.push({ text, x, y, color: color || '#ffffff', age: 0 });
    };

    LevelScene.prototype.updateGundosFloatTexts = function (dt) {
      if (!this.gundosFloatTexts) return;
      for (const item of this.gundosFloatTexts) {
        item.age += dt;
        item.y -= 0.035 * dt;
      }
      this.gundosFloatTexts = this.gundosFloatTexts.filter(item => item.age < 900);
    };

    LevelScene.prototype.drawGundosFloatTexts = function (ctx) {
      if (!this.gundosFloatTexts || !this.gundosFloatTexts.length) return;
      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 22px Arial';
      for (const item of this.gundosFloatTexts) {
        const alpha = Math.max(0, 1 - item.age / 900);
        ctx.globalAlpha = alpha;
        ctx.lineWidth = 4;
        ctx.strokeStyle = 'rgba(0,0,0,0.75)';
        ctx.fillStyle = item.color;
        ctx.strokeText(item.text, item.x, item.y);
        ctx.fillText(item.text, item.x, item.y);
      }
      ctx.restore();
    };

    LevelScene.prototype.releaseGundosGuardWall = function () {
      for (const enemy of this.enemies || []) {
        if (enemy && enemy.gundosMinion && enemy.gundosGuarding && enemy.releaseGundosGuard) {
          enemy.releaseGundosGuard();
        }
      }
    };

    const previousSeparateEnemies = LevelScene.prototype.separateEnemies;
    LevelScene.prototype.separateEnemies = function (dt, force) {
      const saved = [];
      for (const enemy of this.enemies || []) {
        if (enemy && enemy.enemyType === 'gundos') {
          saved.push({ enemy, x: enemy.x, y: enemy.y });
        }
      }
      previousSeparateEnemies.call(this, dt, force);
      for (const item of saved) {
        item.enemy.x = item.x;
        item.enemy.y = item.y;
      }
    };

    const previousEnemyHasPhysicalPresence = LevelScene.prototype.enemyHasPhysicalPresence;
    LevelScene.prototype.enemyHasPhysicalPresence = function (enemy) {
      if (enemy && enemy.nonPhysical) return false;
      return previousEnemyHasPhysicalPresence.call(this, enemy);
    };

    const previousNextScreen = LevelScene.prototype.nextScreen;
    LevelScene.prototype.nextScreen = function () {
      if (this.gundosVictoryPending) return;
      previousNextScreen.call(this);
    };

    const previousSceneUpdate = LevelScene.prototype.update;
    LevelScene.prototype.update = function (dt) {
      previousSceneUpdate.call(this, dt);
      if (this.gundosVictoryPending) {
        this.encounterCleared = false;
        this.gundosVictoryDelayMs -= dt;
        if (this.gundosVictoryDelayMs <= 0) {
          this.gundosVictoryPending = false;
          if (this.game && this.game.completeCampaignRegion) this.game.completeCampaignRegion();
        }
      }
      this.updateGundosFloatTexts(dt);
    };

    const previousSceneDraw = LevelScene.prototype.draw;
    LevelScene.prototype.draw = function (ctx) {
      if (this.isGundosFinaleScene && this.isGundosFinaleScene()) {
        this.drawGundosFinaleScene(ctx);
        return;
      }
      previousSceneDraw.call(this, ctx);
      if (this.drawLevelForegroundObjects) this.drawLevelForegroundObjects(ctx);
      this.drawGundosFloatTexts(ctx);
    };

    LevelScene.prototype.isGundosFinaleScene = function () {
      return !!((this.enemies || []).some(enemy => enemy && (
        enemy.enemyType === 'gundos' ||
        enemy.enemyType === 'gundosFireball' ||
        enemy.gundosMinion
      )) || this.gundosArenaActive || this.gundosVictoryPending);
    };

    LevelScene.prototype.drawGundosFinaleScene = function (ctx) {
      const bg = this.images.streets[this.screenIndex] || this.images.streets[0];
      if (bg) ctx.drawImage(bg, 0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      else {
        ctx.fillStyle = '#222';
        ctx.fillRect(0, 0, GAME_CONFIG.width, GAME_CONFIG.height);
      }
      if (this.drawLevelBackgroundEffects) this.drawLevelBackgroundEffects(ctx);

      ctx.fillStyle = 'rgba(255,255,255,0.025)';
      ctx.fillRect(0, GAME_CONFIG.laneTop, GAME_CONFIG.width, GAME_CONFIG.laneBottom - GAME_CONFIG.laneTop);
      if (this.drawLevelForegroundObjects) this.drawLevelForegroundObjects(ctx);

      const boss = this.activeGundos || (this.enemies || []).find(enemy => enemy && enemy.enemyType === 'gundos');
      if (boss && boss.alive && boss.transformed && boss.introFinished && boss.drawFireWall) boss.drawFireWall(ctx, this);

      const entities = [{ type: 'player', y: this.player.y, ref: this.player }];
      for (const enemy of this.enemies) entities.push({ type: 'enemy', y: enemy.y, ref: enemy });
      entities.sort((a, b) => a.y - b.y);
      for (const entity of entities) entity.ref.draw(ctx, this.debug);

      if (this.gundosVictoryPending) {
        ctx.save();
        ctx.textAlign = 'center';
        ctx.font = 'bold 28px Arial';
        ctx.fillStyle = 'rgba(255, 220, 120, 0.86)';
        ctx.strokeStyle = 'rgba(0,0,0,0.8)';
        ctx.lineWidth = 4;
        const text = 'ТВАРЬ ПОВЕРЖЕНА';
        ctx.strokeText(text, GAME_CONFIG.width / 2, 360);
        ctx.fillText(text, GAME_CONFIG.width / 2, 360);
        ctx.restore();
      }

      HUD.draw(ctx, this);
      this.drawGundosFloatTexts(ctx);

      if (this.debug) {
        ctx.strokeStyle = 'rgba(255,255,255,0.25)';
        ctx.lineWidth = 2;
        ctx.strokeRect(0, GAME_CONFIG.laneTop, GAME_CONFIG.width, GAME_CONFIG.laneBottom - GAME_CONFIG.laneTop);
      }
    };

    LevelScene.prototype.pauseGundosVoice = function () {
      const boss = this.activeGundos || (this.enemies || []).find(enemy => enemy && enemy.enemyType === 'gundos');
      if (boss && boss.pauseVoice) boss.pauseVoice();
    };

    LevelScene.prototype.resumeGundosVoice = function () {
      const boss = this.activeGundos || (this.enemies || []).find(enemy => enemy && enemy.enemyType === 'gundos');
      if (boss && boss.resumeVoice) boss.resumeVoice();
    };

    LevelScene.prototype.stopGundosVoice = function () {
      for (const enemy of this.enemies || []) {
        if (enemy && enemy.enemyType === 'gundos' && enemy.stopVoice) enemy.stopVoice();
      }
      this.gundosIntroActive = false;
      this.gundosIntroLocked = false;
      this.gundosArenaActive = false;
      this.activeGundos = null;
    };
  }

  if (typeof Player !== 'undefined') {
    const previousPlayerUpdate = Player.prototype.update;
    Player.prototype.update = function (dt, scene) {
      if (scene && scene.gundosIntroLocked) {
        this.state = 'idle';
        this.attackTimer = 0;
        this.attackHasHit = false;
        this.walkTimer = 0;
        return;
      }
      previousPlayerUpdate.call(this, dt, scene);
    };
  }

  if (typeof GameApp !== 'undefined') {
    const previousSetState = GameApp.prototype.setState;
    GameApp.prototype.setState = function (nextState) {
      const previousState = this.state;
      const scene = this.scene;
      if (scene && previousState === 'level' && nextState !== 'level') {
        const keepPausedForHeroSwitch = nextState === 'characterSelect' && this.characterSelectMode === 'switchHero';
        if (keepPausedForHeroSwitch && scene.pauseGundosVoice) scene.pauseGundosVoice();
        else if (scene.stopGundosVoice) scene.stopGundosVoice();
      }

      const result = previousSetState.call(this, nextState);

      if (this.scene && previousState !== 'level' && nextState === 'level' && this.scene.resumeGundosVoice) {
        this.scene.resumeGundosVoice();
      }

      return result;
    };

    const previousGameUpdate = GameApp.prototype.update;
    GameApp.prototype.update = function (dt) {
      const wasPaused = !!this.gundosAudioPauseState;
      const shouldPause = this.state === 'level' && !!this.paused;
      if (this.scene) {
        if (shouldPause && !wasPaused && this.scene.pauseGundosVoice) this.scene.pauseGundosVoice();
        if (!shouldPause && wasPaused && this.scene.resumeGundosVoice) this.scene.resumeGundosVoice();
      }
      if (shouldPause && !wasPaused && AudioManager.pauseAllAudio) AudioManager.pauseAllAudio();
      if (!shouldPause && wasPaused && AudioManager.resumePausedAudio) AudioManager.resumePausedAudio();
      this.gundosAudioPauseState = shouldPause;
      return previousGameUpdate.call(this, dt);
    };

    window.addEventListener('load', () => {
      let hiddenPaused = false;
      let hiddenPausedGameplay = false;
      document.addEventListener('visibilitychange', () => {
        const game = window.game || null;
        if (document.hidden) {
          hiddenPaused = true;
          hiddenPausedGameplay = !!(game && game.state === 'level' && !game.paused);
          if (game && game.state === 'level') game.paused = true;
          if (game && game.scene && game.scene.pauseGundosVoice) game.scene.pauseGundosVoice();
          if (AudioManager.pauseAllAudio) AudioManager.pauseAllAudio();
          if (game && game.state === 'level') game.gundosAudioPauseState = true;
        } else if (hiddenPaused) {
          hiddenPaused = false;
          if (game && hiddenPausedGameplay) game.paused = false;
          hiddenPausedGameplay = false;
          if (game && game.scene && game.scene.resumeGundosVoice && !game.paused) game.scene.resumeGundosVoice();
          if (AudioManager.resumePausedAudio && (!game || !game.paused)) AudioManager.resumePausedAudio();
        }
      });
      window.addEventListener('blur', () => {
        const game = window.game || null;
        if (game && game.state === 'level') game.paused = true;
        if (game && game.scene && game.scene.pauseGundosVoice) game.scene.pauseGundosVoice();
        if (AudioManager.pauseAllAudio) AudioManager.pauseAllAudio();
        if (game && game.state === 'level') game.gundosAudioPauseState = true;
      });
    });
  }

  configureFarEastFinale();
})();



/* ===== src/hitboxEditorPatch.js ===== */
(() => {
  if (typeof GAME_CONFIG === 'undefined') return;

  const COLORS = {
    body: '#ff3030',
    pushbox: '#ffd500',
    attack1: '#45ff45',
    attack2: '#45ff45',
    attack3: '#45ff45',
    attack: '#45ff45',
    slideAttack: '#45ff45',
    biteAttack: '#45ff45'
  };

  const ANATOMICAL_HITBOX_VERSION = 3;

  const SPRITE_METRICS = {
    heroes: {
      boris: { w: 1254, h: 1254, scalePath: 'heroes.boris.scale' },
      alexey: { w: 1024, h: 1024, scalePath: 'heroes.alexey.scale' },
      anna: { w: 1024, h: 1536, scalePath: 'heroes.anna.scale' }
    },
    enemies: {
      dogRegime: { w: 1122, h: 1340, scalePath: 'enemies.dogRegime.scale' },
      zetnik: { w: 1024, h: 1536, scalePath: 'enemies.zetnik.scale' },
      sucker: { w: 1024, h: 1536, scalePath: 'enemies.sucker.scale' },
      bastard: { w: 1122, h: 1402, scalePath: 'enemies.bastard.scale' },
      horse: { w: 1024, h: 1536, scalePath: 'enemies.horse.scale' },
      gundos: { w: 1536, h: 1024, scalePath: 'enemies.gundos.scale' }
    }
  };

  const ANATOMY_PROFILES = {
    boris: { bodyW: 0.36, minBodyW: 68, bodyH: 0.78, bodyTop: 0.96, pushW: 0.34, pushH: 0.16, attackY: 0.76, attackH: 0.24, reach: [0.26, 0.3, 0.36] },
    alexey: { bodyW: 0.34, minBodyW: 64, bodyH: 0.79, bodyTop: 0.96, pushW: 0.32, pushH: 0.16, attackY: 0.76, attackH: 0.24, reach: [0.28, 0.33, 0.39] },
    anna: { bodyW: 0.28, minBodyW: 58, bodyH: 0.74, bodyTop: 0.95, pushW: 0.3, pushH: 0.14, attackY: 0.72, attackH: 0.22, reach: [0.27, 0.31, 0.37] },
    humanEnemy: { bodyW: 0.42, minBodyW: 72, bodyH: 0.92, bodyTop: 0.99, pushW: 0.42, pushH: 0.18, attackY: 0.66, attackH: 0.28, attackW: 0.52 },
    dogRegime: { bodyW: 0.42, minBodyW: 72, bodyH: 0.92, bodyTop: 0.99, pushW: 0.42, pushH: 0.18, attackY: 0.66, attackH: 0.28, attackW: 0.572 },
    skinnyEnemy: { bodyW: 0.36, minBodyW: 64, bodyH: 0.9, bodyTop: 0.99, pushW: 0.38, pushH: 0.16, attackY: 0.66, attackH: 0.27, attackW: 0.55 },
    sucker: { bodyW: 0.5, minBodyW: 82, bodyH: 0.88, bodyTop: 0.99, pushW: 0.46, pushH: 0.18, slideY: 0.66, slideH: 0.27, slideW: 0.62, biteY: 0.64, biteH: 0.28, biteW: 0.45 },
    horse: { bodyW: 0.32, minBodyW: 58, bodyH: 0.92, bodyTop: 0.99, pushW: 0.36, pushH: 0.16, attackY: 0.58, attackH: 0.34, attackW: 1.55 },
    gundos: { bodyW: 0.26, bodyH: 0.88, bodyTop: 0.98, pushW: 0.3, pushH: 0.18, attackY: 0.66, attackH: 0.3, attackW: 0.42 }
  };

  function getByPath(path, fallback) {
    const parts = String(path || '').split('.');
    let node = GAME_CONFIG;
    for (const part of parts) {
      if (!node || node[part] == null) return fallback;
      node = node[part];
    }
    return Number(node) || fallback;
  }

  function roundBox(box) {
    return {
      x: Math.round(box.x),
      y: Math.round(box.y),
      w: Math.max(1, Math.round(box.w)),
      h: Math.max(1, Math.round(box.h))
    };
  }

  function metric(group, key) {
    const data = SPRITE_METRICS[group] && SPRITE_METRICS[group][key];
    const scale = data ? getByPath(data.scalePath, group === 'heroes' ? GAME_CONFIG.playerScale : GAME_CONFIG.enemyScale) :
      (group === 'heroes' ? GAME_CONFIG.playerScale : GAME_CONFIG.enemyScale);
    return {
      w: (data ? data.w : 1024) * scale,
      h: (data ? data.h : 1340) * scale
    };
  }

  function scaleSignature() {
    const parts = [];
    for (const group of Object.keys(SPRITE_METRICS)) {
      for (const key of Object.keys(SPRITE_METRICS[group])) {
        const data = SPRITE_METRICS[group][key];
        parts.push(group + ':' + key + '=' + getByPath(data.scalePath, group === 'heroes' ? GAME_CONFIG.playerScale : GAME_CONFIG.enemyScale));
      }
    }
    return parts.join('|');
  }

  function bodyBox(size, profile) {
    const w = Math.max(profile.minBodyW || 1, size.w * profile.bodyW);
    const h = size.h * profile.bodyH;
    const bottom = -size.h * (1 - profile.bodyTop);
    return roundBox({ x: -w / 2, y: bottom - h, w, h });
  }

  function pushBox(size, profile) {
    const w = size.w * profile.pushW;
    const h = size.h * profile.pushH;
    return roundBox({ x: -w / 2, y: -h, w, h });
  }

  function attackBox(size, profile, reach) {
    const h = size.h * profile.attackH;
    const w = size.w * reach;
    return roundBox({
      x: size.w * 0.14,
      y: -size.h * profile.attackY,
      w,
      h
    });
  }

  function makeHeroBoxes(key) {
    const size = metric('heroes', key);
    const profile = ANATOMY_PROFILES[key];
    return {
      body: bodyBox(size, profile),
      pushbox: pushBox(size, profile),
      attack1: attackBox(size, profile, profile.reach[0]),
      attack2: attackBox(size, profile, profile.reach[1]),
      attack3: attackBox(size, profile, profile.reach[2])
    };
  }

  function makeEnemyBoxes(key, profileKey) {
    const size = metric('enemies', key);
    const profile = ANATOMY_PROFILES[profileKey || 'humanEnemy'];
    return {
      body: bodyBox(size, profile),
      pushbox: pushBox(size, profile),
      attack: attackBox(size, profile, profile.attackW || 0.5)
    };
  }

  function makeSuckerBoxes() {
    const size = metric('enemies', 'sucker');
    const profile = ANATOMY_PROFILES.sucker;
    return {
      body: bodyBox(size, profile),
      pushbox: pushBox(size, profile),
      slideAttack: roundBox({ x: size.w * 0.04, y: -size.h * profile.slideY, w: size.w * profile.slideW, h: size.h * profile.slideH }),
      biteAttack: roundBox({ x: size.w * 0.12, y: -size.h * profile.biteY, w: size.w * profile.biteW, h: size.h * profile.biteH })
    };
  }

  const DEFAULT_HITBOXES = {
    heroes: {
      boris: makeHeroBoxes('boris'),
      alexey: makeHeroBoxes('alexey'),
      anna: makeHeroBoxes('anna')
    },
    enemies: {
      dogRegime: makeEnemyBoxes('dogRegime', 'dogRegime'),
      zetnik: makeEnemyBoxes('zetnik', 'skinnyEnemy'),
      sucker: makeSuckerBoxes(),
      bastard: makeEnemyBoxes('bastard', 'humanEnemy'),
      horse: makeEnemyBoxes('horse', 'horse'),
      gundos: makeEnemyBoxes('gundos', 'gundos')
    }
  };

  function clone(value) {
    return JSON.parse(JSON.stringify(value));
  }

  function mergeMissing(target, source) {
    for (const key of Object.keys(source)) {
      if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
        if (!target[key]) target[key] = {};
        mergeMissing(target[key], source[key]);
      } else if (target[key] === undefined) {
        target[key] = source[key];
      }
    }
  }

  function migrateHitboxEntity(target, defaults) {
    if (!target || !defaults) return clone(defaults);
    if (target.hurt && !target.body) target.body = clone(target.hurt);
    if (target.club && !target.attack) target.attack = clone(target.club);
    if (target.slide && !target.slideAttack) target.slideAttack = clone(target.slide);
    delete target.hurt;
    delete target.club;
    delete target.counter;
    delete target.slide;
    mergeMissing(target, defaults);
    for (const key of Object.keys(target)) {
      if (!defaults[key]) delete target[key];
    }
    return target;
  }

  function ensureHitboxes() {
    const signature = scaleSignature();
    if (!GAME_CONFIG.hitboxes ||
        GAME_CONFIG.hitboxes.profileVersion !== ANATOMICAL_HITBOX_VERSION ||
        GAME_CONFIG.hitboxes.scaleSignature !== signature) {
      GAME_CONFIG.hitboxes = {
        profileVersion: ANATOMICAL_HITBOX_VERSION,
        scaleSignature: signature,
        heroes: {},
        enemies: {}
      };
    }
    if (!GAME_CONFIG.hitboxes.heroes) GAME_CONFIG.hitboxes.heroes = {};
    if (!GAME_CONFIG.hitboxes.enemies) GAME_CONFIG.hitboxes.enemies = {};
    GAME_CONFIG.hitboxes.profileVersion = ANATOMICAL_HITBOX_VERSION;
    GAME_CONFIG.hitboxes.scaleSignature = signature;

    for (const key of Object.keys(DEFAULT_HITBOXES.heroes)) {
      GAME_CONFIG.hitboxes.heroes[key] = migrateHitboxEntity(GAME_CONFIG.hitboxes.heroes[key], DEFAULT_HITBOXES.heroes[key]);
    }
    for (const key of Object.keys(DEFAULT_HITBOXES.enemies)) {
      GAME_CONFIG.hitboxes.enemies[key] = migrateHitboxEntity(GAME_CONFIG.hitboxes.enemies[key], DEFAULT_HITBOXES.enemies[key]);
    }
    const dog = GAME_CONFIG.hitboxes.enemies.dogRegime;
    const dogDefault = DEFAULT_HITBOXES.enemies.dogRegime;
    if (dog && dog.attack && dogDefault && dogDefault.attack) {
      dog.attack.w = Math.max(dog.attack.w || 0, dogDefault.attack.w);
    }
  }

  function mirrorBox(box) {
    return { x: -box.x - box.w, y: box.y, w: box.w, h: box.h };
  }

  function worldBox(anchorX, anchorY, facing, box) {
    if (!box) return null;
    const b = facing === -1 ? mirrorBox(box) : box;
    return { x: anchorX + b.x, y: anchorY + b.y, w: b.w, h: b.h };
  }

  function heroBox(heroKey, boxKey) {
    ensureHitboxes();
    const heroBoxes = GAME_CONFIG.hitboxes.heroes[heroKey] || GAME_CONFIG.hitboxes.heroes.boris;
    return heroBoxes[boxKey] || DEFAULT_HITBOXES.heroes.boris[boxKey];
  }

  function enemyBox(enemyType, boxKey) {
    ensureHitboxes();
    const enemyBoxes = GAME_CONFIG.hitboxes.enemies[enemyType] || GAME_CONFIG.hitboxes.enemies.dogRegime;
    return enemyBoxes[boxKey] || DEFAULT_HITBOXES.enemies.dogRegime[boxKey];
  }

  function strokeBox(ctx, box, color, label) {
    if (!box) return;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.strokeRect(box.x, box.y, box.w, box.h);
    if (label) {
      ctx.font = 'bold 11px Arial';
      ctx.fillStyle = color;
      ctx.fillText(label, box.x + 3, box.y - 4);
    }
    ctx.restore();
  }

  function boxOverlap(a, b) {
    return a && b && a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
  }

  ensureHitboxes();

  if (typeof Player !== 'undefined') {
    Player.prototype.getHitbox = function () {
      const key = this.comboStep === 3 ? 'attack3' : this.comboStep === 2 ? 'attack2' : 'attack1';
      return worldBox(this.x, this.y, this.facing, heroBox(this.heroKey, key));
    };

    Player.prototype.getBodyBox = function () {
      const hero = GAME_CONFIG.heroes && (GAME_CONFIG.heroes[this.heroKey] || GAME_CONFIG.heroes.boris);
      const knockdownBody = (this.state === 'knockdown' || this.state === 'pinned') && hero && hero.knockdownBody;
      if (knockdownBody) {
        const w = Math.max(1, knockdownBody.w || 160);
        const h = Math.max(1, knockdownBody.h || 44);
        return {
          x: this.x - w / 2,
          y: this.y - h,
          w,
          h
        };
      }
      return worldBox(this.x, this.y, this.facing, heroBox(this.heroKey, 'body'));
    };

    Player.prototype.getPushbox = function () {
      return worldBox(this.x, this.y, this.facing, heroBox(this.heroKey, 'pushbox'));
    };

    Player.prototype.canCounterSlide = function (enemy) {
      if (this.state !== 'attack' || !enemy) return false;
      if (typeof Combat !== 'undefined' && Combat.laneCanConnect && !Combat.laneCanConnect(this, enemy, {
        laneTolerance: (GAME_CONFIG.enemies.sucker && GAME_CONFIG.enemies.sucker.counterRangeY) || GAME_CONFIG.yHitTolerance
      })) return false;
      const data = this.getAttackData();
      if (this.attackTimer < data.activeStart || this.attackTimer > data.activeEnd) return false;

      const config = (GAME_CONFIG.enemies && GAME_CONFIG.enemies.sucker) || {};
      const rangeY = config.counterRangeY || GAME_CONFIG.enemyAttackRangeY || 58;
      const counterZone = this.getHitbox();
      const forgiveness = config.counterForgiveness == null ? 2 : config.counterForgiveness;
      const targets = [];
      if (enemy.state === 'slide' && typeof enemy.getSlideHitbox === 'function') targets.push(enemy.getSlideHitbox());
      if (enemy.state === 'slide' && typeof enemy.getHurtbox === 'function') targets.push(enemy.getHurtbox());

      return targets.some(target => target && Combat.canMeleeHit(this, enemy, {
        attackBox: counterZone,
        targetBox: {
        x: target.x - forgiveness,
        y: target.y - forgiveness,
        w: target.w + forgiveness * 2,
        h: target.h + forgiveness * 2
        },
        laneTolerance: rangeY
      }));
    };

    const originalPlayerDraw = Player.prototype.hitboxSimpleDrawOriginal || Player.prototype.draw;
    Player.prototype.hitboxSimpleDrawOriginal = originalPlayerDraw;
    Player.prototype.draw = function (ctx, debug = false) {
      originalPlayerDraw.call(this, ctx, false);
      if (!debug) return;
      strokeBox(ctx, this.getBodyBox(), COLORS.body, 'BODY');
      strokeBox(ctx, this.getPushbox(), COLORS.pushbox, 'PUSHBOX');
      if (this.state === 'attack') strokeBox(ctx, this.getHitbox(), COLORS.attack1, 'ATTACK');
    };
  }

  if (typeof DogRegimeEnemy !== 'undefined') {
    DogRegimeEnemy.prototype.getBodyBox = function () {
      return worldBox(this.x, this.y, this.facing, enemyBox(this.enemyType, 'body'));
    };

    DogRegimeEnemy.prototype.getHurtbox = function () {
      return this.getBodyBox();
    };

    DogRegimeEnemy.prototype.getPushbox = function () {
      return worldBox(this.x, this.y, this.facing, enemyBox(this.enemyType, 'pushbox'));
    };

    DogRegimeEnemy.prototype.getGroundBodyBox = function () {
      return this.getPushbox();
    };

    DogRegimeEnemy.prototype.getAttackBox = function () {
      return worldBox(this.x, this.y, this.facing, enemyBox(this.enemyType, 'attack'));
    };

    DogRegimeEnemy.prototype.getClubReachBox = function () {
      return this.getAttackBox();
    };

    DogRegimeEnemy.prototype.canClubReachPlayer = function (player, anticipation = false) {
      if (!player || typeof player.getBodyBox !== 'function') return false;
      const attack = this.getAttackBox();
      const config = (GAME_CONFIG.enemies && GAME_CONFIG.enemies[this.enemyType]) || {};
      const contactPad = this.enemyType === 'dogRegime' ? (config.clubContactTolerance == null ? 10 : config.clubContactTolerance) : 0;
      const pad = anticipation ? Math.max(4, contactPad) : contactPad;
      const activeBox = pad > 0 ?
        { x: attack.x - pad, y: attack.y - Math.max(2, pad * 0.5), w: attack.w + pad * 2, h: attack.h + Math.max(4, pad) } :
        attack;
      return Combat.canMeleeHit(this, player, {
        attackBox: activeBox,
        targetBox: player.getBodyBox(),
        laneTolerance: anticipation ? (this.attackRangeY || GAME_CONFIG.yHitTolerance) : GAME_CONFIG.yHitTolerance
      });
    };

    DogRegimeEnemy.prototype.isInAttackRange = function (player) {
      return this.canClubReachPlayer(player, true);
    };

    DogRegimeEnemy.prototype.updateAttack = function (dt, scene) {
      if (this.enemyType === 'horse') {
        if (!this.attackFacing) this.attackFacing = this.facing || 1;
        if (!this.attackPositionLocked) {
          this.attackLockX = this.x;
          this.attackLockY = this.y;
          this.attackPositionLocked = true;
        }
        this.x = this.attackLockX;
        this.y = this.attackLockY;
        this.facing = this.attackFacing;
      }
      this.attackTimer += dt;
      const windupMs = this.attackWindupMs || GAME_CONFIG.enemyWindupMs;
      const activeMs = this.attackActiveMs || GAME_CONFIG.enemyActiveMs;
      const recoveryMs = this.attackRecoveryMs || GAME_CONFIG.enemyRecoveryMs;
      const activeStart = windupMs;
      const activeEnd = windupMs + activeMs;
      const finalWhiplashAt = windupMs + activeMs * 0.45;

      if (this.enemyType === 'horse' && !this.whiplashFinalSfxPlayed) {
        const horseConfig = GAME_CONFIG.enemies.horse || {};
        const leadMs = horseConfig.whiplashFinalSfxLeadMs == null ? 80 : horseConfig.whiplashFinalSfxLeadMs;
        const startAt = horseConfig.whiplashFinalSfxStartAt == null ? 0.24 : horseConfig.whiplashFinalSfxStartAt;
        if (this.attackTimer >= Math.max(windupMs, finalWhiplashAt - leadMs)) {
          AudioManager.playSfx('horseWhiplashFinal', 0.9, { startAt });
          this.whiplashFinalSfxPlayed = true;
        }
      }

      if (!this.attackHasHit && this.attackTimer >= activeStart && this.attackTimer <= activeEnd) {
        const player = scene.player;
        if (this.canClubReachPlayer(player, false)) {
          const hit = player.receiveDamage(this.damage, { source: 'melee', knockbackX: this.facing * 18 });
          if (hit) scene.hitStop = 42;
        }
        this.attackHasHit = true;
      }

      if (this.attackTimer >= windupMs + activeMs + recoveryMs) {
        this.state = 'walk';
        this.intent = Math.random() < 0.58 ? 'retreat' : 'strafe';
        this.strafeDirection = Math.random() < 0.5 ? -1 : 1;
        this.retreatTimer = this.postAttackRetreatMs || 220;
        const min = this.attackCooldownMinMs || 300;
        const max = this.attackCooldownMaxMs || 520;
        this.cooldown = min + Math.random() * Math.max(1, max - min);
        this.attackTimer = 0;
        this.attackHasHit = false;
        this.whiplashFinalSfxPlayed = false;
        this.attackFacing = null;
        this.attackPositionLocked = false;
        this.attackLockX = null;
        this.attackLockY = null;
      }
    };

    const originalEnemyDraw = DogRegimeEnemy.prototype.hitboxSimpleDrawOriginal || DogRegimeEnemy.prototype.draw;
    DogRegimeEnemy.prototype.hitboxSimpleDrawOriginal = originalEnemyDraw;
    DogRegimeEnemy.prototype.draw = function (ctx, debug = false) {
      originalEnemyDraw.call(this, ctx, false);
      if (!debug || !this.alive) return;
      strokeBox(ctx, this.getBodyBox(), COLORS.body, 'BODY');
      strokeBox(ctx, this.getPushbox(), COLORS.pushbox, 'PUSHBOX');
      if (this.state === 'attack') strokeBox(ctx, this.getAttackBox(), COLORS.attack, 'ATTACK');
    };
  }

  if (typeof SuckerEnemy !== 'undefined') {
    const originalSuckerGetBodyBox = SuckerEnemy.prototype.getBodyBox || DogRegimeEnemy.prototype.getBodyBox;
    SuckerEnemy.prototype.getBodyBox = function () {
      if (this.state === 'pinBite') {
        const box = { x: -58, y: -58, w: 116, h: 58 };
        return worldBox(this.x, this.y, this.facing, box);
      }
      return originalSuckerGetBodyBox.call(this);
    };

    SuckerEnemy.prototype.getHurtbox = function () {
      return this.getBodyBox();
    };

    SuckerEnemy.prototype.getSlideHitbox = function () {
      return worldBox(this.x, this.slideY || this.y, this.facing, enemyBox('sucker', 'slideAttack'));
    };

    SuckerEnemy.prototype.getBiteAttackBox = function () {
      return worldBox(this.x, this.y, this.facing, enemyBox('sucker', 'biteAttack'));
    };

    const originalSuckerDraw = SuckerEnemy.prototype.hitboxSimpleDrawOriginal || SuckerEnemy.prototype.draw;
    SuckerEnemy.prototype.hitboxSimpleDrawOriginal = originalSuckerDraw;
    SuckerEnemy.prototype.draw = function (ctx, debug = false) {
      originalSuckerDraw.call(this, ctx, debug);
      if (!debug || !this.alive) return;
      if (this.state === 'slide') strokeBox(ctx, this.getSlideHitbox(), COLORS.slideAttack, 'SLIDE_ATTACK');
      if (this.state === 'pinBite') strokeBox(ctx, this.getBiteAttackBox(), COLORS.biteAttack, 'BITE_ATTACK');
    };
  }

  if (typeof DevPanel !== 'undefined' && !DevPanel.hitboxEditorSimplePatchApplied) {
    if (!DevPanel.tabs.includes('HITBOXES')) DevPanel.tabs.push('HITBOXES');
    DevPanel.selectedHitboxEntityIndex = DevPanel.selectedHitboxEntityIndex || 0;
    DevPanel.selectedHitboxBoxIndex = DevPanel.selectedHitboxBoxIndex || 0;

    DevPanel.hitboxEntities = function () {
      return [
        { group: 'heroes', key: 'boris', label: 'Hero: Boris' },
        { group: 'heroes', key: 'alexey', label: 'Hero: Alexey' },
        { group: 'heroes', key: 'anna', label: 'Hero: Anna' },
        { group: 'enemies', key: 'dogRegime', label: 'Enemy: Dog' },
        { group: 'enemies', key: 'zetnik', label: 'Enemy: Zetnik' },
        { group: 'enemies', key: 'sucker', label: 'Enemy: Sucker' },
        { group: 'enemies', key: 'bastard', label: 'Enemy: Bastard' },
        { group: 'enemies', key: 'horse', label: 'Enemy: Horse' },
        { group: 'enemies', key: 'gundos', label: 'Enemy: Gundos' }
      ];
    };

    DevPanel.hitboxBoxKeys = function (entity) {
      const data = GAME_CONFIG.hitboxes[entity.group][entity.key] || {};
      return Object.keys(data);
    };

    DevPanel.getSelectedHitboxEntity = function () {
      const entities = this.hitboxEntities();
      this.selectedHitboxEntityIndex = ((this.selectedHitboxEntityIndex % entities.length) + entities.length) % entities.length;
      return entities[this.selectedHitboxEntityIndex];
    };

    DevPanel.getSelectedHitboxBoxKey = function () {
      const entity = this.getSelectedHitboxEntity();
      const keys = this.hitboxBoxKeys(entity);
      if (keys.length === 0) return null;
      this.selectedHitboxBoxIndex = ((this.selectedHitboxBoxIndex % keys.length) + keys.length) % keys.length;
      return keys[this.selectedHitboxBoxIndex];
    };

    DevPanel.getSelectedHitbox = function () {
      const entity = this.getSelectedHitboxEntity();
      const key = this.getSelectedHitboxBoxKey();
      return GAME_CONFIG.hitboxes[entity.group][entity.key][key];
    };

    DevPanel.hitboxEditorRects = function () {
      const panel = this.panelRect();
      const x = panel.x + 36;
      const y = panel.y + 122;
      return {
        box: { x, y, w: 978, h: 492 },
        entityPrev: { x: x + 110, y: y + 24, w: 36, h: 28 },
        entityNext: { x: x + 600, y: y + 24, w: 36, h: 28 },
        boxPrev: { x: x + 110, y: y + 64, w: 36, h: 28 },
        boxNext: { x: x + 600, y: y + 64, w: 36, h: 28 },
        preview: { x: x + 650, y: y + 24, w: 300, h: 420 }
      };
    };

    const originalHandleClick = DevPanel.hitboxOriginalHandleClick || DevPanel.handleClick;
    DevPanel.hitboxOriginalHandleClick = originalHandleClick;
    DevPanel.handleClick = function (point, game) {
      const panel = this.panelRect();
      if (!this.inRect(point, panel)) return;
      const close = { x: panel.x + panel.w - 78, y: panel.y + 14, w: 56, h: 32 };
      if (this.inRect(point, close)) { this.open = false; return; }
      const tab = this.getClickedTab(point);
      if (tab) { this.tab = tab; this.setStatus('Tab: ' + tab); return; }
      if (this.handleFooterClick(point, game)) return;
      if (this.tab === 'HITBOXES') { this.handleHitboxEditorClick(point, game); return; }
      originalHandleClick.call(this, point, game);
    };

    DevPanel.handleHitboxEditorClick = function (point, game) {
      const r = this.hitboxEditorRects();
      const entity = this.getSelectedHitboxEntity();
      if (this.inRect(point, r.entityPrev)) { this.selectedHitboxEntityIndex--; this.selectedHitboxBoxIndex = 0; this.setStatus('Entity changed'); return true; }
      if (this.inRect(point, r.entityNext)) { this.selectedHitboxEntityIndex++; this.selectedHitboxBoxIndex = 0; this.setStatus('Entity changed'); return true; }
      if (this.inRect(point, r.boxPrev)) { this.selectedHitboxBoxIndex--; this.setStatus('Box changed'); return true; }
      if (this.inRect(point, r.boxNext)) { this.selectedHitboxBoxIndex++; this.setStatus('Box changed'); return true; }

      const props = ['x', 'y', 'w', 'h'];
      const hb = this.getSelectedHitbox();
      for (let i = 0; i < props.length; i++) {
        const y = r.box.y + 140 + i * 46;
        const minus = { x: r.box.x + 118, y: y - 22, w: 34, h: 28 };
        const plus = { x: r.box.x + 452, y: y - 22, w: 34, h: 28 };
        const bar = { x: r.box.x + 166, y: y - 13, w: 270, h: 12 };
        const prop = props[i];
        const min = prop === 'w' || prop === 'h' ? 4 : -240;
        const max = prop === 'w' || prop === 'h' ? 280 : 240;
        if (this.inRect(point, minus)) { hb[prop] = Math.max(min, hb[prop] - 2); this.applyToCurrentScene(game); this.setStatus(prop + ': ' + hb[prop]); return true; }
        if (this.inRect(point, plus)) { hb[prop] = Math.min(max, hb[prop] + 2); this.applyToCurrentScene(game); this.setStatus(prop + ': ' + hb[prop]); return true; }
        if (this.inRect(point, bar)) {
          const ratio = Math.max(0, Math.min(1, (point.x - bar.x) / bar.w));
          hb[prop] = Math.round(min + ratio * (max - min));
          this.applyToCurrentScene(game);
          this.setStatus(prop + ': ' + hb[prop]);
          return true;
        }
      }
      return false;
    };

    const originalDraw = DevPanel.hitboxOriginalDraw || DevPanel.draw;
    DevPanel.hitboxOriginalDraw = originalDraw;
    DevPanel.draw = function (ctx) {
      if (!GAME_CONFIG.adminTuningEnabled) return;
      if (!this.open || this.tab !== 'HITBOXES') { originalDraw.call(this, ctx); return; }

      const panel = this.panelRect();
      ctx.fillStyle = 'rgba(0,0,0,0.92)';
      ctx.fillRect(panel.x, panel.y, panel.w, panel.h);
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.strokeRect(panel.x, panel.y, panel.w, panel.h);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 24px Arial';
      ctx.fillText('DEVELOPER PANEL', panel.x + 22, panel.y + 38);
      ctx.font = '13px Arial';
      ctx.fillStyle = '#aaa';
      ctx.fillText('Hitbox editor: BODY receives damage, ATTACK deals damage, PUSHBOX is only movement collision.', panel.x + 22, panel.y + 58);
      this.drawButton(ctx, panel.x + panel.w - 78, panel.y + 14, 56, 32, 'X');
      this.drawTabs(ctx);
      this.drawHitboxEditor(ctx);
      this.drawFooter(ctx);
      this.drawStatus(ctx, panel);
    };

    DevPanel.drawHitboxEditor = function (ctx) {
      const r = this.hitboxEditorRects();
      const entity = this.getSelectedHitboxEntity();
      const boxKey = this.getSelectedHitboxBoxKey();
      const hb = this.getSelectedHitbox();

      ctx.fillStyle = 'rgba(255,255,255,0.06)';
      ctx.fillRect(r.box.x, r.box.y, r.box.w, r.box.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.strokeRect(r.box.x, r.box.y, r.box.w, r.box.h);

      ctx.fillStyle = '#ccc';
      ctx.font = '14px Arial';
      ctx.fillText('Entity:', r.box.x + 24, r.box.y + 43);
      this.drawButton(ctx, r.entityPrev.x, r.entityPrev.y, r.entityPrev.w, r.entityPrev.h, '<');
      this.drawButton(ctx, r.entityNext.x, r.entityNext.y, r.entityNext.w, r.entityNext.h, '>');
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 15px Arial';
      ctx.fillText(entity.label, r.box.x + 160, r.box.y + 43);

      ctx.fillStyle = '#ccc';
      ctx.font = '14px Arial';
      ctx.fillText('Box:', r.box.x + 24, r.box.y + 83);
      this.drawButton(ctx, r.boxPrev.x, r.boxPrev.y, r.boxPrev.w, r.boxPrev.h, '<');
      this.drawButton(ctx, r.boxNext.x, r.boxNext.y, r.boxNext.w, r.boxNext.h, '>');
      ctx.fillStyle = COLORS[boxKey] || '#fff';
      ctx.font = 'bold 15px Arial';
      ctx.fillText(String(boxKey).toUpperCase(), r.box.x + 160, r.box.y + 83);

      const props = ['x', 'y', 'w', 'h'];
      for (let i = 0; i < props.length; i++) this.drawHitboxSlider(ctx, props[i], hb[props[i]], r.box.x + 24, r.box.y + 140 + i * 46);

      this.drawHitboxPreview(ctx, r.preview, entity, boxKey);

      ctx.fillStyle = '#aaa';
      ctx.font = '12px Arial';
      ctx.fillText('BODY + ATTACK are combat. PUSHBOX is only for spacing/separation.', r.box.x + 24, r.box.y + 370);
      ctx.fillText('SAVE stores locally. EXPORT prints hitboxes so they can be copied into permanent config.', r.box.x + 24, r.box.y + 392);
    };

    DevPanel.drawHitboxSlider = function (ctx, prop, value, x, y) {
      const min = prop === 'w' || prop === 'h' ? 4 : -240;
      const max = prop === 'w' || prop === 'h' ? 280 : 240;
      const ratio = (value - min) / (max - min);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 14px Arial';
      ctx.fillText(prop.toUpperCase(), x, y);
      ctx.fillStyle = '#ccc';
      ctx.fillText(String(value), x + 46, y);
      this.drawButton(ctx, x + 94, y - 22, 34, 28, '-');
      ctx.fillStyle = '#222';
      ctx.fillRect(x + 142, y - 13, 270, 12);
      ctx.fillStyle = '#55ccff';
      ctx.fillRect(x + 142, y - 13, 270 * Math.max(0, Math.min(1, ratio)), 12);
      ctx.strokeStyle = '#777';
      ctx.strokeRect(x + 142, y - 13, 270, 12);
      this.drawButton(ctx, x + 428, y - 22, 34, 28, '+');
    };

    DevPanel.drawHitboxPreview = function (ctx, rect, entity, selectedBoxKey) {
      ctx.fillStyle = 'rgba(0,0,0,0.34)';
      ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.strokeRect(rect.x, rect.y, rect.w, rect.h);
      const anchor = { x: rect.x + rect.w / 2, y: rect.y + rect.h - 48 };
      const img = this.getPreviewImage(entity);
      if (img) {
        const scale = entity.group === 'heroes'
          ? ((GAME_CONFIG.heroes[entity.key] && GAME_CONFIG.heroes[entity.key].scale) || GAME_CONFIG.playerScale)
          : ((GAME_CONFIG.enemies[entity.key] && GAME_CONFIG.enemies[entity.key].scale) || GAME_CONFIG.enemyScale);
        const w = img.width * scale;
        const h = img.height * scale;
        ctx.drawImage(img, anchor.x - w / 2, anchor.y - h, w, h);
      }
      ctx.fillStyle = 'rgba(255,255,255,0.35)';
      ctx.fillRect(anchor.x - 5, anchor.y - 1, 10, 2);
      ctx.fillRect(anchor.x - 1, anchor.y - 5, 2, 10);

      const boxes = GAME_CONFIG.hitboxes[entity.group][entity.key] || {};
      for (const key of Object.keys(boxes)) {
        const b = worldBox(anchor.x, anchor.y, 1, boxes[key]);
        strokeBox(ctx, b, COLORS[key] || '#fff', key === selectedBoxKey ? key.toUpperCase() : '');
      }
    };

    DevPanel.getPreviewImage = function (entity) {
      const game = window.game || null;
      const images = game && game.images;
      if (!images) return null;
      if (entity.group === 'heroes') return images.heroes && images.heroes[entity.key] && images.heroes[entity.key].idle;
      return images.enemies && images.enemies[entity.key] && images.enemies[entity.key].idle;
    };

    const originalExportConfig = DevPanel.hitboxOriginalExportConfig || DevPanel.exportConfig;
    DevPanel.hitboxOriginalExportConfig = originalExportConfig;
    DevPanel.exportConfig = function () {
      originalExportConfig.call(this);
      console.log('STREETS_OF_RUSSIA_HITBOXES_ONLY');
      console.log(JSON.stringify(GAME_CONFIG.hitboxes, null, 2));
    };

    DevPanel.hitboxEditorSimplePatchApplied = true;
  }
})();



/* ===== src/devCacheBustPatch.js ===== */
(function () {
  const DEV_CACHE_BUST = String(Date.now());

  function addCacheBust(url) {
    if (typeof url !== 'string') return url;
    if (!url.startsWith('assets/')) return url;
    const separator = url.includes('?') ? '&' : '?';
    return url + separator + 'dev=' + DEV_CACHE_BUST;
  }

  function patchAssetTree(value) {
    if (typeof value === 'string') return addCacheBust(value);
    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i += 1) value[i] = patchAssetTree(value[i]);
      return value;
    }
    if (value && typeof value === 'object') {
      for (const key of Object.keys(value)) value[key] = patchAssetTree(value[key]);
    }
    return value;
  }

  if (typeof window !== 'undefined') window.DEV_CACHE_BUST = DEV_CACHE_BUST;
  if (typeof Assets !== 'undefined') patchAssetTree(Assets);

  console.info('[dev-cache] cache bust enabled:', DEV_CACHE_BUST);
})();



